INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1, 'COMP1001', 'Exploring Multimedia and Internet Computing', '3 Credit(s)', 'The course introduces the organization and basic working mechanism of a computer system, including the development of the trend of modern computer system. It covers the fundamentals of computer hardware design and software application development. The course emphasizes the application of the state-of-the-art software tools to solve problems and present solutions via a range of skills related to multimedia and internet computing tools such as internet, e-mail, WWW, webpage design, computer animation, spreadsheet charts/figures, presentations with graphics and animations, etc. The course also covers business, accessibility, and relevant security issues in the use of computers and Internet.', 'CORE 1231, ISOM 2010, any COMP courses of 2000-level or above', '[BLD] Blended learning', '2026-08-11 15:32:50.745722');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (2, 'COMP1021', 'Introduction to Computer Science', '3 Credit(s)', 'This course introduces students to the world of Computer Science. Students will experience a range of fun and interesting areas from the world of computing, such as game programming, web programming, user interface design and computer graphics. These will be explored largely by programming in the Python language. For all students, except students of School of Engineering; Data Science and Technology major and Dual Degree students with Engineering as one of the degrees.', 'COMP 1022P (prior to 2025-26), COMP 1023, COMP 2011, COMP 2012H, ISOM 3400', '', '2026-08-11 11:25:13.338098');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (3, 'COMP1023', 'Introduction to Python Programming', '3 Credit(s)', 'This introductory course is designed to provide a comprehensive overview of the Python programming language and its core concepts, such as data types, variables, operators, and control structures, as well as the collection data types, including lists, tuples, sets, and dictionaries. Additionally, it covers the language''s functions and the fundamentals of object-oriented programming. The course also explores a range of useful Python modules and packages, such as NumPy, Pandas, Matplotlib, through meaningful examples and applications, as well as hands-on experimentation using a well-known integrated development environment and AI tools. Furthermore, this course will discuss good programming practices and debugging skills.', 'COMP 1021, COMP 1022P (prior to 2025-26), COMP 1029P, COMP 2011, COMP 2012H, COMP 2211, CIVL 1121, IEDA 1180, ISOM 3400', '', '2026-08-11 11:25:13.343094');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (4, 'COMP1028', 'Extended Python Programming Bridging Course', '1 Credit(s)', 'This course is designed for students who have already completed COMP 1021 Introduction to Computer Science and want to learn additional material for AI programming in Python, as well as to meet the prerequisites for courses requiring COMP 1023 Introduction to Python Programming. It includes the topics found in COMP 1023 that are not covered in COMP 1021. The course goes into greater detail on the concepts from COMP 1021 and covers more advanced topics, such as NumPy, Pandas, and Matplotlib. Students will engage in these topics through self-learning of course materials and guided programming exercises. Students without the prerequisites but with relevant programming knowledge may seek the instructor''s approval to enroll in the course. Graded P or F.', 'COMP 1021', '[SPO] Self-paced online delivery', '2026-08-11 15:32:50.758513');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (5, 'COMP1029C', 'C Programming Bridging Course', '1 Credit(s)', 'This course introduces the C programming language. It is intended for students who already have some experience in computer programming but wish to learn how to apply those programming skills to the C language. The course covers basic programming topics, such as variables, control, loops, and functions, to more advanced topics. Students explore these by self-learning of course materials together with guided programming exercises. Students without the prerequisites but possess relevant programming knowledge may seek instructor''s approval for enrolling in the course. Graded P or F.', 'COMP 1021 OR COMP 1022P (prior to 2025-26) OR COMP 1023 OR ISOM 3230 OR ISOM 3320 OR ISOM 3400', '', '2026-08-11 11:25:13.353832');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (6, 'COMP1029J', 'Java Programming Bridging Course', '1 Credit(s)', 'This course introduces the Java programming language. It is intended for students who already have some experience in computer programming but wish to learn how to apply those programming skills to the Java language. The course covers basic programming topics such as variables, control statements, loops, functions, and object-oriented programming concepts. Students explore these by self-learning of course materials together with guided programming exercises. Students without the prerequisites but possess relevant programming knowledge may seek instructor''s approval for enrolling in the course. Graded P or F.', 'COMP 1021 OR COMP 1023 OR ISOM 3230 OR ISOM 3400', '', '2026-08-11 11:25:13.358960');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (7, 'COMP1029P', 'Python Programming Bridging Course', '1 Credit(s)', 'This course introduces the Python programming language. It is intended for students who already have some experience in computer programming but wish to learn how to apply those programming skills to the Python language. The course covers basic programming topics, such as variables, functions and loops, to more advanced topics. Students explore these by self-learning of course materials together with guided programming exercises. Students without the prerequisites but possess relevant programming knowledge may seek instructor''s approval for enrolling in the course. Graded P or F.', 'COMP 1022P (prior to 2025-26) OR ISOM 3230 OR ISOM 3320', '', '2026-08-11 11:25:13.362963');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (8, 'COMP1029V', 'Excel VBA Programming Bridging Course', '1 Credit(s)', 'This course introduces the VBA programming language, in the context of Microsoft Excel. It is intended for students who already have some experience in computer programming but wish to learn how to apply those programming skills to VBA, within Excel. The course covers basic programming topics, such as variables, functions and loops, to more advanced topics. Appropriate features of the Excel program are also covered. Students explore these by self-learning of course materials together with guided programming exercises. Students without the prerequisites but possess relevant programming knowledge may seek instructor''s approval for enrolling in the course. Graded P or F.', 'COMP 1021 OR COMP 1022P (prior to 2025-26) OR COMP 1023 OR ISOM 3320 OR ISOM 3400', '', '2026-08-11 11:25:13.367423');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (9, 'COMP1942', 'Exploring and Visualizing Data', '3 Credit(s)', 'This course teaches concepts and tools for exploring and visualizing data. There are a lot of real-life decision-making problems (e.g., business, logistics, economics, marketing, finance, resource management, forecasting and engineering) which can be formulated using some existing data analysis models. Existing computer science tools such as Microsoft Excel can help us to model and solve these problems easily, and to visualize the solutions.', 'CORE 1232', '', '2026-08-11 15:32:50.773651');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (10, 'COMP1943', 'Creative Sound and Video Design', '3 Credit(s)', 'This experiential project course will provide hands-on experiences in creating music videos and movie/game trailers by creatively remixing music, recutting video, and applying effects. It will provide a creative outlet where students can apply their problem-solving skills in a deep and engaging way to create music remixes, mashups, character videos, and reimagined video stories. It will also give students a chance to work with emerging video technologies. Whether students have music and video editing background or not, this course will provide them a chance to create like a sound designer, video editor, and director. For each of their music video creations, students will also create a behind-the-scenes commentary video that describes what they did and how they did it. They will share their creations and commentaries in class, and learn from and be inspired by one another.', 'CORE 1233', '[EXP] Experiential learning', '2026-08-11 15:32:50.779133');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (11, 'COMP1944', 'Artificial Intelligence Ethics', '3 Credit(s)', 'The last decades have seen a huge growth in the capabilities and applications of Artificial Intelligence. The technological advances and the societal impact of the use of AI arose increasing public attention. There are large expectations of AI’s potential to help to solve many current problems and to support the well-being of all, while concerns are growing about the role of AI in privacy, transparency, fairness, safety, and many other ethical issues. This course aims at providing an overview and encouraging discussions of AI ethics issues for students of different backgrounds, not necessarily technical. To the end, humans are the ones who can and must ensure ethical AI in such an emerging and challenging time.', 'COMP 4901M, CORE 1234', '[BLD] Blended learning', '2026-08-11 15:32:50.783735');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (25, 'AMCC2010', 'Digital Audio Workstation Composition', '3 Credit(s)', 'This course will introduce students to electronic music composition using Digital Audio Workstations (DAWs) with a focus on creative and technical fluency. Students will learn the fundamentals of compositional thought, audio editing, mixing, and production while exploring creative strategies unique to electronic and digital music-making. The course will also incorporate contemporary machine learning and AI music tools, enabling students to experiment with algorithmic generation and manipulation of musical material to enhance their creative workflow. Students will explore sampling, synthesis, Musical Instrument Digital Interface (MIDI), and the integration of AI-tools into traditional DAW environments. Since we will be working with concrete sound rather than notated music, no prior experience in music notation, music theory, composition or performance is required. The course will culminate in a concert of original works that showcase students’ ability to creatively organize sound using technology. By the end of the course, students will have developed both practical DAW skills and critical awareness of how AI tools are reshaping modern music production.', 'None', 'Not Specified', '2026-08-11 15:29:14.973525');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (26, 'AMCC2020', 'Coding for Artistic Expression and Creation', '3 Credit(s)', 'This course introduces students to the world of creative coding, where technology meets artistic expression. Students will engage in hands-on projects that explore concepts such as randomness, sound art, image processing, and generative art. Through individual assignments and a collaborative final project, students will learn to harness code as a medium for creativity, producing unique art pieces that blend visual, auditory, and interactive elements. While prior programming knowledge is preferred, this course will accommodate students with varying levels of programming experience. However, the emphasis will be on using coding as a tool for artistic expression rather than systematically covering all programming elements.', 'Preferred but not required', 'Not Specified', '2026-08-11 15:29:14.980978');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (27, 'AMCC4900', 'Independent Study in Arts and Machine Creativity', '1-4 Credit(s)', 'Independent studies or projects under the directed guidance of a faculty member. Course requirements include readings on the relevant topic and a research or survey project specifically defined for the research topic. Credits assigned depend on the workload and may be repeated if different topics are taken. Enrollment requires approval of the course instructor. May be graded by letter, P/F or DI/PA/F for different offerings.', 'Approval of the course instructor', 'Not Specified', '2026-08-11 15:29:14.984363');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (61, 'CTDL1901', 'Cognitive Foundations of University Education: Critical Thinking and Data Literacy', '3 Credit(s)', 'This course provides an introduction to critical thinking and data literacy. Students will be equipped with critical tools to analyse problems of reasoning, evaluate the truthfulness of evidence, examine the fallacies of thinking, as well as the ability to construct valid arguments and reasonable solutions for their personal and professional life.', 'CORE 1901, IDPO 1020 (prior to 2022-23)', 'Fall, Spring', '2026-08-11 15:33:20.475422');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (62, 'CTDL1902', 'AI and Society: Ethics, Cognition, and Critical Analysis', '3 Credit(s)', 'This course explores how artificial intelligence (AI) will impact society and the economy. It covers key topics such as ethics, social justice, and the benefits and existential risks of AI. Throughout the course, students will learn about AI through by using AI to complete various tasks. The course is designed around active learning exercises encouraging students to develop hybrid critical thinking skills, which leverage generative AI to extend their natural human capabilities.', 'IDPO 2500B', 'Blended Learning', '2026-08-11 15:33:20.483875');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (63, 'CTDL1950', 'Decision - Inside Out: Empowering Interdisciplinary Thinking', '3 Credit(s)', 'In today’s fast-paced world, strong thinking skills are essential for academic success and personal growth across various disciplines. This interdisciplinary course, offered by Academy of Interdisciplinary Studies, is designed for junior-level students to enhance their critical thinking, problem-solving, and decision-making abilities by integrating perspectives from multiple fields.', 'None', 'Not specified', '2026-08-11 15:33:20.489877');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (64, 'DSCT4900', 'Academic and Professional Development', '0 Credit(s)', 'This course is for academic and professional development of students in the BSc program in Data Science and Technology offered by the Department of Mathematics and Department of Computer Science and Engineering. Activities may include seminars, workshops, advising and sharing sessions, interaction with faculty and teaching staff, and discussion with student peers or alumni. Graded PP, P or F. For DSCT students only.', 'For DSCT students only.', 'Not specified.', '2026-08-11 12:02:56.055187');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (68, 'EMIA1901', 'Introduction to Smart City Development', '3 Credit(s)', 'Smart city development is a crucial area in today''s public policy, technology, and business landscapes. This course provides students with foundational knowledge in this interdisciplinary field, focusing on public policy, technological innovations, and urban challenges. Students will explore Dr. Boyd Cohen''s Smart City Wheel, covering six key areas: Smart People, Smart Economy, Smart Environment, Smart Government, Smart Living, and Smart Mobility. Through lectures and guest speakers from industry, students will gain insights into real-world applications and case studies. A special workshop on the use of open data and common spatial data infrastructure (CSDI) in smart city innovations. Assessments include formative evaluations, critical reflections, active discussions, and group projects. By the end of the course, students will be equipped to propose sustainable solutions, critically evaluate technology adoption, and understand future trends in smart city development. This knowledge will help them make informed decisions when selecting majors and minors in technology, social science, environmental science, business, and sustainability.', '', '', '2026-08-11 15:35:42.911652');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (69, 'EMIA1902', 'Digital Information Governance in the AI Era', '3 Credit(s)', 'This course explores how digital information disorder - including misinformation, disinformation, deepfakes, and AI-generated content - shapes public discourse, trust, and governance in today’s globalized world. Through interdisciplinary perspectives from media studies, political science, and technology ethics, students examine real-world cases from Hong Kong, Asia, Europe, and the U.S., and analyze how different societies respond to these challenges. The course covers key topics such as algorithmic bias, social media manipulation, media regulation, AI ethics, and platform governance. Interactive activities - including debates, policy simulations, and fact-checking workshops - equip students with practical skills to analyze and respond to digital misinformation. By integrating international case studies and ethical reasoning, the course prepares students to think critically, engage in informed debate, and develop responsible solutions to address digital information disorder in both local and global contexts.', '', '', '2026-08-11 15:35:42.919218');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (70, 'EMIA2010', 'Cross-disciplinary Seminar', '0 Credit(s)', 'A compulsory course for students enrolling in the extended major programs throughout their course of study. It is a seminar series presented by faculty members and guest speakers on interdisciplinary topics in extended major area and its applications related to the major. For Year 2 or above students with extended major. Graded P or F.', '', '', '2026-08-11 15:35:42.948804');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (71, 'EMIA2020', 'Cross-disciplinary Design Thinking', '3 Credit(s)', 'This course focuses on user-collaborative design methods for generating inclusive product solutions that integrate stakeholder and product functionality perspectives. Students will create specified product/process/policy/protocol/plan (5P) concept models using recursive user feedback engagement methods, experimental prototyping, and divergent and convergent ideation strategies. Featured topics include design thinking; stakeholder research; concept development, screening, and selection; and interaction design. For students enrolling in extended major programs and students with consent from the instructor.', '', '', '2026-08-11 15:35:42.961006');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (72, 'EMIA2200', 'Introduction to Digital Media and Culture', '3 Credit(s)', 'This course provides an integrated introduction to the theories, cultures, and practical techniques of digital media, designed to prepare students for advanced study and opportunities in the Extended Major Program in DMCA. Through a balanced focus on both conceptual and technical skills, students will explore the aesthetics, theory, and practice of digital photography, cinematography, content creation, visual storytelling, media design, interactive and immersive media, and generative arts. The course combines lectures, workshops, demonstrations, and critiques, covering topics such as digital graphics editing, stop-motion, data visualization, AI-generated art, and virtual production. Students will gain hands-on experience with industry-relevant software and hardware, including picture and sound editing, digital effects, motion capture, and VR applications. Guest speakers and curators from leading institutions enrich the learning experience with current practices and insights. For students enrolled in the Extended Major Program in DMCA.', '', '', '2026-08-11 15:35:42.970666');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (73, 'EMIA2210', 'Sci-Fi Storytelling', '3 Credit(s)', 'Sci-fi Storytelling offers a creative exploration of sci-fi topics such as perception of reality, existentialism in the multiverse, and philosophical and ethical questions on identity, AI, genetic engineering and so on. This course not only discusses these topics, it also offers students opportunities to exercise power of creative imagination and to practice art of storytelling by developing students’ own original sci-fi story. In this analytical, creative, critical thinking and collaborative process, students will team up to develop and present their story analysis and creation. This course offers visions of the future through studying important visionary film masters and related creative sci-fi works in films, TV and animations, which stimulate thought-provoking discussion and forward thinking. Students will combine sci-fi knowledge, art and technique of visual storytelling, analytical, creative and critical thinking to screen-related research, analysis, sci-fi story creation through world, character and tension building. For students enrolling in extended major program in DMCA and students with consent from the instructor.', '', '', '2026-08-11 15:35:42.976206');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (74, 'EMIA2220', 'Technical Theater Arts', '3 Credit(s)', 'Offered by EMIA in collaboration with MTPC, this 3-credit Technical Theater Arts course delves into the backstage realm of theater production. Students will explore the collaborative nature of diverse technical disciplines in shaping a stage production. Through hands-on experience with hardware, software, and a custom-designed meta-verse training tool, they will study techniques that deliver real-world performance and presentation. The course also covers front of house fundamentals, field trips, and a performance-based capstone project, providing students with a comprehensive understanding of theater operations. Students will be required to submit an introductory video and obtain the instructor''s approval for enrolling in the course. Interview may also be required.', '', '', '2026-08-11 15:35:42.982466');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (75, 'EMIA2500', 'Special Topics (I)', '1-4 Credit(s)', 'This special topic course will help students to gain a more in-depth knowledge and to have a better understanding on the topics related to their interdisciplinary studies or emerging interdisciplinary areas. A range of professional activities are eligible for study, including seminars/lectures, professional activities/meetings, journal readings or structured readings. May be repeated for credits if different topics are taken. May be graded by letter, P/F or DI/PA/F for different offerings.', '', '', '2026-08-11 15:35:42.989873');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (76, 'EMIA3500', 'Special Topics (II)', '1-4 Credit(s)', 'This special topic course will help students to gain a more in-depth knowledge and to have a better understanding on the topics related to their interdisciplinary studies or emerging interdisciplinary areas. A range of professional activities are eligible for study, including seminars/lectures, professional activities/meetings, journal readings or structured readings. May be repeated for credits if different topics are taken. May be graded by letter, P/F or DI/PA/F for different offerings.', '', '', '2026-08-11 15:35:42.995340');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (77, 'EMIA4110', 'Practical Machine Learning', '3 Credit(s)', 'This course consists of three parts: 1) the foundation of machine learning including its history and core algorithms; 2) the mainstream open platforms and sources for machine learning with an emphasis on practical applications; 3) case studies to illustrate how machine learning can be used to solve the problems from different fields. This course will equip students from different backgrounds with the essential knowledge about machine learning and practical algorithms, systems, and platforms available for solving real-world problems. For students enrolled in extended major programs only.', 'COMP 1023 OR COMP 2011 OR COMP 2012H; COMP 4211, MATH 4432', '', '2026-08-11 15:35:43.004610');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (78, 'EMIA4500', 'Special Topics (III)', '1-4 Credit(s)', 'This special topic course will help students to gain a more in-depth knowledge and to have a better understanding on the topics related to their interdisciplinary studies or emerging interdisciplinary areas. A range of professional activities are eligible for study, including seminars/lectures, professional activities/meetings, journal readings or structured readings. May be repeated for credits if different topics are taken. May be graded by letter, P/F or DI/PA/F for different offerings.', '', '', '2026-08-11 15:35:43.009634');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (79, 'EMIA4900', 'Independent Study', '1-4 Credit(s)', 'Independent studies or projects under the directed guidance of a faculty member. Course requirements include readings on the relevant topic and a research or survey project specifically defined for the research topic. Credits assigned depend on the workload and may be repeated if different topics are taken. For students with approval from instructor for enrolling in the course. May be graded by letter, P/F or DI/PA/F for different offerings.', '', '', '2026-08-11 15:35:43.019153');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (80, 'EMIA4990', 'Interdisciplinary Capstone Design', '0 Credit(s)', 'This course is to be taken simultaneously with a Final Year or Capstone Project offered by a student’s enrolled Major. Students will apply knowledge learnt in the Extended Major and interdisciplinary problem-solving skills to solve real-world problems in their Major areas. Approval from EMIA is required to ensure the Final Year or Capstone Project integrates the knowledge of the extended AI major. If the enrolled Final Year or Capstone Project is in a major which is not the student''s enrolled first major, they must also seek approval from their enrolled first major confirming that the project also integrates knowledge of their first major. Graded P or F. May be graded PP.', '', '', '2026-08-11 15:35:43.026661');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (81, 'EMIA4991', 'Interdisciplinary Capstone Project', '3 Credit(s)', 'Students are expected to complete an interdisciplinary Capstone Project with strong components in an emerging area of specialization under the guidance of faculty members. The objective is to train students to apply knowledge learnt in the extended major and interdisciplinary problem-solving skills to solve real-world problems in their Major areas. For extended major students who do not take Final Year or Capstone Projects offered by any majors only. Maybe graded PP.', '', '', '2026-08-11 15:35:43.031641');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (82, 'ENTR1001', 'Entrepreneurship 1001: Designing Your Future', '3 Credit(s)', 'This course introduces a variety of key entrepreneurship competence including skills, knowledge, and mindsets. Through working on student-centric and team-based projects, students will learn through the practice of entrepreneurship. In addition to experiential learning, students will also participate in in-depth conversations with entrepreneurs from all walks of life. Students will have opportunities to gain authentic entrepreneurial experiences and embark on their own entrepreneurial journey. This course does not require students to have previous entrepreneurial experience or any form of business training. Students from all majors and backgrounds are welcome!', '', '', '2026-08-11 11:39:31.990497');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (83, 'ENTR2010', 'Entrepreneurship Mentorship and Readings', '1 Credit(s)', 'This course introduces entrepreneurship through mentorship and readings to broadly expose students to the area. Students can choose their own area of interest to study, and they can also explore and further develop their interested area with their mentor. While there will be group meetings every two weeks, students are required to explore and participate in entrepreneurship activities on their own. The instructor will help students consolidate their experiences. Instructor''s approval is required for course enrollment. Graded P or F.', '', '', '2026-08-11 11:39:31.997056');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (84, 'ENTR3012', 'Tech startup and entrepreneurs ecosystem: growth and innovation', '3 Credit(s)', 'This course provides hands-on, practical experience in developing and implementing growth strategies for technology startups and innovative digital services in early stages. Focused on the unique challenges of the entrepreneurial and startups’ ecosystem, students will explore cutting-edge business models and frameworks designed to navigate the uncertain and resource-constrained environment that startups face. The course emphasizes learning through case studies, projects, and interactive workshops, interaction with real practitioners including successful and unsuccessful tech entrepreneurs, venture capitalists, and industry experts, ensuring students gain practical skills that can be applied in entrepreneurial ventures.', 'ENTR 4000C, GBUS 2030, TEMG 3950', '', '2026-08-11 15:36:26.232644');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (85, 'ENTR3013', 'Prototyping Skills for Entrepreneurs', '3 Credit(s)', 'The ability to quickly and effectively transform ideas into tangible prototypes is a critical skill for aspiring entrepreneurs. This course is designed to equip students interested in the entrepreneurship path with the necessary knowledge and hands-on experience to master the art of prototyping across various domains, including software, hardware and mechanical area, empowering them to bring their innovative concepts to life. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 11:39:32.007643');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (86, 'ENTR3030', 'Social Innovations and Entrepreneurship', '3 Credit(s)', 'Building a social enterprise can be markedly different from building a commercial one. When well deployed, social innovations can meet social needs that the government welfare, business corporations or charity-based social welfare cannot easily fulfill. A commercial entity should also be aware of the social impacts of its business decisions. This course introduces corporate social responsibility (CSR), social innovations, and the factors of consideration to start a social enterprise. This includes current topics on operation models, sustainability, team building, case studies, strategies, practices, etc. Site visits and student projects will be involved. Instructor''s approval is required for course enrollment.', '', '', '2026-08-11 11:39:32.011860');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (87, 'ENTR3100', 'Industrial Landscape: Understanding the Elements to Start a Business', '3 Credit(s)', 'This course is jointly run by the Schools of Engineering, Science and Business & Management. It acquaints students with the landscapes of various industries, by examining important elements to start up a business and introducing the markets of various sectors. The goal is to expose students interested in entrepreneurship to the diversity, competition, interaction and decision-making process of various ecosystems. Professors and visitors from the schools will discuss enabling technologies, key processes, business models, and cases on topics of current interests. Students form teams to survey and analyze the companies and ecosystem of a particular sector, in order to identify the operation models, similarities, differentiations and opportunities ahead.', '', '', '2026-08-11 11:39:32.016447');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (88, 'ENTR3350', 'Global Product Development', '3 Credit(s)', 'Joint lecture and project-based course on global product development through a global and interdisciplinary team approach among three institutions in Beijing, Hong Kong and Seoul. This course requires students to go out into global society and industry companies beyond (China, Hong Kong, Korea) for seeking and defining a global user-centered design problem by themselves, to develop the engineering design alternative to solve it, and then to build a working critical function prototype. Students will collaborate through online tools as well as 3 face-to-face meetings throughout the semester in the three respective campuses. This course provides various lectures such as marketing, industrial design, patent law, creative thinking, conceptual design methodology, and case studies in problem ideation. Instructor''s approval is required.', '', '', '2026-08-11 11:39:32.021635');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (89, 'ENTR3360', 'From Product Innovations to Successful Technology Startups', '3 Credit(s)', 'This course is intended for students who want to seriously pursue technology startups. Students will be guided to identify critical steps and important milestones associated with each step in order to build a technology startup. The course requires students to take an existing project idea with early conceptual design and prototype, and bring it to the next level of project realization. Lecture topics include market research, industrial design, patent law, supply chain management and business model development. Cross-college faculty and external experts will provide individual and team mentoring for student projects. Company visits, field trips, trade shows and interactions with experienced entrepreneurs will be arranged. Students with good performance in this course are recommended to different funding and incubation opportunities. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 11:39:32.026370');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (90, 'ENTR4000', 'Special Topics in Entrepreneurship', '1-4 Credit(s)', 'This course discusses selected, emerging and/or hot topics on entrepreneurship which are not currently covered by existing courses. May be graded by letter, P/F, or DI/PA/F subject to different offerings. Students may repeat the course for credits if different topics are taken.', '', '', '2026-08-11 11:39:32.031365');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (91, 'ENTR4901-4904', 'Student-led Entrepreneurship Acceleration Project', '1-4 Credit(s)', 'Many successful IT startups begin in university years. This is a project course led by students to accelerate their entrepreneurship endeavor under the guidance and advice of a faculty member. Students work in team of size 2 to 3 to develop an idea from its scratch to become viable in market. In the process, students work on ideation, prototyping, making presentations, developing operation strategies, conducting experimental trials, designing market survey, collecting user feedbacks, writing business plan, and soft-launching and pivoting the product or services. Written reports, presentations, and/or business/operation plan are required. May be repeated for credits if different topics are taken. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 11:39:32.035877');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (92, 'ENTR4911', 'IT Entrepreneurship', '3 Credit(s)', 'Basic elements of starting a new business in information technology; exploiting an "unfair" advantage; preparing a business plan; arranging financial support; accounting and legal requirements; exit strategy. Case studies of successful and failed ventures in Hong Kong and elsewhere.', 'COMP 4911; COMP 1021 or COMP 1022P (prior to 2025-26) or COMP 1022Q or COMP 1023 or COMP 2011 or COMP 2012H or ISOM 3230', '', '2026-08-11 15:36:26.248487');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (95, 'UPOP1920', 'Career Readiness Training Program', '1 Credit(s)', 'This course aims to hone students’ required skills for their job search quests and smooth transition into the professional world. Highlights of this course are 1) train up students’ job interview, leadership evaluation interview, CV writing and networking skills and offer personalized feedback, 2) through small group engagement, business leaders will foster students’ understanding about the challenges and requirements of different jobs in different industries, and 3) the experiential nature of this course allows students to dive deep into the 1.5-day intense workshop with challenges resembling real-life situations. This course is a prerequisite for UPOP 2920 Undergraduate Practice Opportunities, the two-credit common core internship course. Instructor''s approval is required for enrollment in the course. For Year 2 or above students. Graded P or F.', '', '', '2026-08-11 15:48:30.263556');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (96, 'UPOP2920', 'Undergraduate Practice Opportunities', '2 Credit(s)', 'This course integrates a 6-week full-time internship in which students have the opportunities to apply an array of soft skills and their domain academic knowledge to real jobs. Students will gain valuable exposure from these areas 1) apply important soft skills into practice – in this case it relates to job exploration and effective workplace skills, 2) initiating their job search journeys from scratch and eventually landing on internship jobs, 3) receive feedback from peers, supervisors and faculties, submit internship reports to reflect on their takeaways, and participate in an end-of-term conference for experience sharing, and 4) continue with the self-discovery and development journeys with boosted confidence and new learnings. The internship offers valuable exposure to students to learn from real work environments and better prepare them for their future career trajectory expeditions. Instructor''s approval is required for enrollment in the course. For Year 2 or above students. Graded P or F.', 'GNED 2510 OR SCIE 1100 OR SHSS 1030 OR UPOP 1920', '', '2026-08-11 15:48:30.269365');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (97, 'TEMG1010', 'T&M Professional Activities', '0 Credit(s)', 'A compulsory course for students enrolling in the Dual Degree Program in Technology and Management throughout their five years of study. This course is designed to provide academic advising to students, to enhance their personal and professional skills, to improve their understanding of latest business and technology development and to improve their communication skills. Activities involve executive forums, workshops and mentoring program. Graded P or F.', '', '', '2026-08-11 15:48:32.487179');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (98, 'TEMG1011', 'T&M Professional Activities I', '0 Credit(s)', 'A compulsory course for Year 1 students enrolling in the Dual Degree Program in Technology and Management. This course is designed to provide academic advising to students, to enhance their personal and professional skills, to improve their understanding of latest business and technology development and to improve their communication skills. Activities involve executive forums, workshops and outreach program. Graded P or F.', '', '', '2026-08-11 15:48:32.492557');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (99, 'TEMG1012', 'T&M Professional Activities II', '0 Credit(s)', 'A compulsory course for Year 2 students enrolling in the Dual Degree Program in Technology and Management. This course is designed to provide academic advising to students, to enhance their personal and professional skills, to improve their understanding of latest business and technology development and to improve their communication skills. Activities involve executive forums, workshops and outreach program. Graded P or F.', '', '', '2026-08-11 15:48:32.496338');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (100, 'TEMG1013', 'T&M Professional Activities III', '0 Credit(s)', 'A compulsory course for Year 3 students enrolling in the Dual Degree Program in Technology and Management. This course is designed to provide academic advising to students, to enhance their personal and professional skills, to improve their understanding of latest business and technology development and to improve their communication skills. Activities involve executive forums, workshops and outreach program. Graded P or F.', '', '', '2026-08-11 15:48:32.502545');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (101, 'TEMG1014', 'T&M Professional Activities IV', '0 Credit(s)', 'A compulsory course for Year 4 students enrolling in the Dual Degree Program in Technology and Management. This course is designed to provide academic advising to students, to enhance their personal and professional skills, to improve their understanding of latest business and technology development and to improve their communication skills. Activities involve executive forums, workshops and outreach program. Graded P or F.', '', '', '2026-08-11 15:48:32.509356');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (102, 'TEMG1015', 'T&M Professional Activities V', '0 Credit(s)', 'A compulsory course for Year 5 students enrolling in the Dual Degree Program in Technology and Management. This course is designed to provide academic advising to students, to enhance their personal and professional skills, to improve their understanding of latest business and technology development and to improve their communication skills. Activities involve executive forums, workshops and outreach program. Graded P or F.', '', '', '2026-08-11 15:48:32.513086');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (103, 'TEMG3950', 'T&M Case Analysis and Product Innovation', '3 Credit(s)', 'TEMG3950 is divided into 2 parts. Part 1 is ''Case Analysis'' for students to develop structured problem-solving skills using MECE frameworks and communicate solution using 5-Step Persuasive Selling in essay and presentation format. Part 2 is ''Product Innovation'' for students to develop critical thinking skills using techniques such as Design Thinking. Value Proposition Design and Business Model Canvas. Instructor consent is needed for this course.', '', '', '2026-08-11 15:48:32.522058');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (104, 'TEMG4000', 'Special Topics', '0-4 Credit(s)', 'Selected topics of current interest in Technology and Management. May be repeated for credits if different topics are covered.', '', '', '2026-08-11 15:48:32.539780');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (105, 'TEMG4940', 'T&M Prototyping and Research Project', '3-5 Credit(s)', 'TEMG4940 series of project-based courses is for T&M-DDP students to gain deep insight into an industry domain by working with corporate-sponsor(s) to understand a new trend in the industry, appreciate the business challenges behind the problem, and develop a working prototype incorporating innovative business strategies and advanced software tools. Students may repeat the course for credits if the topics are different. Instructor consent is required for this course.', '', '', '2026-08-11 15:48:32.546904');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (106, 'TEMG4950', 'T&M Corporate Consulting Project', '3-5 Credit(s)', 'TEMG 4950 series are experiential-learning courses where students role-play management consultants using technology & management (T&M) strategies to solve a complex problem currently faced by an industry leading firm. This project uses the format of a consulting engagement with at least 5 client meetings. Final solution recommendation will be presented before a panel of executives from the client’s organization, project sponsors and industry subject experts. Students are allowed to repeat TEMG 4950 projects with the projects covering different topics. Instructor consent is required for this course.', '', '', '2026-08-11 15:48:32.554893');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (107, 'TEMG4970', 'T&M IBPC Startup Project', '1-5 Credit(s)', 'TEMG4970 International Business Plan Competition (IBPC) offers an opportunity for aspiring young students to work in a multi-discipline and multi-cultural environment to develop startup businesses leveraging breakthroughs in technology and business innovation to impact a lot of lives. Students may repeat the course for credits if the topics are different. Instructor consent is required for this course.', '', '', '2026-08-11 15:48:32.561353');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (108, 'UROP1000', 'Undergraduate Research Opportunities', '0 Credit(s)', 'This course is developed under the Undergraduate Research Opportunities Program (UROP). It provides a platform on which students can gain some hands-on experience in conducting research in faculty-led projects during the summer session. Approval by faculty supervisor(s) is required. Students are required to submit a written report upon completion of the project. This course can only be taken once for stipend option only; no course credit is assigned. Graded P or F.', '', 'Summer Session', '2026-08-11 15:48:45.719259');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (109, 'UROP1100', 'Undergraduate Research Opportunities Series 1', '1 Credit(s)', 'This is the first course of a four-course series under the Undergraduate Research Opportunities Program (UROP), which allows students to engage in faculty-led research projects that can span up to four terms. Successful completion of UROP 1100 is a prerequisite for proceeding to UROP 2100, which can involve either the same or a different project led by the same faculty supervisor. Progression from UROP 1100 to UROP 4100, regardless of whether it is on the same or a different research project, must be under the guidance of the same faculty supervisor. In case of a change in faculty supervisor, students need to restart from UROP 1100. Approval by faculty supervisor(s) is required. Students are required to submit a written report upon completion of each course. Graded P or F.', '', '', '2026-08-11 15:48:45.726179');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (110, 'UROP2100', 'Undergraduate Research Opportunities Series 2', '1 Credit(s)', 'This is the second course of the four-course Undergraduate Research Opportunities Program (UROP) series, which allows students to engage in faculty-led research projects that can span up to four terms. Successful completion of UROP 1100 is a prerequisite for proceeding to UROP 2100, which can involve either the same or a different project led by the same faculty supervisor. Progression from UROP 1100 to UROP 4100, regardless of whether it is on the same or a different research project, must be under the guidance of the same faculty supervisor. In case of a change in faculty supervisor, students need to restart from UROP 1100. Approval by faculty supervisor(s) is required. Students are required to submit a written report upon completion of the course. Graded P or F.', 'UROP 1100', '', '2026-08-11 15:48:45.732480');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (111, 'UROP3100', 'Undergraduate Research Opportunities Series 3', '1 Credit(s)', 'This is the third course of the four-course Undergraduate Research Opportunities Program (UROP) series, which allows students to engage in faculty-led research projects that can span up to four terms. Successful completion of UROP 2100 or UROP 3200 is a prerequisite for proceeding to UROP 3100, which can involve either the same or a different project led by the same faculty supervisor. Progression from UROP 1100 to UROP 4100, regardless of whether it is on the same or a different research project, must be under the guidance of the same faculty supervisor. In case of a change in faculty supervisor, students need to restart from UROP 1100. Approval by faculty supervisor(s) is required. Students are required to submit a written report upon completion of the course. Graded P or F.', 'UROP 2100 OR UROP 3200', '', '2026-08-11 11:43:56.730558');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (112, 'UROP3200', 'Undergraduate Research Opportunities with Mini-conference Experience', '1 Credit(s)', 'This course offers students a platform to gain hands-on research experience and extend their involvement in the Undergraduate Research Opportunities Program (UROP). Students have the opportunity to work on either the same research project or a different project under the supervision of the same faculty supervisor. Students are required to participate in a mini-conference to deliver project presentations and submit a final report. Approval by faculty supervisor(s) is required. Graded P or F.', '(TWO passing grades in UROP 1100) OR (a passing grade in UROP 1100 and UROP 2100)', '', '2026-08-11 11:43:56.733938');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (113, 'UROP4100', 'Undergraduate Research Opportunities Series 4', '1 Credit(s)', 'This is the final course of the four-course Undergraduate Research Opportunities Program (UROP) series, which allows students to engage in faculty-led research projects that can span up to four terms. Successful completion of UROP 3100 or UROP 3200 is a prerequisite for proceeding to UROP 4100, which can involve either the same or a different project led by the same faculty supervisor. Progression from UROP 1100 to UROP 4100, regardless of whether it is on the same or a different research project, must be under the guidance of the same faculty supervisor. In case of a change in faculty supervisor, students need to restart from UROP 1100. Approval by faculty supervisor(s) is required. Students are required to submit a written report upon completion of the course. Graded P or F.', 'UROP 3100 OR UROP 3200', '', '2026-08-11 11:43:56.738326');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (123, 'AISC1000', 'Foundations of AI Literacy: Human-AI Orchestration', '3 Credit(s)', 'Foundations of AI Literacy: Human-AI Orchestration is a course for first-year undergraduate students that equips them with the cognitive, technical, and ethical foundations to operate effectively in human-AI ecosystems. The course develops AI literacy as orchestration: understanding AI systems from tools to agents; understanding human cognition (attention, memory, bias, metacognition); and designing workflows that treat AI as a collaborator rather than a shortcut. Students’ progress from individual AI collaboration to team orchestration and then to organizational and societal governance, equity, and human flourishing, using interactive activities and real-world cases to support longitudinal integration rather than isolated topic coverage.', '', 'Self-paced online delivery / Blended learning', '2026-08-11 15:29:18.689048');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (124, 'AISC2500', 'Special Topics (I)', '1-4 Credit(s)', 'This special topics course will help students to gain a better understanding on the topics related to their interdisciplinary studies. A range of professional activities are eligible for study, including seminars/ lectures, professional activities/ meetings, journal readings or structured readings. May be repeated for credits if different topics are taken. May be graded by letter, P/F or DI/PA/F for different offerings.', 'IDPO 2500', '', '2026-08-11 11:58:51.522989');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (125, 'AISC2800', 'AIS Cooperative Education Program', '3 Credit(s)', 'This course is intended to enhance AIS students’ career readiness by combining classroom-based education with practical work experience. By taking any two standalone career development programs offered by the Career Center or those as recognized by the School, students are required to apply the skills and knowledge learnt in a full-time coop work experience for a single employer for at least 4 months. Approval from the course coordinator is required for enrollment in the course. For AIS Year 2 students or above only. Graded P, PP or F.', '', 'Experiential learning', '2026-08-11 14:44:34.080923');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (126, 'AISC3500', 'Special Topics (II)', '1-4 Credit(s)', 'This special topics course will help students to gain a more in-depth knowledge and to have a better understanding on the topics related to their interdisciplinary studies. A range of professional activities are eligible for study, including seminars/ lectures, professional activities/ meetings, journal readings or structured readings. May be repeated for credits if different topics are taken. May be graded by letter, P/F or DI/PA/F for different offerings.', 'IDPO 3500', '', '2026-08-11 11:58:51.530399');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (127, 'AISC4500', 'Special Topics (III)', '1-4 Credit(s)', 'This special topics course will help students to gain a more in-depth knowledge and to have a better understanding on the topics related to their interdisciplinary studies. A range of professional activities are eligible for study, including seminars/ lectures, professional activities/ meetings, journal readings or structured readings. May be repeated for credits if different topics are taken. May be graded by letter, P/F or DI/PA/F for different offerings.', 'IDPO 4500', '', '2026-08-11 11:58:51.536005');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (128, 'AISC4950', 'Interdisciplinary Special Project', '0-4 Credit(s)', 'Special projects on selected interdisciplinary topics supervised by one or a group of faculty members. May be repeated for credits if different topics are taken. Enrollment may require approval of the course instructor. For DDP, RMBI, EVMT, and IIM students or those with approval from instructor for enrolling in the course. May be graded by letter, P/F or DI/PA/F for different offerings.', 'IDPO 4950', '', '2026-08-11 14:44:34.087979');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (129, 'BIEN1010', 'Introduction to Biomedical Engineering', '3 Credit(s)', 'This course is designed as an introductory course in biomedical engineering. The aim of this course is to present some of the basic science and human physiology knowledge used by biomedical engineers and illustrates the first steps in applying this knowledge to solve problems in human medicine. The second goal of this course is to link knowledge of basic science and engineering to fields of specialization and current research. This course also introduces the sub-specialties in biomedical engineering and through real-life examples to emphasize the types of problems biomedical engineers solve.', '', '', '2026-08-11 11:59:38.535593');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (130, 'BIEN1600', 'Introduction to Bioengineering', '3 Credit(s)', 'This course provides an overview and lays the foundation for the bioengineering discipline. Students will delve into diverse topics such as biomaterials, biosensors, tissue engineering, and bioimaging. Through lectures with case studies, students will analyze the design and development of technological advances in healthcare and life science, including biomolecular tools, medical devices, and regenerative medicine applications.', '', '', '2026-08-11 11:59:38.543397');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (131, 'BIEN1610', 'Engineering Life: Synthetic Biology and Innovations for Human Health', '3 Credit(s)', 'This course offers an introductory overview of synthetic biology and its innovations for human health, encompassing both technical and business aspects, tailored for undergraduate students. It is suitable for those intrigued by the cutting-edge technologies driving the emerging biopharmaceutical industry and interested in the transformation of synthetic biology. This course begins by exploring the timeline of biotechnology''s emergence and development, delving into the discovery of groundbreaking pharmaceuticals in human history and the evolution of synthetic biology. It provides students with a framework for critical thinking while exploring the current landscape of synthetic biology. The course covers key milestones, explains foundational scientific concepts, and highlights the transformative impact of synthetic biology on human health. Through case studies, students gain insights into the opportunities and limitations in current and future technological advancements. Additionally, the course features guest lectures by experts from the industry and investment sector, offering valuable perspectives on course-related topics.', 'CENG 1600', '', '2026-08-11 15:30:00.821589');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (132, 'BIEN1620', 'Revolutionizing Health: Biomedical Innovations in Everyday Life', '3 Credit(s)', 'This course offers a comprehensive introduction to biomedical engineering, equipping students with foundational knowledge in basic sciences and human physiology. Key topics include bioinstrumentation, where students explore techniques for measuring physiological parameters such as temperature, blood pressure, and blood composition. The bioimaging segment covers advanced imaging modalities like MRI, CT, and ultrasound, which are vital for diagnostic applications. In biomolecular engineering, students will learn about the working principles and development history of vaccines, antibodies, innovative drug delivery systems, and various gene editing technologies. Additionally, the course also introduces bioinformatics, focusing on genomic sequencing and its significance in modern healthcare. Throughout the course, an engineering and user-centered design approach will guide students, emphasizing the importance of creating solutions that prioritize patient needs and real-world applications. This blend of theory and practical experience prepares students to tackle challenges and fosters an appreciation for the evolving field of biomedical engineering.', 'BIEN 1010', '', '2026-08-11 15:30:00.828707');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (133, 'BIEN2310', 'Modeling for Chemical and Biological Engineering', '3 Credit(s)', 'Modeling of physical, chemical and biological processes. Balance Equations. Dimensional and scaling analysis. Analytical and numerical solutions to initial and boundary value problems. Use of computer tools for engineering calculations. This course uses examples in the Bioengineering discipline. For BIEN students only.', 'MATH 1014 OR MATH 1020 OR MATH 1024', '[BLD] Blended learning', '2026-08-11 11:59:38.555516');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (134, 'BIEN2410', 'Cellular and Systems Physiology for Engineers', '3 Credit(s)', 'Essential cellular and systems physiology for engineers. Hierarchical organization of a complex organism: from organelles to organ systems. Cellular physiology, neurophysiology, vision, muscle and movement, and the cardiovascular system.', 'LIFS 1901 OR Level 3 or above in HKDSE 1x Biology', '', '2026-08-11 11:59:38.559039');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (135, 'BIEN2610', 'Chemical Biology for Engineers', '3 Credit(s)', 'A concise introduction of biochemistry, cell biology, and pharmacology to engineers. Molecular and supramolecular building blocks of biological systems. Analysis and engineering of biological systems by chemical principles. Introduction to transcriptomics, proteomics and metabolomics.', '(CHEM 1010 (prior to 2022-23) OR CHEM 1012) AND (LIFS 1901 OR (Level 3 or above in HKDSE 1x Biology))', '', '2026-08-11 11:59:38.562460');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (136, 'BIEN2990', 'Academic and Professional Development I', '1 Credit(s)', 'For students in the Bioengineering major. This course is designed to provide academic advising to students, to enhance their understanding of the bioengineering field, to encourage them to pursue co-curricular learning opportunities available to them, and to improve their communication skills. Students are required to attend discussion sessions with advisors and fellow students and selected workshops and seminars. Graded P or F.', '', '', '2026-08-11 11:59:38.565745');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (137, 'BIEN3250', 'Rate and Transport Processes in Biological Systems', '3 Credit(s)', 'Analysis of transport phenomena and rate processes, including fluid flow, energy and mass transport, and reactions in biological systems. Applications in human physiology, bioreactors, medical devices, drug delivery, and biosensors. Mathematical and computational tools for solving problems and designing applications involving such processes.', 'CENG 2320 AND (PHYS 1112 OR PHYS 1312)', '', '2026-08-11 11:59:38.569175');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (138, 'BIEN3300', 'Data Science for Molecular Engineering', '3 Credit(s)', 'This course is an introductory course on the application of machine learning methods in molecular engineering problems. It covers fundamental data processing and machine learning methods to analyze data in chemistry and biology such as molecular similarity calculation and property prediction.', 'CENG 3300, COMP 1023', '', '2026-08-11 15:30:00.840307');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (139, 'BIEN3310', 'Data Science for Neural Engineering', '3 Credit(s)', 'This is an introductory course on data science and its applications in neural engineering. The course introduces the fundamentals of data science, principles of neuroscience, and the technologies and implementations of neural engineering. The topics include probability, random variables, statistical detection and estimation, random process, structure and function of the nervous system, encoding and decoding, population coding, neural network, plasticity and learning, neural interfaces and rehabilitation.', 'ELEC 3810 AND (CENG 2310 OR ELEC 2600 OR LIFS 3150 OR MATH 2411) AND (BIEN 3300 OR CENG 3300 OR MATH 2111)', '', '2026-08-11 15:30:00.843612');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (140, 'BIEN3320', 'Data Science for Biology and Medicine', '3 Credit(s)', 'This is an introductory course for the application of data science in biology and medicine. The course will introduce the fundamental principles on data science, the technologies and implementations of data mining, as well as the modeling of several practical questions in biomedicine. The topics include introduction to biomedical data, data visualization, regression methods and classification methods.', '(COMP 1021 OR COMP 1023) AND (level 3 or above in HKDSE 1x Biology OR LIFS 1901)', '', '2026-08-11 15:30:00.848822');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (141, 'BIEN3410', 'Bioimaging and Image Analysis', '3 Credit(s)', 'This course introduces various bioimaging methods and their data analysis approaches, including optical coherence tomography, fluorescence microscopy, nonlinear microscopy, super-resolution microscopy, ptychographic microscopy, and photoacoustic tomography. Students will be able to understand, design, and evaluate those imaging techniques. This course requires basic knowledge of linear algebra, calculus, and geometry.', '', '', '2026-08-11 11:59:38.582779');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (142, 'BIEN3420', 'Biosensors and Bioinstrumentation for Healthcare', '3 Credit(s)', 'This course will cover the fundamental principles in bioinstrumentation and biosensing devices, and practical examples of such in biomedical applications. Concepts in bioelectric and biochemical signals, their measurement and transduction will be introduced.', 'BIEN 1600', '', '2026-08-11 15:30:00.853624');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (143, 'BIEN3910', 'Bioengineering Laboratory', '4 Credit(s)', 'This course provides hands-on experience with molecular biotechnology, biomolecular engineering, biosensors, biomedical devices, and bioanalytical techniques. Laboratory experiments including cell culture, genetic engineering techniques, bioanalytical methods, biosensors and biomedical devices, with additional emphasis on data analysis. For students of the CBE department only. May be graded PP.', 'BIEN 2410 AND BIEN 2610', '', '2026-08-11 15:30:00.857141');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (144, 'BIEN4000', 'Special Topics in Bioengineering', '1-4 Credit(s)', 'Selected topics of current interest not covered by existing courses. May be graded by letter, P/F, or DI/PA/F for different offerings.', '', '', '2026-08-11 11:59:38.594770');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (145, 'BIEN4110', 'Regulatory Affairs in the Healthcare Industry', '3 Credit(s)', 'This course aims to introduce basic concepts of regulatory science, while familiarizing students with product development, manufacturing, medical and engineering operations, and quality control / quality assurance processes in the pharmaceutical and medical device industry. Students will also be introduced to the associated regulatory requirements, with an emphasis on Hong Kong, Great Bay Area, China and beyond, in topics such as Good Manufacturing Practice (GMP), pharmaceutical product registration, pharmacovigilance, and clinical trials.', 'BIEN 4000C', '', '2026-08-11 11:59:38.598432');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (146, 'BIEN4910', 'Independent Study', '1-4 Credit(s)', 'Independent studies or projects under the directed guidance of a faculty member on a bioengineering topic. Enrollment in the course requires prior approval of the course instructor, and credits assigned depend on the workload. Students may repeat the course if different topics are taken. The course may be grade by letter or P/F subject to different offerings. May be graded PP.', '', '', '2026-08-11 14:45:23.033514');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (147, 'BIEN4920', 'Bioengineering Capstone Design', '6 Credit(s)', 'A final-year project course offers practice of bioengineering design through a group design project chosen to integrate materials covered in the curriculum. Credit load may be spread over a year. May be graded PP. For students in the Bioengineering major only.', 'BIEN 3910', '', '2026-08-11 15:30:00.865774');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (148, 'BIEN4930', 'Bioengineering Thesis Research', '6 Credit(s)', 'A final-year project course offers an opportunity to conduct individual bioengineering research under the direct supervision of a faculty member, which leads to a Bachelor''s thesis. Credit load may be spread over a year. May be graded PP. For students in the Bioengineering major with approval from the department only.', 'BIEN 3910 AND (CENG 4980 OR UROP 2100)', '', '2026-08-11 15:30:00.869412');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (149, 'BIEN4940', 'Bioengineering Industrial Project', '6 Credit(s)', 'This course is intended to provide final-year bioengineering students with practical hands-on training in the form of a full-time or part-time internship or co-op program in a bioengineering company. Credit load may be spread over a year. May be graded PP. For students in the Bioengineering major with approval from the department only.', 'BIEN 3910', '', '2026-08-11 15:30:00.873031');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (150, 'BIEN4990', 'Academic and Professional Development II', '1 Credit(s)', 'For final-year Bioengineering students. This course is designed to prepare students for the workplace, to instill in them a sense of professional responsibility, and to enhance their career management skills. Students are required to attend selected workshops and seminars by practicing bioengineers. Graded P or F.', 'BIEN 2990', '', '2026-08-11 11:59:38.617441');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (151, 'CHEM1002', 'Introduction to Chemistry of Cosmetics', '3 Credit(s)', 'This course concentrates on the basic scientific principles in cosmetic science. Various topics with emphasis on molecular approach related to cosmetic products'' formulation and proper uses of cosmetic products will be covered. Major topics include definition of cosmetics, make-up cosmetics, skin-care cosmetics, hair-care cosmetics, vehicles of cosmetic products, surfactants, colorants, alpha hydroxyl acids & beta hydroxyl acids, anti-oxidants and sunscreens, skin-whitening agents, hydrating substances / moisturizers, antiperspirants & deodorants and botanical ingredients.', '', '', '2026-08-11 12:01:07.881228');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (152, 'CHEM1004', 'Chemistry in Everyday Life', '3 Credit(s)', 'This common core course takes students on a chemical journey, through which they will learn what is chemistry and how chemistry connects with our daily life and sustainable development. Students will engage in a self-guided study project; they will also learn chemical concepts through many real-life case studies.', 'Level 3 or above in HKDSE Chemistry, a passing grade in GCE-A/AS Level Chemistry, CHEM 1008, CHEM 1010 (prior to 2022-23), CHEM 1011, CHEM 1012, any CHEM courses at or above 2000-level', '', '2026-08-11 15:35:15.578986');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (153, 'CHEM1008', 'Introductory Chemistry', '3 Credit(s)', 'This course targets science or engineering students with very little to no chemistry background. It provides a general introduction to basic principles of chemistry. Key topics include state of matters, atoms and elements, molecules and compounds, atomic structures and periodicity, molecular structures, quantities in chemical reactions, bonding theories, acids and bases, and solution chemistry.', 'Level 3 or above in HKDSE 1/2x Chemistry OR HKDSE 1x Chemistry, any CHEM courses at or above 1004-level, CORE 1120', '', '2026-08-11 15:35:15.658208');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (154, 'CHEM1011', 'General Chemistry A: Reactions, Thermodynamics, and Reaction Kinetics', '3 Credit(s)', 'This course targets at students who have acquired prior knowledge in fundamental Chemistry in high school. Key topics include stoichiometry, chemical energy, properties of aqueous solutions, acids and bases, thermodynamics and equilibrium, reaction kinetics, and electrochemistry.', 'CHEM 1030, Level 3 or above in HKDSE 1/2x OR level 3 or above in HKDSE 1x Chemistry OR CHEM 1004 OR CHEM 1008', '', '2026-08-11 12:01:07.911642');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (155, 'CHEM1012', 'General Chemistry B: Atomic Structure, Molecules, and Bonding Theories', '3 Credit(s)', 'This course targets at students who have acquired prior knowledge in fundamental Chemistry in high school. Key topics include atomic structure and periodicity, molecules, bonding theories, and properties of gases, liquids and solids.', 'CHEM 1020, Level 3 or above in HKDSE 1/2x OR level 3 or above in HKDSE 1x Chemistry OR CHEM 1004 OR CHEM 1008, CHEM 1010 (prior to 2022-23)', '', '2026-08-11 15:35:15.683587');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (156, 'CHEM1051', 'Laboratory for General Chemistry A', '1 Credit(s)', 'This course is the laboratory class designed for students who are enrolled in CHEM 1011. With laboratory experience acquired in this course, students will be able to relate the physical and chemical principles and theories learned in the corresponding lecture course, perform basic chemical laboratory techniques, and develop their data analyzing skills. Graded P or F.', 'CHEM 1055, CHEM 1011', '', '2026-08-11 12:01:07.930059');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (157, 'CHEM1052', 'Laboratory for General Chemistry B', '1 Credit(s)', 'This course is the laboratory class designed for students who are enrolled in CHEM 1012. With laboratory experience acquired in this course, students will be able to relate the physical and chemical principles and theories learned in the corresponding lecture course, perform basic chemical laboratory techniques, and develop their data analyzing skills. Graded P or F.', 'CHEM 1050, CHEM 1012', '', '2026-08-11 12:01:07.934546');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (158, 'CHEM2110', 'Organic Chemistry I', '3 Credit(s)', 'This is the first part of the organic chemistry course series designed for students taking a major/minor in chemistry/life science under the four-year degree. Topics covered include: structure and bonding; regio-, geometric, and stereoisomerism; polar and radical reactions of alkenes and alkynes; substitution and elimination reactions; synthesis and reactions of alcohols and epoxides.', 'CHEM 1012, CHEM 2111', '', '2026-08-11 12:01:07.939667');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (159, 'CHEM2111', 'Fundamentals of Organic Chemistry', '3 Credit(s)', 'Various classes of organic compounds, emphasizing organic chemical reactions and mechanisms of major functionalities and their importance in the area of biological chemistry. For non-CHEM students in programs that designate this course as required course/specified elective only.', 'CHEM 1010 (prior to 2022-23) OR CHEM 1011 OR CHEM 1012, CHEM 2110', '', '2026-08-11 12:01:07.947422');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (160, 'CHEM2155', 'Fundamental Organic Chemistry Laboratory', '1 Credit(s)', 'This is the laboratory course designed for non-CHEM students who enrolled in CHEM 2110 or CHEM 2111. Students will perform a series of organic experiments related to the theories learnt in the related lecture courses.', 'CHEM 1051 OR CHEM 1052, CHEM 2110 OR CHEM 2111, CHEM 2550', '', '2026-08-11 15:35:15.724516');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (161, 'CHEM2210', 'Inorganic Chemistry I', '3 Credit(s)', 'This course is designed for students who have taken CHEM 1011 under the four-year degree. Key topics include atomic structure, molecular structure and bonding, structures of simple solids, physical techniques in inorganic chemistry, molecular symmetry, acids and bases, introduction to coordination chemistry, electronic structures and spectra of coordination compounds.', 'CHEM 1012', '', '2026-08-11 15:35:15.740544');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (162, 'CHEM2310', 'Fundamentals of Analytical Chemistry', '3 Credit(s)', 'Fundamental and practical aspects of chemical analysis, including titrimetric, electrical and spectroscopic methods, analytical separations by GLC and HPLC.', 'CHEM 1012, CHEM 2311', '', '2026-08-11 15:35:15.789816');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (163, 'CHEM2311', 'Analytical Chemistry', '3 Credit(s)', 'Fundamental and practical aspects of chemical analysis, including titrimetric, electrical, optical and mass spectroscopic methods, analytical separations by chromatography.', 'CHEM 1010 (prior to 2022-23) OR CHEM 1011 OR CHEM 1012, CHEM 2310', '', '2026-08-11 15:35:15.814849');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (164, 'CHEM2355', 'Fundamental Analytical Chemistry Laboratory', '1 Credit(s)', 'This is the laboratory course corresponding to the lecture courses of CHEM 2310 and CHEM 2311. Experiments covered in this course will be closely connected with the topics covered in the lecture courses, including calibration principle, and some basic optical and chromatographic instrumental techniques.', 'CHEM 1051 OR CHEM 1052, CHEM 2310 OR CHEM 2311, CHEM 2350 (prior to 2022-23)', '', '2026-08-11 15:35:15.838273');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (165, 'CHEM2401', 'Physical Principles for Biomolecular Science', '4 Credit(s)', 'This course introduces the physical principles that are essential to understanding important biological systems, utilizing techniques from chemistry, physics, and biology. Topics of study include enzyme dynamics, nucleic acid structures, metalloprotein active sites, and protein-ligand interactions.', 'MATH 1005 OR MATH 1006 OR MATH 1013 OR MATH 1020 OR MATH 1023', '', '2026-08-11 12:01:08.014026');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (166, 'CHEM2409', 'Mathematical Methods for Physical Chemistry', '4 Credit(s)', 'This course covers mathematical and numerical methods for solving typical complex problems found in undergraduate-level physical chemistry courses. Topics include single variable integration, multivariate calculus, series and limits, ordinary and partial differential equations, determinants, matrices, vectors, and probability and statistics.', 'MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1023', '', '2026-08-11 15:35:16.071441');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (167, 'CHEM2410', 'Physical Chemistry I: Equilibrium Thermodynamics and Statistical Mechanics', '3 Credit(s)', 'The course consists of two parts. First part teaches the equilibrium thermodynamics with applications to various problems in phase equilibrium, chemical and electrochemical equilibrium. Second part teaches the equilibrium statistical thermodynamics covering statistical ensembles and their relations to thermodynamics functions.', 'CHEM 1011 AND (CHEM 2409 OR MATH 2351)', '', '2026-08-11 15:35:16.080665');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (168, 'CHEM2450', 'Physical Chemistry Laboratory', '1 Credit(s)', 'This is the laboratory course corresponding to the lecture course CHEM 2410.', 'CHEM 1011 AND (CHEM 2409 OR MATH 2351), CHEM 2410, AMAT 2450', '', '2026-08-11 15:35:16.094091');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (169, 'CHEM2550', 'Synthetic Chemistry Laboratory I', '2 Credit(s)', 'This is the laboratory course designed for students who enrolled in CHEM 2110 Organic Chemistry I and CHEM 2210 Inorganic Chemistry I. It includes a series of organic and inorganic experiments related to the theory learnt in the lecture courses.', 'CHEM 1052, CHEM 2110 AND CHEM 2210, CHEM 2155', '', '2026-08-11 15:35:16.112043');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (170, 'CHEM2555', 'Molecular Characterization Chemistry Laboratory I', '2 Credit(s)', 'This is the laboratory course corresponding to the lectures of CHEM 2410 Physical Chemistry I. Topics of experiments covered in this course are closely connected with the topics covered in the lecture courses.', 'CHEM 1052 AND (CHEM 2409 OR MATH 2351), CHEM 2310 AND CHEM 2410, CHEM 2350 (prior to 2022-23)', '', '2026-08-11 15:35:16.127826');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (171, 'CHEM3010', 'Great Ideas in Chemistry', '3 Credit(s)', 'The course covers many major advances, historical developments and contemporary applications of critical concepts in Chemistry. Unlike other Chemistry courses, it focuses on the background to our knowledge, on what experimental evidence our current theories are based, and how old ones were overturned or modified.', 'Any CHEM course at or above 1000-level or CORE 1120', '', '2026-08-11 15:35:16.139542');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (172, 'CHEM3020', 'Chemistry in the Mass Media', '3 Credit(s)', 'This experiential learning course aims to teach students to understand and apply the scientific method through highly interactive lectures and a case study project based on a chosen social or daily life Chemistry topic from the mass media.', '(CHEM 1010 (prior to 2022-23) OR CHEM 1011 OR CHEM 1012) AND CHEM 1052', '', '2026-08-11 15:35:16.152259');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (173, 'CHEM3030', 'Introduction to AI for Chemistry', '4 Credit(s)', 'This is a science-popularization course that introduces how AI is transforming chemistry, from predicting molecular properties to designing new drugs and materials.', 'CHEM 1012 AND (MATH 1005 OR MATH 1006 OR MATH1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023)', '', '2026-08-11 12:01:08.085720');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (174, 'CHEM3120', 'Organic Chemistry II', '3 Credit(s)', 'Continuation of CHEM 2110. Dienes, resonance and aromaticity; electrophilic aromatic substitution and nucleophilic aromatic substitution; benzylic and allylic reactivity; the chemistry of carbonyl compounds and carboxylic acid derivatives.', 'CHEM 2110', '', '2026-08-11 15:35:16.173678');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (175, 'CHEM3220', 'Inorganic Chemistry II', '3 Credit(s)', 'Mechanism of inorganic reactions, organometallic and bioinorganic chemistry, catalysis.', 'CHEM 2210', '', '2026-08-11 12:01:08.113195');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (176, 'CHEM3320', 'Instrumental Analysis', '3 Credit(s)', 'Continuation of CHEM 2310. Topics covered include electrochemistry, mass spectrometry and separation sciences.', 'CHEM 2310', '', '2026-08-11 12:01:08.129295');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (177, 'CHEM3420', 'Physical Chemistry II', '3 Credit(s)', 'Basic quantum theory, atomic and molecular structure, equilibrium statistical thermodynamics.', 'CHEM 2410', '', '2026-08-11 12:01:08.138357');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (178, 'CHEM3550', 'Synthetic Chemistry Laboratory II', '2 Credit(s)', 'This is the laboratory course corresponding to the lecture courses CHEM 3120 and CHEM 3220. Topics of experiments covered in the laboratory course will be related to those taught in the lecture courses.', 'CHEM 2550, CHEM 3120 AND CHEM 3220, CHEM 2155', '', '2026-08-11 15:35:16.227367');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (179, 'CHEM3555', 'Molecular Characterization Chemistry Laboratory II', '2 Credit(s)', 'This is the laboratory course corresponding to the lecture courses CHEM 3320 and CHEM 3420.', 'CHEM 2555, CHEM 3320 AND CHEM 3420', '', '2026-08-11 12:01:08.154713');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (180, 'CHEM3610', 'Chemistry Internship', '2-3 Credit(s)', 'This course provides students with an opportunity to gain work experience in the chemistry field. Students will undertake training and supervised internships in our collaborating organizations/units.', 'CHEM 3550 OR CHEM 3555', '', '2026-08-11 15:35:16.242448');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (181, 'CHEM4110', 'Structural Elucidation in Organic Chemistry', '3 Credit(s)', 'Use of modern ID- and 2D-NMR, IR, and Mass Spectrometric techniques for structure determination of organic molecules; theory of each technique with emphasis on development of problem-solving techniques.', 'CHEM 3120', '', '2026-08-11 15:35:16.261376');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (182, 'CHEM4120', 'Biomolecular Chemistry', '3 Credit(s)', 'This course will introduce the fundamental chemical principles underlying the structure, properties, and functions of biologically important molecules.', 'CHEM 2110 OR CHEM 2111', '', '2026-08-11 12:01:08.204643');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (183, 'CHEM4130', 'Medicinal Chemistry', '3 Credit(s)', 'This course will introduce the chemistry principles underlying the drug-target interaction and the development of drugs. One of its major topics is the molecular basis of the interaction of medicinal compounds with various biomolecules.', 'CHEM 3120', '', '2026-08-11 15:35:16.345009');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (184, 'CHEM4140', 'Intermediate Organic Chemistry', '3 Credit(s)', 'Provides further training in the multistep organic synthesis of natural and unnatural products, and will focus on retrosynthetic analysis, control of stereochemistry, carbonyl group chemistry, and pericyclic reactions.', 'CHEM 3120', '', '2026-08-11 15:35:16.355577');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (185, 'CHEM4150', 'Biomolecular Synthesis Laboratory', '1 Credit(s)', 'This course provides hands-on experience for students in the biomolecular chemistry option. It focuses on synthesis of molecules of biological relevance, such as small-molecule drugs, peptides, and DNA.', 'CHEM 3550, CHEM 4155', '', '2026-08-11 15:35:16.362072');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (186, 'CHEM4155', 'Biomolecular Characterization Laboratory', '1 Credit(s)', 'This course provides hands-on experience for students in the biomolecular chemistry option.', 'CHEM 3555', '', '2026-08-11 12:01:08.281166');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (187, 'CHEM4160', 'Cheminformatics', '3 Credit(s)', 'Basics of Chemometrics; Database mining (CSD and PDB); Multivariate data sets, statistics and data reduction; Data analysis and visualization; Molecular representation and chemical descriptors.', '(CHEM 2110 OR CHEM 2111) AND (CHEM 2409 OR MATH 2351 OR DASC 2010)', '', '2026-08-11 15:35:16.372503');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (188, 'CHEM4210', 'Solid State Chemistry', '3 Credit(s)', 'Structure and bonding in solids; metals, semiconductors and dielectrics; crystal chemistry of ceramics, silicate minerals and zeolites.', 'CHEM 3220', '', '2026-08-11 15:35:16.407738');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (189, 'CHEM4220', 'Materials Chemistry', '3 Credit(s)', 'An introduction of crystalline solids, crystal structures, materials synthesis and characterization techniques, synthesis of functional inorganic materials and nanomaterials.', 'CHEM 3220', '', '2026-08-11 15:35:16.428977');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (190, 'CHEM4230', 'Materials Characterization Method', '3 Credit(s)', 'This course will introduce a selected series of materials characterization methods with an emphasis on methods of nanomaterials.', 'CHEM 2310 AND CHEM 2410', '', '2026-08-11 15:35:16.475415');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (191, 'CHEM4240', 'Intermediate Inorganic Chemistry', '3 Credit(s)', 'Selected advanced topics in inorganic chemistry including spectroscopy, solid state chemistry, bioinorganic chemistry and catalysis.', 'CHEM 3220', '', '2026-08-11 12:01:08.348834');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (192, 'CHEM4250', 'Materials Preparation Laboratory', '1 Credit(s)', 'A laboratory course for students to gain hands-on experiences in the preparation of modern materials.', 'CHEM 3550', '', '2026-08-11 15:35:16.494277');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (193, 'CHEM4255', 'Materials Characterization Laboratory', '1 Credit(s)', 'A laboratory course for students to gain hands-on experiences in the characterization of modern materials.', 'CHEM 3555, CHEM 4250', '', '2026-08-11 15:35:16.511497');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (194, 'CHEM4310', 'Environmental Chemistry', '3 Credit(s)', 'Chemical phenomena in the hydrosphere, lithosphere and atmosphere; their interaction with the biosphere; origin and treatment of pollutants and environmental analysis.', 'CHEM 2310 OR CHEM 2311', '', '2026-08-11 15:35:16.523081');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (195, 'CHEM4320', 'Environmental Analytical Chemistry', '3 Credit(s)', 'Topics covered include fundamentals of sampling issues, sample pretreatment techniques, water Analysis of major and trace constituents; determination of soil pollutants.', 'CHEM 2310 OR CHEM 2311', '', '2026-08-11 15:35:16.528917');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (196, 'CHEM4330', 'Separation Science', '3 Credit(s)', 'This course aims to provide an in-depth understanding of the working principles in separating substances by chemical and physical techniques.', 'CHEM 2310 OR CHEM 2311', '', '2026-08-11 15:35:16.540749');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (197, 'CHEM4340', 'Bioanalytical Techniques', '3 Credit(s)', 'Topics covered include fundamentals of optical microscopic techniques, protein analysis, enzymatic bioassays; DNA techniques and biomicrofluidic techniques.', 'CHEM 2310 OR CHEM 2311', '', '2026-08-11 15:35:16.558441');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (198, 'CHEM4350', 'Environmental Chemistry Laboratory', '1 Credit(s)', 'This is a laboratory course for students to gain hands-on experience in collecting and handling environmental samples.', '(CHEM 2310 OR CHEM 2311) AND (CHEM 2555 OR CHEM 2355)', '', '2026-08-11 15:35:16.573800');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (199, 'CHEM4355', 'Instrumental Analytical Chemistry Laboratory', '1 Credit(s)', 'A laboratory course for students to gain hands-on experiences in operation of the modern instruments.', '(CHEM 2310 OR CHEM 2311) AND (CHEM 2555 OR CHEM 2355)', '', '2026-08-11 15:35:16.591583');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (200, 'CHEM4410', 'Physical Chemistry in Biological Applications', '3 Credit(s)', 'This course covers the applications of physical chemistry in biological science.', 'CHEM 3420', '', '2026-08-11 15:35:16.603739');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (201, 'CHEM4420', 'Statistical Machine Learning Methods for Chemical Data Analysis', '3 Credit(s)', 'The basic knowledge of probability and statistics, chemical data preparation and visualization; numerical methods for chemical data analysis.', 'CHEM 2409 OR DASC 2010', '', '2026-08-11 12:01:08.435360');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (202, 'CHEM4430', 'Symmetry in Chemistry and Spectroscopy', '3 Credit(s)', 'Symmetry principle and group theory, molecular spectroscopy, advanced topics in molecular orbital theory and bonding, chemical kinetics.', 'CHEM 2110 AND CHEM 2210 AND CHEM 2410', '', '2026-08-11 15:35:16.612466');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (203, 'CHEM4550', 'Advanced Synthetic Laboratory', '1 Credit(s)', 'This course provides hands-on experience for students in the pure chemistry option.', 'CHEM 3550', '', '2026-08-11 15:35:16.652931');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (204, 'CHEM4555', 'Advanced Molecular Characterization Laboratory', '1 Credit(s)', 'This course is designed for chemistry major students who are enrolling in Pure Chemistry option.', 'CHEM 3555', '', '2026-08-11 15:35:16.657086');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (205, 'CHEM4620', 'Organometallic Chemistry', '3 Credit(s)', 'Bonding, structure and reactivity of organometallic compounds, applications to catalytic processes and organic synthesis.', 'CHEM 3220', '', '2026-08-11 12:01:08.466932');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (206, 'CHEM4640', 'Chemistry for Advanced Solar Cell Technologies', '3 Credit(s)', 'Solar Cells are considered as one of the most promising renewable energy technologies.', '(for Science students) CHEM 2110 AND CHEM 2410; (for Engineering students) CHEM 2111', '', '2026-08-11 15:35:16.672496');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (207, 'CHEM4680', 'Undergraduate Research', '3 Credit(s)', 'Students do original research in accordance with their ability and background, and under the supervision of a faculty.', 'CHEM 2550', '', '2026-08-11 15:35:16.709378');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (208, 'CHEM4688', 'Undergraduate Thesis', '3 Credit(s)', 'Students do original research in accordance with their ability and background and under the supervision of a faculty.', 'CHEM 4680', '', '2026-08-11 15:35:16.737015');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (209, 'CHEM4689', 'Capstone Project', '3 Credit(s)', 'Under the supervision of a faculty member, students will complete a capstone project which requires the integration of the chemical knowledge learnt from their previous courses.', 'CHEM 3550 AND CHEM 3555, CHEM 4691', '', '2026-08-11 15:35:16.744505');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (210, 'CHEM4691', 'Capstone Research I', '3 Credit(s)', 'Students will carry out a research project in one of the Chemistry research laboratories under the supervision of a faculty member.', 'CHEM 3550 AND CHEM 3555, CHEM 4689', '', '2026-08-11 15:35:16.757902');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (211, 'CHEM4692', 'Capstone Research II', '3 Credit(s)', 'Continuation of research project started in CHEM 4691 and to be conducted under the supervision of a faculty member.', 'CHEM 4691', '', '2026-08-11 15:35:16.778148');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (212, 'CIVL1000', 'Academic and Professional Development for Civil and Environmental Engineering I', '0 Credit(s)', 'A compulsory, one year course for students of the Civil and Environmental Engineering Department only. This is the first course of the APD course series (CIVL1000/2000/3000/4000) for Year 1 students. This course is designed to provide academic advising to students and/or to develop students'' interpersonal skills in handling technical and non-technical issues in their professional careers. Students admitted via school-based admission are exempted from taking CIVL 1000. Graded P, PP or F.', '', 'Fall, Spring', '2026-08-11 15:31:46.518378');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (213, 'CIVL1010', 'Academic and Professional Development I', '0 Credit(s)', 'A compulsory, one year course for CIVL/CIEV/CIGBM students only. This course is designed to provide academic advising to students and/or to develop students'' interpersonal skills in handling technical and non-technical issues in their professional careers. Graded P, PP or F.', '', 'Fall, Spring', '2026-08-11 15:31:46.526293');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (214, 'CIVL1100', 'Discovering Civil and Environmental Engineering', '3 Credit(s)', 'A general overview of civil and environmental engineering, infrastructure development and engineering ethics is provided. The course includes both lectures and laboratory sessions, where the laboratory sessions are primarily directed to students who require the development of feasible conceptual solutions for the analysis and design of the basic problems in structural, geotechnical and environmental engineering.', '', 'Fall, Spring', '2026-08-11 15:31:46.531787');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (215, 'CIVL1121', 'Introduction to Computation for Civil Engineers', '3 Credit(s)', 'This course aims to introduce Civil Engineering students with a basic understanding of the computation role in solving real-world Civil Engineering problems, and provide a broad overview of the computation for their engineering career. It will give students fundamental capabilities to write small programs that allow them to accomplish useful goals. The class will use the Python programming language.', 'COMP 1021, COMP 1022P (prior to 2025-26), COMP 1023', 'Fall, Spring', '2026-08-11 15:31:46.541022');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (216, 'CIVL1140', 'Environment and Society: Sustainable Development Goals and Carbon Neutrality', '3 Credit(s)', 'Introduction of up-to-date environmental issues in both local and global scales and elaboration of essential concepts in physical, chemical, biological and societal aspects will be provided for students to understand the issues related to sustainable development goals and carbon neutrality.', '', 'Fall, Spring', '2026-08-11 15:31:46.546092');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (217, 'CIVL1160', 'Civil Engineering and Modern Society', '3 Credit(s)', 'An introduction to civil engineering practice and infrastructure development, with an emphasis on Hong Kong projects. The basic principles and technology used in typical civil engineering works such as foundations, buildings, bridges, slopes and water supply systems will be covered.', 'CIVL 1100', 'Fall, Spring', '2026-08-11 15:31:46.549848');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (218, 'CIVL1161', 'Building the Future: Civil Engineering Challenges & Solutions', '3 Credit(s)', 'This course offers an exploration of civil engineering practices in Hong Kong, with a focus on the solutions engineers implement to address current infrastructure challenges. Students will develop an understanding of how advanced technology and sustainable practices are influencing the built environment.', 'CIVL 1160', 'Fall, Spring', '2026-08-11 15:31:46.553603');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (219, 'CIVL1180', 'Monitoring Changing Climate from Space', '3 Credit(s)', 'This course introduces the fundamental principles of satellite remote sensing and its role in monitoring our changing climate and environment. It covers the science underlying remote sensing, various remote sensing methods and technologies, observational evidence of climate change from space, and use of satellite data to advance science understanding.', '', 'Fall, Spring', '2026-08-11 15:31:46.559627');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (220, 'CIVL1190', 'Climate Change, Big History and Sustainability', '3 Credit(s)', 'Big History as an emerging interdisciplinary framework provides a long-term perspective on reconstructing the history from the big bang to the present. The course discusses climate change and how it relates to the sustainability of the planet’s environment, focusing on extreme weather events and collective learning.', 'CORE 1223, CIVL 1170 (prior to 2022-23), ENVR 1170', 'Fall, Spring', '2026-08-11 15:31:46.563083');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (221, 'CIVL1210', 'Fundamental of Green Buildings', '3 Credit(s)', 'This course dives into the fundamental elements of green building, strategies and techniques that optimize various perspectives of green buildings. Students will learn how to achieve energy efficiency and sustainability in building design and operation.', 'CIVL 2910, ENVR 2070', 'Fall, Spring', '2026-08-11 15:31:46.567097');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (296, 'EABU3000', 'Eurasian Leadership Development', '1 Credit(s)', 'The course aims to enhance students'' personal development, teamwork, communication skills, career readiness, leadership abilities, and global perspectives. It consists of three components: (1) Workshops and seminars that help students adapt to university and SBM life, offer academic advice, and provide a foundation for well-being. These sessions may also include training on professional interview skills and internship practices. (2) Mingle and munch events that create opportunities for students to build interpersonal, teamwork, and communication skills. (3) Industry sharing and company tours that foster interaction with the business community, provide exposure to global business, and help with career preparation. For EABU students only. Graded P or F.', 'For EABU students only.', 'Not specified', '2026-08-11 12:03:05.585625');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (297, 'EABU3040', 'Business and ESG Management for Eurasia and Emerging Markets', '3 Credit(s)', 'This course aims to provide a comprehensive understanding of the contextual factors in Eurasia and emerging market countries, focusing on the risks, challenges, and solutions for doing business in these regions. Students will study the key economic, financial, political, social, and cultural traits of these countries, learn about regional differences and explore how these variations influence business strategies and managerial decisions. Topics related to corruption, corporate governance, and ESG will also be addressed. For EABU students or students with consent from instructor.', 'For EABU students or students with consent from instructor.', 'Not specified', '2026-08-11 12:03:05.591645');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (298, 'EABU3050', 'Deal Making in Eurasia and Emerging Markets', '3 Credit(s)', 'This course introduces students to cross-border and cross-cultural business transactions in Eurasia and emerging markets. By analyzing case studies of various real business deals, the course offers a comprehensive overview of doing business in these regions. Students will have the opportunity to strategize as corporate decision makers through discussions, role plays, and presentations. The goal is to enhance students'' skills in deal structuring, financing, negotiating, and closing from a strategic management perspective. For EABU students or students with consent from instructor.', 'For EABU students or students with consent from instructor.', 'Not specified', '2026-08-11 12:03:05.595026');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (434, 'ENGG1050', 'Academic and Professional Development for Engineering + AI', '1 Credit(s)', 'This course is designed to provide academic advising to Engineering students enrolled in the extended major in artificial intelligence, to enhance their sense of identity and belonging, to familiarize them with various engineering disciplines and their connections with the emerging technologies of artificial intelligence. Activities include meetings with faculty advisors, senior students and alumni, seminars and workshops, and various community building activities. Graded P or F. For engineering students with extended AI major only.', 'For engineering students with extended AI major only.', 'Not specified', '2026-08-11 15:36:37.841188');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (435, 'ENGG1100', 'First Year Cornerstone Engineering Design Project Course', '3 Credit(s)', 'This project course is designed specifically for first year engineering students. This course aims at providing engineering students experiential learning experience through exposing students to knowledge and skills from different SENG disciplines before making decision on their majors. Students in this course will be divided into design teams. Each team will use the acquired knowledge and skills to design and build an engineering artifact, e.g. an airship. In order to offer the course at scale, the technical components will be offered online and students would be engaged in experiential learning through working on team projects. For First year Engineering students only.', 'For First year Engineering students only.', 'Not specified', '2026-08-11 15:36:37.845323');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (436, 'ENGG1200', 'Engineering Team Design Experience', '3 Credit(s)', 'The Engineering Team Design Experience course allows students to explore various areas of engineering in order to design and work towards a final road show demonstration before the end of the term. Students in this course will be divided into design teams with a common goal: construct their project artifact or virtual 3D model, taken from a wide range of engineering and design contexts. There will be three main aspects: engineering skills, design/creativity, and teamwork. Fundamental engineering skills will be introduced in different engineering fields, such as 3D modelling or hands-on prototyping skills, along with exposure to various kinds of advanced technology available. Some class sessions will focus on design thinking and creativity. They are key to creating practical and interesting products. Students will work together in teams to realize their common idea of their final roadshow project, to have a real-world experience working with a design team.', 'Not specified', 'Not specified', '2026-08-11 15:36:37.850062');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (437, 'ENGG1300', 'Design Thinking for Health Innovation', '3 Credit(s)', 'A project‐based, experiential course that exposes students to the design thinking process for health innovation to address the real‐world unmet needs in the society. The goal of this course is to develop students’ communication, interpersonal, teamwork, analytical, design and project management skills through a multi‐disciplinary, team‐based design experience. The design thinking process modules: empathize, define, ideate, prototype and test, will be introduced and the students will learn experientially by applying these process modules to solve the health unmet needs they observe in real life. The students are required to report their progress throughout the semester. At the end of the course, they will showcase their prototype in a roadshow and submit their project report and reflection on their design journey. It is a common core course for students from different schools who have no background in design thinking or are looking for practical experience in design thinking.', 'Not specified', 'Not specified', '2026-08-11 15:36:37.858686');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (438, 'ENGG1400', 'Designing Your Life for Engineering Students', '1 Credit(s)', 'Originated from Stanford University’s Life Design Lab (Bill Burnett and Dave Evans), this course employs a method called “design thinking” to help students from any program develop a constructive and effective approach to finding and designing their vocation after university. Through small group discussions, in-class activities, personal reflections and individual coaching, this course teaches students to use design thinking to explore many of life’s major challenges, such as pursuing careers they love and finding personal fulfillment. Topics include the integration of work and worldviews, ideation techniques, a portfolio approach to thriving, designing to increase balance and energy and how to prototype all aspects of students’ life. The capstone assignment is the creation of an “Odyssey Plan” focusing on taking actions in the 3-5 years following their graduation. For Engineering students only. Graded P or F.', 'For Engineering students only.', 'Not specified', '2026-08-11 15:36:37.863246');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (439, 'ENGG1500', 'Technological Innovation: From Concept to Reality', '3 Credit(s)', 'This course examines the impact and value of technological innovations on humanity from concept to reality. Through real-world case studies, students will engage in learning through group projects & investigations that foster critical thinking and problem-solving skills. Collaborative discussions will encourage idea sharing and diverse perspectives. The curriculum emphasizes the scientific skepticism approach to analyze and evaluate technological innovations. This would allow students to assess the effectiveness of various technologies in modern settings and to explore how the technologies are revolutionizing our lives & enhancing our everyday experiences. Ultimately, this course empowers students to become innovative leaders, equipped with the skills and enthusiasm needed to tackle contemporary challenges in an evolving technological landscape.', 'Not specified', 'Not specified', '2026-08-11 15:36:37.868699');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (440, 'ENGG1900', 'Service Learning Program', '1 Credit(s)', 'With the collaboration of local or non-local NGO and support from the School of Engineering, students enrolled in this program would be provided an opportunity to engage themselves in community service. Lectures, talks or training sessions will be provided to students to build up their communication skills and/or broaden their horizon. Students should also fulfill the requirements set by the NGO. At the end of the Program, students are required to submit report, reflective paper, group projects or to make a presentation as appropriate. Graded P or F.', 'Instructor''s approval required.', 'Not specified', '2026-08-11 15:36:37.872410');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (441, 'ENGG2010', 'Engineering Seminar Series', '0 Credit(s)', 'This course is designed for non-freshman students in the School of Engineering to promote the awareness of the role of engineers and the impact of engineering in the society. As a continuation of ENGG 1010, students are required to attend a few seminars from a series of seminars offered by the school each year. The seminars cover areas including the ethical and environmental responsibilities as an engineer, the importance and the considerations of safety and health related issues in engineering designs and solutions, and in general the impact of engineering to the society. This course helps to provide the needed components for meeting the accreditation requirement and also helps to broaden the students'' horizon in different engineering disciplines. For SENG students not in their first year of study only. Graded P or F.', 'For SENG students not in their first year of study only.', 'Not specified', '2026-08-11 15:36:37.876632');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (442, 'ENGG2201', 'The Law of Contract', '6 Credit(s)', 'Contract law with the laws of tort and unjust enrichment constitutes the “law of obligations”. It plays an important part of everyday life for individuals, businesses and even public agencies. Knowledge of contract law is imperative in a variety of practical dispute resolution and problem solving contexts. This course will guide students to examine the law of contract in England and Wales, drawing on materials from other jurisdictions (particularly Hong Kong). Topics include enforceability of agreements; terms of contracts; exception clauses, limitation clauses and unfair terms; misrepresentation; mistake and frustration; duress, undue influence and unconscionable bargains; and remedies. The course will put emphasis on applying the rules, principles and concepts of contract law to real-life cases with practical consequences and contextualizing the law in different settings. Good command of English Language is required to deal with legal readings. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified', '2026-08-11 15:36:37.880224');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (443, 'ENGG2800', 'SENG Cooperative Education Program', '3 Credit(s)', 'This course is intended to enhance engineering students’ career readiness by combining classroom-based education with practical work experience. By taking any two standalone career development programs offered by the Career Center or those as recognized by the School, students are required to apply the skills and knowledge learnt in a full-time coop work experience for a single employer for at least 4 months. Approval from the course coordinator is required for enrollment in the course. For SENG Year 2 students or above only. Graded P, PP or F.', 'For SENG Year 2 students or above only.', 'Not specified', '2026-08-11 15:36:37.885107');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (444, 'ENGG2900', 'Community Services Project', '1-4 Credit(s)', 'The course is offered in a form of a community project at a designated non-governmental organization (NGO) under the supervision of the School. Students are required to attend all the training sessions, design and implement the service project / participate in the service learning tasks as instructed by the host NGO and/or the course instructors. By the end of the course, students have to submit a reflective statement in the format of a paper, a group project report or a presentation to demonstrate the attainment of all intended learning outcomes, in addition to other requirements of the relevant NGO as appropriate. Approval from the course coordinator is needed prior to enrolling in the course. Graded PP, P or F. Students may repeat the course for credits if different topics are taken.', 'Approval from the course coordinator is needed prior to enrolling in the course.', 'Not specified', '2026-08-11 15:36:37.888374');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (445, 'ENGG2990', 'Special Topics', '1-3 Credit(s)', 'Selected topics in engineering. May be repeated for credits if different topics are taken. May be graded by letter, PP, P/F or DI/PA/F for different offerings.', 'Not specified', 'Not specified', '2026-08-11 15:36:37.892232');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (446, 'ENGG2991-2993', 'Undergraduate Student-initiated Experiential Learning', '1-3 Credit(s)', 'This course shall encourage students to carry our projects of their own ideas under guidance of faculty supervisors to apply engineering knowledge they learnt and integrate other expertise. In the end of the term, students are required to submit reports/demonstrations in an open house to show what they have achieved. Project and budget proposal should be submitted to the School of Engineering for application approval. May be repeated for credits if different topics are taken. Graded PP, P or F. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified', '2026-08-11 15:36:37.895847');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (447, 'ENGG3960-3962', 'Robotics Special Project', '1-4 Credit(s)', 'A robotics-related special project supervised by one or a group of faculty members. Normally, a project proposal and a final report are required. May be repeated for credits if the projects have different emphases or cover different topics. Enrollment in the project course may require instructor''s approval. May be graded by letter or P/F for different offering. May be graded PP.', 'Enrollment in the project course may require instructor''s approval.', 'Not specified', '2026-08-11 15:36:37.900036');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (448, 'ENGG4901', 'Integrated Final Year Project - First Major', '3 Credit(s)', 'Student who enrolled in this course should have declared additional major and both majors are BEng majors. The project would be an integrated, tailor-made project which can fulfill both majors’ program intended learning outcomes. It should be conducted under the supervision of faculty members from both majors. This course would be assessed by criteria set by first major. Student should use this course to substitute FYP requirement for both majors. Student enrolled in this course must concurrently enroll in ENGG 4902. May be graded PP. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified', '2026-08-11 15:36:37.904145');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (449, 'ENGG4902', 'Integrated Final Year Project - Second Major', '3 Credit(s)', 'Student who enrolled in this course should have declared additional major and both majors are BEng majors. The project would be an integrated, tailor-made project which can fulfill both majors’ program intended learning outcomes. It should be conducted under the supervision of faculty members from both majors. This course would be assessed by criteria set by second major. Student should use this course to substitute FYP requirement for both majors. Student enrolled in this course must concurrently enroll in ENGG 4901. May be graded PP. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified', '2026-08-11 15:36:37.907847');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (450, 'ENGG4903', 'Integrated Final Year Thesis - First Major', '3 Credit(s)', 'Student who enrolled in this course should have declared additional major and both majors are BEng majors. The thesis would be an integrated, tailor-made thesis which can fulfill both majors’ program intended learning outcomes. It should be conducted under the supervision of faculty members from both majors. This course would be assessed by criteria set by first major. Student should use this course to substitute FYT requirement for both majors. Student enrolled in this course must concurrently enroll ENGG 4904. May be graded PP. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified', '2026-08-11 15:36:37.911314');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (451, 'ENGG4904', 'Integrated Final Year Thesis - Second Major', '3 Credit(s)', 'Student who enrolled in this course should have declared additional major and both majors are BEng majors. The thesis would be an integrated, tailor-made thesis which can fulfill both majors’ program intended learning outcomes. It should be conducted under the supervision of faculty members from both majors. This course would be assessed by criteria set by second major. Student should use this course to substitute FYT requirement for both majors. Student enrolled in this course must concurrently enroll in ENGG 4903. May be graded PP. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified', '2026-08-11 15:36:37.916368');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (452, 'ENGG4950', 'Engineering Special Project', '1-4 Credit(s)', 'A special project supervised by one or a group of faculty members. Normally, a project proposal and a final report are required. May be repeated for credits if the projects have different emphases or cover different topics. Enrollment in the project course may require instructor''s approval. May be graded by letter or P/F for different offering. May be graded PP.', 'Enrollment in the project course may require instructor''s approval.', 'Not specified', '2026-08-11 15:36:37.920808');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (510, 'GNED2000', 'Selected Topics in General Education', '0-3 Credit(s)', 'Selected topics and subject matter aimed at meeting the University''s objective to provide students a well-rounded education that enhances the development of their creativity, critical thinking, global outlook, and cultural awareness. Maybe graded DI/PA/F.', '', '', '2026-08-11 12:06:48.994409');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (511, 'GNED2510', 'Career Building', '1 Credit(s)', '[ND] Non-designated GEE. The course is open to all undergraduate students, with priority given to Year 2 students or above. It aims at empowering students in making rewarding career choices by 1) introducing the career planning process, 2) enhancing their understanding of the current job market and employers'' expectation, and 3) equipping them with essential and practical job search skills like CV writing, interview, aptitude test, group discussion, etc. so as to increase their competitiveness. Experiential learning opportunities and personalized feedback will be provided to prepare students for the recruitment process. Seasoned practitioners from different sectors will be invited to shed light on recruitment criteria and industry updates. Graded DI/PA/F. Detailed course contents are available at the Career Center website.', '', '', '2026-08-11 15:38:06.561579');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (512, 'GNED2710', 'Service Learning Project', '1 Credit(s)', '[ND] Non-designated GEE. The course aims to enhance students'' civic awareness and engagement through structured service activities related to one or more community organizations. Students will be divided into small groups to work on service projects and consolidate their learning experience through guided reflective activities. Students may take this course up to two times if the scope of the service projects is different. Graded P/F/PP. Instructor''s approval is required for admission to the course.', '', '', '2026-08-11 15:38:06.570447');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (552, 'HMAW1905', 'Behavioral Foundations of University Education: Habits, Mindsets, and Wellness', '3 Credit(s)', 'This course will help students adapt to university life through advising, sharing and discussion, and applying the science of well‐being to enhance their personal and interpersonal development. It also aims to foster their self‐understanding and confidence as young adults who can fully enjoy their university education and career thereafter. The course has 3 components: Lectures and Seminars, Self‐Directed Experience, and Advising and Community Meetings. Lectures and Seminars will orientate students to their respective Schools/IPO, provide academic advice and equip them with the scientific bases of well‐being. Self‐Directed Experience will provide opportunities to develop mindsets and habits for students’ physical and social‐emotional wellness and personal enrichment. In Advising and Community Meetings, students will bring knowledge and skills together through reflection and discussion with peers and School/IPO advisors. Topics such as learning and time management skills, purpose of university education, and planning for personal and professional development will be covered. Graded PP, P or F.', 'CORE 1905, IDPO 1010 (prior to 2022-23)', 'Not specified.', '2026-08-11 15:38:16.265298');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (553, 'HLTH1010', 'Healthy Lifestyle', '0 Credit(s)', 'A compulsory, one-year course for all undergraduates to learn how to maintain a well-balanced and healthy lifestyle that will help them to manage their lives, learning, transitions and holistic development. Students will complete at least 45 hours of activities including physical and wellness assessments, sports skill classes, organized sports and fitness events, community service, as well as enrichment topics, for example, mental health, wellness, transitions, student life, and personal growth. Students with special personal reasons may seek exemption from the Director of Student Affairs. Graded P or F. On successful completion of the course, students will be able to: 
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (577, 'IIMP2000', 'Academic and Professional Development', '0 Credit(s)', 'This course is designed to assist students in developing attributes necessary for professional growth throughout their studies in the IIM program. It will also provide academic advising to students, to enhance their job hunting skills and, to improve their communication skills. Students are required to attend discussion sessions with advisors and selected workshops. For IIM students only. Graded P/PP/F.', '', '', '2026-08-11 15:39:15.719206');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (578, 'IIMP4970', 'Interdisciplinary Industrial Project', '6 Credit(s)', 'Students in this project will be engaged in practical hands-on training for a period of at least 6 months, in a form of a full-time or part-time internship or co-op program in an organization or company relevant to the students’ area of interest. Students are required to complete a final year project under the supervision of an industrial supervisor and a faculty member during the co-op. Students who are interested to take this course must obtain prior approval from the IMAC. For IIM students only. May be graded PP.', 'IIMP4980, IIMP4990', '', '2026-08-11 15:39:15.727280');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (579, 'IIMP4980', 'Interdisciplinary Capstone Project I', '3 Credit(s)', 'Each IIM student is required to complete a capstone project before graduation. This is the first course of a two-term project in which the student can synthesize and apply skills and knowledge learnt from the program. The project is conducted under the supervision of the student’s Individualized Major Advisory Committee (IMAC). For IIM students only. May be graded PP.', '', '', '2026-08-11 15:39:15.733830');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (580, 'IIMP4990', 'Interdisciplinary Capstone Project II', '3 Credit(s)', 'Continuation of IIMP4980. For IIM students only.', 'IIMP4980', '', '2026-08-11 15:39:15.737496');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (581, 'IIMP4991', 'Interdisciplinary Capstone Project', '6 Credit(s)', 'Each IIM student is required to complete a capstone project before graduation. This is a year-long project course which the student can synthesize and apply skills and knowledge learnt from the program. The project is conducted under the supervision of the student’s Individualized Major Advisory Committee (IMAC). May be graded PP. The credit load will be spread over the year. For students in Individualized Interdisciplinary Major (IIM).', 'IIMP4970, IIMP4980, IIMP4990', '', '2026-08-11 15:39:15.741192');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (582, 'IROP1000', 'International Research Opportunities Program', '0 Credit(s)', 'This course is designed for undergraduate students from overseas and recommended by their home institution to participate in the International Research Opportunities Program (IROP) offered during the summer term. Participating students will be assigned a faculty from HKUST as their supervisor and conduct research in a faculty-led project. Students are required to submit a written report upon completion of the project. This course can only be taken once; no course credit is assigned. Graded P or F.', 'None', 'Summer', '2026-08-11 15:39:18.908388');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (734, 'LEGL1000', 'Legal Education (Basic Law, National Security Law and Safeguarding National Security Ordinance)', '0 Credit(s)', 'A compulsory legal education course for all undergraduates to learn about the PRC Constitution, Basic Law, National Security Law, Safeguarding National Security Ordinance, and Legal System of HKSAR. Students will gain an understanding on these topics and their relevance to the society. The course is a self-paced online course and will cover the topics in 3 modules. Students will be required to complete and pass an assessment for each module to obtain a ''Pass'' grade for the course. Graded P or F. On successful completion of the course, students will be able to have broad understanding of the basic information about Hong Kong’s legal system, understand the different levels of court and the role of the National People’s Congress, get the background information of Hong Kong’s National Security Law, and define and comprehend the rules and boundaries in public events and introduce the public order offences in Hong Kong.', 'None', 'Self-paced online delivery, check specific offerings', '2026-08-11 15:41:25.301159');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (868, 'MECH1001', 'Academic and Professional Development I', '0 Credit(s)', 'This course is tailored for Year 1 and Year 2 MAE students, focusing on career guidance and exploration of various career options. It will feature guest speakers who will share insights on local and global job markets, along with organized site visits to companies. It is a two-year course (PP for first 3 terms and Pass/Fail for Spring Term of Year 2.)', '', 'Year 1 and Year 2', '2026-08-11 15:44:39.959888');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (869, 'MECH1902', 'Energy Systems in a Sustainable World', '3 Credit(s)', 'Various fuels used by mankind, fossil and renewable sources; power generation technologies and the controversies; energy efficient technologies and the applications in buildings and consumable products; energy efficient manufacturing technologies; low energy infrastructure and impact to modern life style; myths behind sustainable energy systems and the debates; energy entrepreneurship, case studies and social impact.', '', '', '2026-08-11 15:44:39.965384');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (870, 'MECH1905', 'Buildings for Contemporary Living', '3 Credit(s)', 'This course introduces the applications of modern mechanical engineering technologies to buildings systems and how they relate to our livings. A wise design of building systems offers high convenience to the occupants. Building systems, such as structural design, water supply, safety and air conditioning are of high importance to maintain a satisfying temperature, humidity, lighting and indoor air quality for comfortable living and efficient working.', 'CORE 1270', '', '2026-08-11 15:44:39.972755');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (871, 'MECH1906', 'Mechanical Engineering for Modern Life', '3 Credit(s)', 'Mechanical Engineering covers the broadest range of engineering amongst all related disciplines. In addition to the production of modern products useful in daily life, it is also associated with power generation and distribution, as well as new materials development.', 'First year students are preferred.', '', '2026-08-11 15:44:39.978314');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (872, 'MECH1907', 'Introduction to Aerospace Engineering', '3 Credit(s)', 'Introduction to the field of Aerospace engineering, discussion of basic aerospace systems and disciplines, working vocabulary of the field. Basic concepts. Demonstration through examples.', '', '', '2026-08-11 15:44:39.986807');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (873, 'MECH1908', 'Exploration of Mechanical Design and Engineering', '3 Credit(s)', 'This course provides a comprehensive introduction to the field of mechanical engineering and its growing intersection with the generative design principle.', '', '', '2026-08-11 15:44:39.990316');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (874, 'MECH1910', 'Foundations of Mechanical and Aerospace Engineering', '3 Credit(s)', 'This course serves as an introduction to Mechanical and Aerospace engineering, covering theoretical concepts and basic core principles across four key sub-areas: aerospace engineering; mechanics and materials; thermo-fluids; design and manufacturing.', '', '', '2026-08-11 15:44:39.994352');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (875, 'MECH2002', 'Academic and Professional Development II', '0 Credit(s)', 'This course is designed for Year 3 and Year 4 MAE students as a continuation of MECH1001. It prepares students for the job market by focusing on essential skills such as resume writing, interview techniques, and networking.', 'MECH 1001', '', '2026-08-11 15:44:40.003893');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (876, 'MECH2007', 'Aerospace Engineering: Principles and Systems', '3 Credit(s)', 'Basic principles in key disciplines of aerospace systems and interconnections among the various disciplines.', 'MATH 1013 OR MATH 1020 OR MATH 1023', '', '2026-08-11 15:44:40.009481');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (877, 'MECH2020', 'Statics and Dynamics', '3 Credit(s)', 'Fundamental course on the analysis of the equilibrium and dynamic behavior of mechanical systems.', '(MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023) AND (PHYS 1111 OR PHYS 1112 OR PHYS 1312)', '', '2026-08-11 15:44:40.013072');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (878, 'MECH2040', 'Solid Mechanics I', '3 Credit(s)', 'Forces, moments, equilibrium; principles of virtual work; analysis of structural members under axial load, torsion and bending; shear force and bending moment diagrams; statically indeterminate trusses; buckling and structural stability.', 'MECH 2020, CIVL 2120, AMAT 2320', '', '2026-08-11 15:44:40.017687');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (879, 'MECH2210', 'Fluid Mechanics', '3 Credit(s)', 'Fundamental concepts; hydrostatics; integral and differential equations of fluid flows; conservation of mass, momentum and energy; dimensional analysis; pipe flow; channel flow and boundary layers.', '(MATH 2011 OR MATH 2023) AND MECH 2310', '', '2026-08-11 15:44:40.021689');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (880, 'MECH2300', 'Engineering Computation with Matrices and AI', '3 Credit(s)', 'This course covers the theoretical foundations of linear algebra and their role in engineering analysis.', 'COMP 1023 OR COMP 2011 OR COMP 2012H, MATH 2111', '', '2026-08-11 15:44:40.026165');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (881, 'MECH2310', 'Thermodynamics', '3 Credit(s)', 'Fundamental concepts; pure substance; work and heat; control volume; Ideal and real gases. First and second laws of thermodynamics. Entropy. Elementary power and refrigeration cycles.', 'MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023', '', '2026-08-11 15:44:40.033891');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (882, 'MECH2410', 'Engineering Materials I', '3 Credit(s)', 'This course introduces atomic bonding of materials; crystal structure and defects; mechanical properties of materials; phase diagrams and phase transformations; heat treatment of metals; and processing and applications of metallic materials.', 'PHYS 3040, PHYS 3042', '', '2026-08-11 15:44:40.040761');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (883, 'MECH2520', 'Design and Manufacturing I', '3 Credit(s)', 'This course introduces engineering design process and engineering graphics.', '', '', '2026-08-11 15:44:40.044924');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (884, 'MECH3030', 'Mechanisms of Machinery', '3 Credit(s)', 'Application of kinematics and dynamics in the analysis, design and synthesis of mechanisms.', 'MECH 2020, SMMG 3080', '', '2026-08-11 15:44:40.050964');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (885, 'MECH3110', 'Materials for Energy Technologies', '3 Credit(s)', 'The societal energy transition from fossil fuels to renewable sources requires novel energy technologies, with material design and engineering at the center of the innovation process.', 'ENEG 3110, AMAT 3590, ENEG 3110', '', '2026-08-11 15:44:40.055387');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (886, 'MECH3300', 'Energy Conversion', '3 Credit(s)', 'Thermodynamics of combustion, chemical equilibrium, refrigeration and mixtures of gases.', 'MECH 2310', '', '2026-08-11 15:44:40.059326');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (887, 'MECH3310', 'Heat Transfer', '3 Credit(s)', 'Transient and steady heat conduction. Natural and forced convection. Radiative exchange.', 'MECH 2210 AND MECH 2310', '', '2026-08-11 15:44:40.062753');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (888, 'MECH3400', 'Introduction to Engineering Composite Materials', '3 Credit(s)', 'The course will introduce fundamentals of engineering composite materials.', 'MECH 2040', '', '2026-08-11 15:44:40.070424');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (889, 'MECH3410', 'Engineering Materials II', '3 Credit(s)', 'As an extension of MECH 2410, this course is composed of modules including electrical, thermal, magnetic, and optical properties of engineering materials.', 'MECH 2410 [BLD] Blended learning', 'NA', '2026-08-11 12:15:16.604066');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (890, 'MECH3510', 'Computer-Aided Design and Manufacturing', '3 Credit(s)', 'This course covers topics: curves and surfaces, geometric modeling basics, data structures in CAD/CAM, finite element analysis, optimization, tool path generation.', 'SMMG 3690', '', '2026-08-11 15:44:40.078807');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (891, 'MECH3610', 'Control Principles', '3 Credit(s)', 'Introduction to system equations, block diagrams, signal flow graphs, state-space systems, transient response using convolution integral.', 'ELEC 3200, SEEN 3060', '', '2026-08-11 15:44:40.086803');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (892, 'MECH3620', 'Aircraft Design', '3 Credit(s)', 'Students will work in teams to develop a conceptual design for a complete flight vehicle, using knowledge and skills acquired in the Aerospace Engineering Major curriculum.', 'MECH 1907 AND MECH 3640 AND MECH 3650, MECH 3660 AND MECH 3670', '', '2026-08-11 15:44:40.090764');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (893, 'MECH3630', 'Electrical Technology', '3 Credit(s)', 'Electromagnetic circuits, transformers, electromechanical energy conversion, DC machines, asynchronous and synchronous machines, special machines, transients and dynamics, three-phase circuits and power electronics.', 'ELEC 2420', '', '2026-08-11 15:44:40.094276');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (894, 'MECH3640', 'Aerodynamics', '3 Credit(s)', 'Irrotational flow, circulation, lift and drag, aerofoil, conformal mapping, lifting line theory, elliptical wing, swept wing, delta wing, supersonic flow.', 'CENG 2220 OR CIVL 2510 OR MECH 1907 OR MECH 1910 OR MECH 2210', '', '2026-08-11 15:44:40.098187');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (895, 'MECH3650', 'Aircraft Structural Analysis', '3 Credit(s)', 'Elasticity, structural analysis, energy and matrix methods, fatigue, vibration, airworthiness and aeroelasticity.', 'CIVL 2120 OR MECH 1907 OR MECH 1910 OR MECH 2040', '', '2026-08-11 15:44:40.102293');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (896, 'MECH3660', 'Aircraft Propulsion', '3 Credit(s)', 'The course introduces modern propulsion systems on aerial vehicles.', '(MATH 2111 OR MATH 2350 OR MATH 2351) AND MECH 3640', '', '2026-08-11 15:44:40.105572');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (897, 'MECH3670', 'Aircraft Performance and Stability', '3 Credit(s)', 'Introduction to the dynamics and control of atmospheric flight vehicles. Airplane performance, static longitudinal stability, maneuvering flight, directional stability and control, control surfaces, aerodynamic coefficients.', 'CENG 2220 OR CIVL 2510 OR MECH 1907 OR MECH 1910 OR MECH 2020 OR MECH 2210', '', '2026-08-11 15:44:40.109088');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (898, 'MECH3680', 'Avionics Systems', '3 Credit(s)', 'This course covers avionic systems and communications, including analog and digital systems.', 'ELEC 2420', '', '2026-08-11 15:44:40.114529');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (899, 'MECH3690', 'Aerospace Engineering Laboratory', '3 Credit(s)', 'Fundamentals of instrumentation and measurement and their application in engineering testing and experimentation.', 'MECH 3640 OR MECH 3650 OR MECH 3660 OR MECH 3670 OR MECH 3680', '', '2026-08-11 15:44:40.118484');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (900, 'MECH3710', 'Manufacturing Processes and Systems', '3 Credit(s)', 'Introduction to the principles of manufacturing processes; process characteristics, capabilities and limitations.', 'MECH 2410', '', '2026-08-11 15:44:40.123433');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (901, 'MECH3740', 'Introduction to Aerospace Computational Fluid Dynamics (CFD)', '3 Credit(s)', 'This course introduces students to computational fluid dynamics (CFD) relevant to aerospace engineering.', 'MECH 4830, MECH 3640', '', '2026-08-11 15:44:40.127555');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (902, 'MECH3750', 'Vibration, Control and Programming', '3 Credit(s)', 'Single-degree-of-freedom vibration, multiple-degree-of-freedom vibration, beam theory, energy method, passive control, active control, programming, MATLAB.', 'MECH 4750, MECH 2020, CIVL 4330', '', '2026-08-11 15:44:40.132269');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (903, 'MECH3830', 'Laboratory', '3 Credit(s)', 'Introductory laboratory course to provide training in experimental techniques and laboratory procedures, data acquisition, analysis and presentation.', '', '', '2026-08-11 15:44:40.141892');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (904, 'MECH3907', 'Mechatronic Design and Prototyping', '3 Credit(s)', 'This is an extended version of industrial training designed for MAE students.', 'MECH 2907, MECH 2520, ROAS 3400', '', '2026-08-11 15:44:40.147105');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (905, 'MECH4000', 'Special Topics', '3 Credit(s)', 'Covers selected topics of current interest to the Department not covered by existing courses.', '', '', '2026-08-11 15:44:40.151776');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (906, 'MECH4010', 'Materials Failure in Mechanical Applications', '3 Credit(s)', 'Failure analysis, brittle and ductile fracture, creep rupture, fatigue cracking, environmental degradation of materials, damage tolerance design, life predication of engineering components, case studies.', 'MECH 2410', '', '2026-08-11 15:44:40.157225');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (907, 'MECH4100', 'Experiential Projects in Aerospace Engineering', '3 Credit(s)', 'This course takes an experiential approach to aerospace engineering through a series of seminars and workshops delivered by faculty and industry professionals.', 'MECH 1907 OR MECH 1910 OR (MECH 2020 AND MECH 2310)', '', '2026-08-11 15:44:40.162354');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (908, 'MECH4340', 'Air Conditioning Systems', '3 Credit(s)', 'Introduction of heating, ventilating and air conditioning (HVAC) systems, moist air properties, heat transmission in building structures.', 'MECH 3310', '', '2026-08-11 15:44:40.166223');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (909, 'MECH4350', 'Indoor Air Quality in Buildings', '3 Credit(s)', 'Indoor air pollutants in buildings and their transport dynamics with respect to building ventilation systems.', 'MECH 2310, IBTM 5430, JEVE 5350', '', '2026-08-11 15:44:40.172835');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (910, 'MECH4360', 'Introduction to Intelligent Building Systems', '3 Credit(s)', 'Introduction to intelligent building and building automation, communication, safety and security systems.', 'MECH 2310 and MECH 3610', '', '2026-08-11 15:44:40.176302');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (911, 'MECH4430', 'Materials Characterization', '3 Credit(s)', 'Study of microstructure, morphology, and chemical compositions of engineering materials using optical, X-ray and electron methods.', 'MECH 2410', '', '2026-08-11 15:44:40.183194');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (912, 'MECH4450', 'Introduction to Finite Element Analysis', '3 Credit(s)', 'Basic concepts of finite element methods, element equations for basic structural elements, implementation and application of FEMs in 1-D and 2-D structural analysis.', 'MECH 2040', '', '2026-08-11 15:44:40.189926');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (913, 'MECH4710', 'Introduction to Robotics', '3 Credit(s)', 'Rigid body motion, forward and inverse kinematics, manipulator Jacobians, force relation, dynamics and position control robot manipulators.', 'MECH 2020 OR MECH 3610', '', '2026-08-11 15:44:40.194958');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (914, 'MECH4720', 'Introduction to Precision Engineering', '3 Credit(s)', 'Principles of precision design, precision machining, and precision measurement.', 'MECH 2520, SMMG 4650', '', '2026-08-11 15:44:40.198454');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (915, 'MECH4740', 'Numerical Methods in Engineering', '3 Credit(s)', 'This course is intended for senior undergraduate students and early graduate students in engineering.', 'MATH 2111 OR MATH 2121 OR MATH 2350 OR MATH 2351', '', '2026-08-11 15:44:40.204957');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (916, 'MECH4810', 'Unmanned Aviation Vehicle', '3 Credit(s)', 'This course will introduce students unmanned aerial vehicles (UAV) that are capable to operate remotely or autonomously in various environments.', 'MECH 3680', '', '2026-08-11 15:44:40.208782');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (917, 'MECH4890', 'Introduction to Nanosatellite Engineering', '3 Credit(s)', 'This course will introduce the fundamental concepts of CubeSat.', 'MATH 2011 AND (MATH 2111 OR MATH 2350 OR MATH 2351) AND (PHYS 1111 OR PHYS 1112 OR PHYS 1312)', '', '2026-08-11 15:44:40.213286');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (918, 'MECH4900', 'Final Year Design Project', '6 Credit(s)', 'A one-year project course offers practice of engineering design through a group design project.', 'MECH 4950', '', '2026-08-11 15:44:40.219579');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (919, 'MECH4912', 'Green Technologies for Buildings, Energy and Water', '3 Credit(s)', 'This course introduces principles and technologies for sustainable and traditional cooling technologies for buildings.', 'MECH 3300 OR MECH 3310 OR CENG 3220', '', '2026-08-11 15:44:40.230399');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (920, 'MECH4950', 'Co-op Program', '6 Credit(s)', 'This course is intended to provide final year UG students with practical hands-on training in the form of a co-op program in an engineering company.', '', '', '2026-08-11 15:44:40.238211');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (921, 'MECH4980', 'Final Year Aerospace Design Project', '6 Credit(s)', 'A one-year Design project offers practice of aircraft design for the modern aerospace industry.', 'MECH 4950', '', '2026-08-11 15:44:40.244103');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (922, 'MECH4990', 'Aerospace Research Project', '6 Credit(s)', 'An individual one-year research project under the close supervision of a faculty member of the department.', 'MECH 4950', '', '2026-08-11 15:44:40.248647');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (923, 'MECH4995', 'Research Project', '6 Credit(s)', 'An individual one-year research project under the close supervision of a faculty member of the department.', 'MECH 4950', '', '2026-08-11 15:44:40.254573');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (924, 'ACCT1010', 'Accounting, Business and Society', '3 Credit(s)', 'Overview of accounting in business and social contexts; use of accounting information for accountability and decision-making in companies, non-profit organizations, and government; major elements of accounting, including assets, liabilities, revenues and expenses; discharge of accountability by companies through corporate social and environmental reports. The aim of this course is to make students aware of how accounting could be applicable to fundamental business transactions and ways to evaluate how businesses are operated.', '', '', '2026-08-11 15:29:39.156365');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (925, 'ACCT1610', 'Laws in Society and Business', '3 Credit(s)', 'This course provides an introduction to law and business society. Topics include general introduction to the concepts in law; an introduction to the Hong Kong legal system under the principle of ''one country, two systems''; copyright law; trademark law; agency law; insolvency law; employment law and business ethics. As Hong Kong is a well-developed business society, this course is intended to build students'' understanding of the relationship between the law and the society and discuss laws in society and business.', 'ACCT 3610', '', '2026-08-11 15:29:39.161953');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (926, 'ACCT2010', 'Principles of Accounting I', '3 Credit(s)', 'This is the first course of the principles of accounting sequence. Introduction to the concepts and principles of financial accounting, including the analysis, recording, and reporting of business transactions and preparation of financial statements.', '', '[BLD] Blended learning', '2026-08-11 15:29:39.165850');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (927, 'ACCT2200', 'Principles of Accounting II', '3 Credit(s)', 'This is the second course of the principles of accounting sequence. It introduces concepts, accounting methods, and analytical tools related to managerial and cost accounting. Topics include fundamental cost concepts, job-order and process costing systems, CVP analysis, budgets and standards, segment reporting, and decision-making using cost information.', '(for non-BIBU students) ACCT 2010', '', '2026-08-11 15:29:39.171317');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (928, 'ACCT3010', 'Financial Accounting I', '3 Credit(s)', 'Study of the application of generally accepted accounting principles to accounting for business organizations; evaluation of balance sheet accounts and the related effects on income determination.', 'ACCT 2010, ACCT 3030', '[BLD] Blended learning', '2026-08-11 15:29:39.175194');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (929, 'ACCT3020', 'Financial Accounting II', '3 Credit(s)', 'Continuation of ACCT 3010. Special problems in accounting for owner''s equity and long-term liabilities including corporate bonds, leases, deferred taxation and pensions.', 'ACCT 3010, ACCT 3030', '', '2026-08-11 15:29:39.178545');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (930, 'ACCT3030', 'Intermediate Financial Accounting for Non-Accounting Majors', '3 Credit(s)', 'Financial accounting concepts and practices with particular emphasis on the analysis and interpretation of financial reports and data.', 'ACCT 2010, ACCT 3010, ACCT 3020', '', '2026-08-11 15:29:39.181861');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (931, 'ACCT3210', 'Advanced Management Accounting', '3 Credit(s)', 'This course covers advanced quantitative methods for management decision-making (decision trees, linear regression, learning curves, and linear programming), pricing and transfer pricing decisions, allocation of common and joint costs, variance analysis, performance measurement and incentive compensation.', 'ACCT 2200', '', '2026-08-11 15:29:39.186056');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (932, 'ACCT3610', 'Business Law', '3 Credit(s)', 'This course is to provide students with an awareness of the overall legal framework in which businesses in Hong Kong operate so as to enable them to apply the relevant laws and practices to business problems and practical solutions.', '', '', '2026-08-11 15:29:39.189334');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (933, 'ACCT3630', 'ESG Measurement, Disclosure and Applications', '3 Credit(s)', 'Environment, Society and Governance (ESG) are three pillars in the emerging system of sustainable finance. This course is designed for students interested in the concept of ESG, especially for those who aspire to learn about the measurement and disclosure of ESG and their applications in the management of business and investment.', 'ACCT 2010 AND FINA 2303, ENVR 4320', '', '2026-08-11 15:29:39.192544');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (934, 'ACCT3880', 'Professional Excellence Program', '1 Credit(s)', 'Introductory-level seminars and workshops on the accounting/auditing professions; development of life-skills including writing and other communication skills; and individual thinking skills; ethics for accountants.', '', 'For SB&M students only.', '2026-08-11 15:29:39.195827');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (935, 'ACCT4010', 'Advanced Financial Accounting', '3 Credit(s)', 'Addresses accounting issues associated with (1) intercorporate investment activity that conveys significant influence or control and (2) cross-border activities.', 'ACCT 3020', '', '2026-08-11 15:29:39.199350');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (936, 'ACCT4410', 'Taxation', '3 Credit(s)', 'The Hong Kong taxation system and its administration; taxation of individuals, partnerships and corporations; stamp duty; obligations compliance.', 'ACCT 3010 AND ACCT 3610', '', '2026-08-11 15:29:39.203281');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (937, 'ACCT4510', 'Auditing', '3 Credit(s)', 'Objectives, standards and procedures of auditing; preparation of working papers; applications of statistical sampling; computer-assisted auditing and auditing of electronic data processing (EDP) services; professional liability and ethics.', 'ACCT 3020', '', '2026-08-11 15:29:39.206551');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (938, 'ACCT4610', 'Company Law', '3 Credit(s)', 'Law relating to companies registered in Hong Kong; company formation and records; share and loan capital; management and administration; reconstructions; mergers and take-overs; liquidation and receivership.', 'ACCT 3610', '', '2026-08-11 15:29:39.209646');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (939, 'ACCT4710', 'Accounting Analytics for Professional Accountants', '3 Credit(s)', 'Data analytics is reshaping the work of accountants. Applications of data analytics in accounting including: Auditing/Assurance - data analytics techniques used by accounting professionals and auditors nowadays to detect fraud and conduct forensic accounting.', 'ACCT 2010 AND ISOM 2010', '', '2026-08-11 15:29:39.212847');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (940, 'ACCT4720', 'Equity Investment with Machine Learning', '3 Credit(s)', 'This course is designed for students interesting in the investment management business, especially for those who aspire to learn the application of quantitative and machine learning technology in equity investing.', 'ACCT 2010 AND ISOM 3400', '', '2026-08-11 15:29:39.216074');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (941, 'ACCT4801', 'Cryptocurrency, blockchain and their business applications', '3 Credit(s)', 'This course introduces cryptocurrencies (including Bitcoin, Ethereum, and others), blockchain, also known as distributed ledger technology (DLT), and their multidimensional business applications.', '', 'For ACCT students in their third year of study or above only.', '2026-08-11 15:29:39.220107');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (942, 'ACCT4802', 'Valuation and Risk Management in Mergers and Acquisitions', '3 Credit(s)', 'This course is designed to enhance student ability in reading, understanding and analyzing complicated financial statements that involve mergers and acquisitions (M&A) based on a number of case studies.', 'ACCT 2010', 'For ACCT students in their third year of study or above only.', '2026-08-11 15:29:39.223605');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (943, 'ACCT4803', 'Artificial Intelligence for Accounting Practice and Analysis', '3 Credit(s)', 'This course will put the current uses of artificial intelligence (AI) in the context of its development at the nexus of cognitive science, computer science, cybernetics (the study of complex systems), and statistics.', '', 'For ACCT students in their third year of study or above only.', '2026-08-11 15:29:39.226910');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (944, 'ACCT4804', 'Forensic Accounting and Fraud Detection', '3 Credit(s)', 'This course introduces students to the principles and practices of forensic accounting and its role in addressing financial crime.', '', 'For ACCT students in their third year of study or above only.', '2026-08-11 15:29:39.229857');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (945, 'ACCT4980', 'Independent Study', '1-4 Credit(s)', 'Directed study of selected problems in accounting not covered in other courses. Graded letter grade or P/F subject to different offerings.', '', '', '2026-08-11 15:29:39.233108');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (946, 'BIBU1010', 'Biotechnology and Business Seminar', '1 Credit(s)', 'Study on selected current topics in biotechnology and business through attending seminars in related areas. This course provides a platform for students to interact and learn from different academic and practitioner leaders in both biotechnology and business fields. Graded P or F. For BIBU students only.', 'For BIBU students only.', 'Not specified', '2026-08-11 15:29:31.267317');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (947, 'BIBU4820', 'Biotechnology Entrepreneurship and Business Operations', '3 Credit(s)', 'This course allows students to acquire a combination of essential scientific principles and practical business know-how in the biotechnology market, with an emphasis on the uniqueness and complexities of biotechnology entrepreneurship. Special focus will be placed on analyzing the critical factors that are pertinent to a successful venture in biotechnology. These factors will include scientific and technological advancements, intellectual property rights, as well as regulatory and commercial considerations. Students will eventually learn how to translate the knowledge into a business plan for start-up processes within the biotechnology industry. Guest speakers will include those who have experience in starting or managing biotechnology companies. For BIBU and BIOT students in their fourth year of study only. Other students may seek instructor’s approval for enrolment.', 'LIFS 4820, For BIBU and BIOT students in their fourth year of study only. Other students may seek instructor’s approval for enrolment.', 'Not specified', '2026-08-11 15:29:31.273423');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (948, 'BIBU4830', 'Biotechnology Management', '3 Credit(s)', 'This course provides students with a general outlook of the roles and responsibilities in managing the biotech business. Business constraints like sales and marketing, partnerships, critical success factors in operations, market entry barriers, risk management and relationships with stakeholders will be covered in this course, with special focus on strategic development in the biotech business. Guest speakers will contribute their personal experience to offer a professional view of the key issues, pitfalls and opportunities in their daily business activity. A large use of case studies and other process management techniques will simulate potential scenarios in which students may be called to operate soon after they completed their university career. For BIBU students in their fourth year of study only.', 'For BIBU students in their fourth year of study only.', 'Not specified', '2026-08-11 15:29:31.277544');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (949, 'BIBU4840', 'Biotechnology and Business Capstone Project', '3 Credit(s)', 'Under the supervision of faculty members, students in small groups will undertake a project to investigate selected topics relevant to the biotechnology industry and its business operations. The project will be delivered through the format of literature review. Course assessment will be based on students’ written report and oral presentation that documents the project work and learning experiences. For BIBU students with approval of the course instructor for enrollment in the course.', 'For BIBU students with approval of the course instructor for enrollment in the course.', 'Not specified', '2026-08-11 15:29:31.282783');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (950, 'BIBU4850', 'Biotechnology and Business Project Research', '6 Credit(s)', 'This is a one-year course. With a one-on-one supervision by faculty member, students will undertake a research project of their choice in biotechnological innovation/ideas: design of experiments, analysis of data, submission of a business plan/proposal in order to commercialize the selected biotechnological innovation/ideas. Credit load will be spread over the year. For BIBU students with approval of the course instructor for enrolling in the course. May be graded PP.', 'For BIBU students with approval of the course instructor for enrolling in the course.', 'Not specified', '2026-08-11 15:29:31.286622');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (951, 'CENG1000', 'Foundations of Chemical and Biological Engineering', '3 Credit(s)', 'This foundational course is designed to equip students with a comprehensive understanding of the core principles of the disciplines within the Department of Chemical and Biological Engineering (CBE). It serves as a springboard for all CBE students, providing a broad overview of their major programs, essential knowledge and skills for engineering studies, and insights into career opportunities. The course combines lectures with hands-on projects, demonstrations, and experiments.', 'Level 3 or above in HKDSE 1/2x Chemistry OR in HKDSE 1x Chemistry OR CHEM 1004 OR CHEM 1010 (prior to 2022-23) OR CHEM 1012', '', '2026-08-11 14:45:49.373758');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (952, 'CENG1010', 'Academic and Professional Development I', '0 Credit(s)', 'This course is designed to provide academic advising to new students in the Department of Chemical and Biological Engineering, to enhance their sense of identity and belonging, to familiarize them with their major disciplines, to encourage them to pursue co-curricular learning opportunities, and to improve their communication skills. Activities include meetings with faculty advisors, senior students and alumni, seminars and workshops, and various community building activities. For CBE students only. Graded P or F.', '', '', '2026-08-11 14:45:49.379723');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (953, 'CENG1110', 'Introduction to Chemical Engineering', '3 Credit(s)', 'Application of material and energy balances to batch and continuous processes involving reactive and non-reactive unit operations and recycle systems. Introductions to chemical process and product design, equipment design, simulation and computational tools.', 'CENG 2110, CENG 1000, CHEM 1012', '', '2026-08-11 15:31:17.070843');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (954, 'CENG1500', 'A First Course on Materials Science and Applications', '3 Credit(s)', 'The scope of this course is to introduce different categories of materials and to elucidate their applications. We will start from the basic concepts of matter to the basic structures at molecular scale, and then to the science and engineering of materials. The focus of the course is the structure/property relationship. The principles for designing and developing useful materials for special applications will be discussed.', 'MECH 2410, PHYS 3040', '', '2026-08-11 14:45:49.386940');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (955, 'CENG1600', 'Biotechnology and Its Business Opportunities', '3 Credit(s)', 'This course gives an introductory overview of biotechnology from both technical and business perspectives. It surveys the current landscape of medical biotechnology, discusses the significant milestones in this field, describes underlying scientific concepts, and emphasizes the impact of innovations on human health and economy.', 'Level 3 in HKDSE 1/2x Biology OR LIFS 1901', '', '2026-08-11 14:45:49.390945');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (956, 'CENG1700', 'Introduction to Environmental Engineering', '3 Credit(s)', 'Fundamentals of environmental impact assessment will be discussed. Life cycle analysis of carbon and energy will be introduced using case studies. Principles of environmental engineering for control of air, water, solid and noise pollution will be discussed, including global pollution, pollution prevention and minimization. Cost of available technologies will be analyzed.', 'CIVL 2410, Level 3 in HKDSE 1/2x Chemistry OR CHEM 1010 (prior to 2022-23)', '', '2026-08-11 15:31:17.081822');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (957, 'CENG1800', 'Introduction to Food Science and Technology', '3 Credit(s)', 'This course aims to provide students with fundamental knowledge of food science (chemistry, nutrition, microbiology, etc.) and safety issues for daily consumption, and preliminary perspective for further exploration on food processing technologies.', 'CORE 1212', '[BLD] Blended learning', '2026-08-11 15:31:17.090470');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (958, 'CENG1980', 'Industrial Training', '0 Credit(s)', 'A practical training course in an industrial simulated environment. For students of the Chemical and Biological Engineering Department only. Graded P, PP or F.', '', '', '2026-08-11 14:45:49.401208');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (959, 'CENG2210', 'Chemical and Biological Engineering Thermodynamics', '3 Credit(s)', 'First law of thermodynamics for closed and open systems, enthalpy and the energy equation. PVT data and thermodynamic properties, methods for their estimation, phase equilibria. Second and third laws of thermodynamics, entropy and the Carnot engine. Examples from chemical and biological processes.', '(BIEN 2310 OR CENG 2310 OR MATH 1014 OR MATH 1020 OR MATH 1024) AND (PHYS 1111 OR PHYS 1112 OR PHYS 1312) CHEM 1008 OR CHEM 1012', '[BLD] Blended learning', '2026-08-11 15:31:17.100016');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (960, 'CENG2220', 'Transport Phenomena I', '3 Credit(s)', 'Fundamentals of transport phenomena with emphasis on physical properties, flow behavior and diffusive transport of fluids in chemical and biological systems.', '(BIEN 2310 OR CENG 2310 OR MATH 1014 OR MATH 1020 OR MATH 1024) AND (PHYS 1111 OR PHYS 1112 OR PHYS 1312) MECH 2210 AMAT 2380 BIEN 2310 or CENG 2310 or basic programming', '', '2026-08-11 15:31:17.106546');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (961, 'CENG2310', 'Modeling for Chemical and Biological Engineering I', '3 Credit(s)', 'This is the first of a sequence of two courses to train students on the foundational skills of mathematical modeling in chemical and biological engineering. Students will learn to use deterministic and stochastic models to describe physical, chemical and biological processes.', '(MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023) AND COMP 1023', '[BLD] Blended learning', '2026-08-11 15:31:17.114204');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (962, 'CENG2320', 'Modeling for Chemical and Biological Engineering II', '3 Credit(s)', 'This is the second of a sequence of two courses to train students on the foundational skills of mathematical modeling in chemical and biological engineering. More complex models involving higher-order ordinary differential equations and partial differential equations, and essential concepts in linear algebra and numerical methods will be introduced.', 'CENG 2310', '', '2026-08-11 15:31:17.148448');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (963, 'CENG3110', 'Process Dynamics and Control', '3 Credit(s)', 'Basic concepts, mathematical model, transfer function. Dynamics of first - and higher-order systems. Feedback control, controller tuning, frequency response methods.', 'CENG 1110, ELEC 3200, MECH 3610', '', '2026-08-11 15:31:17.195755');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (964, 'CENG3150', 'Integrated Chemical Process and Product Design', '5 Credit(s)', 'Conceptual design of chemical processes and products. Integration of prior knowledge in the execution of a structured design project, under the direct guidance of faculty.', '(BIEN 2310 OR CENG 2310) AND CENG 1000, AMAT 3820', '[EXP] Experiential learning', '2026-08-11 15:31:17.199447');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (965, 'CENG3210', 'Separation Processes', '3 Credit(s)', 'Phase equilibria. Ideal and nonideal mixtures. Thermodynamic properties and VLE from equations of state.', 'CENG 1110 AND CENG 2210', '', '2026-08-11 15:31:17.205058');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (966, 'CENG3220', 'Transport Phenomena II', '3 Credit(s)', 'Application of transport phenomena in chemical processes. Fluid flow in pipes and channels. Conductive, forced and free convective, and radiative heat transfer.', 'CENG 2220, MECH 3310', '', '2026-08-11 15:31:17.210722');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (967, 'CENG3230', 'Chemical and Biological Reaction Engineering', '3 Credit(s)', 'Stoichiometry and reaction equilibria. Homogeneous reactions kinetics. Mole balances: batch, continuous-stirred tank and plug flow reactors.', '(BIEN 2310 OR CENG 2310) AND CENG 1000 AND CHEM 1012', '', '2026-08-11 14:45:49.431999');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (968, 'CENG3300', 'Data Science for Molecular Engineering', '3 Credit(s)', 'This course is an introductory course on the application of machine learning methods in molecular engineering problems. It covers fundamental data processing and machine learning methods to analyze data in chemistry and biology.', 'BIEN 3300, COMP 1023, AMAT 3530, BIEN 3300', '', '2026-08-11 15:31:17.219869');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (969, 'CENG3950', 'Chemical and Environmental Engineering Laboratory', '4 Credit(s)', 'Integrated laboratory course for students in Chemical Engineering and Chemical and Environmental Engineering. Experimental modules on various unit operations and processes in chemical engineering and environmental engineering. Laboratory safety and risk assessment.', 'CENG 1110, CENG 3210 AND CENG 3230', '', '2026-08-11 15:31:17.230320');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (970, 'CENG4000', 'Special Topics', '3 Credit(s)', 'Selected topics of current interest. May be graded by letter or DI/PA/F subject to different offerings.', '', '', '2026-08-11 14:45:49.443270');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (971, 'CENG4020', 'Academic and Professional Development II', '0 Credit(s)', 'This course is designed to provide academic advising to students in the Department of Chemical and Biological Engineering, to familiarize them with possible career paths and to prepare them for the transition to the workplace or graduate studies.', '', '', '2026-08-11 15:31:17.239900');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (972, 'CENG4130', 'Plant Design and Economics', '3 Credit(s)', 'Computer-aided-design and process evaluation. Risk assessment, qualitative and quantitative assessment. Hazard analysis and safety. Plant safety and hazard analysis.', 'CENG 1110, AMAT 4810', '', '2026-08-11 15:31:17.372535');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (973, 'CENG4140', 'Energy Resources, Conversions and Technologies', '3 Credit(s)', 'The course will provide the fundamental knowledge of energy resources, their conversions and utilization technologies. Basic thermodynamics such as fuel and combustion models will be taught.', '(CENG 1110 OR ENEG 1700) AND CENG 2210 AND CHEM 1012', 'CENG 2210 OR MECH 2310', '2026-08-11 15:31:17.378789');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (974, 'CENG4510', 'Nature Engineering and DNA Nanotechnology', '3 Credit(s)', 'Integration of materials science, chemical engineering, thermodynamics, bioengineering, environmental engineering, and microelectronics. For BIEN and CENG students in their third or fourth year of study only.', 'CENG 4000O', '', '2026-08-11 15:31:17.384004');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (975, 'CENG4540', 'Nanomaterials and Applications in Chemical Engineering', '3 Credit(s)', 'Introduction to nanostructured materials and nanotechnology. Synthesis and characterization of nanostructured materials.', 'CENG 5840, NANO 5350', '', '2026-08-11 14:45:49.461101');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (976, 'CENG4620', 'Bioproducts and Processing', '3 Credit(s)', 'Survey of bioproducts, cellular production hosts, production techniques, separation and purification processes, product formulation.', 'Level 3 in HKDSE 1x Biology OR LIFS 1901', '', '2026-08-11 15:31:17.397228');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (977, 'CENG4630', 'Food Processing Technology', '3 Credit(s)', 'Principles of Food Spoilage and Preservation, Thermal Processing, Chilling & Freezing, Separation and concentration.', '', '', '2026-08-11 15:31:17.402356');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (978, 'CENG4640', 'Biomolecular Engineering', '3 Credit(s)', 'Students not studying in the Department of Chemical Engineering may enroll in the course upon instructor''s approval. Topics include molecular biology, protein engineering, and metabolic engineering.', 'CENG 2210 AND CENG 3230 AND (Level 3 in HKDSE 1x Biology OR LIFS 1901)', '', '2026-08-11 15:31:17.408346');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (979, 'CENG4650', 'Biomaterials and Drug Delivery', '3 Credit(s)', 'This course covers relevant concepts in biology, material science, and engineering principles for the design and applications of biomaterials to meet medical needs.', 'BIEN 4000B (CHEM 1010 (prior to 2022-23) OR CHEM 1012) AND (LIFS 1901 OR BIEN 2410 OR BIEN 2610) AND AMAT 4540', '', '2026-08-11 15:31:17.414408');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (980, 'CENG4670', 'Pharmaceutical Engineering', '3 Credit(s)', 'Survey of western pharmaceuticals; pharmaceutical processing technologies including reactions and separations; pharmaceutical dosage forms.', 'CHEM 1012, CENG 3210 AND CENG 3230', '', '2026-08-11 15:31:17.419464');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (981, 'CENG4710', 'Environmental Control', '3 Credit(s)', 'Wastes from the process industries. Behavior of toxic chemicals and environmental control.', '(CENG 1110 OR ENEG 1700) AND CHEM 1012 SEEN 4180 CENG 1110 AND CENG 3210 AND CENG 3230', '', '2026-08-11 15:31:17.427074');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (982, 'CENG4720', 'Environmental Impact Assessment and Management Systems', '3 Credit(s)', 'This course will review the methods for assessing environmental impacts, including environmental legislation and auditing systems.', 'ENEG 1700 CIVL 4430', '', '2026-08-11 15:31:17.430235');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (983, 'CENG4920', 'Chemical Engineering Capstone Design', '6 Credit(s)', 'A final-year project course offers practice of chemical engineering design through a group design project chosen to integrate materials covered in the curriculum.', 'CENG 3150 OR CENG 3950 CENG 4930, CENG 4940', '', '2026-08-11 15:31:17.438381');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (984, 'CENG4930', 'Chemical Engineering Thesis Research', '6 Credit(s)', 'A final-year project course offers an opportunity to conduct individual chemical engineering research under the direct supervision of a faculty member.', '(CENG 3150 OR CENG 3950) AND (CENG 4980 OR UROP 2100) CENG 4920, CENG 4940', '', '2026-08-11 15:31:17.446644');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (985, 'CENG4940', 'Chemical Engineering Industrial Project', '6 Credit(s)', 'This course provides final-year chemical engineering students with practical hands-on training in an engineering company.', 'CENG 3150 OR CENG 3950 CENG 4920, CENG 4930', '', '2026-08-11 15:31:17.451069');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (986, 'CENG4950', 'Chem-E-Car', '3 Credit(s)', 'This course is a platform for entry-level engineer students to participate in Chem-E-car competition, to design and construct a car powered by a chemical or biochemical energy source.', 'CENG 4000I', '', '2026-08-11 15:31:17.457868');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (987, 'CENG4980', 'Investigation Project', '3 Credit(s)', 'Students conduct in-depth experimental or computational investigations on selected topics in one of the departmental research areas.', '', '', '2026-08-11 15:31:17.470147');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (988, 'CIVL1220', 'Big Data for Smarter Cities', '3 Credit(s)', 'Students will discover the exciting world of smart cities. This course introduces urban big data analysis using powerful techniques like data visualization, data mining, and AI.', '', 'Fall, Spring', '2026-08-11 15:31:46.572552');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (989, 'CIVL2000', 'Academic and Professional Development for Civil and Environmental Engineering II', '0 Credit(s)', 'Continuation of CIVL 1000. This compulsory course for CIVL students is designed to provide academic advising and develop interpersonal skills in handling technical issues in the professional field. Graded P, PP or F.', 'CIVL 1000', 'Fall, Spring', '2026-08-11 15:31:46.576964');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (990, 'CIVL2010', 'Academic and Professional Development II', '0 Credit(s)', 'Continuation of CIVL 1010. Graded P, PP or F.', 'CIVL 1010', 'Fall, Spring', '2026-08-11 15:31:46.580117');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (991, 'CIVL2020', 'Industrial and BIM Training', '0 Credit(s)', 'A practical training course in an industrial simulated environment for students of the Civil and Environmental Engineering Department only. Graded P, PP or F.', '', 'Fall, Spring', '2026-08-11 15:31:46.584199');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (992, 'CIVL2021', 'Industrial Training: BIM, Drawing, Surveying, and Sustainability', '3 Credit(s)', 'This course introduces BIM, engineering drawings, engineering surveying, and sustainability, including theoretical and practical training.', 'CIVL 2020', 'Fall, Spring', '2026-08-11 15:31:46.588998');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (993, 'CIVL2035', 'Mathematical Methods for Civil Engineers', '3 Credit(s)', 'This course provides an introduction to multivariable calculus, linear algebra, and differential equations with emphasis on civil engineering applications.', 'MATH 1014 OR MATH 1020 OR MATH 1024, MATH 2011, MATH 2350', 'Fall, Spring', '2026-08-11 15:31:46.593298');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (994, 'CIVL2110', 'Statics', '3 Credit(s)', 'Application of Newton’s laws to engineering problems; equilibrium of rigid bodies and analysis of truss and frame structures.', 'PHYS 1112 OR PHYS 1312, MATH 1014 OR MATH 1020 OR MATH 1024', 'Fall, Spring', '2026-08-11 15:31:46.596761');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (995, 'CIVL2120', 'Mechanics of Materials', '3 Credit(s)', 'Analysis of stress, strain, and deformation behaviors of materials; bending of beams, and stability of structures.', 'CIVL 2110, MECH 2040', 'Fall, Spring', '2026-08-11 15:31:46.600903');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (996, 'CIVL2160', 'Modeling Systems with Uncertainties', '3 Credit(s)', 'This course deals with non-deterministic problems in civil engineering, covering stochastic concepts and simulation models.', 'MATH 1014 OR MATH 1020 OR MATH 1024, MATH 2411', 'Fall, Spring', '2026-08-11 15:31:46.606244');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (997, 'CIVL2170', 'Infrastructure Systems Engineering and Management', '3 Credit(s)', 'This course covers basic principles for analyzing engineering systems, including optimization and economic analysis.', 'MATH 2350, IEDA 3010', 'Fall, Spring', '2026-08-11 15:31:46.609997');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (998, 'CIVL2410', 'Environmental Assessment and Management', '3 Credit(s)', 'This course presents current environmental issues and management concepts with a focus on pollution problems.', '(CHEM 1010 (prior to 2022-23) OR CHEM 1012) AND CIVL 1100', 'Fall, Spring', '2026-08-11 15:31:46.613185');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (999, 'CIVL2510', 'Fluid Mechanics', '3 Credit(s)', 'An introduction to fluid mechanics, including fluid properties and applications in civil engineering.', 'MATH 2011, CIVL 2110, MECH 2210', 'Fall, Spring', '2026-08-11 15:31:46.617913');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1000, 'CIVL2810', 'Construction Materials', '3 Credit(s)', 'This course covers properties of engineering materials including concrete and related issues in construction.', 'CIVL 2120', 'Fall, Spring', '2026-08-11 15:31:46.622866');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1001, 'CIVL2910', 'Principles of Construction Management', '3 Credit(s)', 'This course provides an overview of construction management disciplines, methods, and project processes.', '', 'Fall, Spring', '2026-08-11 15:31:46.627385');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1002, 'COMP1945', 'Artificial Intelligence for Everyone: From Data to Applications', '3 Credit(s)', 'Dive into the fascinating world of artificial intelligence (AI) with this engaging course designed for non-programmers. You will explore the history and fundamental concepts of AI while discovering its diverse applications in fields like computer vision, natural language processing, deep learning and robotics. Learn how to identify AI problems, develop solutions, and understand the ethical implications surrounding AI technologies. Through case studies, hands-on projects, and insights from industry experts, you will gain practical knowledge and critical thinking skills. By the end of the course, you will be equipped to analyze AI''s impact on society and present your own innovative AI project.', 'COMP 2211, any COMP courses of 3000‐level or above', '', '2026-08-11 15:32:50.794016');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1003, 'COMP1991', 'Industrial Experience', '0 Credit(s)', 'Full-time internship training for a period of at least six weeks in an organization or company recognized by the Department for providing qualified internship training relevant to the computer science and engineering profession. Cantonese or other working languages may be used in off-campus trainings and internships, in some situations. For students of the Department of Computer Science and Engineering in their second year of study or above only. Internship coordinator''s approval is required for enrollment in the course. Graded P, PP or F.', '', '', '2026-08-11 15:32:50.801109');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1004, 'COMP2011', 'Programming with C++', '4 Credit(s)', 'This course covers programming and data structures using C++. In addition to basic programming concepts such as variables and control statements, students will learn about arrays, pointers, dynamic data allocation, linked lists, stacks, queues, binary trees, recursion, and the basics of object oriented programming.', 'COMP 1023 OR COMP 1028', '', '2026-08-11 15:32:50.807253');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1005, 'COMP2012', 'Object-Oriented Programming and Data Structures', '4 Credit(s)', 'To learn the fundamental concepts and techniques behind object-oriented programming. They include: abstract data types; creation, initialization, and destruction of objects; class hierarchies; polymorphism, inheritance and dynamic binding; generic programming using templates. To learn the object-oriented view of data structures: linked lists, stacks, queues, binary trees, and algorithms such as searching and hashing.', 'COMP 2011', '', '2026-08-11 15:32:50.813098');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1006, 'COMP2012H', 'Honors Object-Oriented Programming and Data Structures', '5 Credit(s)', 'This course is an accelerated and intensive course on concepts and techniques behind object-oriented programming (OOP) and data structures using an OOP language. It covers the major materials of COMP2011 and COMP2012, and its curriculum is designed for students with excellent programming background or substantial programming experience. Topics include: functions; pointers; abstract data types and their class implementation; static and dynamic construction and destruction of objects; data member and member functions; public interface and encapsulation; class hierarchies; polymorphism; inheritance and dynamic binding; standard template library; generic programming using templates; object-oriented view of data structures: linked lists, queues, stacks, trees, and their algorithms such as searching, sorting and hashing.', '(Grade A or above in COMP 1023) OR (Grade A or above in COMP 1021 AND Pass grade in COMP 1028)', '', '2026-08-11 15:32:50.820773');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1007, 'COMP2211', 'Introduction to Artificial Intelligence', '3 Credit(s)', 'This course provides a gentle introduction to artificial intelligence (AI), and emphasizes hands-on practical experiences with Python and AI software tools to explore AI applications. Interesting applications that have been covered in previous class offerings include, but are not limited to, medical diagnosis, predictions of customer behaviour and user attitudes, character recognition, spam mail detection, text and image classifications and recognitions, sentiment analysis, and retinal vessel segmentation. The course also explores recent advances and discusses the history and ethics of AI. Only for students in their first and second year of study or those with approval from instructor by applying requisite waiver.', 'COMP 1023 OR COMP 1028', 'AIAA 2211', '2026-08-11 15:32:50.828874');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1008, 'COMP2611', 'Computer Organization', '4 Credit(s)', 'Inner workings of modern digital computer systems and tradeoffs at the hardware-software interface. Topics include: instructions set design, memory systems, input-output systems, interrupts and exceptions, pipelining, performance and cost analysis, assembly language programming, and a survey of advanced architectures.', 'COMP 2011 OR COMP 2012H', 'ELEC 2350, MICS 2710', '2026-08-11 15:32:51.024900');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1009, 'COMP2633', 'Competitive Programming in Cybersecurity I', '0 Credit(s)', 'Cyber-attacks mounted by malicious attackers have been creating significant damage to various companies and individuals around the globe in the recent years; cybersecurity is now a high priority consideration for the major businesses worldwide. To deepen the practical knowledge in fighting against the cybersecurity threats, cybersecurity competitions are being organized every year by various institutions and organizations. This course prepares interested students with the practical knowledge for taking part in cybersecurity contests. The course will be offered as a 0-credit course in the Fall semester. Enrolled students will learn the common topics in the first 5 weeks of the Fall, getting trained in fundamental knowledge of cybersecurity. Then they will divide into two tracks in the remainder of the Fall. One track will be concentrating on topics like binary analysis, reverse engineering, the other track will be concentrating on topics like web exploitation, cryptography, computer forensics, and other miscellaneous topics. Graded P or F.', '', '', '2026-08-11 15:32:51.037185');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1010, 'COMP2711', 'Discrete Mathematical Tools for Computer Science', '4 Credit(s)', 'Basic concepts in discrete mathematics needed for the study of computer science: enumeration techniques, basic number theory, logic and proofs, recursion and recurrences, probability theory and graph theory. The approach of this course is specifically computer science application oriented.', 'Level 3 or above in HKDSE Mathematics Extended Module M1/M2', '(For students without prerequisites) MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1014 OR MATH 1020 OR MATH 1023 OR MATH 1024', '2026-08-11 15:32:51.043406');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1011, 'COMP3011', 'Database Management Systems', '3 Credit(s)', 'Principles of database systems; conceptual modeling and data models; logical and physical database design; query languages and query processing; database services including concurrency, crash recovery, security and integrity. Hands-on DBMS experience.', 'COMP 2011 OR COMP 2012 OR COMP 2012H', 'COMP 5311, IEDA 3300, ISOM 3260', '2026-08-11 15:32:51.047880');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1012, 'COMP3511', 'Operating Systems', '3 Credit(s)', 'Principles, purpose and structure of operating systems; processes, threads, and multi-threaded programming; CPU scheduling; synchronization, mutual exclusion; memory management and virtual memory; device management; file systems, security and protection.', 'COMP 2611 OR [ELEC 2350 AND (COMP 2011 OR COMP 2012H)]', 'AIAA 3511', '2026-08-11 15:32:51.070072');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1013, 'COMP4631', 'Cryptography', '3 Credit(s)', 'This course is the foundation of cybersecurity and computer security. It covers the following topics: mathematical foundations of cryptography, private-key and public-key ciphers, public key infrastructure, key management, digital signature schemes, authentication protocols, hash functions, keyed hash functions, security services, security tools, cryptographic protocols, cryptographic primitives, secret sharing.', 'COMP 4631', 'COMP 2711 OR COMP 2711H, COMP 5631', '2026-08-11 15:32:51.154348');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1014, 'COMP4632', 'Practicing Cybersecurity: Attacks and Counter-measures', '3 Credit(s)', 'This course equips students with cybersecurity knowledge and current IT practices on security risk management. Through hands-on laboratory sessions, students will understand existing IT security issues, learn how to assess IT security risks, and conduct experiments on ethical hacking. They will practice system attack and defense strategies using security tools, so as to gain practical experience to become a cybersecurity professional. The course covers current security trends, industrial practices on IT security, design requirements for secure web and mobile applications, security assessment, risk analysis and risk management. Knowledge in web programming and database administration is not essential but a plus.', 'COMP 2012 OR COMP 2012H', '', '2026-08-11 15:32:51.199605');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1015, 'COMP4900', 'Academic and Professional Development', '0 Credit(s)', 'This course is for academic and professional development of students in the programs offered by the Department of Computer Science and Engineering. Activities may include seminars, workshops, advising and sharing sessions, interaction with faculty and teaching staff, and discussion with student peers or alumni. Graded P/PP/F.', '', '', '2026-08-11 15:32:51.224251');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1016, 'COMP4910', 'Co-op Program', '6 Credit(s)', 'Students in this co-op program will be engaged in practical hands-on training for a period of at least 5 months working in an organization or company that provides qualified training relevant to the computer engineering profession. Students are required to complete a final year project under the supervision of an industrial supervisor and a faculty member during the co-op. May be graded PP. For COMP and COSC students in their third or fourth year of study only. Approval of the course coordinator is required for enrollment in the course.', 'COMP 4981, COMP 4981H', '', '2026-08-11 15:32:51.239426');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1017, 'CPEG1930', 'Academic and Professional Development I', '0 Credit(s)', 'A compulsory, one year course for Computer Engineering students only. This course is intended to offer advice to students on academic and professional matters, and to improve the students'' communication skills. This will be achieved through: (1) Meetings with an assigned advisor; (2) Professional and academic seminars, and (3) Social activities. Graded P, PP or F.', '', '', '2026-08-11 15:33:12.323473');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1018, 'CPEG1971', 'Industrial Experience', '0 Credit(s)', 'Full-time internship training for a period of at least six weeks in an organization or company recognized by the Program for providing qualified internship training relevant to the computer engineering profession. Separately, students must also complete the 1-day Safety Training module. Cantonese or other working languages may be used in off-campus trainings and internships, in some situations. For students in the BEng in Computer Engineering program under the four-year degree only. Internship coordinator''s approval is required for enrollment in the course. Graded P, PP or F.', '', '', '2026-08-11 15:33:12.330666');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1019, 'CPEG2930', 'Academic and Professional Development II', '0 Credit(s)', 'A compulsory, one year course for Computer Engineering students only. This course is intended to offer advice to students on academic and professional matters, and to improve the students'' communication skills. This will be achieved through: (1) Meetings with an assigned advisor; (2) Professional and academic seminars, and (3) Social activities. Graded P, PP or F.', '', '', '2026-08-11 15:33:12.336131');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1020, 'CPEG3930', 'Academic and Professional Development III', '0 Credit(s)', 'Continuation of CPEG 2930. This is a compulsory, one year course for Computer Engineering students only. Graded P, PP or F.', '', '', '2026-08-11 15:33:12.339829');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1021, 'CPEG4901', 'Computer Engineering Final Year Project in COMP', '6 Credit(s)', 'Each student of the Computer Engineering program is required to complete a final year project before graduation. The student is expected to conduct a project on a topic related to Computer Engineering and/or its application. The project is guided and conducted under the supervision of faculty members from the Department of Computer Science and Engineering. Credit load will be spread over the year. Instructor''s approval is required for enrollment in the course. For CPEG students only.', '', '', '2026-08-11 15:33:12.347064');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1022, 'CPEG4902', 'Computer Engineering Final Year Thesis in COMP', '6 Credit(s)', 'Each student taking the Research Option of the Computer Engineering program is required to complete an individual thesis before graduation. The student is expected to conduct a research on a topic related to Computer Engineering and/or its application. The thesis is conducted under the supervision of faculty members from the Department of Computer Science and Engineering. Credit load will be spread over the year. Instructor''s approval is required for enrollment in the course. For CPEG students only.', '', '', '2026-08-11 15:33:12.356390');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1023, 'CPEG4910', 'Co-op Program', '6 Credit(s)', 'Students in this co-op program will be engaged in practical hands-on training for a period of at least 5 months working in an organization or company that provides qualified training relevant to the computer engineering profession. Students are required to complete a final year project under the supervision of an industrial supervisor and a faculty member during the co-op. May be graded PP. For CPEG students in their third or fourth year of study only. Approval of the course coordinator is required for enrollment in the course.', 'CPEG 4901, CPEG 4902, CPEG 4911, CPEG 4912', '', '2026-08-11 15:33:12.369927');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1024, 'CPEG4911', 'Computer Engineering Final Year Project in ELEC', '6 Credit(s)', 'Each student of the Computer Engineering program is required to complete a final year project before graduation. The student is expected to conduct a project on a topic related to Computer Engineering and/or its application. The project is guided and conducted under the supervision of faculty members from the Department of Electronic and Computer Engineering. Credit load will be spread over the year. Instructor''s approval is required for enrollment in the course. For CPEG students only.', '', '', '2026-08-11 15:33:12.374755');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1025, 'CPEG4912', 'Computer Engineering Final Year Thesis in ELEC', '6 Credit(s)', 'Each student taking the Research Option of the Computer Engineering program is required to complete an individual thesis before graduation. The student is expected to conduct a research on a topic related to Computer Engineering and/or its application. The thesis is conducted under the supervision of faculty members from the Department of Electronic and Computer Engineering. Credit load will be spread over the year. Instructor''s approval is required for enrollment in the course. For CPEG students only.', '', '', '2026-08-11 15:33:12.380451');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1026, 'DASC2010', 'Calculus for Data Analytics in Science', '3 Credits', 'A concise introduction to multivariable calculus using numerical computing software. Fundamental concepts from multivariable calculus with emphasis on applications and calculations using software. Topics from vectors, curves and parametric equations, differentiation in several variables, applications in approximation, optimization and gradient descent algorithm, and integration in several variables.', 'MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:33:48.035421');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1027, 'DASC2020', 'Applied Linear Algebra for Least Squares Optimization and Machine Learning', '3 Credits', 'This course aims to equip students with the necessary knowledge and techniques in linear algebra to enable them to study linear least squares optimization and machine learning. Topics include vector and matrix operations, linear systems, matrix inverse, decomposition, eigendecomposition, and singular value decomposition. These techniques will be applied to topics including regression, classification, model validation, inversion, regularization, constrained least squares problem, clustering, and dimensionality reduction. Numerical computation is used throughout the course as a learning tool. No previous knowledge of linear algebra is assumed.', '(MATH 1014 OR MATH 1020 OR MATH 1024) AND (COMP 1021 OR COMP 1023)', '', '2026-08-11 15:33:48.040656');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1028, 'DASC2110', 'Object-oriented Programming for Data Analytics in Science', '3 Credits', 'This course is designed to provide students with a solid understanding of Core Python Programming and Python Object-Oriented Programming (POOP), as well as the skills to apply these concepts to practical data analytics applications. It is divided into three sections: Core Python programming, Object-Oriented Programming, and Graphical User Interface (GUI) applications development.', 'COMP 1021 OR COMP 1023', '', '2026-08-11 15:33:48.045256');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1029, 'DASC2210', 'A Survey on Big Data in Science and Society', '1 Credit', 'To give students a broad understanding of the theoretical and practical aspects of data analytics and their applications in data-intensive fields. Topics include an introduction to the field of data science and Artificial Intelligence (AI), the data analytics workflow, and basic data analytics toolkits for making sense of data. Graded DI, PA or F.', '', '', '2026-08-11 15:33:48.051038');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1030, 'DASC2220', 'Statistics and Probability for Data Analytics in Science', '3 Credits', 'The course is designed for students who are new to data science and provides them with a basic training of probability and statistics. Some ideas and principles of data analytics with probability and statistics are covered. In addition to the knowledge of data, students will learn some data analytical skills and have hands-on experience of processing and analyzing real datasets by using a software like R or Python.', '(COMP 1021 OR COMP 1023) AND (MATH 1014 OR MATH 1020 OR MATH 1024)', '', '2026-08-11 15:33:48.056725');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1031, 'DASC3120', 'Data Structures for Data Analytics in Science', '3 Credits', 'This course is a continuation of DASC 2110. It will cover topics on data structures, including arrays, lists, dictionaries, stacks, queues, and linked lists, as well as various searching and sorting algorithms. Students will have the opportunity to apply their knowledge to data analytics applications, with an emphasis on efficiency.', 'DASC 2110', '', '2026-08-11 15:33:48.066470');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1032, 'DASC3230', 'Statistical Modeling and Machine Learning', '3 Credits', 'This course introduces fundamental principles and techniques of statistical modeling for uncovering patterns and making predictions from data. Various statistical learning methods routinely used in the fields of data science and machine learning will be covered, including linear regression, classification, random forest, support vector machines, dimension reduction, clustering, graphical models, and neural networks. The course contents include both theoretical concepts and Python coding demonstrations to help students develop a solid understanding of the core principles and gain practical experience in algorithm implementation. Through conceptual and hands-on explorations, students will acquire essential knowledge and skills for careers in a society that is increasingly driven by data and machine intelligence.', 'DASC 2020 AND DASC 2220', '', '2026-08-11 15:33:48.071968');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1033, 'DASC3240', 'Data Visualization in Science', '3 Credits', 'Data visualization is the graphical representation of applied data science. It can also provide us with a powerful way to communicate data-driven findings, motivate analyses, and detect flaws in an infographic or dashboard. This course illustrates how to use the techniques of data visualization and discovery tools to explore, visualize and analyze data. By the end of the course, students will be able to utilize tools and packages in R or Python to enhance their skills on science communication.', 'DASC 2220', '', '2026-08-11 15:33:48.078692');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1034, 'DASC3250', 'Numerical Methods for Data Analytics in Science', '3 Credits', 'This course introduces numerical methods for various data analytic tools. Topics include numerical algorithms for linear systems, eigenvalues and eigenvectors, nonlinear equations, interpolation and approximation, numerical integration and solution of ordinary differential equations, fundamental theory and techniques of constrained and unconstrained optimizations, fundamental techniques and software for machine learning. Examples are taken from various applications in both physical and life sciences.', '(COMP 1021 OR COMP 1023) AND (DASC 2020 OR MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350)', '', '2026-08-11 15:33:48.087575');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1035, 'DASC4010', 'Practical Artificial Intelligence in Science', '3 Credits', 'This course provides students with an overview of the field of Artificial Intelligence (AI) focusing on machine learning (ML) and its applications. It introduces several basic AI/ML Python software packages with emphasis on using existing AI techniques provided by the Python packages to solve problems in science. Throughout the course, students will gain hands-on experiences of using modern AI/ML software via solving practical problems. Students without the prerequisites but possess relevant knowledge may seek instructor''s approval for enrolling in the course.', '(COMP 1021 OR COMP 1023) AND DASC 2020 AND DASC 2220', '', '2026-08-11 15:33:48.099982');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1036, 'DASC4020', 'Structured Query Language for Data Analytics', '3 Credits', 'This course is designed to provide students with a solid foundation in database design principles and the practical skills to apply these concepts in data analytics. By the end of this course, students will be able to design databases, write simple and complex SQL queries, and integrate database techniques into data analytics workflows.', 'COMP 1021 OR COMP 1023', '', '2026-08-11 15:33:48.104986');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1037, 'DASC4300', 'Capstone Project for Data Analytics in Science', '3 Credits', 'This course provides final-year Data Analytics and Artificial Intelligence in Science (DASC) students in the School of Science with a platform to apply and integrate their acquired knowledge, technical skills, and problem-solving abilities. By completing this capstone project in a chosen area of interest and under the supervision of a faculty member, students will gain practical experience in managing data analytics challenges.', '', '', '2026-08-11 15:33:48.113401');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1038, 'DASC4400', 'Data Analytics in Information Science', '3 Credits', 'This course introduces various case studies drawn from different areas of data and information sciences to illustrate the use of data analytics as a problem-solving tool. Topics include recommendation systems, data from social media and FinTech. Each application integrates mathematical models, numerical techniques and computer implementations into a coherent perspective.', 'DASC 3250', '', '2026-08-11 15:33:48.120198');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1039, 'ECON1220', 'Thinking like an Economist I: Microeconomics', '3 Credit(s)', 'Students learn the ''economic way of thinking'' in this course. We will explore fundamental microeconomic concepts and tools such as comparative advantage and specialization, demand-supply analysis, market equilibrium, government''s role in markets, game theory, and people''s interactions in order to explain and analyze consumer and producer decisions and social issues.', 'ECON 2103, ECON 2113, SOSC 1440', 'UCUG 1807', '2026-08-11 15:34:27.040932');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1040, 'ECON1221', 'Thinking like an Economist II: Macroeconomics', '3 Credit(s)', 'Students learn the ''economic way of thinking'' in this course. We will introduce the ways economists look at economy from an ''aggregate'' perspective. The course starts by introducing key macro variables that measure aggregate economic performance.', 'ECON 2123, ECON 3123, SOSC 1440', '', '2026-08-11 15:34:27.050399');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1041, 'ECON1222', 'What Economics Tells Us About Our Life and Social Policy', '3 Credit(s)', 'This course will provide students opportunities to critically read and interpret social science literature on human capital development over the life cycle. It will also discuss how this evidence could be applied in the real world policy design.', '', '', '2026-08-11 15:34:27.057765');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1042, 'ECON2103', 'Principles of Microeconomics', '3 Credit(s)', 'Theory of firm in a free enterprise system; theory of consumer demand; market structures and resource allocation; efficiency of competitive markets; selected topics on government regulation.', 'ECON 1220, ECON 2113, ECON 3113, ECON 3133, SOSC 1440, Level 3 or above in HKDSE Economics', '', '2026-08-11 15:34:27.066270');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1043, 'ECON2113', 'Microeconomics', '3 Credit(s)', 'Theory of the firm in a free enterprise system; theory of consumer demand; market structures and resource allocation; selected topics on government regulation. More depth than ECON 2103.', 'Level 3 or above in HKDSE Economics, ECON 1220, ECON 2103, ECON 3113, ECON 3133, SOSC 1440', 'FTEC 2320', '2026-08-11 15:34:27.078230');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1044, 'ECON2123', 'Macroeconomics', '3 Credit(s)', 'Theory of national income determination and business fluctuation; monetary and fiscal policies; selected topics in macroeconomic policies and open economy macroeconomics.', 'ECON 1221, ECON 3123, ECON 3143, SOSC 1440', 'FTEC 2330', '2026-08-11 15:34:27.084304');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1045, 'ECON2174', 'Mathematics for Economists', '4 Credit(s)', 'This course provides students with mathematical tools frequently used in economic analysis. Topics include single and multivariable functions, matrix algebra, multivariate calculus, and constrained optimization.', 'MATH 1003 OR MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023', 'MATH 2011, MATH 2023', '2026-08-11 15:34:27.091708');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1046, 'ECON3014', 'Managerial Microeconomics', '4 Credit(s)', 'Demand estimation, business and economic forecasting; production, innovation and cost; market structure; decision making under uncertainty.', 'One of ECON 2103 OR ECON 2113', 'ECON 3113, ECON 3133', '2026-08-11 15:34:27.134777');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1047, 'ECON3024', 'Managerial Macroeconomics', '4 Credit(s)', 'This course modifies standard models studied in introductory macroeconomics, emphasizing expectations in determining aggregate outputs.', 'ECON 2123 AND ECON 3334', 'ECON 3143', '2026-08-11 15:34:27.143682');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1048, 'ECON3113', 'Microeconomic Theory I', '4 Credit(s)', 'This course presents a detailed study of microeconomics with emphasis on analytical and mathematical approaches.', 'ECON 2103 OR ECON 2113', 'ECON 3014, SOSC 1440', '2026-08-11 15:34:27.154891');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1049, 'ECON3123', 'Macroeconomic Theory I', '3 Credit(s)', 'This course covers basic terms of macroeconomics, business cycle analysis, and current accounts.', 'ECON 2123, ECON 3024, SOSC 102I, SOSC 1440', '', '2026-08-11 15:34:27.164871');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1050, 'ECON3133', 'Microeconomic Theory II', '4 Credit(s)', 'This course builds on Microeconomic Theory I, focusing on production theory and firms'' behavior under different market structures.', 'ECON 3113', 'ECON 3014, SOSC 1440', '2026-08-11 15:34:27.179485');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1051, 'ECON3143', 'Macroeconomic Theory II', '4 Credit(s)', 'This course focuses on long-term economic growth and structural change within macroeconomic contexts.', 'ECON 3113 AND ECON 3123', '', '2026-08-11 15:34:27.187691');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1052, 'ECON3334', 'Introduction to Econometrics', '4 Credit(s)', 'Topics on the use of statistical regression techniques in modeling and estimating economic and business relationships.', 'One of ISOM 2500, MATH 2411 or MATH 3423', 'FTEC 3340', '2026-08-11 15:34:27.196319');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1053, 'ECON3700', 'Writing as an Economist', '3 Credit(s)', 'This course hones students’ ability to apply economic concepts and reasoning to real-world phenomena and express that application clearly in writing.', '(ECON 2103 OR ECON 2113) AND (ECON 2123 OR ECON 3123) AND LABU 2040', '[EXP] Experiential learning', '2026-08-11 15:34:27.204492');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1054, 'ECON4114', 'Industrial Organization and Competitive Strategy', '4 Credit(s)', 'Market structures and their implications for industry performance and strategic decision-making by firms.', 'ECON 3014 OR (ECON 3113 AND ECON 3133)', '', '2026-08-11 15:34:27.214322');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1055, 'ECON4124', 'Applied Game Theory', '4 Credit(s)', 'This course introduces the basic concepts of game theory with applications in economics and social interactions.', 'ECON 2103 OR ECON 2113', 'MATH 4321', '2026-08-11 15:34:27.221528');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1056, 'ECON4134', 'Economics of Uncertainty and Information', '4 Credit(s)', 'Research on decision making and strategic interaction under risk and uncertainty, covering expected-utility model and more.', 'ECON 4999T', 'ECON 3014 OR (ECON 3113 AND ECON 3133)', '2026-08-11 15:34:27.233264');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1057, 'ELEC1010', 'Electronic and Information Technology', '3 Credit(s)', 'This general-education course introduces the basics of electronic and information technology and their applications to daily-life consumer electronics and communication devices. Contents include the representation of signals in the time and frequency domains; digitization of information; coding for data compression and error protection; transmission of signals; cellular mobile phones and wireless communications; and the Internet. It is expected that through studying these technologies and how they address the problems encountered in the information technology area, students will also grasp the skills in solving problems with engineering approach and spirit and appreciate how these technologies impact the society.', 'CORE 1240, any ELEC courses of 2000-level or above', 'Not specified', '2026-08-11 15:35:53.758311');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1058, 'ELEC1030', 'The Rise of Autonomous Robots', '3 Credit(s)', 'This course is designed to give students with little or no technical background a general understanding about robots and their potential impact. Our society is on the verge of a new era of technology convergence: robotic devices are envisioned to become a nearly ubiquitous part of our day‐to‐day lives. New technologies such as wireless communication and voice and visual recognition will make robots become behaviour‐based, cognitive and biologically-inspired humanoids. Fundamental social, economic, and technological issues of a human‐machine society will be identified and discussed in interactive sessions.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.766853');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1059, 'ELEC1095', 'Special Topics', '1-4 Credit(s)', 'Selected introductory topics in Electronic and Computer Engineering. May be repeated for credit, if different topics taken.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.772289');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1060, 'ELEC1100', 'Introduction to Electro-Robot Design', '4 Credit(s)', 'The course introduces the fundamental knowledge on the design, implementation and evaluation of a robot and its sub-systems. It covers the basic principles of analog and digital circuits as well as robot sensing and control mechanisms.', 'Students who have completed ELEC 2200, ELEC 2350, ELEC 2400, ELEC 2420, or ELEC 3310 must obtain instructor''s approval to take this course.', 'Not specified', '2026-08-11 15:35:53.775504');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1061, 'ELEC1150', 'Information Technology Revolution: Past, Present and Future', '3 Credit(s)', 'This course introduces the scientific foundation, technology breakthroughs, and basic concepts in information technology, while leading students to reflect on the impacts of information technology in our daily life.', 'CORE 1203, ENGG 1150', 'Not specified', '2026-08-11 15:35:53.781290');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1062, 'ELEC1200', 'A System View of Communications: from Signals to Packets', '4 Credit(s)', 'Have you ever wondered what technologies go into your mobile phone or a WiFi hotspot? Through hands on work with a simple but fully functional wireless communication system, you will understand the basic engineering tools used and tradeoffs encountered in the design of these systems.', '(COMP 1021 OR COMP 1022P (prior to 2025-26) OR COMP 1023) AND (MATH 1003 OR MATH 1014 OR MATH 1020 OR MATH 1024)', 'Not specified', '2026-08-11 15:35:53.785965');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1063, 'ELEC1300', 'Introduction to Microelectronics and Integrated Circuits', '4 Credit(s)', 'This course introduces the foundations and applications of microelectronics and integrated circuits (ICs). Topics are divided into five categories covering various essential aspects.', 'MATH 1014 AND (PHYS 1114 OR PHYS 1314)', 'Not specified', '2026-08-11 15:35:53.789827');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1064, 'ELEC1910', 'Academic and Professional Development I', '0 Credit(s)', 'A compulsory, one year course for Electronic Engineering and Microelectronics and Integrated Circuits students only. This course is designed to provide academic advising to students and/or to develop students'' communication skills.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.792931');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1065, 'ELEC2100', 'Signals and Systems', '4 Credit(s)', 'This is an introductory course for signal and system analysis. The course covers signal analysis tools including continuous- and discrete-time Fourier series and Fourier transform, and Laplace Transform.', 'MATH 2011 OR MATH 2023 OR MATH 2111 OR MATH 2350 OR MATH 2351 OR MATH 2352', 'Not specified', '2026-08-11 15:35:53.797743');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1066, 'ELEC2350', 'Introduction to Computer Organization and Design', '4 Credit(s)', 'This is an introductory course to computer hardware and software organization. The topics covered include computing systems, computing programming, and hardware-software collaboration.', 'ELEC 1100', 'Not specified', '2026-08-11 15:35:53.804313');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1067, 'ELEC2400', 'Electronic Circuits', '4 Credit(s)', 'Fundamental electronic concepts for DC and AC circuits, KVL and KCL, linearity and superposition, nodal analysis, sinusoidal steady state, and phasor representation.', 'ELEC 1100 AND (MATH 1003 OR MATH 1014 OR MATH 1020 OR MATH 1024)', 'Not specified', '2026-08-11 15:35:53.807822');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1068, 'ELEC2420', 'Basic Electronics', '3 Credit(s)', 'Basic electronic concepts and components; analysis of signals in electronics.', 'MATH 1014 OR MATH 1020 OR MATH 1024 AND (PHYS 1111 OR PHYS 1112 OR PHYS 1312)', 'Not specified', '2026-08-11 15:35:53.817148');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1069, 'ELEC2600', 'Probability and Random Processes in Engineering', '4 Credit(s)', 'An introduction to statistical inference and random processes in electrical engineering.', 'MATH 1003 OR MATH 1014 OR MATH 1020 OR MATH 1024 AND (MATH 2011 OR MATH 2023)', 'Not specified', '2026-08-11 15:35:53.821505');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1070, 'ELEC2910', 'Academic and Professional Development II', '0 Credit(s)', 'A compulsory, one year course for Electronic Engineering and EE (Information and Communication Engineering) students only. Designed to provide academic advising.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.826176');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1071, 'ELEC2991', 'Industrial Experience (Electronic Engineering)', '0 Credit(s)', 'Full-time internship training for a period of at least six weeks in an organization.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.834169');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1072, 'ELEC3100', 'Signal Processing and Communications', '4 Credit(s)', 'The course provides a comprehensive overview of signal processing and communications.', '(ELEC 2100 OR ELEC 2100H) AND (ELEC 2600 OR ELEC 2600H (prior to 2022-23))', 'Not specified', '2026-08-11 15:35:53.840456');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1073, 'ELEC3120', 'Computer Communication Networks', '3 Credit(s)', 'Overview of computer networks: network architecture and switching techniques.', 'COMP 2011 OR COMP 2012H', 'Not specified', '2026-08-11 15:35:53.846239');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1074, 'ELEC3130', 'Digital Image Processing', '3 Credit(s)', 'Methods to process images on a computer.', 'ELEC 2100 AND ELEC 3100 OR ELEC 3200', 'Not specified', '2026-08-11 15:35:53.868708');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1075, 'ELEC3180', 'Data-Driven Portfolio Optimization', '3 Credit(s)', 'Modern portfolio theory with a focus on risk-adverse investors.', '(IEDA 2520 OR IEDA 2540 OR ELEC 2600) AND (MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350)', 'Not specified', '2026-08-11 15:35:53.874658');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1076, 'ELEC3200', 'System Modeling, Analysis and Control', '4 Credit(s)', 'Basic concepts, tools and techniques for modeling, analysis, and control of dynamical systems.', 'ELEC 2100 AND [MATH 2350 OR (MATH 2111 AND MATH 2351)]', 'Not specified', '2026-08-11 15:35:53.882524');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1077, 'ELEC3300', 'Introduction to Embedded Systems', '4 Credit(s)', 'Techniques on how to integrate machine-level software and hardware.', 'COMP 2611 OR ELEC 2350 OR ISDN 4000F', 'Not specified', '2026-08-11 15:35:53.887471');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1078, 'ELEC3310', 'Digital Fundamentals and System Design', '4 Credit(s)', 'Design and synthesis of digital circuits.', 'ELEC 1100', 'Not specified', '2026-08-11 15:35:53.890738');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1079, 'ELEC3400', 'Introduction to Integrated Circuits and Systems', '4 Credit(s)', 'Overview and design flow of integrated circuits.', 'ELEC 2400', 'Not specified', '2026-08-11 15:35:53.900075');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1080, 'ELEC3410', 'CMOS VLSI Design', '3 Credit(s)', 'CMOS process and design rules.', 'ELEC 4410', 'Not specified', '2026-08-11 15:35:53.905267');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1081, 'ELEC3500', 'Integrated Circuit Devices', '4 Credit(s)', 'Introductory course for semiconductor device operation principles.', 'ELEC 2400', 'Not specified', '2026-08-11 15:35:53.909890');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1082, 'ELEC3600', 'Electromagnetics: From Wireless to Photonic Applications', '4 Credit(s)', 'Applied electromagnetics from fundamentals to applications.', '(MATH 2011 OR MATH 2023) AND MATH 2351 AND PHYS 1114', 'Not specified', '2026-08-11 15:35:53.918125');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1083, 'ELEC3610', 'Quantum Mechanics for Electronic Engineers', '3 Credit(s)', 'Introductory course in quantum mechanics relevant to electronic engineering.', 'ELEC 2600 AND [(MATH 2111 AND MATH 2351) OR MATH 2350] AND (PHYS 1114 OR PHYS 1314)', 'Not specified', '2026-08-11 15:35:53.926058');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1084, 'ELEC4620', 'Photonics and Optical Communications', '4 Credit(s)', 'Introduction to optoelectronics and fiber optics for communications.', 'ELEC 3600', 'Not specified', '2026-08-11 15:35:53.931849');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1085, 'ELEC4900', 'Final Year Design Project', '6 Credit(s)', 'Each undergraduate student registered in Electronic Engineering and Computer Engineering is required to complete a final year design project.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.942487');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1086, 'ELEC4901', 'Final Year Thesis', '6 Credit(s)', 'Each undergraduate student taking the Research Option of the Electronic Engineering program is required to complete an individual thesis.', 'Not specified', 'Not specified', '2026-08-11 15:35:53.958047');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1087, 'ENEG1700', 'Introduction to Energy and Environmental Engineering', '3 Credit(s)', 'This course provides an overview of fundamental concepts and principles in energy and environmental engineering. It covers a range of topics related to energy resources, conversion technologies, environmental systems, and sustainable development. Emphasis is placed on understanding the interplay between energy production, environmental impact, and sustainable practices.', '', '', '2026-08-11 15:35:57.963537');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1088, 'ENEG2910', 'Industrial Training', '0 Credit(s)', 'This course is mainly for the module of internship and plant visits for Sustainable Energy Engineering students, offering practical training to students in the industry sectors. Students are required to take both internship for a duration in the industry sectors and plant visits, learning solid skills to solve technical problems in the working environment. For students in the Sustainable Energy Engineering Program only. Graded P, PP or F.', '', '', '2026-08-11 15:35:57.974009');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1089, 'ENEG2990', 'Academic and Professional Development I', '0 Credit(s)', 'This course is designed to provide academic advising to students, to enhance their understanding of the energy industries and career opportunities available to them, and to improve their communication skills. Students are required to attend discussion sessions with advisors and selected workshops and seminars. For students in the Sustainable Energy Engineering program only. Graded P or F.', '', '', '2026-08-11 15:35:57.978389');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1090, 'ENEG3110', 'Materials for Energy Technologies', '3 Credit(s)', 'The societal energy transition from fossil fuels to renewable sources requires novel energy technologies, with material design and engineering at the center of the innovation process. This course explains the enabling materials science and engineering behind advanced energy technologies, covering topics such as material structure-property correlations used in energy technologies, synthesis and fabrication techniques, and evaluation principles in energy applications.', 'MECH 3110, AMAT 3590, MECH 3110', '', '2026-08-11 15:35:57.989211');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1091, 'ENEG3910', 'Sustainable Energy Laboratory', '3 Credit(s)', 'This course aims to further students'' understanding of various energy technologies and systems through laboratory experiments and training in experimental techniques, data acquisition, analysis, and technical communication. For students in the Sustainable Energy Engineering program only.', '(CENG 2210 OR MECH 2310) AND (CENG 2220 OR MECH 2210)', '', '2026-08-11 15:35:57.994272');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1092, 'ENEG4000', 'Special Topics in Energy and Environmental Engineering', '1-4 Credit(s)', 'Selected topics of current interest in Energy and Environmental Engineering that are not covered by existing courses. May be graded by letter, P/F, or DI/PA/F for different offerings.', '', '', '2026-08-11 15:35:57.999748');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1093, 'ENEG4130', 'Photovoltaic Materials and Devices', '3 Credit(s)', 'This course elaborates on the fundamentals, manufacturing, and process/device engineering of photovoltaic technologies from the perspective of materials science and chemical engineering, focusing on the applications and methods relevant to the solar energy industry.', '', '', '2026-08-11 15:35:58.004906');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1094, 'ENEG4320', 'Energy Storage Technology', '3 Credit(s)', 'Electrochemical energy conversion and storage technologies such as fuel cells, batteries, and solar cells are explored to address energy and environmental problems. The course delivers fundamentals and critical insights into the principles, advantages, and limitations of such technologies.', 'CENG 2210 OR CHEM 2410', 'CBME 5830, CENG 5930, SEEN 4170', '2026-08-11 15:35:58.008761');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1095, 'ENEG4920', 'Energy and Environmental Engineering Capstone Design', '6 Credit(s)', 'This one-year project course offers practice of engineering design through a group project integrating materials from the curriculum. Enrollment requires instructor''s approval. Graded PP.', 'CENG 3150 OR ENEG 3910', '', '2026-08-11 15:35:58.014819');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1096, 'ENEG4930', 'Energy and Environmental Engineering Thesis Research', '6 Credit(s)', 'A final-year project course allowing students to conduct research under faculty supervision, leading to a Bachelor’s thesis. Enrollment subject to department approval. Graded PP.', '(CENG 3150 OR ENEG 3910) AND (CENG 4980 OR UROP 2100)', 'ENEG 4920, ENEG 4940', '2026-08-11 15:35:58.021357');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1097, 'ENEG4940', 'Energy and Environmental Engineering Industrial Project', '6 Credit(s)', 'This course provides final-year students with practical training through internships or co-ops in companies, with a credit load spread over the year. Enrollment requires department approval. Graded PP.', 'CENG 3150 OR ENEG 3910', 'ENEG 4920, ENEG 4930', '2026-08-11 15:35:58.025806');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1098, 'ENEG4980', 'Investigation Project', '3 Credit(s)', 'Students conduct in-depth investigations on selected topics related to energy, benefiting their research experience for graduate school applications. Enrollment subject to approval. Graded PP. For SUSEE students only.', '', '', '2026-08-11 15:35:58.035327');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1099, 'ENEG4990', 'Academic and Professional Development II', '0 Credit(s)', 'Continuation of ENEG 2990, focusing on career-related attributes and aspirations for students in the fourth year of the Sustainable Energy Engineering program. Graded P or F.', '', '', '2026-08-11 15:35:58.039290');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1100, 'ENGG1110', 'Engineering Solutions to Grand Challenges of the 21st Century', '3 Credit(s)', 'Throughout human history, engineering has driven the advance of civilization. In the past century engineering has recorded its greatest accomplishments, but for all these accomplishments the century ahead poses formidable problems sustaining civilization advancement. This course will broaden and raise student''s awareness of challenges faced by coming generations such as climate change, clean water and healthcare. Students will work in small groups in a collaborative learning environment to explore in details and in multiple dimensions the key issues around selected major challenges with experts in the areas. Suggested and proposed engineering solutions based on advances in science and technology will be explored and discussed. Students will be encouraged to develop and present their own innovative engineering approaches to address these major challenges.', 'Not specified', 'Not specified', '2026-08-11 15:36:37.854370');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1101, 'ENVS4012', 'Special Topics in Environmental Science', '1-3 Credit(s)', 'This special topics course will help students to gain a more in-depth knowledge and to have a better understanding on the current research topics concerned in environmental sciences. Typical topics include marine virology, freshwater/terrestrial ecology, energy and sustainability, environmental law, atmospheric modeling, air quality in Hong Kong and Geographic Information System (GIS) and its application. Key concepts are illustrated with real-life examples during field trips and case studies. May be repeated for credits if different topics are taken. For ENVS students in their third and fourth year of study only.', 'None', 'Fall/Spring', '2026-08-11 15:36:45.996515');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1102, 'ENVS4910', 'Independent Study', '1-3 Credit(s)', 'The course will cover review topics restricted to environmental science. Enrolled students will conduct research project or literature review exercise under the supervision of a faculty member. For ENVS students and visiting interns only. Students may take for credits up to two times. Approval of the course instructor is needed for students to enroll in this course. Subject to approval by the department, students may repeat the course once if a different topic is selected. Graded P or F.', 'None', 'Fall/Spring', '2026-08-11 15:36:46.004037');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1103, 'ENVS4964', 'Environmental Science Capstone Project Research', '3 Credit(s)', 'Independent work in an area of environmental science under faculty supervision. The project can be delivered through the format of literature review or research. Oral presentation and project report are required. For ENVS students only. Instructor’s approval is required for enrollment in the course.', 'None', 'Fall/Spring', '2026-08-11 15:36:46.008428');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1104, 'ENVS4974', 'Environmental Science Project Research I', '3 Credit(s)', 'Students will undertake a research project in an area of environmental science under faculty supervision. This course is the first course of a two-term research project. The research training includes experimental design, data analysis, and oral presentation. For ENVS students only. Instructor’s approval is required for enrollment in the course.', 'None', 'Fall/Spring', '2026-08-11 15:36:46.012444');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1105, 'ENVS4984', 'Environmental Science Project Research II', '4 Credit(s)', 'Continuation of ENVS 4974. The research training includes experimental design, data analysis, and presentation of research findings (poster presentation and project report). For ENVS students only. Instructor’s approval is required for enrollment in the course.', 'ENVS 4974', 'Fall/Spring', '2026-08-11 15:36:46.015884');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1106, 'FINA1303', 'Introduction to Financial Markets and Institutions', '3 Credit(s)', 'A broad introduction to financial institutions and financial markets, providing students with an understanding of how financial systems work, the functions of various financial institutions and the role of financial regulation.', 'FINA 3103, CORE 1330', 'Not Specified', '2026-08-11 15:37:44.939662');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1107, 'FINA2203', 'Fundamentals of Business Finance', '3 Credit(s)', 'For BIBU and non-SB&M students. This course provides an introduction to corporate finance for students who may not have background in accounting and business statistics. Topics include financial statement analysis, time value of money, bond and stock valuation, capital budgeting, risk and return concepts and cost of capital.', 'FINA 2303', 'Not Specified', '2026-08-11 15:37:44.947840');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1108, 'FINA2303', 'Financial Management', '3 Credit(s)', 'For SB&M students only. This course provides an introduction to corporate finance. Topics include time value of money, bond and stock valuation, capital budgeting, risk and return concepts and cost of capital.', 'ACCT 2010 AND (CIVL 2160 OR IEDA 2520 OR IEDA 2540 OR ISOM 2500 OR LIFS 3150 OR MATH 2411) FINA 2203', 'Not Specified', '2026-08-11 15:37:44.952646');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1109, 'FINA3001', 'Key Skills for Finance Professionals (A)', '1 Credit(s)', 'The course aims to develop students'' competitive edge so they are well prepared for their internships and future careers. Graded P, PP, or F. For students with major in FINA only. Students are required to complete the course within four regular terms.', 'FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:44.957095');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1110, 'FINA3103', 'Intermediate Investments', '3 Credit(s)', 'This course studies the concepts and evidence relevant to the management of investment portfolios. Topics include diversification, asset allocation, portfolio optimization, factor models, the relation between risk and return, trading, passive (e.g., index-fund) and active (e.g., hedge-fund, long-short) strategies, mutual funds, performance evaluation, long-horizon investing and simulation.', 'FINA 2203 or FINA 2303', 'Not Specified', '2026-08-11 15:37:44.961489');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1111, 'FINA3111', 'Finance Professional Development', '1 Credit(s)', 'The course aims to provide QFIN students with increased opportunities to acquire knowledge of the finance industry, connect with professionals and peers as well as to gain hands-on experience to develop interpersonal skills. The goal is to enhance their employability and long-term career success.', 'For students with major in QFIN only.', 'Not Specified', '2026-08-11 15:37:44.965265');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1112, 'FINA3203', 'Derivative Securities', '3 Credit(s)', 'This course covers options, forward contracts, futures contracts and swaps. By the end of this course, students will have a good knowledge of how derivative contracts work, how they are used and how they are priced.', 'FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:44.969866');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1113, 'FINA3303', 'Intermediate Corporate Finance', '3 Credit(s)', 'The course provides an in-depth treatment of long-term financing decisions, including estimation of the cost of capital, financial leverage, corporate distress, raising financing, dividend policy, and working capital analysis.', 'FINA 2203 OR FINA 2303, FTEC 3330', 'Not Specified', '2026-08-11 15:37:44.973212');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1114, 'FINA3810', 'Bloomberg Market Concepts Certification', '0 Credit(s)', 'The course aims to provide students with knowledge of financial markets and Bloomberg functionality. Students will need to complete all four modules to receive the Bloomberg Market Concepts certification. Graded P or F.', 'FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:44.978489');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1115, 'FINA3820', 'Refinitiv Certification Program', '0 Credit(s)', 'This course will enable students to learn more about market information and the functionality of a Refinitiv data product most commonly used by financial professionals. Students will be eligible in attending the Refinitiv Certification Assessment upon completion of the course. Graded P or F.', 'FINA 2303', 'Not Specified', '2026-08-11 15:37:44.982296');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1116, 'FINA3830', 'Bloomberg, LSEG with Artificial Intelligence Tools', '0 Credit(s)', 'This course provides students with a hands‑on, experiential introduction to professional financial data platforms and emerging AI technologies that are transforming the investment and analytics landscape. Students will develop practical skills using Bloomberg Terminal, London Stock Exchange Group (LSEG) Workspace, and a range of artificial intelligence tools commonly applied in investment analysis.', 'FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:44.985790');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1117, 'FINA4003', 'Wealth Management', '3 Credit(s)', 'This course focuses on a broad understanding of financial and investment issues arising in the context of personal wealth management. Students will gain an understanding of the nature and use of various financial products and legal instruments for developing a financial plan.', 'FINA 3103', 'Not Specified', '2026-08-11 15:37:44.989220');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1118, 'FINA4013', 'Corporate Valuation', '3 Credit(s)', 'This course teaches students how to use financial information to value firms. By the end of this course, students will be able to value firms using discounted cash flow valuation, relative valuation, and real options.', 'FINA 3303', 'Not Specified', '2026-08-11 15:37:44.994040');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1119, 'FINA4103', 'Financial Markets Trading and Structure', '3 Credit(s)', 'This course examines liquidity, market structure and trading. The focus is on examining the efficiency of trading systems and markets, the impact of new algorithmic trading on markets, the role of intermediaries and regulatory actions on market structure issues.', 'FINA 3103, FTEC 4310', 'Not Specified', '2026-08-11 15:37:44.997886');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1120, 'FINA4203', 'Mergers, Acquisitions, and Corporate Restructuring', '3 Credit(s)', 'This course analyzes mechanisms underlying the creation of value in mergers, acquisitions and corporate restructuring. Students will learn analytical techniques and tools to analyze strategy behind corporate restructuring transactions.', 'FINA 3303', 'Not Specified', '2026-08-11 15:37:45.002272');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1121, 'FINA4303', 'Fixed Income Securities', '3 Credit(s)', 'Pricing of bonds, term structure models, duration analysis and immunization techniques, valuation of interest rate options, convertible bonds, mortgage-backed securities, pricing credit derivatives, bond portfolio construction and management.', 'FINA 3103 AND FINA 3203', 'Not Specified', '2026-08-11 15:37:45.006115');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1122, 'FINA4403', 'International Finance', '3 Credit(s)', 'An introduction to the fundamental principles of international financial management and investment. Topics include: international financial markets and instruments; foreign exchange markets; foreign currency derivatives and currency risk.', 'FINA 3103', 'Not Specified', '2026-08-11 15:37:45.010473');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1123, 'FINA4413', 'Family Business', '3 Credit(s)', 'This course aims to provide students with comprehensive and practical understanding of Asian family business, which is the most prominent and significant business form in Asia.', 'FINA 4929N, FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:45.014403');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1124, 'FINA4423', 'Family Office', '3 Credit(s)', 'This course provides students with a comprehensive and most up-to-date understanding of family office, as well as insiders’ view and practical aspects of family office.', 'FINA 4929P, FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:45.017757');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1125, 'FINA4503', 'Banking and Financial Intermediation', '3 Credit(s)', 'This course examines financial intermediaries with a particular emphasis on banks. It introduces students to the nature, purpose, and management of these institutions.', 'FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:45.021246');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1126, 'FINA4513', 'Risk Management', '3 Credit(s)', 'This course covers the role of risk management in supporting companies as they strive to balance the internal and external risk factors surrounding the operation of their business model against their various stakeholder obligations.', 'FINA 3103 AND FINA 3203, FTEC 4420', 'Not Specified', '2026-08-11 15:37:45.024972');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1127, 'FINA4603', 'Venture Capital Financing', '3 Credit(s)', 'This course covers the application of financial tools and techniques to the funding and valuation of an entrepreneurial venture. It seeks to provide students with a background on the venture capital industry.', 'FINA 3303', 'Not Specified', '2026-08-11 15:37:45.030877');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1128, 'FINA4703', 'ESG Investing', '3 Credit(s)', 'This course focuses on the relevance of sustainability factors on financial performance of firms and securities. Topics include market terminology and the impact of ESG factors.', 'FINA 3103', 'Not Specified', '2026-08-11 15:37:45.034672');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1129, 'FINA4713', 'Introduction to Artificial Intelligence and Big Data in Finance', '3 Credit(s)', 'This course provides an overview of the main branches of AI and Big Data, and exposes students to real-world industry use cases to help them understand the impact that AI will have on the finance industry.', 'FINA 4929O, FINA 3103, AIAA 4330', 'Not Specified', '2026-08-11 15:37:45.038500');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1130, 'FINA4723', 'Responsible Finance', '3 Credit(s)', 'This course is designed to give students a thorough overview of responsible finance and ESG, covering fundamental topics related to ESG.', 'FINA 4929Q, FINA 2203 OR FINA 2303', 'Not Specified', '2026-08-11 15:37:45.042853');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1131, 'FINA4803', 'Quantitative Trading', '3 Credit(s)', 'For QFIN students in their fourth year of study only. This is a capstone course for final year students in the BSc Quantitative Finance program.', 'FINA 4810, FINA 4814', 'Not Specified', '2026-08-11 15:37:45.047256');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1132, 'FINA4919', 'Independent Study', '1-4 Credit(s)', 'Directed study of selected issues in Finance. Subject to approval by the department, students may repeat the course once if a different topic is selected.', 'Instructor''s approval is required for enrollment in the course.', 'Not Specified', '2026-08-11 15:37:45.052880');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1133, 'FINA4929', 'Special Topics in Finance', '0-4 Credit(s)', 'Covers current developments in finance. Topics selected by instructors.', 'None', 'Not Specified', '2026-08-11 15:37:45.056557');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1134, 'GBUS1000', 'Global Leadership Development', '0 Credit(s)', 'The course is designed to promote students'' personal development, teamwork, communications skills, career preparation, leadership capability, and a global mindset. For GBUS students only. Grade PP, P or F.', 'None', 'Not specified', '2026-08-11 15:38:01.386266');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1135, 'GBUS2010', 'Global Business Analysis', '3 Credit(s)', 'This course develops students'' proficiency in business analysis by building competence in using fundamental tools for business problem solving and delivering professional presentations. For GBUS students or students with consent from the instructor.', 'None', 'Not specified', '2026-08-11 15:38:01.392741');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1136, 'GBUS2030', 'From Zero to Exit – Journey of A Start-up', '2 Credit(s)', 'This course is designed for students who are interested in starting a business or working for an entrepreneurial company. Students are expected to understand the opportunities and challenges of a start-up journey, from coming up with their own start up idea to incepting the idea, pitching for funding and to growing their own start-up. At the end of the course, they will be equipped with the skills and knowledge necessary to kick start their business as an entrepreneur. Instructor''s approval is required for enrollment in the course. For GBUS students only.', 'Instructor''s approval required', 'Not specified', '2026-08-11 15:38:01.396735');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1137, 'GBUS2040', 'Environmental, Social, and Governance (ESG) Corporate Project', '1 Credit(s)', 'This is a required course for Global Business students that aims to cultivate students’ interest and commitment in Environmental, Social, and Governance (ESG). In this course, students will work with organizations (e.g., non-governmental organizations (NGO) or small and medium enterprise (SME)) to explore ESG initiatives and strategies. This course takes an experiential learning approach that allows students to apply their business knowledge and skill in helping organizations address pressing ESG needs so as to generate value and effect positive changes. For GBUS students. Graded P or F.', 'GBUS 2010', 'Not specified', '2026-08-11 15:38:01.401616');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1138, 'GBUS2050', 'Blue Ocean Strategy Innovation and Execution', '2 Credit(s)', 'This course introduces students to Blue Ocean Strategy, one of the most original ways of developing innovative strategy to appear in business thinking in recent years. This approach to strategy innovation distinguishes between the conventional cutthroat way most companies compete based on price and product features, known as the red ocean, and a new way of competing that emphasizes finding new markets that are free of competition – blue oceans. The course equips students with a set of highly practical tools that can be used in any organization both to develop strategic innovation and then to implement this change successfully. For GBUS students only.', 'None', 'Not specified', '2026-08-11 15:38:01.406031');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1139, 'GBUS3010', 'Global Perspectives on Contemporary Issues', '3 Credit(s)', 'This course aims to develop students'' capacity for critical reflection. To deal with human interactions in a global setting, we need to equip ourselves with a spectrum of understanding and responses that go beyond our parochial mind-set. The course exposes students to issues outside the business field, providing an opportunity to explore relevant topics concerning their community, their world and themselves. For GBUS students or students with consent from instructor.', 'None', 'Not specified', '2026-08-11 15:38:01.409571');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1140, 'GBUS3030', 'Global Business Case Studies', '4 Credit(s)', 'This is an advanced case studies course that develops students'' proficiency in conducting business problem solving and presentations under conditions simulating real business settings. For GBUS students or students with consent from the instructor.', 'None', 'Not specified', '2026-08-11 15:38:01.413981');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1141, 'GBUS3040', 'Business and ESG Management for Asia and Emerging Markets', '3 Credit(s)', 'This course intends to develop a deep understanding of the contextual factors of Asia and emerging market countries, with a specific emphasis on the risks, challenges, and mitigants to doing business in these countries. In studying key business, political, economic, social, financial, and cultural characteristics of these countries, students will recognize regional differences and learn to develop relevant business strategies. Students will also explore how country differences impact business strategies and managerial decision-making. In addition, concepts that relate to corruption, corporate governance, and ESG will be covered. For GBUS students or students with instructor''s approval only.', 'None', 'Not specified', '2026-08-11 15:38:01.420307');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1142, 'GBUS3050', 'Deal Making in Asia and Emerging Markets', '3 Credit(s)', 'This course introduces students to cross-border and cross-cultural business transactions in Asia and emerging markets. Analyzing cases studies of different types of real business deals, the course is designed to provide students with a comprehensive overview of doing business in these regions and the opportunity to strategize as corporate decision makers through discussions, role plays, and presentations. The objective is to sharpen students'' capabilities in deal structuring, financing, negotiating, and deal closing from a strategic management perspective. For GBUS students or students with consent from the instructor.', 'None', 'Not specified', '2026-08-11 15:38:01.424155');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1143, 'GBUS3060', 'Value Investing in Global Markets', '3 Credit(s)', 'This course covers the basic theory and philosophy of value investing as it has developed since Graham. The styles of important value investors including Graham and Buffett will be introduced and discussed. The basic techniques of investing will also be presented: search, valuation and the construction of a portfolio. The framework developed will be adopted in class to study specific companies. This course will only focus on equities. For GBUS students only.', 'None', 'Not specified', '2026-08-11 15:38:01.427888');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1144, 'GBUS4000', 'Special Topics in Global Business', '0-4 Credit(s)', 'The course covers a coherent collection to topics in the current development of global business. May be graded by letter, or P/F for different offerings.', 'None', 'Not specified', '2026-08-11 15:38:01.431629');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1145, 'GBUS4010', 'Independent Study', '1-4 Credit(s)', 'Faculty directed study of selected problems in global business. May be repeated for credits if different topics are taken. Graded P or F. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval required', 'Not specified', '2026-08-11 15:38:01.437288');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1146, 'GBUS4910', 'Capstone Project', '4 Credit(s)', 'The course is designed for final year GBUS students to synthesize skills and knowledge learned from the program by undertaking a challenging individual or team capstone project. For GBUS students only.', 'None', 'Not specified', '2026-08-11 15:38:01.440422');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1147, 'HUMA1000', 'Cultures and Values', '3 Credit(s)', 'The objectives of the course are for communicative capacity building through humanities knowledge and for enrichment of values and perspectives corresponding to the mission and vision of UST, rather than for enhancement of knowledge in specific branch of humanities. Values explored in this course will be drawn from those closely related to the mission and vision of UST like humanistic concerns of others and the environment, respect of differences and justice, communicative sensitivity, complexity of humanity, potential bias and fallacy in popular perceptions, values, and stereotyping, among others. The humanities disciplinary approaches will be drawn from history, philosophy, literature, anthropology, linguistics and art.', '', '', '2026-08-11 15:38:55.706214');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1148, 'HUMA1001', 'Foundational Texts in the Humanities', '3 Credit(s)', 'This course introduces students to foundational texts in the Chinese and Western humanities. In the process, it builds students'' skills at close reading, explication and analytical writing, while expanding their understanding of Chinese and Western cultures and civilizations. The course is offered in separate sections, each has its specific values and approach identified by the teacher. Each section may use different texts, either in Chinese or English. Students should review the texts to be used in each section before registration.', '', '', '2026-08-11 15:38:55.716412');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1149, 'HUMA1009', 'Special Topics', '3 Credit(s)', 'Focuses on a coherent collection of topics selected from the humanities. May be repeated for credit, if topics are different.', '', '', '2026-08-11 15:38:55.720233');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1150, 'HUMA1010', 'Introduction to Language', '3 Credit(s)', 'An examination of fundamental concepts and principles in the scientific analysis of human language, especially concerning speech sounds, syntax, meaning, language acquisition, language processing, sociolinguistics and history of languages. Students who have taken an introductory course in linguistics in universities should not enroll in this course.', '', '', '2026-08-11 15:38:55.727471');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1151, 'HUMA1030', 'Structure of the Chinese Language', '3 Credit(s)', 'The course introduces basic concepts in linguistics and how these concepts are used to describe and analyze the structure of the Chinese language, with emphasis on sounds and grammar. Moreover, similarities and differences among major Chinese dialects, especially those between Cantonese and Mandarin, will be highlighted. Characteristics of the non-Han languages spoken in the neighboring areas will also be compared with those of the Chinese dialects in order to highlight the bi-directional influences between the two groups.', '', '', '2026-08-11 15:38:55.731391');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1152, 'HUMA1060', 'Introduction to Mandarin Chinese Grammar', '3 Credit(s)', 'The course introduces students to basic concepts in Mandarin Chinese grammar and fundamental techniques of grammatical analysis. Differences between Chinese and English as well as between Mandarin and Cantonese will also be highlighted. Topics include word structure and sentence structure of Mandarin Chinese, and characteristics of Chinese grammar, etc.', '', '', '2026-08-11 15:38:55.735379');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1153, 'HUMA1100', 'Music of the World', '3 Credit(s)', 'This course surveys various folk and traditional musics of the non-Western world using an ethnomusicological perspective which involves studying how people make, perform and consume music in their respective cultural contexts. Music cultures will be discussed individually in turn, while maintaining a cross-cultural or cross-regional perspective so as to discern underlying themes and processes common to many of them as well as differences and points of divergence that make each one unique.', '', '', '2026-08-11 15:38:55.740536');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1154, 'HUMA1102', 'Enjoyment of Classical Music', '3 Credit(s)', 'From the power and beauty of the orchestra to masterpieces of the church and concert hall, students will gain an in-depth appreciation for the history and fundamentals of Western classical music. The listening and analytical skills demonstrated will bring about a deeper understanding of music as an art form. Previous musical training, albeit helpful, is not required.', '', '', '2026-08-11 15:38:55.746206');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1155, 'HUMA1107', 'Music and Film', '3 Credit(s)', 'This course explores the relationship between music and film, delving into the historical development of production and the dramatic function of film scores from mainstream to independent cinema. Focusing on the work of a variety of composers and film directors, the course will examine the collaborative process between these artists to achieve these goals. Prior knowledge of music and film, albeit helpful, is not required.', '', '', '2026-08-11 15:38:55.749681');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1156, 'HUMA1150', 'Exploration of Drawing', '3 Credit(s)', 'Drawing is a foundational form of communication extending from prehistoric times to the work of modern-day artists and designers. The creative use of lines, shapes, and textures is both a form of expression and a tool to sharpen one’s thinking and message. In this course, students will explore various types of techniques, mediums, styles, and materials, and learn concepts and history relevant to the fine arts and related industry.', '', '', '2026-08-11 15:38:55.753188');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1157, 'HUMA1210', 'Chinese Women on Screen', '3 Credit(s)', 'This course approaches Chinese women as both historical and fictional figures to unravel the complicated relationship between history and visual representation. Each week revolves around a special topic and a film about Chinese women located in a specific socio-historical period. This course is in chronological order, beginning from Republican women to contemporary female immigrants in the age of globalization. The changing images of women on screen went hand in hand with major cinematic movements in history, including the left turn in the 1930s, the rise of animation, socialist filmmaking, model opera film, underground/independent filmmaking, and the cinematic globalization. The purpose of this course is to build a foundation for students from different academic backgrounds who may have little or no knowledge of Chinese culture and history. Proficiency in Chinese is a plus but not required because all reading materials and class discussion are in English.', '', '', '2026-08-11 15:38:55.757825');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1158, 'HUMA1301', 'World Literature and Film', '3 Credit(s)', 'This course explores the complex interplay between literature and cinema. Selected novels, short stories and plays are analyzed in relation to their cinematic adaptations to gain an understanding of the masterpieces of world literature, and the possibilities and challenges involved in their cinematic manifestations.', '', '', '2026-08-11 15:38:55.761644');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1159, 'HUMA1302', 'World Literature in the 20th Century', '3 Credit(s)', 'This course examines the radical shifts in 20th-century world literature. Moving beyond the 19th century’s more unified humanistic tradition, we explore a diverse landscape characterized by distinct individual voices, fragmented perspectives, and literary movements that shaped the modern literary world.', '', '', '2026-08-11 15:38:55.765003');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1160, 'HUMA1411', 'Inside Chinese Documents and Archives: Methods and Perspectives', '3 Credit(s)', 'This course introduces students to major Chinese documents and archives, including canonical works such as the Shiji (Records of the Grand Historian) and Qijuzhu (Imperial Diaries). Beyond reading of the texts, the course also emphasizes a broader understanding - how books were made, how textual structures were designed, and how versions and variants shaped meaning in Chinese documents. It also explores the special archival tradition behind these practices. Students will learn to engage with Chinese documents not only through textual interpretation, but also through material analysis, exploring physical forms, production methods, and patterns of transmission across time. These approaches equip students with critical tools for studying Chinese history, language, culture, and philosophy.', '', '', '2026-08-11 15:38:55.775240');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1161, 'HUMA1412', 'China Through Time and Space: Chinese Historical Geography', '3 Credit(s)', 'This course introduces an important area of research in history and culture that is playing an increasingly significant role in modern humanities and social sciences. It guides students in exploring the geographical dimensions of Chinese history - an essential aspect of China studies - while also examining human-environment interactions and their influence on the development of Chinese history and culture. Students will engage with a variety of research methods and tools, with a particular focus on digital humanities approaches, such as Quantum GIS. The course will also equip students with valuable skills for both academic and professional development.', '', '', '2026-08-11 15:38:55.779127');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1162, 'HUMA1430', 'History of P. R. China''s Diplomacy, 1949-1989', '3 Credit(s)', 'This course will introduce to students the diplomatic history of the People''s Republic of China (PRC) from 1949 to 1989, focusing on Sino-USSR and Sino-U.S. relations in the context of the Cold War. Key events and leading figures will be covered, newly declassified archival materials will be presented, and critical examination and rethinking of PRC history will be introduced for discussion.', '', '', '2026-08-11 15:38:55.782746');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1163, 'HUMA1520', 'Modern East Asia', '3 Credit(s)', 'This course is a survey of the history of political, social, economic, and cultural changes in East Asia (mainly China and Japan, and to some extent, Korea) from the 1800s to the 1950s. The course studies the internal and external tensions that undermined the traditional orders, compelling China, Japan, and Korea to seek new political and social reforms. Special attention will be given to the revolutionary changes in society, thought, culture, and the rise of a new political order in twentieth-century China, Japan, and Korea.', '', '', '2026-08-11 15:38:55.786402');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1164, 'HUMA1811', 'History of Chinese Philosophy', '3 Credit(s)', 'This course aims at a historical survey of the developments of Chinese philosophy. Through an introduction to the great Chinese thinkers (like Confucius and Mo Zi), the main schools of thought to which they belong (like Confucianism and Mohism), their central theories (like humanity and universal love), and some other important philosophical concepts and issues, students will be guided to explore the evolution of these philosophies against the background of Chinese history and civilization.', '', '', '2026-08-11 15:38:55.792313');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1165, 'HUMA1920', 'Introduction to Moral Philosophy', '3 Credit(s)', 'This introductory course examines various beliefs and questions underlying our moral lives. These include the relation between morality and religion, subjectivism, relativism, self-interest, the rights and wrongs of euthanasia, etc. Also, certain ethical theories claim to help us make the right moral decisions, e.g. utilitarianism. This course is a systematic exploration of such beliefs and theories, emphasizing critical thinking and reasonable justification.', '', '', '2026-08-11 15:38:55.796124');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1166, 'HUMA2000-2001', 'Special Topics in Humanities', '3 Credit(s)', 'Focuses on a coherent collection of topics selected from the humanities. May be repeated for credit, if topics are different.', '', '', '2026-08-11 15:38:55.799589');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1167, 'HUMA2010', 'Metaphors in English and Chinese', '3 Credit(s)', 'A comprehensive study of metaphors in English and Chinese, not only as a rhetorical device, but also as an essential tool of our ordinary language and thought. The course encompasses a wide range of diverse topics such as literary metaphors, metaphors in everyday language (about time, life, change, quantity, love, anger, etc.), and metaphors in politics, mathematics, physics, artificial intelligence, and cyberspace. The approach is interdisciplinary and comparative, and most topics are to be discussed from a cross-linguistic and cross-cultural perspective. An ordinary reading knowledge of Chinese is required for enrollment.', '', '', '2026-08-11 15:38:55.803322');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1168, 'HUMA2031', 'The Cantonese Language', '3 Credit(s)', 'Study of the Cantonese language, from the perspective of linguistics which emphasizes the scientific study of language. The course focuses on the sound and the grammatical systems of Cantonese. It also examines historical and socio-linguistic issues pertinent to the development of Cantonese in the context of Hong Kong. Students enrolling in this course are expected to have basic knowledge of Chinese.', '', '', '2026-08-11 15:38:55.807700');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1169, 'HUMA2101', 'Enjoyment of Western Opera', '3 Credit(s)', 'An examination of the historical development of western opera, and selected western operas with their related literary texts. This course will also put some emphasis on works that are related to Asian cultures, and operas that will be performed in Hong Kong. No previous knowledge of opera is required.', '', '', '2026-08-11 15:38:55.811416');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1170, 'HUMA2102', 'Music Theory I: Introduction to Tonal Music', '3 Credit(s)', 'This course is an introduction to the fundamentals of Western music theory with an emphasis on reading and writing musical notation, ear training, and analytical listening. Students will develop an understanding of how texture, harmony, rhythm, dynamics, melodic development, and other parameters interact to create music. Examples used in the class will be drawn mostly, but not exclusively, from classical repertoire. Although prior musical training will be helpful, there are no prerequisites for the course.', '', '', '2026-08-11 15:38:55.817725');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1171, 'HUMA2120', 'Chinese Walnut Carving', '3 Credit(s)', 'This course examines the history and development of Chinese walnut carvings, covering the techniques, styles, and historical context.', '', '', '2026-08-11 15:38:55.823001');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1172, 'ENVR1030', 'Environment and Health', '3 Credit(s)', 'This course is intended for UG students of all backgrounds. This course aims to introduce students to the fundamental aspects of environmental health. It will explore the factors contributing to environmental health issues from both population and community perspectives.', '', '', '2026-08-11 15:39:08.123093');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1173, 'ENVR1080', 'The Smart Consumer - Uncovering the Hidden Story behind the Product Label', '3 Credit(s)', 'The choices we make in daily life - the food we eat, the clothes we wear, the products and services we use - define our lifestyle. This course will investigate everyday products and explore features that make them (un)sustainable by applying a product life-cycle approach.', 'CORE 1943', '[EXP] Experiential learning', '2026-08-11 15:39:08.131313');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1174, 'ENVR1150', 'Climate Change Impacts and Extreme Weather Events', '3 Credit(s)', 'This course aims to inspire students to take a broader perspective on environmental issues, in addition to advancing the scientific knowledge of climate change and extreme weather events. Case studies that emphasize the implications of extreme events and their linkage with global warming will be introduced.', 'CORE 1941', '', '2026-08-11 15:39:08.135817');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1175, 'ENVR1170', 'Science, Environment and Society - From Big Bang to Big Data', '3 Credit(s)', 'This course outlines how scientific methods can be used to understand the evolution of the physical, biological, and social environment around us. It highlights transdisciplinary nature and the importance of collaboration in addressing challenges.', 'CIVL 1190', '', '2026-08-11 15:39:08.140008');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1176, 'ENVR1811', 'Environmental Management and Technology Study Trip I', '1 Credit(s)', 'The course is a study trip that will provide students with the opportunity to travel to various study sites exploring environmental or sustainability issues. Students will prepare a presentation on one site and write a reflective report.', 'Instructor approval required.', '', '2026-08-11 15:39:08.145757');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1177, 'ENVR2001', 'Academic and Professional Development I', '1 Credit(s)', 'This course is designed to assist students in developing attributes necessary for professional growth, providing academic advising, enhancing understanding of environmental topics.', 'For EVMT students only.', '', '2026-08-11 15:39:08.149832');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1178, 'ENVR2002', 'Special Topics in Environmental Studies', '1-4 Credit(s)', 'Selected topics of current interest in environmental studies. May be repeated for credit if different topics are studied.', '', '', '2026-08-11 15:39:08.153665');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1179, 'ENVR2010', 'Environmental Science Fundamentals', '3 Credit(s)', 'Understanding our environment, including the ecological, biodiversity, and cycles of environmental ecosystems, human environmental impacts such as climate change, and the exploration of new green technologies.', '', '', '2026-08-11 15:39:08.156958');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1180, 'ENVR2020', 'Urban Air Pollution', '3 Credit(s)', 'The course is aimed at providing insights into how to deal with environmental problems and the interfaces with public health. It covers major topics on air pollution sources, air chemistry, and quality management.', 'CORE 2941', '', '2026-08-11 15:39:08.161620');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1181, 'ENVR2030', 'Material and Energy Balance for Environmental Management', '3 Credit(s)', 'Material and energy balance provides a quantitative account for materials and energy redistribution. It is a tool for predicting or solving practical problems like pollution control and management.', 'For EVMT students only.', '', '2026-08-11 15:39:08.165013');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1182, 'ENVR2050', 'Sustainability Thinking', '3 Credit(s)', 'This hands-on class starts by challenging traditional decision-making methods while developing new skills in systems thinking, future thinking, and strategic thinking for sustainable solutions.', 'CORE 2942', '[BLD] Blended learning, [EXP] Experiential learning', '2026-08-11 15:39:08.169561');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1183, 'ENVR2060', 'From Trash to Treasure: Transforming Waste into Resources', '3 Credit(s)', 'This course introduces sustainable management techniques for municipal solid waste focusing on waste recovery and prevention strategies.', 'CORE 2943', '', '2026-08-11 15:39:08.173074');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1184, 'ENVR2070', 'Smart Buildings for a Warming Planet', '3 Credit(s)', 'This course discusses the role of smart buildings in contributing to zero carbon emissions and the deployment of smart technologies for energy conservation.', 'CORE 2944, CIVL 1210', '[BLD] Blended learning, [EXP] Experiential learning', '2026-08-11 15:39:08.176671');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1185, 'ENVR2080', 'Circular Economy and Life Cycle Assessment', '3 Credit(s)', 'This course discusses green finance and its role in promoting sustainable economic systems. It covers assessment mechanisms for corporate performance in the context of Circular Economy.', 'SUST 1000', '', '2026-08-11 15:39:08.182312');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1186, 'ENVR2090', 'Environmental Laboratory', '3 Credit(s)', 'An integrated laboratory course designed for students to perform environmental laboratory experiments, collect and handle samples, and analyze data.', 'For EVMT students only.', '', '2026-08-11 15:39:08.186315');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1187, 'ENVR2811', 'Environmental Management and Technology Study Trip II', '1 Credit(s)', 'This course focuses on a study trip that provides students with opportunities to travel to various environmental sites where they can discuss issues with practitioners.', 'Instructor approval required.', '', '2026-08-11 15:39:08.189521');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1188, 'ENVR2900', 'Internship/Service Learning', '1 Credit(s)', 'This structured professional work experience allows students to apply their knowledge to real-world community problems. It emphasizes teamwork, communication, and professional skills.', '', '', '2026-08-11 15:39:08.193196');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1189, 'ENVR3001', 'Academic and Professional Development II', '1 Credit(s)', 'The second course designed to assist students in developing attributes necessary for professional growth and academic advising.', 'For EVMT students only.', '', '2026-08-11 15:39:08.198495');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1190, 'ENVR3004', 'Life Cycle Assessment', '3 Credit(s)', 'Students will learn how to assess environmental life cycle impacts and apply methods for Life Cycle Assessment on various products.', 'ENVR 2040, SEEN 3070', '', '2026-08-11 15:39:08.202123');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1191, 'ENVR3005', 'Environmental Risks: Principles and Practices', '3 Credit(s)', 'This course explores methods for assessing and managing environmental risks with a focus on vulnerability, exposure, and risk perception.', 'SUST 1000', '[BLD] Blended learning', '2026-08-11 15:39:08.206018');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1192, 'ENVR3010', 'Special Topics in Environmental Studies', '1-4 Credit(s)', 'Selected topics of current interest. May be repeated for credit if topics differ.', '', '', '2026-08-11 15:39:08.209807');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1193, 'ENVR3110', 'Life Cycle Assessment for Sustainable Development', '3 Credit(s)', 'This course explores LCA tools for assessing environmental impacts and integrating social practices to promote sustainable development.', 'CIVL 1170 OR ENVR 1170', '', '2026-08-11 15:39:08.214050');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1194, 'ENVR3210', 'Environmental Technology for Impact Assessment', '3 Credit(s)', 'Integrates environmental technologies with management protocols to assess qualities like air, water, noise, and waste.', 'ENVR 2010 AND ENVR 2030, CIVL 2410', '', '2026-08-11 15:39:08.219617');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1195, 'ENVR3220', 'Energy Sources and Usage', '3 Credit(s)', 'This course provides understanding of different energy resources, their use, and the socio-political issues surrounding them.', '[BLD] Blended learning', '', '2026-08-11 15:39:08.223404');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1196, 'ENVR3310', 'Green Business Strategy', '3 Credit(s)', 'Exploration of strategic opportunities arising from environmental risks and the balance needed between business and environmental health.', 'MGMT 3160', '', '2026-08-11 15:39:08.228368');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1197, 'ENVR3410', 'Economics for Environmental Policy and Management', '3 Credit(s)', 'Examines economic theories behind environmental policy-making including market failures and methods of non-market valuation.', 'ECON 2103 OR ECON 2113 OR ECON 3113, ECON 4454', '', '2026-08-11 15:39:08.232613');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1198, 'ENVR3420', 'Environmental Law and Regulations', '3 Credit(s)', 'This course covers legal concepts relevant to environmental science and the relationship between law and environmental management.', '', '', '2026-08-11 15:39:08.236371');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1199, 'ENVR4000', 'Special Topics in Environmental Studies', '1-4 Credit(s)', 'Selected topics of current interest. May be repeated for credit if the topics studied are different.', '', '', '2026-08-11 15:39:08.240546');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1200, 'ENVR4001', 'Academic and Professional Development III', '1 Credit(s)', 'This is the third course in the series aimed at assisting students in developing professional growth attributes.', 'For EVMT students only.', '', '2026-08-11 15:39:08.244792');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1201, 'ENVR4010', 'Independent Study in Environment Issues', '1-4 Credit(s)', 'Faculty directed independent study of selected topics in Environmental issues.', 'For EVMT students or by consent.', '', '2026-08-11 15:39:08.248722');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1202, 'ENVR4320', 'ESG Management and Reporting', '3 Credit(s)', 'Examines frameworks for organizations to report their ESG performance including a review of real-world cases.', 'ACCT 3630', '[BLD] Blended learning', '2026-08-11 15:39:08.252386');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1203, 'ENVR4330', 'Environmental Geographical Information System', '3 Credit(s)', 'Covers Geographical Information System (GIS) concepts and practices applied to environmental planning and management.', 'ENVR 5330, EVSM 5240', '', '2026-08-11 15:39:08.255769');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1204, 'ENVR4340', 'Social Sustainability: Risks and Challenges', '3 Credit(s)', 'Examine challenges concerning social sustainability using the Sustainable Development Goals (SDGs).', 'SUST 1000', '', '2026-08-11 15:39:08.259420');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1205, 'ENVR4350', 'Governing Green Finance: National and International Perspectives and Approaches', '3 Credit(s)', 'Covers instruments and dynamics in the governance of green finance with real-world case evaluations.', 'SUST 1000 AND ENVR 3005 AND ENVR 4340', '', '2026-08-11 15:39:08.264149');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1206, 'ENVR4470', 'Air Quality Control and Management', '3 Credit(s)', 'Discusses pollution sources, air quality management frameworks, and strategies for managing air pollution.', 'CIVL 4470', '', '2026-08-11 15:39:08.268123');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1207, 'ENVR4480', 'Climate Modeling and Risk Assessment', '3 Credit(s)', 'Introduction to climate models and their applications in understanding climate processes and assessing risks.', 'MATH 1003 OR MATH 1012 OR MATH 1013 OR MATH 1020 OR MATH 1023', '', '2026-08-11 15:39:08.271918');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1208, 'ENVR4800', 'Environmental Management and Technology Seminar', '1 Credit(s)', 'A year-long seminar series presented by faculty and guest speakers on selected topics in environmental management and technology.', 'For EVMT students only.', '', '2026-08-11 15:39:08.275961');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1209, 'ENVR4980', 'Environmental Management and Technology Capstone Project I', '3 Credit(s)', 'Each EVMT student must complete a capstone project under faculty supervision, synthesizing knowledge from their courses.', '', '', '2026-08-11 15:39:08.282516');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1210, 'ENVR4990', 'Environmental Management and Technology Capstone Project II', '3 Credit(s)', 'Continuation of ENVR 4980.', 'ENVR 4980', '', '2026-08-11 15:39:08.285974');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1211, 'IEDA1010', 'Academic and Professional Development I', '0 Credit(s)', 'A compulsory one-year course for IEDA students. This course aims to provide academic and professional advising to students and to develop their technical and non-technical communication skills. Industrial and academic seminars will be offered. Graded P or F.', '', '', '2026-08-11 15:39:58.025926');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1212, 'IEDA1020', 'Academic and Professional Development II', '0 Credit(s)', 'A compulsory one-year course for IEDA students, which is a continuation of IEDA 1010. Graded P or F.', '', '', '2026-08-11 15:39:58.036461');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1213, 'IEDA1180', 'Python for Analytics', '3 Credit(s)', 'This course introduces Python programming with a focus on its core concepts. Topics include variables, data types, operators, control structures, and the main collection types such as lists, tuples, sets, and dictionaries. Students will also learn to write functions, organize code through modularization, and understand the basics of object-oriented programming. Good programming practices, debugging techniques, and the use of development environments and AI tools will be emphasized. In addition, the course covers essential Python libraries such as NumPy, Pandas, and Matplotlib for data handling and visualization.', 'COMP 1021, COMP 1022P (prior to 2025-26), COMP 1023', '', '2026-08-11 15:39:58.050841');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1214, 'IEDA1250', 'Optimizing Decisions for Personal and Business Development', '3 Credit(s)', 'This course introduces basic analytical tools that can be used to optimize decisions for personal and business development. Students will learn different tools for scenarios encountered by individuals and companies in real life. For example, how to make decisions when one has limited resources? How to make intelligent decisions for now when one needs to make subsequent decisions later? How to make smart decisions when interacting with other people whose decisions also affect the final outcomes? How to gain insight from data by conducting basic data analytics?', 'CIVL 2170, IEDA 3010, ISOM 3710', '', '2026-08-11 15:39:58.056694');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1215, 'IEDA1280', 'Decision Analytics for Modern Society', '3 Credit(s)', 'This course introduces key concepts, methods, and applications of decision analytics to optimize decision-making in modern society. Students will explore how to make informed decisions under constraints, plan for future actions, manage risks, and interact strategically with others. The course also emphasizes strategies for succeeding in a dynamic and uncertain world by providing the tools and techniques needed to address complex and evolving challenges. Students will apply these analytical tools to solve practical problems and improve outcomes effectively.', 'IEDA 2010, CIVL 2170, ISOM 2700', '', '2026-08-11 15:39:58.062574');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1216, 'IEDA1901', 'Industrial Training and Experience', '0 Credit(s)', 'This course is intended to provide UG students with practical hands-on training in the form of either a full-time internship training or industrial training course in an industrial simulated environment. Students who opt for internship training should complete a full-time internship training for a period of at least 4 weeks in an organization or company recognized by the Department for providing qualified internship training relevant to the industrial engineering and decision analytics. Students must also complete the USTSIEB Safety Training module. For IEDA students in their second year of study or above only. Students should seek approval of the internship coordinator for enrollment in the course. Graded P, PP or F.', '', '', '2026-08-11 15:39:58.070445');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1217, 'IEDA1990', 'Industrial Training', '0 Credit(s)', 'A practical training course in an industrial simulated environment. For students of the Industrial Engineering and Decision Analytics Department only. Graded P, PP or F.', 'IEDA 1991', '', '2026-08-11 15:39:58.075038');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1218, 'IEDA1991', 'Industrial Experience', '0 Credit(s)', 'Full-time internship training for a period of at least 4 weeks in an organization or company recognized by the Department for providing qualified internship training relevant to the industrial engineering and decision analytics. Students must also complete the USTSIEB Safety Training module. For IEDA students in their second year of study or above only. Students should seek approval of the internship coordinator for enrollment in the course. Graded P or F. May be graded PP.', 'IEDA 1990', '', '2026-08-11 15:39:58.081703');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1219, 'IEDA2010', 'Introduction of Industrial Engineering and Decision Analytics', '3 Credit(s)', 'This course provides an introduction to industrial engineering and decision analytics (IEDA). It comprises of two parts. The first part introduces basic IE analytical tools, such as optimization, game theory, probability and statistics, at a conceptual level. In the second part, many of the IEDA practical concepts, including production and operations management, logistics and supply chain management, financial technology are introduced.', 'IEDA 2200 (prior to 2022-23)', '', '2026-08-11 15:39:58.087005');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1220, 'IEDA2100', 'Computing in Industrial Applications', '3 Credit(s)', 'Introduction to microprocessor technologies and computer hardware with industrial applications. Computer systems for industrial control. Digital communication, mobile computing and RFID technology.', '', '', '2026-08-11 15:39:58.092221');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1221, 'IEDA2410', 'Introduction to Modern Logistics', '3 Credit(s)', 'Introduction to the operations of common transportation modes, including road, water, and air transportation, as well as their roles in logistics. Learning the organization of modern logistics such as third-party and fourth-party logistics, international logistics, logistics coordination, and supply chain management. Discussion of characteristics, issues, and practices of the above topics.', '', '', '2026-08-11 15:39:58.097654');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1222, 'IEDA2520', 'Probability for Engineers', '3 Credit(s)', 'This is a systematic introduction to basic probability theory for engineering, including sample space and sampling methods, calculus of probability, conditional probability, joint distribution, moment generating functions, the law of large numbers and central limit theorem. Along the course, students will learn a wide range of discrete and continuous probability distributions, which are important and useful in various applications.', 'MATH 1014 OR MATH 1020 OR MATH 1024', 'ELEC 2600, ELEC 2600H (prior to 2022-23), MATH 2421, MATH 2431', '2026-08-11 15:39:58.103587');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1223, 'IEDA2540', 'Statistics for Engineers', '3 Credit(s)', 'This is a systematic introduction to statistics for engineering, including descriptive statistics, point and interval estimation, hypothesis testing and linear regression analysis. In addition to theories, students will be taught a statistical language (R or Python) and have hands on experience of processing and analyzing data.', 'IEDA 2520', 'MATH 2411, ISOM 2500, LIFS 3150', '2026-08-11 15:39:58.108999');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1224, 'IEDA3010', 'Prescriptive Analytics', '3 Credit(s)', 'Introduction to optimization methods. Topics include linear programming, integer programming, nonlinear programming, decision-making under uncertainty, and sequential decision-making. Software packages are used to solve data-driven decision-making problems in engineering and business.', 'MATH 2111', 'CIVL 2170, ISOM 3710, SMMG 3030', '2026-08-11 15:39:58.117132');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1225, 'IEDA3130', 'Ergonomics and Safety Management', '3 Credit(s)', 'Introduction to ergonomics and safety management. Work environment stressors and their reduction. Technical compliance of Occupational Safety and Health Ordinance and their respective laws in UK, EC, and US. Accident causation models.', 'IEDA 2520 AND IEDA 2540', '', '2026-08-11 15:39:58.123165');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1226, 'IEDA3230', 'Engineering Economics and Accounting', '3 Credit(s)', 'Application of microeconomics to engineering and managerial decision making. Basic accounting cash flow analysis of capital investment. Present worth, rate of return, taxes and depreciation, capital budgeting, cost accounting, risk and uncertainty.', 'FINA 2203, FINA 2303', '', '2026-08-11 15:39:58.129946');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1227, 'IEDA3250', 'Stochastic Models', '3 Credit(s)', 'Poisson process, Markov process, and Markov decision processes; inventory theory, reliability, queuing theory. Application softwares.', '(IEDA 2520 AND IEDA 2540) OR (MATH 2411 AND MATH 2421)', '', '2026-08-11 15:39:58.135909');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1228, 'IEDA3270', 'Data-Driven Quality Technology', '3 Credit(s)', 'Control charts and statistical on-line quality control methods, off-line quality control and parameter design, modern quality philosophy and Taguchi method.', '(IEDA 2520 AND IEDA 2540) OR MATH 2411, ISOM 3730', '[BLD] Blended learning', '2026-08-11 15:39:58.141054');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1229, 'IEDA3300', 'Industrial Data Systems', '3 Credit(s)', 'Fundamental concepts on database, network, object-oriented methodology, and system integration; design and development of database systems for productions (e.g. MRP), manufacturing (e.g. CAPP), and management (e.g. BPR).', 'COMP 1021 OR COMP 1022P (prior to 2025-26)', 'COMP 3311, ISOM 3260', '2026-08-11 15:39:58.155640');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1230, 'IEDA3302', 'E-Commerce Technology and Applications', '3 Credit(s)', 'A significant portion of modern commercial activity is dependent on electronic commerce. In this course, students will gain familiarity with common e-commerce business models and get an understanding of how and when they are used. The course will cover important enabling technologies, including basics of internet communication, security, clouds, as well as low level technology enabling functions such as localization and tracking.', 'COMP 1021 OR COMP 1022P (prior to 2025-26)', 'IEDA 3560', '2026-08-11 15:39:58.161139');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1231, 'IEDA3330', 'Introduction to Financial Engineering', '3 Credit(s)', 'This course is intended to provide an introduction to important aspects of financial engineering. Specifically, this course will primarily cover fundamentals of the financial system, interest rate and term structure, various financial markets, financial derivatives, option pricing and hedging, risk management, and financial modeling.', 'CIVL 2160 OR ELEC 2600 OR (IEDA 2520 AND IEDA 2540) OR ISOM 2500 OR MATH 2411 OR MATH 2421 OR MATH 2431', 'FINA 3203, FINA 4303', '2026-08-11 15:39:58.166616');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1232, 'IEDA3410', 'Routing and Fleet Management', '3 Credit(s)', 'Applications and algorithms for network optimization, vehicle routing, shortest path problems, maximum flow problems, matching models and dynamic vehicle allocation.', 'IEDA 3010', '', '2026-08-11 15:39:58.171865');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1233, 'IEDA3460', 'Demand and Supply Analytics', '3 Credit(s)', 'This course will introduce students to an array of tools to efficiently manage supply and demand networks. Topics include service and inventory trade offs, stock allocation, pricing, markdown management and contracts, timely product distribution to market while avoiding excess inventory, allocating adequate resources to the most profitable products and selling the right product to the right customer at the right price and at the right time.', 'IEDA 2520', '', '2026-08-11 15:39:58.176367');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1234, 'IEDA3560', 'Predictive Analytics', '3 Credit(s)', 'This course focuses on how companies identify, evaluate, and capture decision analytic opportunities to create value. Basic analytic methods as well as real corporate cases studies will be covered. The analytical methods include ways to use data to develop insights and predictive capabilities using machine learning, data mining, and forecasting techniques.', 'IEDA 2540', 'COMP 4211, IEDA 3302', '2026-08-11 15:39:58.180397');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1235, 'IEDA4000', 'Special Topics', '1-3 Credit(s)', 'Selected topics in Industrial Engineering, Logistics Management or Decision Analytics. May be repeated for credit, if different topics are covered.', '', '', '2026-08-11 15:39:58.186277');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1236, 'IEDA4100', 'Integrated Production Systems', '3 Credit(s)', 'Basic concepts and techniques in design and operational control of integrated production systems, including MRP, JIT, forecasting, production planning, inventory control, and shop floor control and scheduling.', 'IEDA 2520 AND IEDA 3010', 'ISOM 2700', '2026-08-11 15:39:58.189970');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1237, 'IEDA4130', 'System Simulation', '3 Credit(s)', 'Basic concepts and algorithm of discrete-event simulation, generation of random variates, modeling input distributions, statistical analysis of simulation outputs, verification and validation of simulation models, comparisons and optimization via simulation, simple spreadsheet simulation, intermediate modeling and analysis with a commercial simulation package.', 'IEDA 2520', 'ISOM 4720', '2026-08-11 15:39:58.194524');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1238, 'IEDA4180', 'Service Engineering and Management', '3 Credit(s)', 'Service system design, service level, quality of service, service product life cycle, measurements, design for serviceability, analysis, productivity in services, client satisfaction, training and services logistics.', 'IEDA 2520', '', '2026-08-11 15:39:58.199122');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1239, 'IEDA4200', 'Design of Logistics and Manufacturing Systems', '3 Credit(s)', 'Facility location, process and material flow analysis, space allocation and plant layout, computerized layout planning, material handling equipment, material handling system design.', 'IEDA 3010', 'SMMG 4630', '2026-08-11 15:39:58.203652');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1240, 'IEDA4331', 'Quantitative Methods in Financial Engineering', '3 Credit(s)', 'The course covers some quantitative methods commonly used in financial engineering for modeling, analyzing, and solving basic financial engineering problems. The course will start with basic concepts in stochastic calculus and stochastic differential equations.', '(FINA 3203 OR IEDA 3330) AND (IEDA 3250 OR ISOM 2500)', '', '2026-08-11 15:39:58.207610');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1241, 'IEDA4410', 'Data Driven Supply Chain Management', '3 Credit(s)', 'An introduction to the design, development, and management of integrated logistics supply chain systems, including inventory management, distribution channels, and information systems.', 'IEDA 4100', 'EEMT 5300, ISOM 3770, SMMG 4640', '2026-08-11 15:39:58.211964');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1242, 'IEDA4420', 'Dynamic Pricing and Revenue Optimization', '3 Credit(s)', 'This course focuses on capacity allocation, dynamic pricing and revenue management. It covers pricing implications of revenue management models for perishable and/or products in limited supply.', 'IEDA 3010 AND IEDA 3250', '', '2026-08-11 15:39:58.217126');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1243, 'IEDA4500', 'Engineering Foundations of FinTech', '3 Credit(s)', 'FinTech, short for financial technology, is a remarkably booming industry that aims at improving traditional financial services by applying novel technologies. In this course, students will acquire an understanding of popular financial technologies and learn how they are employed to enhance the effectiveness and efficiency of the existing financial systems.', 'IEDA 3330 OR FINA 3203', '', '2026-08-11 15:39:58.222117');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1244, 'IEDA4510', 'Systems Risk Management', '3 Credit(s)', 'This course seeks to develop the knowledge and analytical skills for risk management in operations. It covers different technical approaches for systems risk management, such as evaluating and modeling risk from data, making robust operational plans, preparing contingency plans, and generating disruption recovery solutions.', 'IEDA 3010 AND IEDA 3250', '', '2026-08-11 15:39:58.226306');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1245, 'IEDA4520', 'Numerical Methods for Financial Engineering', '3 Credit(s)', 'The course aims to introduce various important numerical methods that have been widely applied in financial engineering. The topics consist primarily of lattice methods, Monte Carlo simulation, and finite difference methods.', '(IEDA 3250 OR ISOM 2500) AND (IEDA 3330 OR FINA 3203)', '', '2026-08-11 15:39:58.230145');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1246, 'IEDA4900', 'Independent Study in Industrial Engineering and Decision Analytics', '3 Credit(s)', 'Undertaken by students under the supervision of a faculty member. Course requirements include readings on the relevant topic and a research or survey project specifically defined for the research option.', '', '', '2026-08-11 15:39:58.236276');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1247, 'IEDA4901', 'Final Year Thesis', '6 Credit(s)', 'Students who opt for the research option must register for this course instead of the final year project. The course requires a research project under the supervision of an instructor, and the results must be reported in the form of a thesis or a research paper.', '', '', '2026-08-11 15:39:58.239655');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1248, 'IEDA4920', 'Decision Analytics Final Year Project', '6 Credit(s)', 'This is a one-year course undertaken by students in their final year. The course will require students to engage in a company sponsored project that provides practical experience to the students on topics they have learnt in their major courses.', 'IEDA 4901, IEDA 4960', '', '2026-08-11 15:39:58.244723');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1249, 'IEDA4950', 'Industrial Engineering Special Project', '1-4 Credit(s)', 'A special project supervised by a faculty member. A project proposal and a final report are required. May be repeated for credit if the projects cover different topics.', '', '', '2026-08-11 15:39:58.250072');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1250, 'IEDA4960', 'Industrial Engineering and Engineering Management Final Year Project', '6 Credit(s)', 'A one year long final year project related to industrial engineering and engineering management. Supervised by a faculty member. A project proposal and a final report are required.', 'IEDA 4901, IEDA 4920, IEDA 4990 (prior to 2021-22)', '', '2026-08-11 15:39:58.254144');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1251, 'ISDN1001', 'Introduction to Integrative Systems and Design', '3 Credit(s)', 'This is a foundation course in which students will learn about the societal, economical, and cultural impact of integrative systems and the importance of integrating design into the creation of integrative systems. Through lectures, discussions, case-study and presentation, hands-on dis-assembly and re-assembly exercises, students will learn about the basic design principles, design terminology, design skill-sets, design thinking and process, and how a good design relates to the design principles. Students will also learn about what is an integrative system and the importance of using technology to build an integrative system and how it is decomposed into different sub-systems that involve multiple technology components, interacting with each other.', '', '', '2026-08-11 15:40:45.738044');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1252, 'ISDN1002', 'Redefining Problems for the Real Needs', '3 Credit(s)', '', '', '', '2026-08-11 15:40:45.744040');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1253, 'ISDN1004', 'Sketching', '1 Credit(s)', 'This course focuses on developing the skills to generate, visualize and define design concepts in 2-D and 3D in both paper and digital formats. Topics covered include freehand sketching on paper, freehand sketching on mobile devices, illustrating the basics of perspective and orthogonal drawing, storyboarding, and visual communication. Students will develop skills in sketching both organic as well as geometric forms.', '', '', '2026-08-11 15:40:45.747674');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1254, 'ISDN1006', 'Human-centered Innovation', '3 Credit(s)', 'A project-based, experiential course that exposes students to practice the five modules in design thinking - “Empathize”, “Define”, “Ideate”, “Prototype” and ‘Test”. The unmet needs will be identified by observing the daily routine of real services and people. Research on existing solutions and how to conduct the stakeholder and market analyses will be taught for designing the needs screening matrix in needs selection. Students are going to unlock their creativity potentials through the in-class activities.The new ideas of addressing the unmet needs are generated in which the ideas are grouped ad organized into a concept map. To translate a promising concept from an idea into a rudimentary design, the concept exploration is facilitated by prototyping. The prototypes are tested by the potential users. This course aims to develop students’ communication, interpersonal, analytical, design and project management skills.', 'ISDN 1002, ISDN 1007', '[EXP] Experiential learning', '2026-08-11 15:40:45.752846');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1255, 'ISDN1007', 'From Design Thinking to Design Action: Defining Problems for Better Solutions', '3 Credit(s)', 'This course combines design research and design thinking to equip students with the skills to address real-world challenges. Following the five modules of “Empathize”, “Define”, “Ideate”, “Prototype”, and “Test”, students will learn to explore and understand complex problems using design research methods. Starting with contextual and user research, students will identify the primary stakeholders and their needs in a given context. The second part of the course will focus on ideating and prototyping innovative solutions to the identified problems, turning creative ideas into actionable solutions. Throughout the course, students will engage in hands-on projects, working collaboratively to develop their communication, analytical, and project management skills.', 'ISDN 1002, ISDN 1006', '', '2026-08-11 15:40:45.757071');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1256, 'ISDN1010', 'Academic and Professional Development I', '0 Credit(s)', 'This course is designed to provide academic advising to enhance personal and professional skills for ISD students throughout their 4 years of study. Activities involve workshops and a mentoring program. For ISD students only. Graded P, PP or F.', '', '', '2026-08-11 15:40:45.761049');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1257, 'ISDN1011', 'Industrial Training', '0 Credit(s)', 'This course is designed to provide practical technical and design training to ISDN students. For ISDN students only. Graded P, PP or F.', '', '', '2026-08-11 15:40:45.764745');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1258, 'ISDN1012', 'Industrial Experience', '2 Credit(s)', 'This course aims to provide students with industrial experience both locally and globally. Under the guidance of the instructor, students will undertake internships (at least 6 consecutive weeks or 240 hours of full-time internships or an equivalent of 240 hours of part-time internships) with potential collaborators, including government departments, NGOs, and engineering/technology/design-related companies. Course assessment will be based on the supervisor’s assessment and the student’s reflective report. This course is for ISD/ISDN/IDT students only and instructor approval is required. Graded P or F.', '', '', '2026-08-11 15:40:45.770284');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1259, 'ISDN1120', 'Bring AI to Your Side', '3 Credit(s)', 'This introductory course offers a hands-on approach to utilizing AI tools for creating personalized text, images, and 3D models. Designed specifically for non-programmers, the course discusses the strengths and limitations of current AI technologies, empowering students to enhance their familiar problem-solving workflows with AI. The course aims to inspire creativity and motivate students to explore potential applications of AI in addressing everyday challenges, including personalized game creation, fashion design, personalized fabrication, and more.', '', '', '2026-08-11 15:40:45.774221');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1260, 'ISDN1130', 'Introduction to Eco-Design', '3 Credit(s)', 'A project-based course that introduces students to the basics of Eco-design. Eco-design is the practice of designing for the purpose of conserving, sustaining and the propagating of Nature’s eco-systems. Given the current crisis of climate change and environmental degradation, students will learn how to use ideas and insights from ‘Science’, ‘Technology’, ‘Arts’, ‘Politics’, ‘Ethics’ and ‘Spirituality’, to develop meaningful designs for products, services and/or communication strategies, that balance man-made needs with the integrity of natural eco-systems. Ideas from leading research in sustainable and ecological practices will be incorporated with methodologies from Design Thinking, Circular Design, Design Futuring and Design Fictions. Students will at the end of the course be able to understand the interdisciplinarity and interrelatedness of Eco-design and be able to use this understanding in their own daily practices and/or chosen professions.', '', '', '2026-08-11 15:40:45.777891');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1261, 'ISDN1200', 'Design Thinking for Technological Innovations', '3 Credit(s)', 'This course explores the dynamic intersection of innovation and technology in today''s rapidly evolving landscape. Students will apply design thinking as a human-centered approach to driving innovation practices, examine the progression and integration of emerging technologies, and learn how to translate from ideas to innovation and entrepreneurship. The course emphasizes hands-on projects, case studies, and collaborative work to foster an innovative mindset and equip students with the tools to drive technological advancements in various industries. By the end of the course, students will work in teams on a mini project to gain hands-on experience in innovation.', 'ISDN 1001', '', '2026-08-11 15:40:45.781279');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1262, 'ISDN2000', 'What is Design and Why Design?', '3 Credit(s)', 'This course introduces what design is and why it is valued. Design is the purposeful act of creative problem solving. Students learn about design history, famous design styles, design thinking, sustainable design principles, sustainable design skills through a project-based learning approach. Students then experience several stages of a creative design process. The process begins by asking students to identify real-world problems through social, business, scientific, and sustainable-focused technological perspectives. To add specificity, students will be able to describe the behaviors and needs of social interactions, observe demographic phenomena, assess business viability, and identify and understand technological changes and sustainable impacts, etc. After defining a problem statement, students will be guided to generate creative solutions using brainstorming tools and creative thinking skills. Selected solutions will be presented in form of prototypes and open for user feedback. This course emphasizes the appreciation of the role and significance of design for our society. The final project of this course will focus on sustainability and how to achieve sustainable goals through a 4-week group design project.', 'CORE 2261', '', '2026-08-11 15:40:45.787710');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1263, 'ISDN2001', 'Second Year Design Project I', '1 Credit(s)', 'This course is the first part of a one-year project course offered to second year students. The project requires application of technology and design to develop innovative solutions to a challenging problem. Each student is assigned a component of a large project, which is sponsored by industry. Project planning. Distribution of tasks among the team members. Identification of the problem through interactions with the staff of the sponsored company. Ideation. Design concept generation. Selection of ideas. Prototyping. Testing and redesigning. Instructor''s approval is required for enrollment in the course.', 'ISDN 1002 OR ISDN 1006 OR ISDN 1007, ISDN 1004 AND ISDN 2300', '', '2026-08-11 15:40:45.791632');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1264, 'ISDN2002', 'Second Year Design Project II', '3 Credit(s)', 'This course is the second part of a one-year project course offered to second year students. The project requires application and integration of technology and design to develop innovative solutions to a challenging problem. Each student is assigned a component of a large project, which is sponsored by industry. The focus of this course is testing and redesigning of the design concept created in 2001. The process is repeated until a final design emerges. Instructor''s approval is required for enrollment in the course.', 'ISDN 2001, ISDN 2400', '', '2026-08-11 15:40:45.795152');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1265, 'ISDN2010', 'Academic and Professional Development II', '0 Credit(s)', 'Continuation of ISDN 1010. Graded P, PP or F.', '', '', '2026-08-11 15:40:45.798523');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1266, 'ISDN2110', 'From Ideas to Assets: Practice of the Creative Economy System', '3 Credit(s)', 'This course focuses on the design and production of intellectual property (IP) and related products, emphasizing the development of powerful visual identity and associated designs with varied craftsmanship. Through project-based learning and hands-on practice of artistic techniques, students will engage in the pathways for inspiration capture, conceptualization, and art expression. The course is expected to unlock students'' innovative thinking while providing a self-healing experience through artistic mediums, benefiting both future startups and current life quality.', 'ISDN 3000A', '', '2026-08-11 15:40:45.803581');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1267, 'ISDN2200', 'Systems Thinking and Design', '3 Credit(s)', 'This course in Systems Thinking aims to gain students systemic understanding when tackling global challenges in the real world. For example, as widely understood that climate change is more than merely a technological problem. Rather, it is systemic problem underlying aspects of people, technology and environment that are all interconnected in the entire environment. With emphasis on systems, it is important to broaden students'' perspective from merely viewing problems in isolation but in relationship with its surroundings. This course stresses on attaining a systemic perspective when approaching technological design in integrative systems. The course introduces studies of systems thinking to aid students systemic understanding. In the course, students are given specific assignment, such as intelligent mobility or waste management systems, and work in groups. At the beginning, they define the systems and analyze specific issues underlying in the systems. Afterwards, they suggest, justify and evaluate their solutions in systemic context.', '', '', '2026-08-11 15:40:45.808097');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1268, 'ISDN2210', 'Introduction to Brand Design', '3 Credit(s)', 'A project-based course that introduces students to the basics of Brand Identity Design. Brands and branding are key business tools and techniques. An understanding of how brands are strategically designed and developed can lead to greater coherence between the design disciplines and business development. This course will introduce to the student the basic principles and practices of brand identity design and development through the lens of graphic design and visual communications. Brand assets such as the logo, brand fonts and secondary graphics, brand tone, tools and touch points (and much more); and how they are structured, designed and developed via brand frameworks and branding strategies will be explored through a series of lectures and in-class exercises. The course will culminate in an extended hands-on project. Guest speaker(s) will also be invited to give context and insight into the practice and profession.', 'ISDN 4000P', '', '2026-08-11 15:40:45.811877');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1269, 'ISDN2300', 'Introduction to 3D Design', '3 Credit(s)', 'This course will provide the theoretical principles and real-life examples of a wide variety of digital design technology. The course includes using computer-aided techniques to convert sketches into digital 3D models, animate static 3D models into computer animation, and finally render the 3D models to become the final product image or video. The course also describes how the 3D models and renderings are being used in Virtual Reality and Augmented Reality. Topics covered will include Photogrammetry, Fundamentals of 3D Modeling, NURBS, Principles of Traditional Animation, Computer Animation, 3D Rendering, Virtual Reality and Augmented Reality. Instructor’s approval is required for enrollment in the course.', '', '', '2026-08-11 15:40:45.815477');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1270, 'ISDN2400', 'Physical Prototyping', '3 Credit(s)', 'The aim of this course is to take design concepts to reality. Students will convert their concepts that were created using sketches or 3D design software to tangible prototypes. Quick prototyping using various materials will provide hands-on experience. The course will also provide knowledge on various 3D prototyping technologies so that students can explore the most suitable means to generate functional and aesthetically pleasing prototypes. Hands-on experience with assembly to generate complete prototypes will be emphasized.', 'ISDN 2300', '', '2026-08-11 15:40:45.820296');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1271, 'ISDN2601', 'Exploring the World through Smart Mechatronics', '3 Credit(s)', 'This course provides an introductory experience into the design and application of smart mechatronic systems on building integrative systems. Students will learn how smart integrative systems are built to sense and interact with humans and the environment, to serve everyday real-world needs. The course includes fundamental theory and also practical hands-on labs and projects for the student to acquire the basic knowledge of designing mechatronic systems, using embedded system to control and practice design thinking process. In the lab sessions, students design and build a succession of mechatronic subsystems, leading to an integrated system in a final project. Lecture topics include embedded system design, basic electronics, use of sensors and actuators, system modelling, measurement and control, and appreciation of the impact of smart mechatronics system in solving real-world problems. In the final project, students will apply design thinking approach to meet the project requirements, specified from users’ perspective.', 'ISDN 4000I, ELEC 1100', '', '2026-08-11 15:40:45.824144');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1272, 'ISDN2602', 'Internet of Things: Integrative System Design', '3 Credit(s)', 'IoT (Internet of Things) is the key enabling technology for many integrative systems. A design thinking-led approach is used to motivate and engage students to design IoT systems, leading to user-centric solutions. Through the design of IoT systems, students learn fundamental theories and gain hands-on working experience on several key components for IoT systems, including circuits and sensors, signal processing, embedded systems, and communication and networking. In the final project, students will apply design thinking approach to meet the project requirements, specified from users’ perspective.', 'ISDN 4000G, ELEC 1200', '', '2026-08-11 15:40:45.828035');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1273, 'ISDN2603', 'Materials, Shape and Design', '3 Credit(s)', 'This is a course on design and materials infused with design thinking. It covers the relationship between materials and their properties that inform their use in the design of things. We take a design-focused view, expanding the design requirements into an exploration of material properties for given shapes. This will lead naturally into a deeper understanding of functional properties and structures of materials on the one hand, and deformation and failure modes of solid mechanical objects on the other. Various material families, including metals, alloys, polymers, copolymers, and composites will be studied, and a basic understanding of how shape affects mechanical performance will be introduced. In the projects, the choice of optimal materials and shapes of an object will be determined using the design thinking approach. Instructor''s approval is required.', '', '', '2026-08-11 15:40:45.831509');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1274, 'ISDN3000', 'Special Topics', '1-3 Credit(s)', 'This course will cover selected advanced topics related to system engineering, robotics, smart cities, biomedical applications, and/or design thinking. It may be repeated for credit if different topics are offered. Grading may be based on letter grades or a satisfactory/unsatisfactory (DI/PA/F) system, depending on the specific offering.', '', '', '2026-08-11 15:40:45.835703');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1275, 'ISDN3001', 'Third Year Design Project I', '3 Credit(s)', 'This course is the first part of a one-year project course offered to third year students. Each student is assigned a component of a large project, which is sponsored by industry. The project is expected to be of increased technical complexity compared with the second year project. Project planning. Distribution of tasks among the team members. Identification of the problem through interactions with the staff of the sponsored company. Ideation. Design concept generation. Selection of ideas. Prototyping. Testing and redesigning. In addition, students have to consider sustainability, manufacturability, and marketability of the proposed product solutions, which have to fulfill needs of the client under a budgetary constraint. Students are expected to spend less time on planning and idea generation as they have already gained these experiences in the second year but more time on prototyping and testing, as this project requires application and integration of more advance technologies and design. Instructor''s approval is required for enrollment in the course.', 'ISDN 2001', '', '2026-08-11 15:40:45.841326');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1276, 'ISDN3002', 'Third Year Design Project II', '3 Credit(s)', 'This course is the second part of the third-year project course offered to third year students. The focus of this course is testing and redesigning of the design concept generated in 3001. The process is repeated until a final design emerges. Instructor''s approval is required for enrollment in the course.', 'ISDN 3001, ISDN 2400', '', '2026-08-11 15:40:45.844635');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1277, 'ISDN3004', 'Advanced Sketching', '2 Credit(s)', 'The course enhances the visual communication and creativity skills of students through a palette of advanced sketching skills such as how to draw in perspective and; how to develop visual narratives vis-à-vis scripts and storyboards. A larger spectrum of tools and materials will be introduced such as drawing with markers and other mixed-media. The course contains extensive in-studio sketching sessions where students will explore various advanced sketching approaches under the guidance of the instructor; to further develop their individual creativity and visual communication skills. The course requires basic knowledge on sketching.', 'ISDN 4000L, ISDN 1004', '', '2026-08-11 15:40:45.848741');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1278, 'ISDN3010', 'Academic and Professional Development III', '0 Credit(s)', 'Continuation of ISDN 2010. Graded P, PP or F.', '', '', '2026-08-11 15:40:45.854720');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1279, 'ISDN3150', 'AI for Design', '3 Credit(s)', 'This course explores the intersection of artificial intelligence (AI) and design, providing students with a general understanding of how AI tools can enhance the design process. Through practical exercises and case studies, students will learn how to use AI to generate design ideas and layouts, predict user behavior and preferences, and create human-centered designs. The course will also cover the ethical considerations of using AI in design, including data bias and privacy concerns. By the end of the course, students will acquire hands-on experience with AI tools and models and be able to incorporate them into their design process.', 'ISDN 1001 OR ISDN 1002 OR ISDN 1006 OR EMIA 2020', '', '2026-08-11 15:40:45.858734');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1280, 'ISDN3200', 'Graphic Communication', '2 Credit(s)', 'This course aims to get the students acquainted with a number of basic components used to build a coherent and meaningful graphic project/entity, which are central to understanding visual communication on fundamental level. This is done through series of lectures and related assignments where these are broken down and applied with special purposes. Necessary technical requirements for digital and physical/material application are covered at the start, after which main design tools (image and text) are analyzed along with basic visual design rules and guidelines (unity, hierarchy, balance, contrast, etc.) followed by addressing elements to build a fundamental graphic narrative (color, reduced visuals, full visuals, infographics), concluded by application of aforementioned items across different media: Deliverables ‐ Poster, Booklet, Digital Presentation, with consistency in translation of semiotic values and with showcasing basic visual literacy in execution of each as a final requirement.', '', '', '2026-08-11 15:40:45.865536');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1281, 'ISDN3300', 'Interaction Design', '3 Credit(s)', 'Interaction Design is a design practice to enhance the interaction between users and design solutions. This course stresses user interaction with technology‐based products, services or systems. It also studies the broader interactions beyond merely interaction between users with computer platforms. Students will be introduced several forms of interaction design and their core design principles and tools improving user interaction. They include, Interaction Design (IxD) studying how to form a structure for users to act and react to the products, services or systems; User Experience Design (UX) exploring how to enhance a positive feeling for users while interacting; User Interface Design (UI) enhancing the experience through better design of the interface elements. Finally, the course will consider broader aspects of Interaction Design, including interfacing the workflow with other teams, privacy, and dark patterns. Students will design an interactive application from the initial ideation to usability testing.', '', '', '2026-08-11 15:40:45.878799');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1282, 'ISDN3350', 'Global Product Development', '3 Credit(s)', 'Joint lecture and project-based course on global product development through a global and interdisciplinary team approach among three institutions in Beijing, Hong Kong and Seoul. This course requires students to go out into global society and industry companies beyond (China, Hong Kong, Korea) for seeking and defining a global user-centered design problem by themselves, to develop the engineering design alternative to solve it, and then to build a working critical function prototype. Students will collaborate through online tools as well as 3 face-to-face meetings throughout the semester in the three respective campuses. This course provides various lectures such as marketing, industrial design, patent law, creative thinking, conceptual design methodology, and case studies in problem ideation. Instructor''s approval is required for enrollment in the course.', 'ISDN 4350, ENTR 3350', '', '2026-08-11 15:40:45.882864');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1283, 'ISDN3360', 'From Product Innovations to Successful Technology Startups', '3 Credit(s)', 'This course is intended for students who want to seriously pursue technology startups. Students will be guided to identify critical steps and important milestones associated with each step in order to build a technology startup. The course requires students to take an existing project idea with early conceptual design and prototype, and bring it to the next level of project realization. Lecture topics include market research, industrial design, patent law, supply chain management and business model development. Cross-college faculty and external experts will provide individual and team mentoring for student projects. Company visits, field trips, trade shows and interactions with experienced entrepreneurs will be arranged. Students with good performance in this course are recommended to different funding and incubation opportunities. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 15:40:45.890696');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1284, 'ISDN4000', 'Special Topics', '1-4 Credit(s)', 'This course will cover the selected topics related to system engineering, robotics, smart city, biomedical applications and/or design thinking. It may be repeated for credits if different topics are taken. May be graded letter grades or DI/PA/F subject to different offerings.', '', '', '2026-08-11 15:40:45.895179');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1285, 'ISDN4001', 'Final Year Design Project I', '4 Credit(s)', 'This course is the first part of the final year project course. Students will continue to expand their skills in technical and design elements as well as knowledge about marketability, sustainability and manufacturability of their product solutions via this project. Students will be assigned into a team and they will define their own project. They will formulate a project proposal to demonstrate project feasibility from a technical and business perspective and seek approval through a proposed project presentation. Students will be given resource and time constraints to complete project milestones under the supervision of a faculty advisor. Regular project meetings will be held to track progress. Each student in a group will be responsible to lead one key element for a successful outcome. A first semester final presentation will update faculty advisors, other ISD faculty and mentors on the project progress and future development plans. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 15:40:45.898950');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1286, 'ISDN4002', 'Final Year Design Project II', '4 Credit(s)', 'This course is the second part of the final year project course, which continues the project based learning training from the first semester. Students will continue their project and come to a conclusion achieving the project milestones or coming up with the final product prototype by the end of the semester. A final project presentation covers the overall project achievements to the faculty advisor, other ISD faculty members and mentors. Instructor''s approval is required for enrollment in the course.', 'ISDN 4001', '', '2026-08-11 15:40:45.906640');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1287, 'ISDN4010', 'Academic and Professional Development IV', '0 Credit(s)', 'Continuation of ISDN 3010. Graded P, PP or F.', '', '', '2026-08-11 15:40:45.910412');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1288, 'ISDN4200', 'Product Management', '3 Credit(s)', 'A product manager can be considered the CEO of a product line. Interdisciplinary skills are required to deal with the design, technical and business aspects to make the product successful in the marketplace. In this course, students are introduced to various responsibilities of a product manager and clear examples are used to illustrate how product managers interface with cross functional team members to make decisions, assess markets and financials, develop strategies and product roadmaps, and seek customer input. The course aims to get students ready for a position as a product manager. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 15:40:45.914025');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1289, 'ISDN4900', 'Independent Study', '1-3 Credit(s)', 'Independent studies or projects under the directed guidance of a faculty member on an integrative systems and design topic. A written report, presentation, and/or an examination are required. Enrollment in the course requires prior approval of the course instructor, and credits assigned depend on the workload. May be repeated for credits. Graded by letter or P/F subject to different offerings. May be graded PP.', '', '', '2026-08-11 15:40:45.922794');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1290, 'ISDN4910', 'Independent Project for Minor in Design', '3 Credit(s)', 'This course is offered as a capstone option for students enrolled in the ISD design minor. Each student is expected to structure their own projects, based on their interests AND on the knowledge and skills learnt in the other ISD required courses, in consultation with the supervisor. Students can conduct the project as an individual though they are highly encouraged to work as a team. In a situation where the student cannot form a team, the supervisor will act as a member of the team. The project is expected to carry BOTH a DESIGN component as well as a TECHNOLOGY component though emphasis will be on design. Both these components will be decided in consultation with the supervisor at the start of the course. Students will be expected to conduct a) Project planning, b) Distribution of tasks (among the team members), c) Identify a problem through interactions w/ users and stakeholders, d) Ideation and design concept generation, e) Selection of ideas, f) Prototyping, g) Testing and h) Proposing a possible redesign. In addition, students have to consider sustainability, manufacturability, and marketability of the proposed design solutions. Students will be expected to produce a working prototype using whatever technologies chosen. Instructor''s approval is required for enrollment in the course. For Minor in Design program students only.', 'Any 1 course from (ISDN 1001 OR ISDN 1002 OR ISDN 1006 OR ISDN 1007 OR ENGG 1300) AND any 2 courses from (ISDN 2000 OR ISDN 2200 OR ISDN 2300 OR ISDN 2400)', '', '2026-08-11 15:40:45.927132');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1291, 'LABU2040', 'Business Case Analyses', '3 Credit(s)', 'This course seeks to equip students with persuasive communication skills, both oral and written, through analyzing business cases and presenting solutions to problems identified. It provides students with a solid framework and hands-on practice to communicate persuasively and professionally in business settings.', 'LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23)', 'LABU 2051, LABU 2052', '2026-08-11 15:40:55.249840');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1292, 'LABU2051', 'Business Case Analyses I', '2 Credit(s)', 'This course lays the foundation for students to engage in business case analyses by developing their critical reading and thinking skills, as well as their ability to present case analysis findings and recommendations in spoken and written forms.', 'LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23)', '', '2026-08-11 15:40:55.256849');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1293, 'LABU2052', 'Business Case Analyses II', '2 Credit(s)', 'This course builds on the foundation built in LABU 2051 and further develops students'' ability to comprehend and analyze business cases, and eventually to present findings and recommendations clearly and persuasively.', 'LABU 2051', '', '2026-08-11 15:40:55.262306');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1294, 'LABU2060', 'Effective Communication in Business', '3 Credit(s)', 'The course activates students'' previously acquired English language skills into a useful managerial communication toolkit targeted toward specific business applications and strategies. Students will learn how to be an effective communicator in the global workplace.', 'LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23)', '', '2026-08-11 15:40:55.268162');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1295, 'ISOM1090', 'Social Media: Collective Intelligence & Creativity', '3 Credit(s)', 'Web technology is now connecting a diversity of people and ideas and encouraging cooperation and collaboration. However, the nascent proliferation of fake news is beginning to have a corrosive effect on the open and peer-to-peer collaborations that are the underpinning of Web 2.0. The aim of the course is to make students aware of the tug of war between beneficial and harmful effects of this social media phenomenon.', 'CORE 1341', '2026-27', '2026-08-11 15:42:09.943103');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1296, 'ISOM1380', 'Technology and Innovation: Social and Business Perspectives', '3 Credit(s)', 'This course describes the development of technology and innovation from social and business perspectives. It covers the technology side of innovations, how an invention can be developed into a successful commercial product, the role of innovation in society and how innovations are created from a socioeconomic perspective.', 'CORE 1340', '2026-27', '2026-08-11 15:42:09.948928');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1297, 'ISOM1400', 'Digital Philanthropy: Harnessing Technology for Social Changes and Beyond', '3 Credit(s)', 'This course explores how digital tools and IT systems are transforming traditional philanthropy and advancing venture philanthropy. Students will gain insights into operational dynamics, digital transformation, and best practices, as well as how commercial models can address philanthropic challenges.', '', '2026-27', '2026-08-11 15:42:09.952778');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1298, 'ISOM1500', 'Insightful Decisions', '3 Credit(s)', 'The course helps students develop better analytical and decision making skills in approaching practical and important social and business issues. Students will derive solutions or conclusions that require critical thinking, creativity, quantitative analysis, and common sense.', '[BLD]', '2026-27', '2026-08-11 15:42:09.958254');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1299, 'ISOM1700', 'Critical Issues in Business Operations', '3 Credit(s)', 'The course will focus on how business organizations should create and sustain value for different stakeholders in the society by designing, optimizing, and improving the operations. Successful businesses have demonstrated their sustainable competitiveness by maintaining a balanced view of economic prosperity, environmental stewardship, and social responsibility.', '', '2026-27', '2026-08-11 15:42:09.962398');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1300, 'ISOM2010', 'Introduction to Information Systems', '3 Credit(s)', 'Information systems (IS) is about managing the applications of IT to create business values. Topics include fundamental concepts of IS, e-commerce, digital and internet economy, web 2.0 and social networks, online advertising, personalization and privacy, digital rights management and piracy, business intelligence and decision-making.', 'COMP 1001', '2026-27', '2026-08-11 15:42:09.966286');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1301, 'ISOM2020', 'Coding for Business', '1 Credit(s)', 'This course intends to introduce students to basic programming concepts and skills for business data coding and business problem solving. Using Python as an illustrative programming language, students will develop logical and critical thinking skills.', 'COMP 1021, COMP 1023', '2026-27', '2026-08-11 15:42:09.969816');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1302, 'ISOM2030', 'Business Protections for Innovations', '3 Credit(s)', 'This course addresses the problems and challenges related to regulatory and business protections for business and scientific innovations, product innovations, service innovations, software licenses, encryption, and digital entertainment.', '[BLD]', '2026-27', '2026-08-11 15:42:09.976138');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1303, 'ISOM2310', 'Fundamentals of E-Commerce: Business, Technology, and the Society', '3 Credit(s)', 'The course covers important topics related to e-commerce including unique features of e-commerce technology, the evolution of e-commerce from its early years to today, and key components of e-commerce business models.', 'CORE 1343', '2026-27', '2026-08-11 15:42:09.980390');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1304, 'ISOM2500', 'Business Statistics', '3 Credit(s)', 'Collection, tabulation and presentation of numerical data; concepts of probability and probability distributions; sampling; statistical estimation and hypothesis testing; correlation and regression analysis.', 'CIVL 2160, IEDA 2520, IEDA 2540, LIFS 3150, MATH 2411, MATH 3423', '2026-27', '2026-08-11 15:42:10.034583');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1305, 'ISOM2600', 'Introduction to Business Analytics', '1 Credit(s)', 'This course introduces students with the foundation needed to apply data analytics to real-world challenges they will confront in their future career.', 'ISOM 2500. (ISOM 2500 AND COMP 1021) or (MATH 2411 AND COMP 1021)', '2026-27', '2026-08-11 15:42:10.039502');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1306, 'ISOM2700', 'Operations Management', '3 Credit(s)', 'Production and service operations viewed from the strategic, tactical and operational levels; capacity planning, process selection, scheduling and quality control.', 'IEDA 4100', '2026-27', '2026-08-11 15:42:10.045169');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1307, 'ISOM3010', 'Information Systems Project Management', '3 Credit(s)', 'This course covers the essential project management knowledge to ensure a successful IS/IT project. Topics include planning, budgeting, scheduling, and risk assessment.', 'ISOM 4750', '2026-27', '2026-08-11 15:42:10.048685');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1308, 'ISOM3180', 'Telecommunications and Computer Networking Management', '3 Credit(s)', 'Essential elements of telecommunications in support of business activities. Topics include OSI Model and TCP/IP Protocol Suite, LAN and WAN technology, communication architectures, networking and security.', 'COMP 4621', '2026-27', '2026-08-11 15:42:10.051708');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1309, 'ISOM3210', 'Information Systems Analysis and Design', '3 Credit(s)', 'The process by which large software systems are built by teams of developers. Techniques for modeling data and process requirements are surveyed and illustrated using CASE tools.', 'ISOM 2010', '2026-27', '2026-08-11 15:42:10.057034');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1310, 'ISOM3270', 'Blockchain Programming in Business Applications', '3 Credit(s)', 'This course provides students with a comprehensive overview of blockchain technology, smart contract development, and hands-on experience in developing and deploying their dApps.', 'ISOM 3000H', '2026-27', '2026-08-11 15:42:10.060285');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1311, 'ISOM3530', 'Business Data Analytics', '4 Credit(s)', 'Practical application of statistics with emphasis on regression. Analysis of business data using a statistical package.', 'ISOM 2500 or MATH 2411', '2026-27', '2026-08-11 15:42:10.063460');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1312, 'ISOM3700', 'Operations Management in Practice', '4 Credit(s)', 'This course extends the introductory course in operations management to focus on advanced topics in strategic planning and decision-making.', 'ISOM 2700', '2026-27', '2026-08-11 15:42:10.066807');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1313, 'ISOM3750', 'Business Project Management', '3 Credit(s)', 'This course covers basic principles and practices of business project management, emphasizing project planning, scheduling, and control.', 'ISOM 2700', '2026-27', '2026-08-11 15:42:10.070018');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1314, 'ISOM4000', 'Special Topics in Information Systems', '0-4 Credit(s)', 'Current developments in information technology. Topics selected by instructors.', '', '2026-27', '2026-08-11 15:42:10.074180');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1315, 'ISOM4300', 'Information Systems Control and Assurance', '3 Credit(s)', 'This course introduces the fundamental concepts and tools to perform information systems (IS) control and assurance.', 'ISOM 2010', '2026-27', '2026-08-11 15:42:10.077690');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1316, 'LANG1006', 'The Art of Public Speaking', '3 Credit(s)', 'This introductory course in public speaking is delivered in two complementary stages. The first, presented in a blended learning environment, will help students to understand some basic terms, concepts and theories applicable to the art of public speaking. The second part consists of small-class face to face tutorials and will have a practical focus. In this part of the course, students will be guided from the theoretical introduction to the practical work of composing and delivering two public speeches. The first speech will be of a knowledge sharing character and the second, longer, speech will be a persuasive public speech. The medium of instruction of the first part of the course will be English, and for the second part of the course, Cantonese, English or Putonghua will be used, depending on the target language chosen by students. Graded P or F.', '', '', '2026-08-11 15:42:31.596182');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1317, 'LANG1101', 'Pinyin for Non-Chinese Language Background Students', '1 Credit(s)', 'This four-and-a-half-week course is designed for students with non-Chinese language background who have not previously learned the Pinyin system. It aims to enhance their ability to pronounce Chinese words correctly and to increase their awareness of Pinyin spelling rules, tone sandhi, erhua, and neutral tone, as well as to help them identify the differences between some easily confused tones, initials and finals. After completing this course, students will be able to use Pinyin as a tool to pronounce commonly used Chinese words and sentences in daily life. Graded P or F.', '', '', '2026-08-11 15:42:31.602223');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1318, 'LANG1102', 'Chinese Characters for Non-Chinese Language Background Students I', '1 Credit(s)', 'The course is designed for non-Chinese language background students who have completed less than 50 hours of Chinese instruction. It aims to equip them with basic knowledge of simplified Chinese characters at HSK (Level 1) for daily and social purposes on a range of familiar topics. After successfully completing the course, students will have acquired basic reading and writing skills in simplified Chinese characters. They will be able to identify information from simple passages and write basic sentences to describe their daily lives. Instructor’s approval is required for enrolling in the course. Graded P or F.', '', '', '2026-08-11 15:42:31.607627');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1319, 'LANG1103', 'Chinese Characters for Non-Chinese Language Background Students II', '1 Credit(s)', 'The course is designed for non-Chinese language background students who have completed less than 50 hours of Chinese instruction. It aims to equip them with Chinese reading and writing skills for daily and social purposes through a range of familiar topics. After successfully completing the course, students will have acquired a basic knowledge of simplified Chinese characters at HSK (Level 1), be able to identify information from simple passages, and write basic sentences to describe their daily lives. Graded P or F.', '', '', '2026-08-11 15:42:31.614476');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1320, 'LANG1117', 'Advanced Chinese Communication', '3 Credit(s)', 'This course seeks to advance the Putonghua speaking and Chinese writing abilities of local Hong Kong students who have attained a reasonably high standard in Chinese language on leaving secondary schools. The course materials and learning tasks help students to engage in rigorous intellectual analysis of academic and socio-economic issues and formulate coherent arguments for Putonghua speaking and Chinese writing in demanding situations such as participation in public fora and writing critical essays for publication in the media.', 'Level 4 or above in HKDSE Chinese', '', '2026-08-11 15:42:31.618115');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1321, 'LANG1130', 'Cantonese for Non-Chinese Language Background Students I', '3 Credit(s)', 'This course is restricted to students with non-Chinese language backgrounds who are beginners in the learning of Cantonese. It equips students with Cantonese communicative competence necessary for living and networking in Hong Kong, thus facilitating their smooth integration into the local community. The learning activities involve developing students'' listening and speaking skills in an attempt to build learners'' confidence and fluency in using Cantonese for daily communication.', '', '', '2026-08-11 15:42:31.639661');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1322, 'LANG1133', 'Cantonese for Chinese Language Background Students I', '3 Credit(s)', 'This course is restricted to students with Chinese language backgrounds who are beginners in the learning of Cantonese. It equips students with Cantonese communicative competence necessary for living and networking in Hong Kong, thus facilitating their smooth integration into the local community. The learning activities involve developing students'' listening and speaking skills in an attempt to build learners'' confidence and fluency in using Cantonese for daily communication.', '', '', '2026-08-11 15:42:31.647634');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1323, 'LANG1210', 'Japanese Language and Culture for Beginners I', '3 Credit(s)', 'This course is designed for students with no prior knowledge of Japanese. It builds foundational skills in listening, speaking, reading, and writing, while introducing essential vocabulary, grammar, and cultural concepts for basic communication. It explores key aspects of Japanese culture, including greetings and social customs.', 'LANG 1211, LANG 1212', '', '2026-08-11 15:42:31.654915');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1324, 'LANG1211', 'Communicative Japanese for Beginners I', '2 Credit(s)', 'This course is designed for students who are just beginning their journey in Japanese and want to develop practical communication skills through face-to-face instruction and practice. Over eight weeks, students will engage in interactive speaking and listening activities in class, focusing on essential conversational skills such as greetings, self-introductions, and asking and answering questions.', 'LANG 1210', '', '2026-08-11 15:42:31.659667');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1325, 'LANG1212', 'Japanese Vocabulary and Grammar Essentials I', '1 Credit(s)', 'This self-paced online course is designed for students beginning their journey in Japanese, focusing on building a solid foundation in vocabulary and grammar structures. The flexible format allows students to progress at their own pace through engaging video lectures and quizzes.', 'LANG 1210', '', '2026-08-11 15:42:31.665989');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1326, 'LANG1230', 'Korean Language and Culture for Beginners I', '3 Credit(s)', 'This course is designed for undergraduate students with no prior knowledge of Korean. The course introduces fundamental language skills and contemporary Korean culture through practical communication in real-life contexts.', '', '', '2026-08-11 15:42:31.678501');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1327, 'LANG1310', 'French Language and Culture for Beginners I', '3 Credit(s)', 'This is a course for learners with no previous knowledge of French. It aims to promote an international perspective by helping them acquire the basics of French.', '', '', '2026-08-11 15:42:31.686147');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1328, 'LANG1330', 'Spanish Language and Culture for Beginners I', '3 Credit(s)', 'This is a course for learners with no previous knowledge of Spanish. It offers students a foundation in Spanish language and related culture, with an emphasis on practical communication.', '', '', '2026-08-11 15:42:31.691031');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1329, 'LANG1402', 'English for University Studies', '3 Credit(s)', 'This course aims for students in their first year of study and will develop students’ spoken and written language proficiency. It introduces academic literacy skills common to all disciplines.', '', '', '2026-08-11 15:42:31.698298');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1330, 'LANG1403', 'Academic English for University Studies', '3 Credit(s)', 'This course emphasises the development of academic literacy skills, in addition to developing students’ language proficiency. Students will learn how to find and evaluate sources for academic tasks.', 'LANG 1401 or LANG 1402', '', '2026-08-11 15:42:31.704539');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1331, 'LANG1404', 'Advanced Academic English for University Studies', '3 Credit(s)', 'This course puts a strong emphasis on developing university-level academic literacy and communication competence in writing, speaking, and multimodal contexts.', 'Level 5* or above in HKDSE English Language or Overall bandscore of 7.0 or above in IELTS or equivalence of the above', '', '2026-08-11 15:42:31.710873');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1332, 'LANG1405', 'Mediated Me: An Introduction to Digital Literacy', '3 Credit(s)', 'This introductory course will help students explore the impact of digital media texts on academic, professional and social communication practices.', '', '', '2026-08-11 15:42:31.718096');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1333, 'LANG1406', 'Academic English for Business Studies', '3 Credit(s)', 'This course puts a strong emphasis on the academic literacy skills essential for business studies.', 'LANG 1402 or Level 5 in HKDSE English Language with all papers at or above Level 4', '', '2026-08-11 15:42:31.723352');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1334, 'LANG1407', 'Academic English for Engineering Studies', '3 Credit(s)', 'This course puts a strong emphasis on the academic literacy skills essential for engineering studies.', 'LANG 1402 or Level 5 in HKDSE English Language with all papers at or above Level 4', '', '2026-08-11 15:42:31.729259');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1335, 'LANG1408', 'Academic English for Humanities and Social Science Studies', '3 Credit(s)', 'This course puts a strong emphasis on the academic literacy skills essential for humanities and social science studies.', 'LANG 1402 or Level 5 in HKDSE English Language with all papers at or above Level 4', '', '2026-08-11 15:42:31.736427');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1336, 'LANG1409', 'Academic English for Science Studies', '3 Credit(s)', 'This course puts a strong emphasis on the academic literacy skills essential for science studies.', 'LANG 1402 or Level 5 in HKDSE English Language with all papers at or above Level 4', '', '2026-08-11 15:42:31.741160');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1337, 'LANG1411', 'Elementary Putonghua for Non-Chinese Language Background Students', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have learned Chinese for less than 50 tuition hours and aims to equip them with listening and speaking skills for communicating in Putonghua.', '', '', '2026-08-11 15:42:31.757738');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1338, 'LANG1412', 'Intermediate Putonghua for Non-Chinese Language Background Students', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have learned Chinese for up to 150 tuition hours.', '', '', '2026-08-11 15:42:31.904318');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1339, 'LANG1413', 'Advanced Putonghua for Non-Chinese Language Background Students', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have learned Chinese for up to 300 tuition hours.', '', '', '2026-08-11 15:42:31.909561');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1340, 'LANG1414', 'Elementary Reading and Writing for Non-Chinese Language Background Students', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have learned Chinese for less than 50 tuition hours and aims to equip students with Chinese reading and writing skills for daily and social purposes.', '', '', '2026-08-11 15:42:31.915738');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1341, 'LANG1415', 'Intermediate Reading and Writing for Non-Chinese Language Background Students', '3 Credit(s)', 'The course is designed for students with non-Chinese language background who have learned Chinese for less than 100 tuition hours.', '', '', '2026-08-11 15:42:31.920375');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1342, 'LANG1416', 'Effective Chinese Communication', '3 Credit(s)', 'This course seeks to enhance the market competitiveness of HKUST graduates by making them effective users of spoken Putonghua and Standard Written Chinese.', 'Level 3 in HKDSE Chinese', '', '2026-08-11 15:42:31.924853');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1343, 'LANG1421', 'Chinese Communication in the Digital Era', '3 Credit(s)', 'This course targets all students who have a background in Chinese, and with a strong interest in the use of Chinese in digital media.', '', '', '2026-08-11 15:42:31.930940');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1344, 'LANG1422', 'Chinese for Workplace Applications', '3 Credit(s)', 'This course is for students who have a background in Chinese. It aims to enhance their Chinese communication skills in workplace contexts.', '', '', '2026-08-11 15:42:31.936320');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1345, 'LANG1423', 'Chinese Communication in Global Context', '3 Credit(s)', 'The course seeks to enhance the Putonghua speaking and Chinese writing abilities of students who have typically undergone schooling in a Chinese language community.', '', '', '2026-08-11 15:42:31.941838');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1346, 'LANG1424', 'Chinese Writing in Cultural Contexts', '3 Credit(s)', 'This course targets all students who have a background in Chinese, and with a strong interest in the study of Chinese writing and cultural issues.', '', '', '2026-08-11 15:42:31.949593');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1347, 'LANG1425', 'Chinese Communication in Interpersonal Relations', '3 Credit(s)', 'This course is designed for students with a background in Chinese to develop the interpersonal communication skills necessary to engage in Chinese cultural and digital contexts.', '', '', '2026-08-11 15:42:31.963281');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1348, 'LANG1426', 'Chinese Communication in Film and Literary Contexts', '3 Credit(s)', 'This course is designed for students with a background in Chinese who are interested in film, literature, and advanced communication.', '', '', '2026-08-11 15:42:31.968670');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1349, 'LANG1511', 'Chinese for Non-Chinese Language Background Students I', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have completed up to 50 hours of Chinese instruction and aims to equip students with listening, speaking, reading skills in Chinese and Putonghua.', '', '', '2026-08-11 15:42:31.973606');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1350, 'LANG1512', 'Chinese for Non-Chinese Language Background Students II', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have completed up to 100 hours of Chinese instruction and aims to equip them with listening, speaking, reading and writing skills in Chinese and Putonghua.', '', '', '2026-08-11 15:42:31.982025');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1351, 'LANG1513', 'Chinese for Non-Chinese Language Background Students III', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have completed up to 150 hours of Chinese instruction and prepares them for an intermediate-level understanding of spoken and written Chinese.', '', '', '2026-08-11 15:42:31.987408');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1352, 'LANG1514', 'Chinese for Non-Chinese Language Background Students IV', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have completed up to 300 hours of Chinese instruction and prepares them for an intermediate to advanced level understanding of spoken and written Chinese.', '', '', '2026-08-11 15:42:32.049086');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1353, 'LANG1515', 'Chinese for Non-Chinese Language Background Students V', '3 Credit(s)', 'The course is designed for non-Chinese language background students who have completed up to 500 hours of Chinese instruction and prepares students for an advanced-level understanding of spoken and written Chinese.', '', '', '2026-08-11 15:42:32.099183');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1354, 'LANG2010', 'English for Science I', '3 Credit(s)', 'An English course for students of the School of Science. The course introduces students to the language and discourse of science and develops their competence in speaking and writing about scientific topics.', 'LANG 1403 OR LANG 2030', '', '2026-08-11 15:42:32.116635');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1355, 'LANG2030', 'Technical Communication I', '3 Credit(s)', 'The course provides students with a broad introduction to English within the discipline of engineering and encourages students to analyze critically the wider social implications of engineering products and processes.', 'LANG 1403 OR LANG 2030 OR LANG 1404 OR LANG 1406', '', '2026-08-11 15:42:32.126566');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1356, 'LANG2061', 'Professional Writing for the Workplace', '3 Credit(s)', 'This course offers students the language and communication skills and strategies to adapt their writing to any professional contexts.', 'LANG 1403 OR LANG 1404', '', '2026-08-11 15:42:32.138691');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1357, 'LANG2062', 'Professional Speaking for the Workplace', '3 Credit(s)', 'This course equips students with the language and communication skills to speak and present professionally in internal and external business settings.', 'LANG 1403 OR LANG 1404', '', '2026-08-11 15:42:32.149098');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1358, 'LANG2063', 'Writing for Workplace Success', '3 Credit(s)', 'This course prepares students extensively for persuasive writing in the workplace, enabling them to become effective writers and communicators in a digitally interconnected world.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.156974');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1359, 'LANG2064', 'Speaking for Workplace Success', '3 Credit(s)', 'This course enhances student awareness of how spoken communication can drive change and persuade action.', 'LANG 1403 OR LANG 1404', '', '2026-08-11 15:42:32.168522');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1360, 'LANG2065', 'Research Writing', '3 Credit(s)', 'This course empowers students to tackle complex academic writing challenges in research project writing regardless of major.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.175746');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1361, 'LANG2066', 'Dynamic Communication for STEAM Topics', '3 Credit(s)', 'This course aims to empower students to communicate STEAM-related concepts in engaging and impactful ways, fostering public understanding and informed decision-making.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.184778');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1362, 'LANG2067', 'Digital Communication: Expressing Your Perspective in Digital Spaces', '3 Credit(s)', 'This course equips students with essential skills for effective communication on digital platforms, which are crucial for success in today’s academic, personal, and professional arenas.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.191663');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1363, 'LANG2068', 'Speaking with Impact', '3 Credit(s)', 'This course is designed to enhance students'' abilities to craft and deliver compelling speeches using advanced communication strategies and technologies.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.199772');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1364, 'LANG2069', 'Supercommunication Offline and On: The Art of Connecting', '3 Credit(s)', 'This course equips students with the language and communication strategies necessary to build meaningful connections in academic, social, and professional contexts.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.209576');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1365, 'LANG2070', 'English Communication for Humanities and Social Science Studies I', '3 Credit(s)', 'Restricted to students in programs offered by the School of Humanities and Social Science. The course is an integrated skills course with a special emphasis on critical reading and thinking.', 'LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23)', '', '2026-08-11 15:42:32.220523');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1366, 'LANG2071', 'From Proposal to Applause: Navigating the Academic Conference Journey', '3 Credit(s)', 'This course equips students with the skills to communicate research effectively across academic contexts.', 'LANG 1403 OR LANG 1404 OR LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409', '', '2026-08-11 15:42:32.227221');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1367, 'LANG2082', 'Communication for Environmental Management and Technology I', '2 Credit(s)', 'This course aims to develop students’ competence in discipline-related English, specifically communicating topics in the field of Environmental Management and Technology to the general public.', 'LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23)', '', '2026-08-11 15:42:32.235830');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1368, 'LANG2083', 'Communication for Environmental Management and Technology II', '2 Credit(s)', 'This course aims to develop students’ competence in discipline-related English, specifically communicating topics in the field of Environmental Management and Technology to a business audience.', 'LANG 2082', '', '2026-08-11 15:42:32.242784');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1369, 'LANG2090', 'Exploring Language and Communication with Big Data', '3 Credit(s)', 'This course investigates the role of language across various sectors such as business, science, health, and media.', '', '', '2026-08-11 15:42:32.317410');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1370, 'LANG2091', 'Phonetics and Speech Technology', '3 Credit(s)', 'This course introduces students to Phonetics, the scientific study of the physical properties of human speech sounds.', '', '', '2026-08-11 15:42:32.323456');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1371, 'LANG2170', 'Chinese Communication Skills for Humanities & Social Science Studies', '3 Credit(s)', 'This course enables students to achieve thorough comprehension of texts written in Chinese, and prepares them for writing academic papers such as project reports and dissertations.', '', '', '2026-08-11 15:42:32.327353');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1372, 'LANG2200', 'Japanese Language and Culture for Beginners II', '3 Credit(s)', 'This course builds on LANG 1210 as an upper-beginner course and prepares students for intermediate-level Japanese studies. It strengthens Japanese vocabulary, grammar, and cultural understanding.', 'LANG 2201, LANG 2202', '', '2026-08-11 15:42:32.340553');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1373, 'LANG2201', 'Communicative Japanese for Beginners II', '2 Credit(s)', 'This course is designed for upper-beginner learners who want to strengthen their speaking and listening skills through interactive and face-to-face communicative practice.', 'LANG 2200', '', '2026-08-11 15:42:32.347932');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1374, 'LANG2202', 'Japanese Vocabulary and Grammar Essentials II', '1 Credit(s)', 'This self-paced online course is designed for upper-beginner Japanese learners and focuses on expanding vocabulary and strengthening grammar skills to prepare students for intermediate-level Japanese studies.', 'LANG 2200', '', '2026-08-11 15:42:32.354606');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1375, 'LANG2310', 'French Language and Culture for Beginners II', '3 Credit(s)', 'This course builds on LANG 1310 as an upper-beginner course and prepares students for intermediate-level French studies.', '', '', '2026-08-11 15:42:32.358578');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1376, 'LANG2330', 'Spanish Language and Culture for Beginners II', '3 Credit(s)', 'This course builds on LANG 1330 as an upper-beginner course and prepares students for intermediate-level Spanish studies.', '', '', '2026-08-11 15:42:32.364056');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1377, 'LANG3021', 'Science Communication in English (Mathematics)', '3 Credit(s)', 'This course focuses on developing students'' ability to communicate mathematical knowledge to the general public through effective writing and speaking skills.', 'LANG 2010 OR LANG 2030', '', '2026-08-11 15:42:32.369523');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1378, 'LANG3022', 'Science Communication in English (Chemistry)', '3 Credit(s)', 'This course focuses on developing students'' ability to communicate chemistry knowledge to the general public through effective writing and speaking skills.', 'LANG 2010', '', '2026-08-11 15:42:32.458924');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1379, 'LANG3023', 'Science Communication in English (Physics)', '3 Credit(s)', 'This course focuses on developing students'' ability to communicate physics knowledge to the general public through effective writing and speaking skills.', 'LANG 2010', '', '2026-08-11 15:42:32.466863');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1380, 'LANG3024', 'Science Communication in English (Life Science)', '3 Credit(s)', 'This course focuses on developing students'' ability to communicate life science knowledge to the general public through effective writing and speaking skills.', 'LANG 2010', '', '2026-08-11 15:42:32.473129');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1381, 'LANG3025', 'Science Communication in English (Environmental Science)', '3 Credit(s)', 'This course focuses on developing students'' ability to communicate environmental science knowledge to the general public through effective writing and speaking skills.', 'LANG 2010', '', '2026-08-11 15:42:32.484615');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1382, 'LANG3027', 'Science Communication in English for Research Students', '3 Credit(s)', 'This course offers undergraduate students the opportunity to improve their skills in writing research articles, abstracts, and review articles.', 'LANG 2010', '', '2026-08-11 15:42:32.503202');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1383, 'LANG3060', 'Advanced Academic Writing', '3 Credit(s)', 'This course offers students advanced strategies and practice in writing texts in their academic disciplines.', 'LANG 1403 OR LANG 1404', '', '2026-08-11 15:42:32.522144');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1384, 'LANG3070', 'English Communication for Humanities and Social Science Studies II', '3 Credit(s)', 'This course builds on the critical reading and thinking skills students have developed, and prepares them for writing up long documents such as project reports and dissertations.', 'LANG 2070', '', '2026-08-11 15:42:32.528089');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1385, 'LANG3081', 'Communication for Environmental Management and Technology III', '2 Credit(s)', 'This course aims to develop students'' ability to use effective and appropriate organizational structures, vocabulary, language and style in Capstone Project proposals, reports and presentations.', 'LANG 2083', '', '2026-08-11 15:42:32.534758');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1386, 'LANG4010', 'From Report to Presentation: Mastering Effective Communication in Environmental Impact Assessments', '3 Credit(s)', 'This course focuses on developing linguistic and analytical skills necessary for evaluating environmental impacts in marine contexts.', 'LANG 1409 OR LANG 2010', '', '2026-08-11 15:42:32.541679');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1387, 'LANG4030', 'Technical Communication II for CSE, CPEG & DSCT', '3 Credit(s)', 'A one-term, major-specific language course for CSE students, focusing on report writing and presentations, and communication in professional contexts relevant to the disciplines.', '(For DDP only) LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23); (For DSCT only) LANG 2010 OR LANG 2030; (For all others) LANG 2030', '', '2026-08-11 15:42:32.553414');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1388, 'LANG4031', 'Technical Communication II for ECE & CPEG', '3 Credit(s)', 'A one-term, major-specific language course for all ECE students and for all CPEG students undertaking an ECE Final Year Project.', '(For DDP only) LANG 1403 OR LANG 1404 OR LANG 1003 (Prior to 2022-23); (For all others) LANG 2030', '', '2026-08-11 15:42:32.562829');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1389, 'LANG4032', 'Technical Communication II for IEDA and ISDN', '3 Credit(s)', 'A one-term, major-specific language course for students in IEDA and ISDN focusing on Final Year Project report writing and presentations.', '(For DDP only) LANG 1403 OR LANG 1404 OR LANG 1003 (prior to 2022-23); (For all others) LANG 2030', '', '2026-08-11 15:42:32.571831');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1390, 'LANG4033', 'Technical Communication II for Civil and Environmental Engineering', '3 Credit(s)', 'A one-term, major-specific course for all students of the CIVL Department focusing on Final Year Project report writing and presentations.', '(For DDP only) LANG 1403 OR LANG 1404 OR LANG 1003 (Prior to 2022-23); (For all others) LANG 2030', '', '2026-08-11 15:42:32.581602');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1391, 'LANG4034', 'Technical Communication II for Mechanical and Aerospace Engineering', '3 Credit(s)', 'A one-term, major-specific course for all Mechanical and Aerospace Engineering students focusing on academic speaking and writing skills for laboratory report writing and the Final Year Design Project.', '(For DDP only) LANG 1403 OR LANG 1404 OR LANG 1003 (Prior to 2022-23); (For all others) LANG 2030', '', '2026-08-11 15:42:32.588536');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1392, 'LANG4035', 'Technical Communication II for Chemical and Biological Engineering', '3 Credit(s)', 'A one-term, major-specific course for all students in the Department of Chemical and Biological Engineering focusing on Final Year Project report writing and presentations.', '(For DDP only) LANG 1403 OR LANG 1404 OR LANG 1003 (Prior to 2022-23); (For all others) LANG 2030', '', '2026-08-11 15:42:32.600160');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1393, 'LANG4036', 'Technical Communication for Technology Projects', '3 Credit(s)', 'This course is designed to meet the language needs of students in Integrative Systems and Design who undertake project work for academic and professional purposes.', 'LANG 1406 OR LANG 1407 OR LANG 1408 OR LANG 1409 OR (For DDP only) LANG 1003 (prior to 2022-23) OR LANG 1403 OR LANG 1404 OR (For non-DDP only) LANG 2030', '', '2026-08-11 15:42:32.605326');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1394, 'LANG4070', 'Academic Writing in Context - Global China Studies', '1 Credit(s)', 'This course with a special delivery mode helps students address their specific writing needs dictated by students'' choices of topics in particular areas of Global China Studies.', '', '', '2026-08-11 15:42:32.610811');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1395, 'LANG4090', 'Report Writing for Final Year Engineering Projects', '1 Credit(s)', 'This course helps engineering students write effective Final Year Project (FYP) reports, guiding students through the writing process to produce high-quality FYP reports.', '', '', '2026-08-11 15:42:32.616959');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1396, 'LANG4091', 'Presentation Skills for Final Year Projects', '1 Credit(s)', 'This course equips students with essential skills to deliver professional, engaging, and impactful presentations for their Final Year Project (FYP) or capstone project.', '', '', '2026-08-11 15:42:32.622595');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1397, 'MARK1220', 'Marketing and Society', '3 Credit(s)', 'This course will challenge the dynamics of marketing and the role it plays within a social, sustainable and ethical context in various industries. Current social issues affecting marketing decisions within the context of business strategy will be explored.', 'None', 'Not specified', '2026-08-11 15:42:47.491400');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1398, 'MARK2120', 'Marketing Management', '3 Credit(s)', 'Introduction to marketing from the perspective of the decision-maker; controllable variables (product, price, promotion and distribution), uncontrollable variables (competition, law, society, technology, and economy), consumer behavior and marketing research.', 'None', 'Not specified', '2026-08-11 15:42:47.499625');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1399, 'MARK3220', 'Marketing Research', '4 Credit(s)', 'Basic research tools and procedures used in marketing research, and strategic uses of marketing research information in managerial decision making.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.548226');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1400, 'MARK3410', 'Promotion and Advertising Management', '4 Credit(s)', 'Major aspects of promotion, with emphasis on advertising: setting of advertising objectives, strategies, tactics, choice of media, budget determination and measuring advertising effectiveness.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.555195');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1401, 'MARK3420', 'Consumer Behavior', '4 Credit(s)', 'Psychological concepts such as perception, learning and motivation, sociological concepts such as reference groups, family and culture and theories of purchase decision processes underlying consumer buying behavior.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.560599');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1402, 'MARK3430', 'Global Marketing', '4 Credit(s)', 'Understanding the formulation of international/multinational marketing strategy; factors influencing international trade, assessment of market potential, threats and opportunities in the international market environment, global marketing activities.', 'MARK 2120', 'Blended learning', '2026-08-11 15:42:47.566847');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1403, 'MARK3460', 'Retail management in the digital age', '4 Credit(s)', 'This course explores the critical concepts and strategies that define the modern retail landscape. It examines the impact of technology on retail operations, consumer behavior, and market dynamics.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.571935');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1404, 'MARK3480', 'Pricing Strategy', '4 Credit(s)', 'This course is designed to deepen understanding of pricing issues which marketing managers may face under some degree of market power.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.575772');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1405, 'MARK3510', 'Business to Business Marketing', '4 Credit(s)', 'The fundamental character of business markets and the decision-making nature of organizational customers; different approaches to business marketing.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.580091');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1406, 'MARK3610', 'Digital Marketing', '4 Credit(s)', 'Digital Marketing has reshaped the consumer landscape, and it is offering business new challenges and opportunities.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.584510');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1407, 'MARK3620', 'Marketing Analytics', '4 Credit(s)', 'This course develops the foundation and integrated framework for understanding marketing analytics.', 'MARK 2120 and ISOM 2500', 'Not specified', '2026-08-11 15:42:47.592172');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1408, 'MARK4210', 'Strategic Marketing', '4 Credit(s)', 'Developing a comprehensive and integrated framework for directing and managing the marketing functions of a company.', 'MARK 2120, MARK 3220 and MARK 3420', 'Not specified', '2026-08-11 15:42:47.600119');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1409, 'MARK4290', 'Special Topics', '0-4 Credit(s)', 'Selected topics in current marketing thought and practices; topics vary from semester to semester.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.606331');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1410, 'MARK4450', 'Brand Management', '4 Credit(s)', 'This course is designed to help students develop a practical understanding of the tools, rules, and strategies of brand management.', 'MARK 2120', 'Not specified', '2026-08-11 15:42:47.614766');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1411, 'MARK4980', 'Independent Study', '2-4 Credit(s)', 'Directed study of selected problems in marketing not covered in other courses.', 'None', 'Not specified', '2026-08-11 15:42:47.620474');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1412, 'LIFS1010', 'Introduction to Biological Sciences', '3 Credit(s)', 'As a living being, you are a part of the biological world. Biological Science is the study of life. It’s the truest way to understand the world around you and answer existential questions. This course introduces students to the fundamental concepts and principles, ranging from the origin of life, the genetic basis of evolution and biodiversity, the chemical basis of life, cell structure and organ functions in humans, conservation, ecology and behavioral biology. How Chinese medicine views life and aging in humans will also be discussed briefly. Examples and case studies will be illustrated to enhance students’ understanding and application of relevant knowledge. Students without HKDSE qualifications may seek the instructor’s approval for enrolment.', 'LIFS 1901, LIFS 1902, Level 3 or above in HKDSE 1/2x Biology OR in HKDSE 1x Biology', 'Fall, Spring', '2026-08-11 15:43:18.848777');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1413, 'LIFS1020', 'Biology of Human Health', '3 Credit(s)', 'This course introduces the basic biological principles of human health and diseases with an emphasis on the contemporary leading causes of death in Hong Kong and the world. Topics mainly focus on common and emerging diseases, aging, and the influence of biotechnology, environment, and culture on human health. Students without HKDSE qualifications may seek instructor’s approval for enrolment.', 'CORE 1130, Level 3 or above in HKDSE 1/2x Biology or in HKDSE 1x Biology, LIFS 1010, LIFS 1901, LIFS 1902, LIFS 1930, LIFS 2060', 'Fall, Spring', '2026-08-11 15:43:18.855970');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1414, 'LIFS1901', 'General Biology I', '3 Credit(s)', 'This course targets science students not having taken HKDSE 1x Biology or AL/AS Biology. It provides students with a general overview of fundamental biology: basic characteristics of life (the chemistry of life, cells), vital life processes (respiration, photosynthesis, genetics), essential concepts of evolution and ecology, and so on. Students without HKDSE qualifications may seek instructor’s approval for enrolment.', 'Level 3 or above in HKDSE 1x Biology', 'Fall, Spring', '2026-08-11 15:43:18.859762');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1415, 'LIFS1902', 'General Biology II', '3 Credit(s)', 'This course targets science students who have acquired basic knowledge in fundamental biology through HKDSE 1x Biology, AL/AS Biology or LIFS 1901. It functions as a bridging course to prepare the students for further study in life science. Its focus is on human biology, biotechnology and human impacts on the environment. Current examples will be used as well to relate the knowledge to real life issues. Students without the prerequisites but have completed biology course or program at equivalent level may seek instructor’s approval for enrollment.', 'LIFS 1901 OR level 3 or above in HKDSE 1x Biology OR a passing grade in AL/AS Biology', 'Fall, Spring', '2026-08-11 15:43:18.864521');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1416, 'LIFS1903', 'Laboratory for General Biology I', '1 Credit(s)', 'This is a practical course accompanied by the lecture course LIFS 1901. It provides students with some basic concepts and some hands-on experience in biological investigation within the areas covered by LIFS 1901. The emphasis is on the understanding and application of the scientific principles underlying the experimental designs and procedures. Graded P or F. For students in their first, second year of study; or third or fourth year students with instructor''s approval.', 'LIFS 1901', 'Fall, Spring', '2026-08-11 15:43:18.868932');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1417, 'LIFS1904', 'Laboratory for General Biology II', '1 Credit(s)', 'This practical course provides students with some basic concepts and hands-on experience in biological investigation within the areas covered by LIFS 1901 or LIFS 1902, including plant biology, human biology and ecology. The emphasis is on the understanding and application of the scientific principles underlying the experiments. Graded P or F. For students in their first and second year of study; or third and fourth year students with instructor''s approval.', 'Level 3 or above in HKDSE 1x Biology, LIFS 1901 OR LIFS 1902', 'Fall, Spring', '2026-08-11 15:43:18.872884');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1418, 'LIFS1930', 'Nature of Life Sciences', '3 Credit(s)', 'This is an innovative blended-learning course that comprises both independent e-learning and face-to-face tutorial components. The course covers general and up-to-date topics such as conservation biology and animal forms and functions in the field of Biology, metabolism and cell signaling in Biochemistry, and recombinant DNA, animal and plant biotechnology and bioethics in Biotechnology. For students in their first, second and third year of study; or fourth year students with instructor''s approval.', 'None', 'Fall, Spring', '2026-08-11 15:43:18.878515');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1419, 'LIFS1980', 'Guided Study on Biomedical and Health Sciences', '1 Credit(s)', 'This course provides students with a general overview about how common and rare diseases are treated, under the directed guidance of life science faculty members and biomedical professionals. This course comprises a combination of lectures as well as volunteering/shadowing opportunities. For students in the BMH program only. Non-BMH students may enroll in the course upon instructor''s approval only. Graded P or F.', 'None', 'Fall, Spring', '2026-08-11 15:43:18.882552');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1420, 'LIFS1982', 'Introduction to Biomedical and Health Science Laboratory Techniques', '2 Credit(s)', 'This laboratory course will offer a practical introduction to essential experimental techniques widely used in biomedical and healthcare research laboratories. Students will gain hands-on experience in microbiological culture and staining, DNA extraction and quantification, PCR and gel electrophoresis, as well as basic protein purification and protein analysis using SDS-PAGE and western blotting. Throughout the course, particular attention will be paid to good laboratory practice, detailed record-keeping, data integrity, and essential laboratory safety. Instructor’s approval is required for enrolling in the course. Graded P or F.', 'LIFS 1980', 'Fall, Spring', '2026-08-11 15:43:18.888885');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1421, 'LIFS2010', 'Modern Approaches to Biochemical and Cell Biological Research', '3 Credit(s)', 'Our current understanding of biochemical reactions and internal organization of a cell was progressively enriched by technological and conceptual breakthroughs in the 20th century. This course will use personal and scientific stories of six prominent scientists to highlight research areas that are still being actively pursued today. Topics to include are DNA and protein biochemistry, physical and chemical methods for biological research, and the use of model organisms.', 'LIFS 1902', 'Fall, Spring', '2026-08-11 15:43:18.892294');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1422, 'LIFS2011', 'A Practicum on Wetland Conservation', '3 Credit(s)', 'This course engages students in practical training and enriches their knowledge in biodiversity and skills in interpretive services under ecotourism. The students will also have a chance to contribute to the society through environmental education. At the end of the course, students should gain hands-on experience in environmental conservation and improve their skills in communication, problem solving, team work, and time management. For LIFS, ENVS and OST students only. Approval of the course coordinator is needed for students to enroll in this course. Graded PP, P or F.', 'LIFS 2060', 'Fall, Spring', '2026-08-11 15:43:18.896018');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1423, 'LIFS2040', 'Cell Biology', '3 Credit(s)', 'Structure and function of the cell and sub-cellular organelles; from genes to proteins; membrane and cytoskeleton; cell communication and cell signaling; cell cycle and programmed cell death.', 'None', 'Fall, Spring', '2026-08-11 15:43:18.900718');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1424, 'LIFS2060', 'Biodiversity', '3 Credit(s)', 'This course introduces students to the diversity of life and habitats; the evolution and extinction of species; the values of biodiversity; challenges to biodiversity and conservation approaches; the interrelationships between humans/biodiversity and the environment. Examples (local and global) and applications will be included to highlight the key concepts.', 'None', 'Fall, Spring', '2026-08-11 15:43:18.904642');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1425, 'LIFS2070', 'Introduction to Biotechnology', '3 Credit(s)', 'This course is designed to introduce some of the major subjects in the field of biotechnology including the history of biotechnology, ethics in genetic modification and use of animals in experimental studies, molecular foundation of biotechnology, animal biotechnology, plant and agricultural biotechnology, and health-care applications.', 'LIFS 1902', 'Fall, Spring', '2026-08-11 15:43:18.908733');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1426, 'LIFS2080', 'Plant Biology', '3 Credit(s)', 'Structure and life processes in plants; cellular structures; molecular and cellular mechanisms; transport of water and nutrients; nutrition and soil; reproduction; photosynthesis; growth and development; biotechnology.', 'LIFS 2040 OR LIFS 2210', 'Fall, Spring', '2026-08-11 15:43:18.913141');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1427, 'LIFS2210', 'Biochemistry I', '3 Credit(s)', 'Major classes of biochemical compounds; primary, secondary, tertiary and quaternary structures of macromolecules; enzyme kinetics and mechanisms; biosynthesis of DNA and RNA; transfer RNA and protein synthesis.', 'LIFS 1901 OR LIFS 1902', 'Fall, Spring', '2026-08-11 15:43:18.917753');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1428, 'LIFS2220', 'Biochemistry II', '3 Credit(s)', 'Principles of bioenergetics and cellular structures; glycolysis, citric acid cycle, electron transport, oxidative phosphorylation and chemiosmosis; carbohydrate, lipid, amino acid and nucleotide metabolism; photosynthesis and nitrogen fixation.', 'LIFS 1902', 'Fall, Spring', '2026-08-11 15:43:18.921787');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1429, 'LIFS2240', 'Cell Biology Laboratory', '3 Credit(s)', 'Exploration and understanding of both theories and practical techniques in cell biology through tutorials and hands-on experiments. Microscopy, cell culture, cell fractionation; and their applications in studying cell division and gene expression will be covered. Graded P or F.', 'LIFS 1902', 'Fall, Spring', '2026-08-11 15:43:18.925403');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1430, 'LIFS2720', 'Biochemistry Laboratory', '2 Credit(s)', 'Investigation of the properties of enzymes, lipids, carbohydrates and nucleic acids by physicochemical methods and specific assays; purification and quantitation of biochemical compounds by various biochemical techniques. Graded P or F.', 'LIFS 2820', 'Fall, Spring', '2026-08-11 15:43:18.929207');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1431, 'LIFS2820', 'Biochemical Laboratory Techniques', '1 Credit(s)', 'Principles of biochemical techniques including spectrophotometry, column chromatography, electrophoresis, metabolite assay, enzyme assay, nucleic acid isolation and protein isolation.', 'LIFS 2720', 'Fall, Spring', '2026-08-11 15:43:18.938160');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1432, 'LIFS2888', 'Introduction to Bioindustries', '3 Credit(s)', 'This course explores the dynamic and rapidly evolving landscape of bioindustries, equipping students with a deep understanding of the key sectors and their strategic importance.', 'CENG 1600', 'Fall, Spring', '2026-08-11 15:43:18.942367');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1433, 'LIFS2901', 'Case Study on Biomedical and Health Sciences I: From Proposal to Practice', '3 Credit(s)', 'In this course, students will analyze one human genetic disease. Working in teams, students will be guided to review the literature so they can formulate a proposal to either simulate the disease in a model organism or perform computational analysis on human populations.', 'LIFS 1980', 'Fall, Spring', '2026-08-11 15:43:18.945632');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1434, 'LIFS3002', 'Special Topics of Biological Sciences', '2-4 Credit(s)', 'This course aims to broaden students'' exposure to a broad range of topics within the biological science discipline. Teaching format and course credits will vary, depending on the subject matters to be covered.', 'LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:18.951005');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1435, 'LIFS3010', 'Molecular and Cellular Biology I', '3 Credit(s)', 'Replication and roles of nucleic acids in cellular and viral systems; genome organization, vector-host systems, expression and regulation of genes; catalytic RNA, genetic code evolution, RNA modification and processing, and anti-sense systems.', 'LIFS 2210 and LIFS 2220', 'Fall, Spring', '2026-08-11 15:43:18.959205');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1436, 'LIFS3020', 'Molecular and Cellular Biology II', '3 Credit(s)', 'Cell structure; the molecular biology of cell signaling and cell cycle control; oncogenes and tumor suppressor genes; the mechanism of cell division; cell junctions and adhesion; cytoskeleton; programmed cell death.', 'LIFS 2040 AND LIFS 2210 AND LIFS 2220', 'Fall, Spring', '2026-08-11 15:43:18.963003');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1437, 'LIFS3040', 'Animal Physiology', '3 Credit(s)', 'Structure and life processes in animals; neurophysiology; circulation; respiration; digestion and absorption; metabolism and energy regulation; muscle and movement; endocrinology.', 'LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:18.967930');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1438, 'LIFS3060', 'Microbiology', '3 Credit(s)', 'Classification, identification, structure, physiology, and genetics of microorganisms; importance of microorganisms in health, environment, and biotechnology.', 'LIFS 2040 OR LIFS 2060', 'Fall, Spring', '2026-08-11 15:43:18.972903');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1439, 'LIFS3070', 'Introduction to Biophysical Instrumentation', '3 Credit(s)', 'The course offers an introduction to principles and applications of a variety of modern biophysical experimental techniques for the structural and functional study of biological systems at the cellular and molecular levels.', 'LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:18.977532');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1440, 'LIFS3110', 'Biotechnological Application of Recombinant DNA Techniques', '3 Credit(s)', 'Practical and theoretical consideration of recombinant DNA techniques, including plasmid construction, PCR, mutagenesis, transformation, sequencing, and bioinformatic analysis. The use of recombinant DNA for protein expression. Graded P or F.', 'LIFS 2040 AND LIFS 2210', 'Fall, Spring', '2026-08-11 15:43:18.985234');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1441, 'LIFS3140', 'General Genetics', '4 Credit(s)', 'Principles and mechanisms of heredity and variation; genetic analysis in pro-and eukaryotic organisms.', 'LIFS 2040 OR LIFS 2210', 'Fall, Spring', '2026-08-11 15:43:18.989966');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1442, 'LIFS3150', 'Biostatistics', '3 Credit(s)', 'Statistical reasoning relevant to biological, medical and agricultural research, statistical analyses and interpretation, statistical techniques applied under various research circumstances.', 'ISOM 2500, MATH 2411', 'Fall, Spring', '2026-08-11 15:43:18.993123');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1443, 'LIFS3220', 'Animal Physiology Laboratory', '3 Credit(s)', 'Physiology is an experimental science and laboratory experience is an important part of the discipline. Students will learn laboratory techniques and develop their powers of observation and data recording to test basic physiological principles. Analytical skill will be emphasized in both the tutorial and lab sessions. Graded P or F.', 'LIFS 2040, LIFS 3040', 'Fall, Spring', '2026-08-11 15:43:18.997411');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1444, 'LIFS3240', 'Introduction to Neurobiology', '3 Credit(s)', 'Principles of neuroscience with a focus on the systems/neural circuit level. Topics covered will include sensory and motor systems, genetic model organisms, optogenetics, and functional imaging.', 'LIFS 2040 OR LIFS 2210', 'Fall, Spring', '2026-08-11 15:43:19.002648');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1445, 'LIFS3260', 'Microbiology Laboratory', '3 Credit(s)', 'Tutorial and practical instruction on cultivation, differentiation, and identification of microorganisms, determination of microbial numbers, sterilization, disinfection, antimicrobials, and the prevalence of microorganisms in the body and environment will be covered. Graded P or F.', 'LIFS 3060', 'Fall, Spring', '2026-08-11 15:43:19.006923');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1446, 'LIFS3280', 'Introduction to Immunology', '3 Credit(s)', 'This course provides an introduction to the fundamental principles of immunology, focusing on how the immune system protects the body against pathogens and maintains health.', 'LIFS 2040 AND LIFS 2210', 'Fall, Spring', '2026-08-11 15:43:19.009947');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1447, 'LIFS3370', 'Human Genetics in Practice', '3 Credit(s)', 'This course will impart essential skills for communicating science to a lay audience in the laboratory setting.', 'LIFS 3110', 'Fall, Spring', '2026-08-11 15:43:19.013802');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1448, 'LIFS3510', 'Junior Research Project I', '2 Credit(s)', 'The objective of the course is to increase awareness of preparation in research and learn how to synthesize a research proposal.', 'LIFS 2040 and LIFS 2240', 'Fall, Spring', '2026-08-11 15:43:19.018349');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1449, 'LIFS3520', 'Junior Research Project II', '2 Credit(s)', 'The aim of the course is for students to acquire hands-on laboratory experience in conducting a short research project and producing a formal written report. Each student will conduct the bench work for the proposal developed in the prerequisite course LIFS 3510.', 'LIFS 3510 OR SCIE 3500', 'Fall, Spring', '2026-08-11 15:43:19.021662');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1450, 'LIFS3580', 'Bioinformatics', '3 Credit(s)', 'An introduction to bioinformatic analysis in life science. Students will learn about the principles and approaches used in working with genetic, genomic and proteomic data.', 'LIFS 4580, LIFS 3140', 'Fall, Spring', '2026-08-11 15:43:19.024991');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1451, 'LIFS3901', 'Case Study on Biomedical and Health Sciences IIA - Generation of Disease Models by Genome Editing', '4 Credit(s)', 'This laboratory course will build on the wet lab skills that students learned in LIFS 2901. Here, working in teams, students will introduce a mutation found in a human genetic disease into the model organism, Caenorhabditis elegans.', 'LIFS 2901', 'Fall, Spring', '2026-08-11 15:43:19.031956');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1452, 'LIFS3902', 'Case Study on Biomedical and Health Sciences IIB - Phenotypic Analysis of Mutant Animal Models', '4 Credit(s)', 'In this course, students will conduct phenotypic analysis on the mutant animal models they generated in LIFS 3901.', 'LIFS 2901', 'Fall, Spring', '2026-08-11 15:43:19.037798');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1453, 'LIFS3903', 'Case Study on Biomedical and Health Sciences IIC - Genome-wide Association Studies in Practice', '4 Credit(s)', 'This course is a continuation of LIFS 2901 and will enhance the students'' understanding of computational biomedical sciences.', 'LIFS 2901, LIFS 4370', 'Fall, Spring', '2026-08-11 15:43:19.041721');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1454, 'LIFS3904', 'Case Study on Biomedical and Health Sciences IID - Analysis of Next-generation Sequencing Data', '4 Credit(s)', 'In this course, students will utilize state-of-the-art computational pipelines to analyze publicly available next-generation sequencing (NGS) data on human genetic diseases.', 'LIFS 2901', 'Fall, Spring', '2026-08-11 15:43:19.045534');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1455, 'LIFS4000', 'Special Topics in Life Science', '1-4 Credit(s)', 'Special topics in an identified area of life science not covered by existing course. Students may repeat the course for credits if the topics studied are different. Graded letter grade or P/F subject to different offerings.', 'None', 'Fall, Spring', '2026-08-11 15:43:19.049027');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1456, 'LIFS4060', 'Immunobiology', '3 Credit(s)', 'Cellular, biochemical and genetic basis of immunity; cells in immune response, antigens and antigen recognition; antibodies and the generation of diversity; major histocompatibility complex; cell mediated immune response; regulation of immune response; autoimmunity, tissue transplantation and rejection.', 'LIFS 2040/2210, and LIFS 3140', 'Fall, Spring', '2026-08-11 15:43:19.053906');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1457, 'LIFS4090', 'Developmental Biology', '3 Credit(s)', 'Processes of cellular and tissue differentiation, early and late embryonic development spanning from molecular, cellular, organ to organismal levels; reproduction, fertilization, gastrulation, neurulation, axis formation, body patterning, cellular communication, short and long range signaling, sex determination, aging, environmental influence and evolutionary significance of different regulatory mechanisms.', 'LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:19.057675');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1458, 'LIFS4140', 'Cancer Biology', '3 Credit(s)', 'Fundamentals in the epidemiology, etiology and treatment of cancers; basic mechanisms of carcinogenesis. For LIFS/BIBU students in their fourth year of study.', 'LIFS 3020 OR LIFS 3140', 'Fall, Spring', '2026-08-11 15:43:19.061600');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1459, 'LIFS4150', 'Plant Biotechnology', '3 Credit(s)', 'Current status and future potential of Biotechnology, with emphasis on the fundamentals of plant molecular biology and biotechnology.', 'LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:19.067454');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1460, 'LIFS4190', 'Cellular Signaling', '3 Credit(s)', 'Recent advances in the study of the molecular mechanisms of cell function, with an emphasis on the structure and function of signaling components that control cell growth, differentiation, and integrated responses in eukaryotic cells.', 'LIFS 3020', 'Fall, Spring', '2026-08-11 15:43:19.071777');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1461, 'LIFS4200', 'Concepts and Issues in Contemporary Biotechnology', '3 Credit(s)', 'This course will survey the methods and applications of biotechnology, in the aspect related to animals, microbes, agriculture, human health and environment.', 'CENG 1600 OR LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:19.075682');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1462, 'LIFS4220', 'Modern Food Science and Technology', '3 Credit(s)', 'This course delves into the principles of food science and technology, focusing on food composition, processing, safety, and innovation.', 'LIFS 2210 AND LIFS 2220', 'Fall, Spring', '2026-08-11 15:43:19.079968');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1463, 'LIFS4320', 'Data Science for Biology and Medicine', '3 Credit(s)', 'This is a course for the application of data science in biology and medicine. The course will introduce the fundamental principles on data science, the technologies and implementations of data mining, as well as the modeling of several practical questions in biomedicine.', 'BIEN 3320 (COMP 1021 OR COMP 1022P (prior to 2025-26) OR COMP 2011) AND (DASC 2220 OR ISOM 2500 OR LIFS 3150 OR MATH 2411) AND (LIFS 3140)', 'Fall, Spring', '2026-08-11 15:43:19.085238');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1464, 'LIFS4370', 'Human Genetics and Personalized Medicine', '3 Credit(s)', 'Many variations in the human population such as hair thickness, tolerance to milk in adults, high blood cholesterol and susceptibility to certain types of cancer can be determined by genetic factors.', 'LIFS 2210 OR LIFS 3140', 'Fall, Spring', '2026-08-11 15:43:19.089498');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1465, 'LIFS4380', 'Pharmacology and Toxicology', '3 Credit(s)', 'Fundamental concepts of drug action and toxicity; clinically useful agents in central and peripheral disorders; toxicology of drugs and agents that are hazardous to living organisms.', 'LIFS 2040', 'Fall, Spring', '2026-08-11 15:43:19.093550');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1466, 'LIFS4540', 'Structure and Function of Proteins', '3 Credit(s)', 'Determination of protein sequences and three-dimensional structures; relationship between structure and function; principles of protein design and engineering.', 'LIFS 2210', 'Fall, Spring', '2026-08-11 15:43:19.097237');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1467, 'LIFS4550', 'Biochemistry of Nutrition', '3 Credit(s)', 'The biochemistry of major food ingredients including proteins, oil, carbohydrates, vitamins and minerals; functional and nutritional properties will be emphasized.', 'None', 'Fall, Spring', '2026-08-11 15:43:19.101879');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1468, 'MATH1003', 'Calculus and Linear Algebra', '3 Credit(s)', 'This course teaches basic application techniques in single-variable calculus and linear algebra. Key topics include: systems of linear equations and matrices, functions and graphing, derivatives and optimization, integration and applications.', 'Level 2 or above in HKDSE Mathematics (Compulsory Part)', '', '2026-08-11 15:43:39.631663');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1469, 'MATH1005', 'Calculus and Statistics', '4 Credit(s)', 'The course covers basic applications and techniques of single-variable calculus, statistics and probability. Key topics of calculus include differentiation and integration of trigonometric, exponential and logarithmic functions, graphing, optimization, and probability.', 'Level 2 or above in HKDSE Mathematics (Compulsory Part)', '', '2026-08-11 15:43:39.636757');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1470, 'MATH1006', 'Calculus, Vectors, and Matrices', '4 Credit(s)', 'The course covers basic applications and techniques of single-variable calculus, vectors and matrices. Key topics of calculus include differentiation and integration, graphing, optimizations, area under a curve, and volume of rotationally symmetric bodies.', 'Level 2 or above in HKDSE Mathematics (Compulsory Part)', '', '2026-08-11 15:43:39.647555');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1471, 'MATH1013', 'Calculus I', '3 Credit(s)', 'This is an introductory course in one-variable calculus. Topics include functions and their limits, continuity, derivatives and rules of differentiation, applications of derivatives, and basic integral calculus.', 'MATH 1012 (prior to 2025-26), MATH 1014, MATH 1020, MATH 1023, MATH 1024', '', '2026-08-11 15:43:39.652135');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1472, 'MATH1014', 'Calculus II', '3 Credit(s)', 'This is an introductory course in one-variable calculus, the second in the Calculus I and II sequence. Topics include applications of definite integral, improper integrals, vectors, curves, and parametric equations.', 'MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1023 OR (grade A- or above in MATH 1003)', '', '2026-08-11 15:43:39.656785');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1473, 'MATH1020', 'Accelerated Calculus', '4 Credit(s)', 'A concise introduction to one-variable calculus, primarily designed for talented secondary school students. Topics include functions, limits, derivatives, definite and indefinite integrals, and their applications.', 'MATH 1013, MATH 1014, MATH 1023, MATH 1024', '', '2026-08-11 15:43:39.662003');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1474, 'MATH1023', 'Honors Calculus I', '3 Credit(s)', 'This is the first in the sequence of honors courses in one-variable calculus, with emphasis on rigorous mathematical reasoning. Topics include inequalities, functions and their graphs, vectors, limit and continuity, and applications of derivatives.', 'Level 5 or above in HKDSE Mathematics Extended Module M2', '', '2026-08-11 15:43:39.665411');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1475, 'MATH1024', 'Honors Calculus II', '3 Credit(s)', 'This is the second in the sequence of honors courses in one-variable calculus, with an emphasis on rigorous mathematical reasoning. Topics include integral calculus, techniques of integration, improper integrals, applications of integrals, and infinite series.', 'MATH 1023', '', '2026-08-11 15:43:39.668859');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1476, 'MATH1701', 'Introductory Topics in Mathematical Sciences', '1-4 Credit(s)', 'This is a general science course that introduces students to selected disciplines or topics of high popular interest, emphasizing the crucial roles that mathematics play.', '', '', '2026-08-11 15:43:39.672815');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1477, 'MATH2001', 'Foundation of Mathematics', '2 Credit(s)', 'This course covers foundational concepts and rigorous reasoning in mathematics essential for higher-level courses. Topics include mathematical induction, set notations and logic, complex numbers, and elementary number theory.', 'Level 5 or above in HKDSE Mathematics Extended Module M2 OR MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023', '', '2026-08-11 15:43:39.678254');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1478, 'MATH2011', 'Introduction to Multivariable Calculus', '3 Credit(s)', 'Differentiation and integration in several variables, vector analysis.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; OR MATH 1014; OR MATH 1020; OR MATH 1024', '', '2026-08-11 15:43:39.683763');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1479, 'MATH2023', 'Multivariable Calculus', '4 Credit(s)', 'Topics include sequences, series, gradients, extrema, line integrals, multiple integrals, and theorems such as Green''s and Stokes’ theorem.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.688153');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1480, 'MATH2024', 'Honors Multivariable Calculus', '4 Credit(s)', 'This honors course covers deeper theoretical concepts of multivariable calculus, targeting mathematically mature students.', 'MATH 1024', '', '2026-08-11 15:43:39.693788');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1481, 'MATH2033', 'Mathematical Analysis', '4 Credit(s)', 'A rigorous course in the principles of mathematical analysis including limits, continuous functions, and Riemann integration.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.697569');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1482, 'MATH2043', 'Honors Mathematical Analysis', '4 Credit(s)', 'An advanced course in mathematical analysis focused on rigorous treatment of functions, continuity, and differentiability.', 'Grade A- or above in MATH 1024', '', '2026-08-11 15:43:39.700760');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1483, 'MATH2111', 'Matrix Algebra and Applications', '3 Credit(s)', 'The course covers systems of linear equations, vector spaces, linear transformations, and canonical forms.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.704508');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1484, 'MATH2121', 'Linear Algebra', '4 Credit(s)', 'This course dives into vector spaces, matrices, systems of linear equations, inner product, and eigenvalues.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.708221');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1485, 'MATH2131', 'Honors in Linear and Abstract Algebra I', '4 Credit(s)', 'An introduction to linear and abstract algebra, including groups, bases, and spectral theorems.', 'Grade A in AL Pure Mathematics; or grade A- or above in MATH 1014/MATH 1020/MATH 1024', '', '2026-08-11 15:43:39.712870');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1486, 'MATH2343', 'Discrete Structures', '4 Credit(s)', 'This course covers core concepts in discrete mathematics such as logic, combinatorics, and set theory.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; or MATH 1014; or MATH 1020; or MATH 1024', '', '2026-08-11 15:43:39.716298');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1487, 'MATH2350', 'Applied Linear Algebra and Differential Equations', '3 Credit(s)', 'Introduction to linear algebra and differential equations, including exposure to MATLAB.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.720622');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1488, 'MATH2351', 'Introduction to Differential Equations', '3 Credit(s)', 'Fundamental methods in solving first and second order ordinary differential equations, and introduction to partial differential equations.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics; OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.725168');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1489, 'MATH2352', 'Differential Equations', '4 Credit(s)', 'This course covers various types of differential equations and concepts like eigenvalues and eigenfunctions.', 'MATH 2111 OR MATH 2121 OR MATH 2131', '', '2026-08-11 15:43:39.730195');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1490, 'MATH2411', 'Applied Statistics', '4 Credit(s)', 'A systematic introduction to statistical inference including estimation, hypothesis testing, and regression analysis.', 'A passing grade in AL Pure Mathematics / AL Applied Mathematics OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.735886');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1491, 'MATH2421', 'Probability', '4 Credit(s)', 'Fundamental concepts in probability including random variables, distributions, and limit theorems.', 'MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.740164');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1492, 'MATH2431', 'Honors Probability', '4 Credit(s)', 'A deeper exploration of probability theory, including distributions and limit theorems.', '(Grade A- or above in MATH 1014) OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.745003');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1493, 'MATH2511', 'Fundamentals of Actuarial Mathematics', '3 Credit(s)', 'Concepts of actuarial financial mathematics applied to cash flow calculations.', 'MATH 1003 OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.749448');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1494, 'MATH2731', 'Mathematical Problem Solving', '3 Credit(s)', 'Focus on problem solving techniques in combinatorics, number theory, and math games.', 'A passing grade in AL Pure Mathematics/AL Applied Mathematics; OR MATH 1014 OR MATH 1020 OR MATH 1024', '', '2026-08-11 15:43:39.753436');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1495, 'MATH3033', 'Real Analysis', '4 Credit(s)', 'Function analysis in several dimensions concerning limits, continuity, and integration.', '(MATH 2011 OR MATH 2023 OR MATH 2024) AND (MATH 2033 OR MATH 2043) AND (MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350)', '', '2026-08-11 15:43:39.757358');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1496, 'MATH3043', 'Honors Real Analysis', '4 Credit(s)', 'An advanced sequence on analysis covering Lebesgue measure and integration.', 'Grade A- or above in MATH 2043', '', '2026-08-11 15:43:39.764719');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1497, 'MATH3121', 'Abstract Algebra', '3 Credit(s)', 'Algebraic structures including polynomials, groups, and linear algebra concepts.', 'MATH 2111/MATH 2121/MATH 2131/MATH 2350', '', '2026-08-11 15:43:39.768182');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1498, 'MATH3131', 'Honors in Linear and Abstract Algebra II', '4 Credit(s)', 'Continues the introductory sequence in linear and abstract algebra focused on rigorous application.', 'Grade B- or above in MATH 2131', '', '2026-08-11 15:43:39.771959');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1499, 'MATH3312', 'Numerical Analysis', '3 Credit(s)', 'Basic numeric analysis including stability of computation and optimization methods.', '(COMP 1021 / COMP 1022P (prior to 2025-26) / COMP 1023) AND (MATH 2111 / MATH 2121 / MATH 2131 / MATH 2350) AND (MATH 2031 / MATH 2033 / MATH 2043)', '', '2026-08-11 15:43:39.778893');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1500, 'MATH3322', 'Matrix Computation', '3 Credit(s)', 'Covers matrix analysis and algorithms in data science applications.', 'MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350', '', '2026-08-11 15:43:39.783663');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1501, 'MATH3332', 'Data Analytic Tools', '3 Credit(s)', 'Introduces tools useful for data analysis including Fourier analysis and functional analysis.', '(MATH 2011 OR MATH 2023 OR MATH 2024) AND (MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350)', '', '2026-08-11 15:43:39.788512');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1502, 'MATH3343', 'Combinatorial Analysis', '3 Credit(s)', 'Introduction to combinatorics including permutations, binomial theorem, and generating functions.', 'MATH 2121/MATH 2111/MATH 2350/MATH 2131; or MATH 2343/COMP 2711', '', '2026-08-11 15:43:39.794728');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1503, 'MATH3423', 'Statistical Inference', '3 Credit(s)', 'Explores sampling theory, point estimation, confidence intervals, and hypothesis testing.', 'MATH 2421 OR MATH 2431', '', '2026-08-11 15:43:39.799333');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1504, 'MATH3424', 'Regression Analysis', '3 Credit(s)', 'Covers estimation in linear regression, multicollinearity, and variable selection.', 'MATH 3423', '', '2026-08-11 15:43:39.802498');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1505, 'MATH4511', 'Quantitative Methods for Fixed Income Derivatives', '3 Credit(s)', 'Topics on bond markets, yields, forward rates, and regression-based hedging.', 'MATH 2011 OR MATH 2023 OR MATH 2024 AND (MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350) AND (IEDA 2520 AND IEDA 2540 OR ISOM 2500 OR LIFS 3150 OR MATH 2411) AND (FINA 2203 OR FINA 2303 OR MATH 2511)', '', '2026-08-11 15:43:39.806882');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1506, 'MATH4512', 'Fundamentals of Mathematical Finance', '3 Credit(s)', 'Topics on bond portfolio management, asset pricing models, and investment performance analysis.', 'MATH 2011 OR MATH 2023 OR MATH 2024 AND (MATH 2111 OR MATH 2121 OR MATH 2131 OR MATH 2350) AND (IEDA 2540 OR ISOM 2500 OR LIFS 3150 OR MATH 2411) AND (MATH 2511 OR FINA 2203 OR FINA 2303)', '', '2026-08-11 15:43:39.814824');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1507, 'MATH4513', 'Life Contingencies Models and Insurance Risk', '3 Credit(s)', 'Covers survival models, insurance benefits, premium calculations, and cash flows.', 'RMBI 4220 OR ELEC 2600 OR ISOM 3540 OR MATH 2421 OR MATH 2431', '', '2026-08-11 15:43:39.818346');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1508, 'MATH4821', 'Special Topics', '1-4 Credit(s)', 'Focus on a coherent collection of topics selected from a particular branch of mathematics.', '', '', '2026-08-11 15:43:39.821616');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1509, 'MGMT1110', 'Introduction to Management', '3 Credit(s)', 'This course provides students with a systematic approach to acquiring a solid foundation in the principles and current practices of management. The focus of the course is about the interaction between individuals (managers) and the organization. We will explore what managers do through discussion of the four fundamental functions of managers, namely planning, organizing, leading and controlling. Topics include: evolution of management theories, environmental influences on management, organizational culture, strategic management, organizational design, change management, organizational control and human resources management.', 'None', 'Not specified', '2026-08-11 15:44:24.384066');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1510, 'MGMT1120', 'Developing the Leader in You', '3 Credit(s)', 'Leading people effectively is a tremendous challenge, a great opportunity, and a serious responsibility. This course is about developing your full potential as a leader. The focus will be on skills development so that you can use leadership theories and concepts to improve your leadership skills. Topics include leadership traits and behavior theories, leadership values, the team concept and group dynamics and leader as coach and developer of people. Interactive class activities will be conducted including videos, discussions and self-assessment exercises.', 'None', 'Not specified', '2026-08-11 15:44:24.389694');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1511, 'MGMT1130', 'Traps and Pitfalls in Judgment and Decision Making', '3 Credit(s)', 'Decision making is a central human activity, but how good are we at it? Scientific evidence suggests that our decisions are often biased and flawed, resulting in disappointing or even disastrous outcomes. This course draws upon contemporary research in psychology and other social sciences to better understand how it is that people make decisions, and why those decisions are often made badly. The course will emphasize a theoretical understanding of human decision making, as well as a comprehension of the real world implications of our mistakes both for us and for our society, and what, if anything, can be done about it.', 'CORE 1373', 'Not specified', '2026-08-11 15:44:24.394277');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1512, 'MGMT2010', 'Business Ethics and the Individual', '2 Credit(s)', 'This course presents and exemplifies three major traditions of ethical thought in East and West moral philosophy - namely utilitarianism, principle-based ethics and virtue-based ethics. Employing guest speakers, lectures, cases, contemporary readings, role-plays, fieldwork, reflective student writing, and discussion groups, the course engages students in a serious consideration of their own ethical standards as applied to their present academic environment and their future careers. Students come to understand through this course that while an ethical dilemma may be viewed in various ways depending on one''s guiding assumptions, decisions and actions must be chosen in harmony with one''s own moral convictions. For Business students only.', 'None', 'Not specified', '2026-08-11 15:44:24.399109');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1513, 'MGMT2011', 'New Venture Creation', '3 Credit(s)', 'This course introduces students to the fundamental knowledge, mindset, and skill sets required to create and manage new ventures. Through a combination of theory, practical exercises, case studies, and projects, students will learn to recognise, assess, and articulate new opportunities for entrepreneurial ventures, generate innovative business ideas based on technological concepts, and understand the resources and strategies necessary for implementation. Students will be exposed to the real-world challenges of creating a new technical venture and will acquire the essential knowledge and skills for setting up and managing a venture. The course also help participants develop a greater awareness of their personal goals, strengths and limitations in venture creation and growth. Instructor''s approval is required for enrollment in the course.', 'MGMT 4220', 'Not specified', '2026-08-11 15:44:24.402368');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1514, 'MGMT2110', 'Organizational Behavior', '3 Credit(s)', 'Human behavior and behavioral issues in organizations studied from the perspective of the individual and that of the organization.', 'None', 'Not specified', '2026-08-11 15:44:24.405811');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1515, 'MGMT2130', 'Business Ethics and Social Responsibility', '2 Credit(s)', 'Taking a discussion-based approach to examining ethical issues in a corporate context, this intermediate business ethics course will focus mainly on the ethical issues related to the interaction between business and society. Students will further develop their ethical knowledge, moral reasoning skills, and attitudes towards social responsibility by considering the overarching corporate implications of their decisions. This highly interactive course will draw upon relevant current issues to help students understand (and overcome) some of the real-world challenges that business executives confront.', '(for non-BIBU and non-SGFN students) MGMT 2010', 'Not specified', '2026-08-11 15:44:24.409399');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1516, 'MGMT3110', 'Human Resources Management', '4 Credit(s)', 'Manpower planning, job analysis and design, recruitment, performance appraisal, compensation, training and development, health and safety at work and discrimination.', 'MGMT 2110', 'Not specified', '2026-08-11 15:44:24.414283');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1517, 'MGMT3120', 'Managerial Leadership', '4 Credit(s)', 'Understand the nature of leadership and how it goes beyond managership. To develop an appreciation for the complexities of dealing with people who hold different values. To introduce, develop and encourage new strategies and techniques to enhance both teamwork and effectiveness in the workplace.', 'MGMT 2110', 'Not specified', '2026-08-11 15:44:24.417938');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1518, 'MGMT3130', 'Judgement and Decision Making in Organizations', '4 Credit(s)', 'This course is about how people make decisions, with special emphasis on decision making in an organizational context. It attempts to provide an understanding of employee and manager decision making at two levels - the individual and the group.', 'MGMT 2110', 'Not specified', '2026-08-11 15:44:24.421731');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1519, 'MGMT3140', 'Negotiation', '4 Credit(s)', 'Theories and processes of negotiation; negotiation strategies; contextual factors in negotiation; other issues in negotiation.', 'None', 'Not specified', '2026-08-11 15:44:24.425746');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1520, 'MGMT3160', 'Environmental Business Strategies', '3 Credit(s)', 'This course covers strategic opportunities arising from environmental risks. Public and regulatory demand for environmental products and services must co-exist with the need for corporations to maximize shareholder wealth. The course examines both theoretical and practical issues that arise in attempting to balance the health of the natural environment with value creation. Lessons from the course will be of interest to students of strategy and the environment. Restricted to MGMT and BBA students.', 'CORE 1371 OR MGMT 1110 OR MGMT 2110', 'Not specified', '2026-08-11 15:44:24.431256');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1521, 'MGMT3170', 'Managing CSR (Corporate Social Responsibility)', '3 Credit(s)', 'This course will focus on specific CSR (Corporate Social Responsibility) issues facing companies today, emphasizing how firms manage positive social and environmental impacts while addressing stakeholder needs. Students will undertake an embedded project with links to real businesses to gain practical grounding in contemporary CSR challenges.', 'None', 'Not specified', '2026-08-11 15:44:24.434877');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1522, 'MGMT4000', 'Special Topics in Management', '0-4 Credit(s)', 'Current development issues in the field of organization and management; topics selected by instructors.', 'MGMT 2110', 'Not specified', '2026-08-11 15:44:24.439945');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1523, 'MGMT4010', 'Independent Study', '1-4 Credit(s)', 'Faculty directed independent study. May be graded letter grades or P/F subject to different offerings.', 'None', 'Not specified', '2026-08-11 15:44:24.443299');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1524, 'MGMT4210', 'Corporate Strategy', '3 Credit(s)', 'Major techniques and approaches to the development and implementation of corporate strategies. Underlying concepts; analytical techniques; internal and external competitor analysis and evaluation of strategic options.', 'MGMT 2110', 'Not specified', '2026-08-11 15:44:24.449263');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1525, 'MGMT4220', 'Entrepreneurship and Innovation', '4 Credit(s)', 'This course introduces knowledge about the creation and management of new business ventures, while addressing corporate entrepreneurship, social entrepreneurship, and family businesses.', 'MGMT 2011', 'Not specified', '2026-08-11 15:44:24.452912');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1526, 'MGMT4230', 'International Management', '4 Credit(s)', 'Understanding and managing multinational corporations in different economic, social, cultural, legal and technological environments.', 'None', 'Not specified', '2026-08-11 15:44:24.470814');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1527, 'MGMT4240', 'Strategic Management in China', '4 Credit(s)', 'This course teaches key theories and frameworks in strategic management and applies them to the Chinese context with case-intensive learning and extensive student participation.', 'MGMT 5480', 'Not specified', '2026-08-11 15:44:24.475939');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1528, 'MGMT4250', 'Management Consulting', '3 Credit(s)', 'This course combines theory and practical skills necessary for understanding and resolving business problems, emphasizing team-based proposals for strategic solutions.', 'CORE 1371 OR MGMT 1110 OR MGMT 2110', 'Not specified', '2026-08-11 15:44:24.483024');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1529, 'MGMT4270', 'Training and Development', '3 Credit(s)', 'Provides an understanding of the training and developing process in organizations, encompassing needs assessment, learning theories, evaluation of training programs, and recent trends.', 'MGMT 3110', 'Not specified', '2026-08-11 15:44:24.487766');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1530, 'MGMT4280', 'Transnational Legal Issues and Dispute Settlement', '3 Credit(s)', 'This course introduces core legal principles of transnational economic law and mechanisms for settling disputes in trade and investment.', 'MGMT 4000D', 'Not specified', '2026-08-11 15:44:24.491547');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1531, 'MGMT4290', 'HR Analytics', '3 Credit(s)', 'Explores the use of HR data and analytical tools to improve decision-making in human resources and enhance organizational effectiveness.', 'MGMT 3110', 'Not specified', '2026-08-11 15:44:24.501912');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1532, 'MGMT4310', 'Power, Influence, and Persuasion', '3 Credit(s)', 'An advanced experiential course focusing on strategies of power and influence in business contexts, integrating theory with practice.', 'MGMT4000F', 'Not specified', '2026-08-11 15:44:24.505396');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1533, 'MECH1990', 'Industrial Training', '0 Credit(s)', 'A practical training course in an industrial simulated environment. For students of the Mechanical and Aerospace Engineering Department only.', '', '', '2026-08-11 15:44:39.997759');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1534, 'MECH3420', 'Engineering Materials II', '3 Credit(s)', 'MECH 3420 is an advanced course on materials science and engineering offered in this department.', 'MECH 2410', '', '2026-08-11 15:44:40.075261');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1535, 'OCES1001', 'The Earth as a Blue Planet', '3 Credit(s)', 'The ocean is the largest life supporting habitat on Earth, and yet, it is less explored than the surface of the moon. This survey course introduces students to the fundamental, cross-disciplinary knowledge of our ocean from its formation, to the physics in circulation and climate modulation, to the chemistry and biology of the living systems within. On successful completion of the course, students will be able to: 1. Describe the physical, chemical, geological, and biological characteristics of the ocean. 2. Demonstrate knowledge of the diversity of marine life and marine ecosystems. 3. Understand fundamental ocean processes through the integration of cross-disciplinary core scientific concepts. 4. Explain how ocean processes influence Earth’s climate and biodiversity. 5. Recognize the role of humans in shaping the ocean’s future and evaluate solutions for sustainable ocean stewardship.', '', '', '2026-08-11 15:45:31.455946');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1536, 'OCES1010', 'Principles and Applications of Environmental Science', '3 Credit(s)', 'This course aims to provide students with a science background to learn and address the environmental issues caused by humans. Key topics include emerging global, regional and local environmental issues; renewable and non-renewable energy; life-supporting systems of our planet and its biodiversity; atmosphere, air pollution and global climate change; water resources and water pollution; ocean plastics and solid waste management; environmental health and toxicology. Through the course, students will be able to understand fundamental knowledge of the inter-relationship between life and our environment, the characteristics of the environmental sustainability, pollution and monitoring measures, and technologies used in pollution control and remediation.', 'OCES 1030', '', '2026-08-11 15:45:31.469378');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1537, 'OCES1030', 'Environmental Science', '3 Credit(s)', 'The course introduces students without a science background to the general concepts of environment, natural resources, and sustainable development. Topics include pressing global, regional and local environmental issues; renewable and non-renewable energy; life-supporting systems of our planet and its biodiversity; atmosphere, air pollution and global climate change; water resources and pollution; ocean plastics and solid waste management; environmental health and toxicology. Throughout the course, students will gain a sufficient background and a better understanding of the root causes of key environmental issues. They will also become more aware of their role, as individuals, in environmental protection and sustainable development.', 'CORE 1140; LIFS 1030, OCES 1010', '', '2026-08-11 15:45:31.474458');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1538, 'OCES2002', 'Marine Chemistry', '3 Credit(s)', 'This course is an introduction to chemical oceanography. It describes the chemistry of the ocean based on distribution and dynamics of elements, isotopes, atoms and molecules. This ranges from fundamental physical, thermodynamic and kinetic chemistry to two-way interactions of ocean chemistry with biological, geological and physical processes. It encompasses both inorganic and organic chemistry, and includes studies of ocean-atmosphere dynamics and marine sediments. Non-OST students may enroll in the course upon instructor’s approval only.', 'CHEM 1030 (prior to 2024-25) OR CHEM 1011', '', '2026-08-11 15:45:31.482402');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1539, 'OCES2003', 'Descriptive Physical Oceanography', '3 Credit(s)', 'This course is an introduction to physical oceanography that includes topics such as physical description of the sea, physical properties of seawater, methods and measurements, wind-driven ocean circulation, abyssal ocean circulation, boundary processes, and wave motions. Large-scale distributions and processes that are central to the ocean’s role in Earth’s climate and biosphere will also be addressed and discussed.', '(PHYS 1101 OR PHYS 1111 OR PHYS 1112 OR PHYS 1312) AND (MATH 1005 OR MATH 1006 OR MATH 1012 (prior to 2025-26) OR MATH 1013 OR MATH 1020 OR MATH 1023)', '', '2026-08-11 15:45:31.496185');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1540, 'OCES2004', 'Sustainable Ocean', '3 Credit(s)', 'This course explores the principles and practices of sustainability as they apply to the world''s oceans. Students will learn about the impacts of human activities on marine ecosystems and how to develop strategies for sustainable use and conservation of ocean resources. The course combines aspects of marine ecology, oceanography, environmental science, and socio-economics.', '', '', '2026-08-11 15:45:31.508235');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1541, 'OCES2005', 'Coastal Marine Habitats', '3 Credit(s)', 'The course introduces students to a range of local marine coastal habitats through lectures and various field trips. Students are expected to deepen their understanding of and interest in marine ecology, biodiversity and natural conservation. After receiving training related to Hong Kong marine ecology and biodiversity, students will conduct group projects on local marine conservation, acquire skills for scientific exploration, and devise related applications. This course emphasizes positive attitudes and values education, which encourage students to care for the environment and respect for life. For OST students only.', '', '', '2026-08-11 15:45:31.520624');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1542, 'OCES2100', 'Conservation Field Trips', '1 Credit(s)', 'This course introduces students to a range of local conservation efforts through various field trips. Through this course, students are expected to enhance their appreciation of our nature, to recognise the importance of harmony between human and the environment, as well as to learn how to contribute to environmental conservation as a responsible citizen. Guided tours may be conducted in Cantonese by the request of hosting organizations. Instructor''s approval is required for enrolling in the course.', 'ENVS 2001', '', '2026-08-11 15:45:31.533030');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1543, 'OCES2130', 'Marine Biology', '3 Credit(s)', 'Survey of the major marine living organisms; their habitat and community structures; trophic interactions and the marine ecosystem.', 'OCES 3130', '', '2026-08-11 15:45:31.546002');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1544, 'OCES2201', 'Internship', '2-4 Credit(s)', 'This course aims to provide students with hands-on experience in environmental and ocean science fields. Students will undertake training and duties under the internship supervisors. Graded P or F. Maybe graded PP. Cantonese may be used in off-campus trainings and internships, in some situations. Instructor’s approval is required for enrolling in the course.', 'ENVS 2002', '', '2026-08-11 15:45:31.552737');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1545, 'OCES2330', 'Marine Biology Laboratory', '3 Credit(s)', 'Both laboratory and field investigations will provide the opportunity to apply and adapt the experimental methods developed here to specific groups of marine organisms, diversified marine habitats, and practical issues in marine/environmental science. Tutorial sessions and field trips will be used to enhance student''s understanding of the practical work and the theories covered in the lectures.', 'OCES 3330; OCES 2130', '', '2026-08-11 15:45:31.564675');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1546, 'OCES3001', 'Coastal Environmental Monitoring', '3 Credit(s)', 'Students will gain hands-on experience in field survey and sampling, laboratory studies including physical, chemical and biological analyses, experimental design, as well as data analyses and presentations. Course topics include coastal survey, water quality monitoring, marine sediment quality monitoring, etc.', 'ENVS 3001; OCES 1001 OR OCES 2001 (prior to 2025-26)', '', '2026-08-11 15:45:31.570230');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1547, 'OCES3003', 'Field Methods in Marine Studies', '4 Credit(s)', 'Through this course, students will be equipped with the knowledge and skills for sample collection and in situ measurement in various marine habitats. The topics will include (i) the design of scientifically robust sampling plans, (ii) safety precautions for field activities, (iii) proper collection and preservation of field samples, (iv) proper measurement and recording of in situ environmental parameters, and (v) post field trip sample storage and data management.', '', '', '2026-08-11 15:45:31.585689');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1548, 'OCES3005', 'Blue Economy', '3 Credit(s)', 'This course explores the concept of the ‘Blue Economy’, which involves the sustainable use of ocean resources for economic growth, improved livelihoods, and jobs while preserving the health of the ocean ecosystem. Students will gain a comprehensive understanding of the key sectors involved, the opportunities and challenges they present, and the policies and frameworks required to foster sustainability.', '', '', '2026-08-11 15:45:31.599987');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1549, 'OCES3160', 'Ecology', '3 Credit(s)', 'Basic principles and patterns of ecology; population growth; community interaction; ecosystem; ecosphere.', '', '', '2026-08-11 15:45:31.612947');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1550, 'OCES3204', 'Essential Oceanography', '3 Credit(s)', 'This course invites students to explore the oceans through an interdisciplinary lens, integrating concepts from biology, chemistry, physics, and geology. Students will investigate oceanic processes, marine ecosystems, and the chemical composition of seawater while considering the interconnectedness of these fields. The curriculum includes topics such as ocean circulation, nutrient dynamics, marine biodiversity, and the impact of climate change on ocean health. Students will gain a comprehensive understanding of human impacts on marine environments and global systems. The course emphasizes critical, equipping students to address complex oceanographic challenges. By bridging multiple disciplines, this course prepares students for careers in marine science, environmental policy, and sustainability.', 'OCES 2001 (prior to 2025-26) OR OCES 2004', '', '2026-08-11 15:45:31.619139');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1551, 'OCES3301', 'Data Analysis in Ocean Science', '3 Credit(s)', 'The goal of the course is to learn basic numerical analysis tools needed to compute and practice simple techniques for analyzing oceanographic data. These analysis include basic statistics, curve fitting, and simple graphics. Students will learn these techniques through examples from ocean data sets. Students will learn to conduct these analyses with Python or R and are not assumed to have experience in programming.', 'COMP 1021 OR COMP 1023', '', '2026-08-11 15:45:31.624792');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1552, 'OCES3302', 'Marine Pollution Tracking', '3 Credit(s)', 'The marine environment is susceptible to a range wide of land-based pollution such as sewage, industrial effluent and terrestrial runoff. Very often the pollution source is either concealed or diffuse without an apparent point of discharge. The tracking of pollution source is essential to accurate assessment of the ecosystem and health consequences as well as effective mitigation and remedial actions. Pollution source tracking is a cross-disciplinary challenge, involving knowledge and skills in microbiology, molecular biology, chemistry, hydrodynamics, etc. This course serves to provide an in-depth understanding of the principle of pollution source tracking, the cutting-edge technology in the field and also case studies from Hong Kong and other parts of the world.', '', '', '2026-08-11 15:45:31.631030');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1553, 'OCES4001', 'Ocean and Climate Change', '3 Credit(s)', 'Ocean is the largest carbon reservoir on the Earth. It plays a central role in regulating the global climate but is currently under severe anthropogenic stress. This course provides students with relevant scientific background in ocean and climate, which enables them to understand the past, present and future climate changes. The impacts of human-induced changes of ocean and climate will also be investigated.', 'ENVS 3004; (OCES 2001 (prior to 2025-26) OR OCES 2002) AND OCES 2003', '', '2026-08-11 15:45:31.635632');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1554, 'OCES4103', 'Fisheries and Aquaculture', '3 Credit(s)', 'Fisheries and Aquaculture introduces the science behind capture fisheries and aquaculture production, from both a global and local perspective. Topics covered include the different types of fishing gears and methods commonly employed, the biology of fisheries resources (including finfish and shellfish), stock assessment, the basics of fish population modeling, and some emerging techniques such as environmental DNA-based fish monitoring methods. Students will learn about the diversity of fishery resources, as well as the status, operation, and sustainable management of capture fisheries. They will also explore the role of aquaculture in food production, its economics, and mariculture operations.', '', '', '2026-08-11 15:45:31.642408');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1555, 'OCES4201', 'Environmental Microbiology', '3 Credit(s)', 'The course aims to introduce the students to (i) the fundamental features of microorganisms that live in the natural environment, (ii) the roles of the microorganisms in natural processes that drive our ecosystem, such as biogeochemical cycling, interactions with plants and animals, (iii) the use of the microorganisms in environmental technology. Key concepts are illustrated with real-life examples and case studies.', 'ENVS 3005; LIFS 2060 OR OCES 1010 OR OCES 1030', '', '2026-08-11 15:45:31.646554');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1556, 'OCES4202', 'Marine Biotechnology', '3 Credit(s)', 'The goal of this course is provide the students a comprehensive understanding of marine biotechnology. The students will be able to learn the basic concepts of marine biodiversity, biotechnology, and the production of different compounds. At the end of this course, the students will be able to evaluate the importance of marine resources and propose a sustainable way to utilize them.', '', '', '2026-08-11 15:45:31.651630');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1557, 'OCES4203', 'Environmental Impact and Risk Assessment', '3 Credit(s)', 'This course gives an overview on the relationships between human health, environment, and sustainable development. Topics include the development and objectives of environmental impact and risk assessment; impacts of environmental quality (including air, water, wastes, ecology) and health risks; assessment and mitigation; public participation; sustainable development. Case studies and guest lectures will be included. For OST, LIFS and CHEM students in their third and fourth year of study only.', 'OCES 1010; LANG 4010', '', '2026-08-11 15:45:31.657118');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1558, 'OCES4204', 'Coral Reef Ecosystem Science', '4 Credit(s)', 'This course provides a grounding in the theory required for comprehensive multi-disciplinary study of subtidal coastal ecosystems. Using coral reefs as an example, lectures will explore global values and threats on coral reefs, the physical, biogeochemical and ecological factors controlling their structure and function, and how to study these factors using integrative, multi-disciplinary research based on the concepts of ecosystem science. For OST students in their third or fourth year of study only.', 'OCES 3003 AND OCES 3160', '', '2026-08-11 15:45:31.662002');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1559, 'OCES4301', 'Environmental Conservation', '3 Credit(s)', 'This course covers the essential topics of environmental conservation, which includes biodiversity, ecosystems, environmental ethics and economics, environmental policy, resource management, and conservation biology. Case studies from Hong Kong and other regions will be investigated. For LIFS and OST students in their third or fourth year of study only.', 'ENVS 4301; OCES 3160', '', '2026-08-11 15:45:31.666974');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1560, 'OCES4303', 'AI and Machine Learning in Marine Science', '3 Credit(s)', 'Machine learning is increasingly prevalent in ocean sciences, and this course provides a hands-on introduction to some of the machine learning tools in the content of the related ocean science problems, in a progressive fashion in terms of complexity. Topics touched on include principles of regression, clustering, dimensionality reduction, trees, neural nets, and extra topics depending the recent updates in the field. The primary focus of the course will be on utilising the tools for ocean science applications, although some foray into the theory behind the tools will also be given.', 'OCES 3301 AND (COMP 1021 OR COMP 1023)', '', '2026-08-11 15:45:31.670725');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1561, 'OCES4320', 'Marine Toxicology', '3 Credit(s)', 'Marine toxicology aims to provide fundamental concepts in the toxicology of marine pollution, with focuses on the general properties and principles of persistent and or toxic substances commonly encountered in the marine environment and in the biota, and their effects on humans and their actions and movement in the marine environment. How chemicals are absorbed, distributed, metabolized, and eliminated by the biological organisms in the marine environment will be examined. The biological response to the toxicants and its mechanisms will be covered. Knowledge and techniques in the monitoring, measurement and management of toxicants and pollutants in the marine environment will be discussed.', 'OCES 2002', '', '2026-08-11 15:45:31.675603');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1562, 'OCES4326', 'Introduction to Fluid Dynamics', '3 Credit(s)', 'Lagrangian and Eulerian methods for the flow description; derivation of the Euler and Navier-Stokes equations; sound wave and Mach number; 2D irrotational flow; elements of aerofoil theory; water wave dispersion relation; shallow water waves; ship wave pattern; dynamics of real fluid, stokes flow and boundary layer theory.', 'MATH 4326; MATH 4052; CIVL 2510, MECH 2210', '', '2026-08-11 15:45:31.679193');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1563, 'OCES4910', 'Independent Study', '1-3 Credit(s)', 'Independent studies or projects under the directed guidance of a faculty member. Enrollment in the course requires prior approval of the course instructor, and credits assigned depend on the workload. Students may repeat the course up to two times if different topics are taken. Graded P or F.', '', '', '2026-08-11 15:45:31.683776');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1564, 'OCES4940', 'Special Topics in Ocean Science and Technology', '1-4 Credit(s)', 'This course will focus on emerging topics in ocean science and technology. The topics will be explored through lectures, field work and/or workshops. For OST students in their third and fourth year of study.', '', '', '2026-08-11 15:45:31.687336');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1565, 'OCES4964', 'Ocean Science and Technology Capstone Project Research', '3 Credit(s)', 'Under the supervision of a faculty member, students will undertake a project about ocean science and technology. The project can be delivered through the format of literature review or research. Students are required to submit a written report. Subject to the nature of the project, students may be required to give oral presentation as well. For OST students in their third and fourth year of study only. Instructor’s approval is needed for enrollment in the course.', '', '', '2026-08-11 15:45:31.694572');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1566, 'OCES4974', 'Ocean Science and Technology Research Project I', '3 Credit(s)', 'This is the first course of the two-term project. Students will undertake a research project about ocean science and technology under faculty supervision. Through the reading of scientific literature, field/laboratory studies, meetings with supervisors, and presentations in laboratory meetings, students will learn the latest knowledge in their chosen field of research and the skills in hypothesis synthesis and testing, experimental design, data collection and analysis, and scientific communication. Students will be evaluated for their performance through continuous assessment by the supervisor and an oral presentation held at the end of the course. For OST students in their fourth year of study only. Instructor’s approval is required for enrollment in the course.', '', '', '2026-08-11 15:45:31.699486');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1567, 'OCES4984', 'Ocean Science and Technology Research Project II', '3 Credit(s)', 'This course is a continuation of OCES 4974 in which students will undertake a research project about ocean science and technology under faculty supervision. Through the reading of scientific literature, field/laboratory studies, meetings with supervisors, and presentations in laboratory meetings, students will learn the latest knowledge in their chosen field of research and the skills in hypothesis synthesis and testing, experimental design, data collection and analysis, and scientific communication. Students will be evaluated for their performance through continuous assessment by the supervisor and a written report to be submitted at the end of the course. For OST students in their fourth year of study only. Instructor’s approval is required for enrollment in the course.', 'OCES 4974', '', '2026-08-11 15:45:31.703066');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1568, 'PPOL1110', 'Public Policy in Cases', '3 Credit(s)', 'This course aims to equip students with conceptual and theoretical abilities that are essential for understanding the complex but fascinating world of public policy. Theoretical knowledge will be illustrated through 13 real-world policy cases from Asia, Africa, and North America, covering a wide range of areas including health care, poverty alleviation, rural development, technology innovation, and crisis management. Students will engage the class through dynamic co-production of knowledge.', '', '', '2026-08-11 15:45:43.301659');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1569, 'PPOL1120', 'Public Policy for a Healthy Society', '3 Credit(s)', 'This course aims to introduce students from all disciplines to fundamental public policy concepts through the lens of public health and sustainable societies. This course will examine how governments, organisations, and communities develop, implement, and evaluate policies that promote health and wellbeing. The course emphasizes interdisciplinary learning by connecting public policy concepts with societal health challenges that affect daily life, from pandemic responses to mental health initiatives.', '', '', '2026-08-11 15:45:43.306067');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1570, 'PPOL1130', 'Introduction to Global Public Policy Through Film', '3 Credit(s)', 'This course utilizes award-winning films to introduce students to the most pressing global public policy challenges facing policymakers today. It is divided into six interconnected modules, focusing on the global governance of poverty and inequality, finance and financial crises, taxation and offshore tax dodging, climate change and ecocide, peace and security, and corporate power and accountability.', '', '', '2026-08-11 15:45:43.309426');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1571, 'PPOL2000', 'Special Topics in Public Policy', '1-4 Credit(s)', 'Selected topics of current interest in public policy studies. The course aims to broaden students'' exposure to a broad range of topics within the public policy discipline. The course may be repeated for credit, if the topics studied are different.', '', '', '2026-08-11 15:45:43.320656');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1572, 'PPOL2110', 'Science, Technology and Society in China', '3 Credit(s)', 'This course aims to cultivate students’ systematic and critical thinking about science, technology, innovation, and society, especially in light of the transition from traditional China to contemporary China. Differing from the usual courses focusing on this subject, this course will take a social and critical approach.', '', 'CORE 2940', '2026-08-11 15:45:43.324590');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1573, 'PPOL2320', 'Experiments in Power: Why We Make the Rules We Make', '3 Credit(s)', 'This interdisciplinary course examines the psychological foundations of governance through hands-on simulations and empirical inquiry. Students explore how individual cognition, group behavior, and social context shape rule-making and public decision processes.', '', '', '2026-08-11 15:45:43.332036');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1574, 'PPOL3000', 'Special Topics in Public Policy', '1-4 Credit(s)', 'Selected topics of current interest in public policy studies. The course aims to provide students with a more in-depth knowledge of a broad range of topics within the public policy discipline.', '', '', '2026-08-11 15:45:43.337117');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1575, 'PPOL3210', 'Energy Policy', '3 Credit(s)', 'This course addresses two fundamental questions about energy policy: Why and how do governments intervene in energy markets? What do we know about the relationships between government decisions and the economic and environmental performance of energy systems?', '', '', '2026-08-11 15:45:43.340504');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1576, 'PPOL3800', 'Ethics, Emerging Technologies and Public Policy', '3 Credit(s)', 'This course studies the ethical dimensions of emerging technologies and public policy. The overarching theme is to explore the moral debate surrounding some pressing policy issues in emerging technologies nowadays.', 'SOSC 3800', '', '2026-08-11 15:45:43.348779');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1577, 'PPOL4000', 'Special Topics in Public Policy', '1-4 Credit(s)', 'Selected topics of current interest in public policy studies. The course aims to provide students the advanced knowledge for a broad range of topics within the public policy discipline.', '', '', '2026-08-11 15:45:43.353773');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1578, 'RMBI1010', 'Risk Management in Financial Institutions', '3 Credit(s)', 'Risk exists in every aspect of our daily life, and risk management is essential for any organization to achieve their business objectives. This course provides an opportunity for students to examine the various kinds of risk existing in society, and learn about the benefits and impacts of risk management. The course focuses on risk measurement and analysis in enterprise business and modern financial institutions. Learning activities consist of a mixture of lectures, case studies and lab exercises. From taking this course, students’ awareness of risk management will be raised. They can also improve their critical thinking and analytical skills, and become responsible and ethical citizens.', '', '', '2026-08-11 15:46:05.752091');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1579, 'RMBI1020', 'Business Intelligence for Data-Driven Decisions', '3 Credit(s)', 'Business intelligence is a discipline that comprises a set of theories, methodologies and processes to analyze business data with the aim of improving an organization''s decision making, business planning and projection. Tomorrow’s employees and executives may not need the advanced skills of a data scientist, but they must be data literate. Therefore, there is a need to bring together data skills and business management by introducing a common core course, specializing at applying data analytics techniques to business scenarios for the implementation of business intelligence. The aim of this course is to introduce the general workflow of business intelligence and various applications of data analytics models in business scenarios. The course also focuses on an analysis of the strengths, limitations, causes and benefits of the use of business intelligence. The course also includes hands-on practical exercises by using data mining and statistics models on real business data sets.', '', '[BLD] Blended learning', '2026-08-11 15:46:05.759010');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1580, 'RMBI2000', 'Special Topics in Risk Management and Business Intelligence', '0-4 Credit(s)', 'This special topics course provides an opportunity for students to understand the fundamental knowledge and current development in the field of risk management and business intelligence. A range of professional activities are eligible for study, including seminars/lectures, professional activities/meetings, journal readings, structured readings, discussion sessions etc depending on the nature of topics. The course maybe repeated for credits if different topics are taken. Enrollment may require approval of the course instructor. May be graded by letter, P/F or DI/PA/F for different offerings.', '', '', '2026-08-11 15:46:05.763426');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1581, 'RMBI2001', 'Academic and Professional Development in Risk Management and Business Intelligence', '0 Credit(s)', 'This course is designed to provide academic advising to students throughout their studies in the RMBI program, to enhance their understanding of the industries relevant to Risk Management and Business Intelligence and the related techniques expected by the market. Students are required to attend seminars and discussion sessions. For RMBI students only. Graded P/PP/F.', '', '', '2026-08-11 15:46:05.767699');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1582, 'RMBI3000', 'Special Topics in Risk Management', '0-4 Credit(s)', 'This special topics course provides an opportunity for students to gain a more in-depth knowledge required for learning the techniques relevant to risk management. A range of professional activities are eligible for study, including seminars/lectures, professional activities/meetings, journal readings, structured readings, discussion sessions, etc., depending on the nature of topics. The course maybe repeated for credits if different topics are taken. Enrollment may require approval of the course instructor. May be graded by letter, P/F or DI/PA/F for different offerings.', '', '', '2026-08-11 15:46:05.772626');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1583, 'RMBI3010', 'Data Analytics with R', '2 Credit(s)', 'This course provides a hands-on introduction to R as a programming language and environment for data analytics and visualization. It will cover the basic syntax including functions and flow control, some commonly used data structures such as vectors, lists, matrices and data frames, as well as data importing and visualization in R. The course will also introduce a few primary data cleaning techniques in dealing with missing values, duplicates and inconsistency, and means to implement simple data transformation and normalization with R. Classic data mining models and the corresponding packages in R will also be presented, with the focus on model fine tuning and parameter calibration for practical applications. For RMBI students only.', 'RMBI 3110', '', '2026-08-11 15:46:05.776728');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1584, 'RMBI3110', 'Introduction to Risk Management and Business Intelligence', '3 Credit(s)', 'This course presents basic concepts and techniques for risk management and business intelligence. Various types of risk such as market risk, credit risk and operational risk are discussed with business applications and regulatory issues. Modern development of business intelligence, data management techniques and related applications like financial analysis, risk assessment, customer relationship management and human capital productivity analysis are also presented.', 'ISOM 2500 or MATH 2411', '', '2026-08-11 15:46:05.780562');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1585, 'RMBI4000', 'Special Topics in Risk Management and Business Intelligence', '1-4 Credit(s)', 'This subject provides an opportunity for students to learn about the current development in the field of risk management and business intelligence. A range of professional activities are eligible for study, including seminars/lectures, professional activities/meetings, journal readings or structured readings.', '', '', '2026-08-11 15:46:05.784559');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1586, 'RMBI4220', 'Life Contingencies Models and Insurance Risk', '3 Credit(s)', 'The topics discussed in this course include survival models, life tables and selection, insurance benefits, annuities, premium calculation, and insurance policy values.', 'MATH 4513, ELEC 2600 OR ISOM 3540 OR MATH 2421 OR MATH 2431', '', '2026-08-11 15:46:05.796098');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1587, 'RMBI4310', 'Advanced Data Mining for Risk Management and Business Intelligence', '3 Credit(s)', 'This course will explore some advanced principles and techniques of data mining, with emphasis on applications in risk management and business intelligence. Topics include data mining process for data transformation and integration, data preprocessing, data mining algorithms and evaluation of data mining models and results. Advanced topics include data stream analysis, using data warehouse for decision support, supervised, semi-supervised and unsupervised learning techniques in data mining. We will cover advanced data mining applications in credit risk analysis, scale up methods for mining massive customer data and various novel applications such as data mining applications in social network analysis. Projects are aimed at familiarize the students with the entire data mining process rather than isolated applications.', 'COMP 4332, COMP 4331 or ISOM 3360', '', '2026-08-11 15:46:05.800849');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1588, 'RMBI4980', 'Risk Management and Business Intelligence Capstone Project I', '4 Credit(s)', 'Student conducts an in-depth study on selected topics in Risk Management and Business Intelligence under the supervision of a faculty. Scope may include the identification of a non-reference problem, followed by subsequent analysis and solution of the problem. Creative and critical thinking in the decision processes made under uncertainty are expected to be demonstrated in the project.', 'COMP 4331 OR ISOM 3360', '', '2026-08-11 15:46:05.806713');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1589, 'RMBI4990', 'Risk Management and Business Intelligence Capstone Project II', '4 Credit(s)', 'This is the continuation of RMBI 4980. Student conducts an in-depth study on selected topics in Risk Management and Business Intelligence under the supervision of a faculty. Scope may include the identification of a non-reference problem, followed by subsequent analysis and solution of the problem. Creative and critical thinking in the decision processes made under uncertainty are expected to be demonstrated in the project.', 'RMBI 4980', '', '2026-08-11 15:46:05.811964');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1590, 'PHYS1001', 'Physics and the Modern Society', '3 Credit(s)', 'This course is for students with no physics background. Course content: Principle of scientific theories and methods, Aristotle''s law, Newtonian mechanics. Thermal physics, heat engine, energy crisis and global warming. Nature of waves and the physics of hearing and vision. Electricity and magnetism, electromagnetic waves and telecommunication. Relativity, quantum physics, nuclear energy and semiconductor. Developments and outlook of contemporary physics. Students without HKDSE qualifications may seek instructor’s approval for enrolment.', 'CORE 1110, Level 3 or above in HKDSE 1/2x Physics or HKDSE 1x Physics; any PHYS courses at 1100-level or above', 'N/A', '2026-08-11 15:46:21.333519');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1591, 'PHYS1002', 'Introduction to Astrophysics and Astronomy', '3 Credit(s)', 'This course addresses the origin of modern astronomy, the solar system, seasons, moon & eclipses, motion & gravity, light & telescopes, star light & atoms, stars (binary, formation, evolution and death), neutron stars & black holes, normal galaxies, peculiar galaxies, dark matter, dark energy and cosmology.', 'PHYS 1006, PHYS 3071', 'N/A', '2026-08-11 15:46:21.339560');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1592, 'PHYS1003', 'Energy and Related Environmental Issues', '3 Credit(s)', 'This course will introduce the basic concepts of the physical principles behind energy. Forms of energy (including fossil energy, nuclear energy and various forms of renewable energy) and their use for electricity generation, as well as their impacts on the environment from both global and regional perspectives will be covered. Issues related to energy conservation and related environmental issues in Hong Kong and the rest of the world will be addressed.', 'CORE 1111', 'N/A', '2026-08-11 15:46:21.346223');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1593, 'PHYS1006', 'Astronomy for Beginners', '3 Credit(s)', 'For students with no physics background. Introduction to our Universe; observation in astronomy; origin of modern astronomy. Newton''s law of motions; gravity; light, atoms and telescope. The Sun; stellar formation and evolution; white dwarfs, neutron stars and black holes. The Milky way Galaxy; Normal galaxies, active galaxies and supermassive black holes. Foundation of modern cosmology; dark matter, dark energy and the fate of the Universe; the beginning of time.', 'Level 3 or above in HKDSE 1/2x Physics OR HKDSE 1x Physics, PHYS 1001, PHYS 1002', 'N/A', '2026-08-11 15:46:21.351080');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1594, 'PHYS1007', 'Quantum Information for Everyone', '3 Credit(s)', 'Information cannot exist without a physical system to represent it. Quantum physics enables some fundamental new ways of information processing. This course offers an introduction to the past, present and future of quantum information processing (QIP). This course starts from a gentle introduction to quantum theory without assuming any physics background, then moves to the key applications of QIP including quantum computing, quantum cryptography, and quantum communication.', 'CORE 1112, PHYS 4812, AMAT 1510', 'N/A', '2026-08-11 15:46:21.357427');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1595, 'PHYS1101', 'Introductory Physics', '4 Credit(s)', 'This course is for students with no physics background. It can serve as a standalone introduction to physics or as a preparatory course for students who intend to take PHYS 1112. Topics covered include heat and gases, force and motion, waves, and electricity and magnetism.', 'Level 3 or above in HKDSE 1/2x Physics or HKDSE 1x Physics; any PHYS courses at 1100-level or above', 'N/A', '2026-08-11 15:46:21.361997');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1596, 'PHYS1111', 'General Physics I', '3 Credit(s)', 'PHYS 1111 and PHYS 1112 target students who have learned the most basic knowledge in physics in high school. Students with more advanced physics background should consider taking PHYS 1312. PHYS 1111 employs an algebra-based approach. Key topics include motions and Newton''s laws, work and energy, conservation of energy and momentum, rotation, rigid body, simple harmonic and damped oscillations, forced oscillations, standing waves and sound waves, kinetic theory and the laws of thermodynamics.', 'Level 3 or above in HKDSE 1/2x OR HKDSE 1x Physics, Level 3 or above in HKDSE Mathematics Extended Module M1/M2, PHYS 1101, PHYS 1112, PHYS 1312', 'N/A', '2026-08-11 15:46:21.365940');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1597, 'PHYS1112', 'General Physics I with Calculus', '3 Credit(s)', 'PHYS 1111 and PHYS 1112 target students who have learned the most basic knowledge in physics in high school. Students with more advanced physics background should consider taking PHYS 1312. PHYS 1112 employs a calculus-based approach. Key topics include motions and Newton’s Laws, work and energy, conservation of energy and momentum, rotation, rigid body, simple harmonic and damped oscillations, forced oscillations, standing waves and sound waves, kinetic theory and the laws of thermodynamics.', '(Level 3 or above in HKDSE 1/2x OR in HKDSE 1x Physics) AND Level 3 or above in HKDSE Mathematics Extended Module M1/M2', 'N/A', '2026-08-11 15:46:21.369530');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1598, 'PHYS1113', 'Laboratory for General Physics I', '1 Credit(s)', 'A laboratory course to accompany PHYS 1111/PHYS 1112/PHYS 1312. Experiments in mechanics and heat are chosen to illustrate the experimental foundations of physics presented in the lecture courses.', 'PHYS 1111 OR PHYS 1112 OR PHYS 1312', 'N/A', '2026-08-11 15:46:21.373002');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1599, 'PHYS1114', 'General Physics II', '3 Credit(s)', 'This course targets students who have learned the most basic knowledge in physics in high school. Students with more advanced physics background should consider taking PHYS 1314. This course employs a calculus-based approach. Key topics include Coulomb''s law, electric field and potential, Gauss'' law, capacitance, circuits, magnetic force and field, Ampere''s law, electromagnetic induction, AC circuit, Maxwell''s equations, electromagnetic waves, wave optics, interference and diffraction.', '(PHYS 1111 OR PHYS 1112 OR PHYS 1312) AND (level 3 or above in HKDSE Mathematics Extended Module M1/M2 OR MATH 1013 OR MATH 1020 OR MATH 1023)', 'N/A', '2026-08-11 15:46:21.377280');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1600, 'PHYS1115', 'Laboratory for General Physics II', '1 Credit(s)', 'A laboratory course to accompany PHYS 1114/1314. Experiments in static and current electricity and magnetism, and optics are chosen to illustrate the experimental foundations of physics presented in the lecture courses.', 'PHYS 1114 OR PHYS 1314', 'N/A', '2026-08-11 15:46:21.382301');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1601, 'PHYS1312', 'Honors General Physics I', '3 Credit(s)', 'This course is a more in-depth version of PHYS 1112. It is intended to provide a solid foundation to students who wish to take more advanced physics courses in the future. Key topics include motions and Newton’s Laws, work and energy, conservation of energy and momentum, rotation, rigid body, simple harmonic and damped oscillations, forced oscillations, standing waves and sound waves, kinetic theory and the laws of thermodynamics.', '(Level 5* or above in HKDSE 1/2x Physics OR in HKDSE 1x Physics) AND (Level 5 or above in HKDSE Mathematics Extended Module M1/M2)', 'N/A', '2026-08-11 15:46:21.386059');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1602, 'PHYS1314', 'Honors General Physics II', '3 Credit(s)', 'This course is a more in-depth version of PHYS 1114. It is intended to provide a solid foundation to students who wish to take more advanced physics courses in the future. Key topics include Coulomb’s law, electric field and potential, Gauss’ law, capacitance, circuits, magnetic force and field, Ampere’s law, electromagnetic induction, AC circuit, Maxwell’s equations, electromagnetic waves, geometric optics, interference and diffraction.', '(Grade A- or above in PHYS 1111 OR PHYS 1112 OR Grade B- or above in PHYS 1312) AND (Level 5 or above in HKDSE Mathematics Extended Module M1/M2 OR MATH 1013 OR MATH 1020 OR MATH 1023)', 'N/A', '2026-08-11 15:46:21.389352');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1603, 'PHYS2010', 'Introductory Biological Physics', '3 Credit(s)', 'This course introduces the use of physical methods in the study of biological systems, including macromolecules, membranes, nerves, muscle, photosynthetic systems and visual systems. The biological systems to which the methods are applied will be surveyed and current interpretations of their structure and function will be discussed. The treatment of biological phenomena will be based on physical principles with appropriate mathematics when necessary.', 'BIPH 2010, (LIFS 1901 OR level 3 or above in HKDSE 1xBiology) AND (PHYS 1111 OR PHYS 1112 OR PHYS 1312)', 'N/A', '2026-08-11 15:46:21.395240');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1604, 'PHYS2022', 'Modern Physics', '3 Credit(s)', 'Introduction to relativity; introduction to quantum theory: particle-wave duality and Schrodinger equation; atoms, molecules; and statistical physics: Maxwell, Bose and Fermi distributions.', 'PHYS 1114 OR PHYS 1314, AMAT 2050, [BLD] Blended learning', 'N/A', '2026-08-11 15:46:21.399472');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1605, 'PHYS2023', 'Modern Physics Laboratory', '1 Credit(s)', 'Laboratory accompanying PHYS 2022.', 'PHYS 2022', 'N/A', '2026-08-11 15:46:21.404874');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1606, 'PHYS2080', 'Physics Seminar and Tutorial I', '1 Credit(s)', 'Appropriate seminars and small group tutorials are scheduled to expose students to a variety of issues in science and society, and to enhance students'' communication with faculties and among themselves. For Physics students in their second year of study under the four-year degree only. Graded P or F.', 'N/A', 'N/A', '2026-08-11 15:46:21.408511');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1607, 'PHYS2090', 'Directed Studies in Physics I', '1 Credit(s)', 'This course covers special topics selected by the instructor on the basis of individual student''s request. For students in the second year of study under the four-year degree only. Instructor''s approval is required for enrollment in the course. May be repeated for credits.', 'CGA at 2.70 or above', 'N/A', '2026-08-11 15:46:21.415068');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1608, 'PHYS2124', 'Mathematical Methods in Physics I', '3 Credit(s)', 'This course will cover most of the mathematical tools required for studying classical mechanics, electromagnetism, quantum mechanics and statistical mechanics. Key topics include complex numbers, vector analysis, Fourier series and transform, ordinary differential equations and series solutions.', '(MATH 2011 OR MATH 2023) AND (MATH 2111 OR MATH 2121 OR MATH 2131)', 'N/A', '2026-08-11 15:46:21.419898');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1609, 'PHYS3031', 'Mathematical Methods in Physics II', '3 Credit(s)', 'Physical applications of analytic and numerical methods are studied in such topics as series, Taylor expansion, complex analysis, gamma function and beta functions, and introduction to partial differential equations.', '(MATH 2011 OR MATH 2023) AND (MATH 2111 OR MATH 2121 OR MATH 2131) AND (MATH 2352 OR PHYS 2124)', 'N/A', '2026-08-11 15:46:21.424353');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1610, 'PHYS3032', 'Classical Mechanics', '3 Credit(s)', 'Newtonian mechanics, including rigid bodies; oscillating systems; gravitation and planetary motion; Lagrange equations; Hamilton''s equations; normal modes and small oscillations.', '(PHYS 1111 OR PHYS 1112 OR PHYS 1312) AND (MATH 2011 OR MATH 2023)', 'N/A', '2026-08-11 15:46:21.429018');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1611, 'PHYS3033', 'Electricity and Magnetism I', '3 Credit(s)', 'A physics core course. Electrostatics: electric charge and fields, multipoles, Laplace equation, dielectrics; magnetostatics: currents, magnetic fields and vector potential, magnetic materials; Maxwell''s equations.', 'PHYS 3053, (PHYS 1114 OR PHYS 1314) AND (MATH 2011 OR MATH 2023)', 'N/A', '2026-08-11 15:46:21.432409');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1612, 'PHYS3034', 'Electricity and Magnetism II', '3 Credit(s)', 'Electrodynamics: applications of Maxwell''s equations, propagation in various media, radiation, relativistic electrodynamics, transmission lines and wave guides.', 'PHYS 3033 OR PHYS 3053', 'N/A', '2026-08-11 15:46:21.435579');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1613, 'PHYS3036', 'Quantum Mechanics I', '3 Credit(s)', 'Basic properties of Schrodinger equation, bound and scattering states in simple one-dimensional potentials, formulation of quantum mechanics in terms of Hilbert space and Dirac bracket notation, Schrodinger equation in three-dimensions, angular momentum, hydrogen atom wavefunction, systems of identical particles, spin and statistics, multi-electron atoms and the periodic table.', 'PHYS 3037, PHYS 2022, PHYS 3037, AMAT 3520', 'N/A', '2026-08-11 15:46:21.441315');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1614, 'PHYS3037', 'Honors Quantum Mechanics I', '4 Credit(s)', 'This course is a more in-depth version of PHYS 3036 Elementary Quantum Mechanics I. Topics include: classical mechanics, Schrodinger equation and simple examples in one-dimension, formulation of quantum mechanics in terms of Hilbert space and Dirac bracket notation, real and momentum space representations, Heisenberg and Schrodinger pictures, Schrodinger equation in three-dimensions, angular momentum, hydrogen atom wavefunction, systems of identical particles, the periodic table.', 'PHYS 3036, Grade B- or above in PHYS 2022', 'N/A', '2026-08-11 15:46:21.449846');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1615, 'PHYS3038', 'Optics', '3 Credit(s)', 'Ray tracing, matrix optics, wave optics, superposition of waves and interference, coherence, Fresnel and Fraunhofer diffraction, polarisation, Fourier optics, holography, phase and group velocity, material dispersion, propagation of Gaussian beams.', 'ELEC 4610', 'N/A', '2026-08-11 15:46:21.454793');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1616, 'PHYS3040', 'Introduction to Materials Science', '3 Credit(s)', 'An integrated study of the nature and behavior of metals, ceramics and polymers. Topics include crystal structures, phase diagrams, microstructures and microscopy, defects, phases and interfaces in materials systems, phase transformations, deformation, annealing and failure of materials.', 'AMAT 3060', 'N/A', '2026-08-11 15:46:21.464251');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1617, 'PHYS3243', 'Probability and Statistics for Data Analysis in Physics', '3 Credit(s)', 'This course serves as an introduction to statistical data analysis in its application to physics experiments. The subjects taught include frequentist and Bayesian approach to probability, basic probability distribution functions, Monte Carlo simulation techniques, estimation of parameters, hypothesis testing and more.', '(COMP 1023 OR COMP 1028) AND (MATH 2011 OR MATH 2023 OR MATH 2024) AND (MATH 2111 OR MATH 2121 OR MATH 2131)', 'N/A', '2026-08-11 15:46:21.469288');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1618, 'PHYS4050', 'Thermodynamics and Statistical Physics', '3 Credit(s)', 'Laws of thermodynamics, entropy, thermodynamic relations, free energy; elementary statistical mechanics: Maxwell-Boltzmann, Bose-Einstein and Fermi-Dirac statistics; elementary transport theory; applications to physical systems.', 'PHYS 2022', 'N/A', '2026-08-11 15:46:21.474852');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1619, 'PHYS4051', 'Quantum Mechanics II', '3 Credit(s)', 'This course is mainly on approximation methods in quantum mechanics. Topics include stationary state perturbation theory, variational principle, WKB method, time-dependent perturbation theory, emission and absorption of radiation, adiabatic approximation and geometric phase, scattering theory.', 'PHYS 3031/MATH 4052, AND PHYS 3036/PHYS 3037', 'N/A', '2026-08-11 15:46:21.480934');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1620, 'PHYS4055', 'Particle Physics and the Universe', '3 Credit(s)', 'In this course, a systematic introduction to particle physics will be provided, covering topics such as Feynman diagrams, the Standard Model, particle physics at colliders, and the interplay between particle physics and cosmology.', 'PHYS 3036 OR PHYS 3037, [BLD] Blended learning', 'N/A', '2026-08-11 15:46:21.484598');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1621, 'PHYS4071', 'Big Bang Cosmology and Inflation', '3 Credit(s)', 'In this course, a systematic introduction to modern cosmology will be provided, with topics including Robertson-Walker metric, Friedmann equation, thermal history of the Universe, Big-Bang nucleosynthesis, cosmic microwave background, dark matter and dark energy, inflation.', 'PHYS 2022 AND (PHYS 2124 OR MATH 2351 OR MATH 2352)', 'N/A', '2026-08-11 15:46:21.488196');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1622, 'SBMT1100', 'Business Study Trip', '0-1 Credit(s)', 'This course is offered in the form of a study trip to another country in the winter and summer term. Each study trip will consist of at least three elements, namely lectures delivered by faculty members at the host institution, company visits and cultural adventure in the host country. Approval from the course coordinator is needed prior to enrolling in the course. Graded P or F.', '', 'Winter and Summer Term', '2026-08-11 15:46:21.610685');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1623, 'SBMT1111', 'Business Student Induction', '0 Credit(s)', 'This is an induction course designed for all new students in the School of Business and Management. Students will be divided into 10 cohorts and assigned to designated academic advisors. They will also be participating in a series of planned activities, aiming to help them build bonds and simultaneously identify personal academic interest, examine educational goals, and develop plans to meet objectives through academic advising and other personal development workshops and programs. Graded P or F.', '', '', '2026-08-11 15:46:21.616230');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1624, 'SBMT2100-2110', 'Community Services Project', '1-4 Credit(s)', 'This course is offered in a form of a community project at a designated non-governmental organization (NGO) under the supervision of the School. Students are required to attend all the training sessions, design and implement the service project or participate in the service learning tasks as instructed by the host NGO and/or the course instructors. By the end of the course, students have to submit a reflective statement in the format of a paper, a group project report, or a presentation to demonstrate the attainment of all intended learning outcomes, in addition to other requirements of the relevant NGO as appropriate. Approval from the course coordinator is needed prior to enrolling in the course. Graded PP, P or F. Students may repeat the course for credits if different topics are taken.', '', '', '2026-08-11 15:46:21.619598');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1625, 'SBMT2200', 'Social Enterprise Internship Program', '1-4 Credit(s)', 'The course is intended to give business undergraduate students an opportunity to gain exposure in the area of social entrepreneurship and apply their knowledge to solve real-world challenges facing these organizations. It is conducted in the form of an internship program at a designated social enterprise under the supervision of the School of Business and Management. Approval from the course coordinator is needed prior to enrolling in the course. Graded P or F. Students may repeat the course for credits if different topics are taken.', '', '', '2026-08-11 15:46:21.623261');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1626, 'SBMT2800', 'SBM Cooperative Education Program', '3 Credit(s)', '[EXP] Experiential learning This course is intended to enhance SBM students’ career readiness by combining classroom-based education with practical work experience. By taking any two standalone career development programs, students are required to apply the skills and knowledge learnt in a full-time coop work experience for a single employer for at least 4 months. Approval from the course coordinator is required for enrollment in the course. For SBM Year 2 students or above only. Graded P, PP or F.', '', '', '2026-08-11 15:46:21.627258');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1627, 'SBMT2900', 'Special Topics in Business and Management', '0-4 Credit(s)', 'Special topics in an identified area of Business and Management; topics vary with instructor. May be graded P or F.', '', '', '2026-08-11 15:46:21.630383');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1628, 'SBMT3100', 'Business Field Study Fundamentals', '1-4 Credit(s)', 'The course is mostly a supervised study of a real-life issue faced by an organization. Students will be given opportunities to support organization''s effort through assisting in collection and analysis of data, identification of strategic questions, design of studies, development and reporting. At the end of the course, students will be given a taste of real-life business experience. Approval from the course coordinator is needed prior to enrolling in the course. May be Graded DI/PA/F.', '', '', '2026-08-11 15:46:21.634081');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1629, 'SBMT3200-3210', 'Corporate Project', '1-4 Credit(s)', 'Students apply skills and knowledge learned from business courses to focus on specific projects in a corporation setting. Students will work on group projects sponsored by participating corporations and supervised by faculty members. Approval from the course coordinator is needed prior to enrolling in the course. Graded PP, P or F. Students may repeat the course for credits if different topics are taken.', '', '', '2026-08-11 15:46:21.637636');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1630, 'SBMT3300', 'Business Competitions', '1 Credit(s)', 'In each business competition, students will be required to examine the conceptual and practical aspects of business policies and policy decision making by utilizing all the concepts, theories and tools that they learned in previous courses. This 1-credit course is offered in recognition of the students'' outstanding performance in their participation of business competitions. Approval from the course coordinator is needed prior to enrolling in the course. Graded P or F. Students may repeat the course for credits if different case competitions are taken.', '', '', '2026-08-11 15:46:21.640876');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1631, 'SBMT4000', 'SBM Undergraduate Honors Research Project', '6 Credit(s)', 'The two‐term SBM Undergraduate Honors Research Project is for SBM students who are interested in pursuing systematic research at the senior undergraduate level. The course will act as a pre‐doctoral training program to help students expand their options in seeking future doctoral study opportunities. Students are expected to research a focused problem under close supervision by a faculty and produce a thesis after completing this course. For SBM students in their final year of study only. Approval from the course coordinator is needed prior to enrolling in the course. May be graded PP.', '', '', '2026-08-11 15:46:21.646134');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1632, 'SGFN4733', 'Green Finance Case Analyses', '3 Credit(s)', 'This course provides students with practical experience of sustainable and green finance through the use of case studies and real life situations. Cases from Harvard Business School, HKUST, UC-Berkeley and other institutions, as well as Yale-style cases based on publicly available information, with a strong focus on Asia will be utilized. Students will be put in the manager’s or protagonist’s role to gather and analyze information before ultimately making decisions. All students in this course are expected to have full and active participation under the seminar style instruction. For SGFN students in their third year of study and above. On successful completion of the course, students will be able to: 1. Critically evaluate the core issues of sustainable and green finance situations/challenges. 2. Analyze the interests of various stakeholders that affecting the decision making. 3. Interpret practical cases in Asia context mainly. 4. Communicate effectively across different disciplines in sustainable and green finance. 5. Integrate interdisciplinary skills and knowledge to make practical recommendations.', 'FINA 2303 AND SUST 1000', '', '2026-08-11 15:46:27.380422');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1633, 'SHSS1020', 'Humanities and Social Science Internship', '1-2 Credit(s)', 'This course aims to provide students with internship educational opportunities locally and globally. Under the guidance of the course coordinator, students will undertake training and supervised internships with our potential collaborators (including government departments, NGOs, museums, media and press, cultural industries, social enterprises, social service organizations, business firms, and public corporations). Course assessment will be based on students'' written reports and supervisors'' evaluation. Cantonese may be used in off-campus trainings and internships, in some situations. May be repeated for credits. For students of GCS and QSA program only. Instructor''s approval is required for enrolling in the course. Graded P or F.', 'For students of GCS and QSA program only. Instructor''s approval is required for enrolling in the course.', 'N/A', '2026-08-11 15:46:43.048680');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1634, 'SHSS1030', 'Career Building for GCS and QSA Students', '1 Credit(s)', 'This course helps students in exploring careers within the arena of Humanities and Social Science and beyond. To achieve this, it guides students to develop basic knowledge of the career planning process, the current job market and employers'' expectation in different fields. This course also equips students with practical job application skills, such as the skills of resume writing, aptitude tests, interviews, group discussions, etc. Experiential learning opportunities and individual feedback will be provided to actively engage students in the learning process. Instructor''s approval is required for enrolling in the course. Graded DI, PA or F.', 'Instructor''s approval is required for enrolling in the course.', 'N/A', '2026-08-11 15:46:43.054931');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1635, 'SHSS1040', 'Service Learning in the Humanities and Social Science', '1-4 Credit(s)', 'This course aims to cultivate students'' humanitarian concern and social awareness through engagement in community services. It will provide students a variety of learning opportunities through community services programs initiated by the faculty of the School of Humanities and Social Science, or in collaboration with the faculty of other Schools and local or non-local NGOs. Students will be guided to apply knowledge in the humanities and social science to understand the needs of service recipients and the work of community service providers, and to reflect on their own active participation. Seminars, talks, training sessions, and project guidance will be provided to broaden students'' horizon, build up their interpersonal and cross-cultural communication skills, and cultivate their leadership and teamwork spirit.', 'For SHSS students only. Instructor''s approval is required for enrolling in the course.', 'N/A', '2026-08-11 15:46:43.059493');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1636, 'SHSS1050', 'Humanities and Social Science Co-op Program', '3 Credit(s)', 'This course aims to engage students in working as an intern at an internship partner workplace in order to gain work experience while being guided by an alumni mentor and/or the staff of the DAO and SHSS program office. Course assessments will be based on students'' written reports and supervisors'' evaluation. Credits will only be granted for working at an internship partner recognized by DAO and SHSS. Course enrollment excludes SHSS students in their final year. Instructor''s approval is required for enrolling in the course. Graded P or F.', 'Course enrollment excludes SHSS students in their final year. Instructor''s approval is required for enrolling in the course.', 'N/A', '2026-08-11 15:46:43.064463');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1637, 'SHSS2800', 'SHSS Cooperative Education Program', '3 Credit(s)', 'This course is intended to enhance SHSS students'' career readiness by combining classroom-based education with practical work experience. By taking any two standalone career development programs, students are required to apply the skills and knowledge learnt in a full-time coop work experience for a single employer for at least 4 months. Approval from the course coordinator is required for enrollment in the course. For SHSS Year 2 students or above only. Graded P, PP or F.', 'Approval from the course coordinator is required for enrollment in the course. For SHSS Year 2 students or above only.', 'N/A', '2026-08-11 15:46:43.069418');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1638, 'SHSS3010', 'SHSS Independent Study', '1-2 Credit(s)', 'The course allows students to undertake a pilot project, explore a research theme or complete focused reading on a topic or a seminal book under the supervision of a faculty member. It is restricted to students in the BSc Global China Studies program. Enrollment in the course requires approval from the course coordinator. Graded P or F.', 'It is restricted to students in the BSc Global China Studies program. Enrollment in the course requires approval from the course coordinator.', 'N/A', '2026-08-11 15:46:43.073629');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1639, 'SHSS4991', 'Capstone Project', '3 Credit(s)', 'The capstone project aims to prepare students for research in humanities and social science, and may serve as an introduction to conducting research and writing a quality research project. For those students that do not wish to do a senior thesis, it will still enable them to learn the skills associated with a detailed research project and the presentation of research results. Enrollment in the course requires approval of the course coordinator.', 'Enrollment in the course requires approval of the course coordinator.', 'N/A', '2026-08-11 15:46:43.077998');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1640, 'SHSS4992', 'Honors Thesis', '6 Credit(s)', 'Qualified students in the SHSS Global China Studies program are provided the option of writing a Senior Theses on an academic topic in a field of their own choice during the final year of study. The senior thesis is based on independent research conducted under the close supervision of a faculty member from SHSS. Enrollment in the course requires approval of the course coordinator.', 'Enrollment in the course requires approval of the course coordinator.', 'N/A', '2026-08-11 15:46:43.081428');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1641, 'SHSS4993', 'Honors Research', '3 Credit(s)', 'The honors research teaches the student to utilize relevant theories and methodologies in a concrete research task. It requires the student to conduct more in-depth research based on the capstone project, to collect and analyze relevant material and to complete a thesis that meets academic standards of using citations and references, statement of a problem or an issue, and a clearly identified theoretical point. Enrollment in the course requires approval of the course coordinator.', 'Enrollment in the course requires approval of the course coordinator.', 'N/A', '2026-08-11 15:46:43.086700');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1642, 'SCIE1000', 'Science School Induction', '0 Credit(s)', 'This is a one-year course designed for year 1 science students. It provides induction activities to help students adapt to university life, and to understand the program structure of the school and the meaning of university education. Led by faculties, staffs, and peers, students will learn and practice skills such as teamwork, communication, time management, and goal setting. Graded P or F.', '', '', '2026-08-11 15:46:51.454014');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1643, 'SCIE1010', 'Enrichment Project', '0-3 Credit(s)', 'For Science students only. This course aims to provide complementary educational experience to students outside normal academic curriculum through engagements in internship or outside-classroom project activities related to his/her own discipline. Students enrolled would work under the supervision of a faculty member and are required to submit a report by the end of the semester, in addition to other criteria set by his/her supervisor. Course coordinator''s approval is required for taking the course. 1 credit is normally assigned for 40 hours of work. Graded P or F. May be graded PP. May be repeated for credits if different topics are taken.', '', '', '2026-08-11 15:46:51.461812');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1644, 'SCIE1030', 'Special Topics', '1-4 Credit(s)', 'Selected topics in Science. May be repeated for credit, if different topics taken. May be graded by letter or DI/PA/F for different offerings.', '', '', '2026-08-11 15:46:51.465670');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1645, 'SCIE1080', 'Development and Management on Science Activities', '1-2 Credit(s)', 'For Science students only. Under the supervision of a faculty member, students are given an opportunity to apply scientific knowledge and experimental skills, through developing 6 to 12 hours Science courses/ workshops/activities for primary/secondary school students, and drafting the operation procedures. They would also be able to polish their skills in aspects like resource and manpower management, team building, etc. Course instructor''s approval is required for taking the course. Maybe graded PP.', '', '', '2026-08-11 15:46:51.470986');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1646, 'SCIE1090', 'Community Services Project', '1-4 Credit(s)', 'The course is offered in a form of a community project at a designated non-governmental organization (NGO) under the supervision of the School. Students are required to attend all the training sessions, design and implement the service project / participate in the service learning tasks as instructed by the host NGO and/or the course instructors. By the end of the course, students have to submit a reflective statement in the format of a paper, a group project report or a presentation to demonstrate the attainment of all intended learning outcomes, in addition to other requirements of the relevant NGO as appropriate. Approval from the course coordinator is needed prior to enrolling in the course. Graded PP, P or F. Students may repeat the course for credits if different topics are taken.', '', '', '2026-08-11 15:46:51.477058');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1647, 'SCIE1100', 'Career Building for Science Students', '1 Credit(s)', 'For Science students only. Co-offered by the School of Science and the Career Center (Dean of Students'' Office), this course helps students in exploring careers within the arena of Science and beyond. To achieve this, it guides students to have basic understanding of the career planning process, the current job market and employers'' expectation in different fields. This course also equips students with practical job application skills, such as the skills for resume writing, aptitude tests, interviews, group discussions, etc. Experiential learning opportunities and individual feedback will be provided to actively engage students in the learning process. Graded DI, PA or F.', 'GNED 2510, GNED 2520', '', '2026-08-11 15:46:51.481980');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1648, 'SCIE1102', 'Designing Your Life for Science Students', '1 Credit(s)', 'Originated from Stanford University’s Life Design Lab (Bill Burnett and Dave Evans), this course employs a method called “design thinking” to help students from any program develop a constructive and effective approach to finding and designing their vocation after university. Through small group discussions, in-class activities, personal reflections and individual coaching, this course teaches students to use design thinking to explore many of life’s major challenges, such as pursuing careers they love and finding personal fulfillment. Topics include the integration of work and worldviews, ideation techniques, a portfolio approach to thriving, designing to increase balance and energy and how to prototype all aspects of your life. For Science students only. Graded P or F.', '', '', '2026-08-11 15:46:51.485840');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1649, 'SCIE1110', 'Great Ideas in Science', '3 Credit(s)', 'The course is designed for students with no science background. Using historical great breakthroughs in science and mathematics as examples, the course intends to inspire students to appreciate scientific approaches and develop a genuine appreciation towards human curiosity in the understanding of the world. The course includes 4 modules covering mathematics, physics, chemistry and biology.', '', '', '2026-08-11 15:46:51.498901');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1650, 'SCIE1120', 'Chemistry and Life', '3 Credit(s)', 'The course aims to introduce students without an extensive science background into the chemistry of life and in life as well as some elementary units and mechanisms of life shaped by core chemical molecules and other compounds. Co-taught by lecturers from chemistry and life science, respectively, approximately one half of the course deals with an introduction into the chemical universe that makes life possible; the other half covers how these compounds are involved in some of the basic mechanisms of life.', 'Any 2000-level or above courses in CHEM, LIFS, CENG, BIEN', '', '2026-08-11 15:46:51.502314');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1651, 'SCIE1130', 'Scientific Understanding of Our World', '1 Credit(s)', 'This course aims to provide students an overall scientific understanding of our world. This course will deal with fundamental questions such as the origin of the universe and life, guiding human behavior, and future prospects. Students are expected to have a Science background. Graded DI/PA/F.', '', '', '2026-08-11 15:46:51.509885');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1652, 'SCIE1500', 'Guided Study on Research I', '1 Credit(s)', 'Studies under the directed guidance of a faculty member on a life science / chemistry / environmental science / mathematics / physics topic aiming to explore knowledge of different disciplines. An individual report or presentations are required. For IRE students only. Non-IRE students may enroll upon instructor''s approval.', '', '', '2026-08-11 15:46:51.513526');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1653, 'SCIE2500', 'Guided Study on Research II', '1 Credit(s)', 'Studies under the directed supervision of a faculty member on a life science / chemistry / environmental science / mathematics / physics topic aiming to equip students with hands-on experience in supervised independent study. An individual report or presentation on a chosen topic are required. For IRE students only.', 'SCIE1500', '', '2026-08-11 15:46:51.516855');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1654, 'SCIE2800', 'SCIE Cooperative Education Program', '3 Credit(s)', 'This course is intended to enhance Science students’ career readiness by combining classroom-based education with practical work experience. Students are required to apply the skills and knowledge learnt in a full-time coop work experience for a single employer for at least 4 months. Approval from the course coordinator is required for enrollment. For SSCI Year 2 students or above only. Graded PP, P or F.', '', '', '2026-08-11 15:46:51.520609');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1655, 'SCIE3110', 'Teaching Science Using Innovative Teaching Tools', '3 Credit(s)', 'This course presents a unique opportunity for students to experience the process of preparing learning activities in contrast to being taught. Students will develop teaching tools for secondary school students under the guidance of instructors. Instructor''s consent is required for enrollment.', 'Level 4 or above in HKDSE (1x Biology OR 1x Physics OR 1x Chemistry OR Mathematics M1/M2)', '', '2026-08-11 15:46:51.525416');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1656, 'SCIE3500', 'IRE Research Project I', '3 Credit(s)', 'This course is a one-term research project course for students in the IRE track. The course aims to equip students with hands-on laboratory experience or independent studies. For IRE students only.', 'SCIE2500', '', '2026-08-11 15:46:51.528523');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1657, 'SCIE3900', 'International Research Experience', '3 Credit(s)', 'Research project under the direct supervision of a local faculty member and a co-supervising foreign faculty member in a foreign institution/national laboratory, which aims to guide students to explore advanced research opportunities.', 'SCIE1500 AND (SCIE3500 OR PHYS3090)', '', '2026-08-11 15:46:51.531721');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1658, 'SCIE4500', 'IRE Research Project II', '3 Credit(s)', 'This course is a one-term research project course for students in the IRE track. Aimed at equipping students with hands-on laboratory experience or independent studies. For IRE students only.', 'SCIE3500', '', '2026-08-11 15:46:51.535638');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1659, 'SCIE4860', 'Young Entrepreneurial Syndicate in Applied Sciences Project', '3 Credit(s)', 'In this course, students will team up to work on entrepreneurial projects under the guidance of faculty and/or mentors from industry. Instructor''s approval is required for enrollment in the course.', '', '', '2026-08-11 15:46:51.543109');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1660, 'SISP1001', 'Innovation in STEM Projects', '1 Credit(s)', 'This course aims to introduce STEM projects and state-of-the-art technologies in science and engineering to solve environmental problems in daily life. This experiential course will provide an overview to potential students who wish to engage in STEM education. Students will design and develop a prototype through various innovative learning activities under the guidance of instructors, explain the underlying scientific principles, integrate the multidisciplinary knowledge with innovation and creativity to critically evaluate complex, real-world problems.', 'None', 'Summer', '2026-08-11 15:47:39.036719');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1661, 'SISP1101', 'Appreciation of Our Nature', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. The course aims at introducing the richness of diversity of living organisms around the world and their conservation programs. Local and global case studies will be used to illustrate the concepts. Course activities include lectures, field trip, and students’ project presentations. At the end of the course, students are expected to enhance their appreciation on our nature.', 'None', 'Summer', '2026-08-11 15:47:39.041870');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1662, 'SISP1102', 'Chemistry in the Modern World', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. Starting with fundamental chemistry concepts, this course intends to inspire students to appreciate how chemistry benefits our society. This course has both lecture and laboratory components covering topics of applications of chemistry to environmental and materials science and medicine.', 'None', 'Summer', '2026-08-11 15:47:39.051263');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1663, 'SISP1103', 'Introductory Game Theory', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. This course is a brief introduction of Game Theory. It intends to give a glimpse of some basic concepts in game theory. Students will be taught how interaction of players be modeled in precise mathematics, and solve the corresponding mathematical problems. Topics include: combinational game; games in extensive form; two-person general-sum games; games in coalition form; ordinal matching game.', 'None', 'Summer', '2026-08-11 15:47:39.057526');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1664, 'SISP1104', 'Calculus: the First Steps', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. Calculus is an important mathematical subject with fascinating applications in a wide range of disciplines. This course aims at providing a general perspective on Calculus for students interested in mathematics. The fundamental ideas and concepts in Calculus discussed in this course include the following: challenging problems in the historical development of Calculus, concepts of functions and limits, derivatives and the shapes of graphs, areas and integration, anti-derivatives and the Fundamental Theorem of Calculus, and interesting applications of Calculus in problem solving.', 'None', 'Summer', '2026-08-11 15:47:39.064766');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1665, 'SISP1105', 'The Physics of Everyday Life', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. This course discusses many examples where simple and basic physics theories are used to understand everyday phenomena. Topics include inertia, formation of typhoons, tidal force and tides, energy crisis, greenhouse effect, sound waves and the physics of hearing, light waves and the physics of vision, formation of rainbows, etc.', 'None', 'Summer', '2026-08-11 15:47:39.070064');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1666, 'SISP1106', 'Combinatorics: The Art of Counting and Its Applications', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. The objective of this course is to introduce to students various powerful counting methods such as permutations and combinations, recurrence relations, generating functions and so on, which can be applied to many real-world problems.', 'None', 'Summer', '2026-08-11 15:47:39.076054');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1667, 'SISP1107', 'Amazing Innovations in Biotechnology', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. The field of biotechnology is constantly advancing. Students will gain further insights into what biotechnology can be used in daily lives. Case studies will be primarily used with the blended learning approach to discuss the power of biotechnology.', 'None', 'Summer', '2026-08-11 15:47:39.102829');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1668, 'SISP1108', 'A First Step to Data Science with Python', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. This course provides fundamental concepts and techniques in the field of data science. Students will study basic concepts in probability, statistics and programming using Python.', 'None', 'Summer', '2026-08-11 15:47:39.110627');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1669, 'SISP1109', 'A Logical Approach to Organic Chemistry', '1 Credit(s)', 'This course is offered under the program of the HKUST Summer Institute for Secondary School Students by the School of Science. This course aims to introduce students to a logical approach to organic chemistry and is designed to encourage them to think about how and why chemical reactions occur.', 'None', 'Summer', '2026-08-11 15:47:39.120447');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1670, 'SISP1110', 'Fundamentals of Neuroscience', '1 Credit(s)', 'This course serves as an introductory survey of topics in neuroscience, such as organization of the nervous system, neuronal communication, the senses, and neurological disorders.', 'None', 'Summer', '2026-08-11 15:47:39.125516');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1671, 'SISP1111', 'Physics in Movies', '1 Credit(s)', 'This course explores the portrayal of physics in movies and how it can be judged against the scientific principles. It encourages critical thinking about physics concepts.', 'None', 'Summer', '2026-08-11 15:47:39.132357');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1672, 'SISP1112', 'Matrix Algebra', '1 Credit(s)', 'This course is about matrices and their applications in solving systems of linear equations, computation of matrix inverses, and understanding eigenvalues and eigenvectors.', 'None', 'Summer', '2026-08-11 15:47:39.137537');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1673, 'SISP1113', 'Human Body and Diseases', '1 Credit(s)', 'This course provides an overview of the structure and function of the human body and focuses on bioscience principles such as anatomy and physiology while analyzing disease mechanisms.', 'None', 'Summer', '2026-08-11 15:47:39.143860');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1674, 'SISP1114', 'Mathematical Wonders in Biology', '1 Credit(s)', 'This course offers an overview of fundamental concepts in quantitative biology and develops students'' ability to apply quantitative principles in biology.', 'None', 'Summer', '2026-08-11 15:47:39.155702');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1675, 'SISP1115', 'Microbial Control in Health and the Environment', '1 Credit(s)', 'This course introduces students to managing and controlling microbes in health and environmental contexts through lectures and hands-on lab work.', 'None', 'Summer', '2026-08-11 15:47:39.160180');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1676, 'SISP1116', 'Astronomy for Beginners', '1 Credit(s)', 'This course provides fundamental concepts and principles of modern astronomy, covering topics such as the solar system, stellar evolution, and galaxies.', 'None', 'Summer', '2026-08-11 15:47:39.170960');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1677, 'SISP1117', 'A First Step to Probability', '1 Credit(s)', 'This course covers fundamental concepts of counting, probability theory, and random variables, focusing on practical application.', 'None', 'Summer', '2026-08-11 15:47:39.176172');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1678, 'SISP1301', 'The Fascinating World of Multimedia and Its Processing', '1 Credit(s)', 'This course provides a background in digital media (speech, audio, image and video) and multimedia applications, including hands-on labs for media editing tools.', 'None', 'Summer', '2026-08-11 15:47:39.181432');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1679, 'SISP1302', 'Fundamentals of Robot Control and Action', '1 Credit(s)', 'This laboratory-based course introduces students to the fundamentals of robotics, focusing on sensing, control, and design of a robot.', 'None', 'Summer', '2026-08-11 15:47:39.186540');
