INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1690, 'SISP1317', 'Water, You and Environment', '1 Credit(s)', 'This course raises environmental awareness through the exploration of the relationship between water and environmental sustainability.', 'None', 'Summer', '2026-08-11 15:47:39.267763');
