INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1699, 'SISP1508', 'Understanding Finance', '1 Credit(s)', 'This course introduces finance concepts and their application in daily life, aiming to spark interest in financial literacy.', 'None', 'Summer', '2026-08-11 15:47:39.328615');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1700, 'SISP1509', 'Social Media in Business', '1 Credit(s)', 'Students will explore how social media is used in business contexts, including marketing and communication strategies.', 'None', 'Summer', '2026-08-11 15:47:39.332376');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1701, 'SISP1510', 'Statistics for Business and Policy Analysis', '1 Credit(s)', 'This course teaches statistics concepts relevant to business and social issues, focusing on practical application and analysis skills.', 'None', 'Summer', '2026-08-11 15:47:39.337275');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1702, 'SISP1511', 'Deep Learning Business Applications', '1 Credit(s)', 'This course introduces students to deep learning techniques and their applications in solving business problems.', 'None', 'Summer', '2026-08-11 15:47:39.342997');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1703, 'SISP1512', 'The Art of Negotiation', '1 Credit(s)', 'Students will learn negotiation strategies through practical exercises and discussions focusing on effective negotiation practices.', 'None', 'Summer', '2026-08-11 15:47:39.351873');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1704, 'SISP1513', 'Managing Risk in Business and Daily Life', '1 Credit(s)', 'This course covers risk management principles applicable to business and personal contexts, emphasizing practical skills.', 'None', 'Summer', '2026-08-11 15:47:39.355846');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1705, 'SISP1701', 'Appreciation of Western Architecture', '1 Credit(s)', 'This course explores masterpieces of Western architecture, covering the historical context and significance of notable structures.', 'None', 'Summer', '2026-08-11 15:47:39.361483');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1706, 'SISP1702', 'History that High-School Textbooks Never Touched: Violence, Sins, ''Great'' Men in China, 1800s-1930s', '1 Credit(s)', 'This course unpacks important yet overlooked aspects of Chinese history, covering topics like violence and cultural impact.', 'Chinese reading', 'Summer', '2026-08-11 15:47:39.369320');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1707, 'SISP1703', 'Psychology and Personal Growth', '1 Credit(s)', 'This course addresses psychological challenges during the transition to adulthood, exploring personal growth and development.', 'None', 'Summer', '2026-08-11 15:47:39.382516');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1708, 'SISP1704', 'Humanities and Leadership', '1 Credit(s)', 'A study of humanistic perspectives on leadership, covering philosophical and ethical challenges across cultures and historical contexts.', 'None', 'Summer', '2026-08-11 15:47:39.391899');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1709, 'SISP1705', 'Introduction to Musical Theatre', '1 Credit(s)', 'Students will explore different types of musical theatre while developing skills in performance through hands-on practice.', 'None', 'Summer', '2026-08-11 15:47:39.402079');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1710, 'SISP1706', 'Sociology and Everyday Life', '1 Credit(s)', 'This course examines sociological perspectives on everyday life, focusing on behavior, culture and interpersonal relationships.', 'None', 'Summer', '2026-08-11 15:47:39.406621');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1711, 'SISP1707', 'The Story of Canto-Pop', '1 Credit(s)', 'Exploring the history of Canto-Pop through its influential artists, this course discusses its cultural significance in Hong Kong.', 'None', 'Summer', '2026-08-11 15:47:39.413742');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1712, 'SISP1708', 'Exploring Music and Film', '1 Credit(s)', 'This course investigates the collaborative relationship between music and film, focusing on production and film scores.', 'None', 'Summer', '2026-08-11 15:47:39.421109');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1713, 'SISP1709', 'Introducing Music Theory', '1 Credit(s)', 'Students learn to read and write music, covering standard notation and harmonic concepts essential for music composition.', 'None', 'Summer', '2026-08-11 15:47:39.427015');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1714, 'SISP1710', 'Creativity and Innovation', '1 Credit(s)', 'This course explores the nature of innovation, its importance, and methods to foster creative thinking in various contexts.', 'None', 'Summer', '2026-08-11 15:47:39.440056');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1715, 'SISP1711', 'Science, Technology and Public Health', '1 Credit(s)', 'Examining health issues arising from technological advances, this course develops critical evaluation skills relating to public health.', 'None', 'Summer', '2026-08-11 15:47:39.448125');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1716, 'SISP1712', 'The ''Belt and Road'' Initiative', '1 Credit(s)', 'This course analyzes China’s Belt and Road Initiative, exploring its socioeconomic implications and evaluating specific infrastructure projects.', 'None', 'Summer', '2026-08-11 15:47:39.454382');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1717, 'SISP1713', 'Will Technology Replace Us?', '1 Credit(s)', 'Students discuss the impact of technology on employment and human capabilities, developing critical tools to analyze this evolving relationship.', 'None', 'Summer', '2026-08-11 15:47:39.498471');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1718, 'SISP1714', 'Population Studies', '1 Credit(s)', 'This course introduces core concepts in population studies relevant to various fields, linking them to societal changes and demographic characteristics.', 'None', 'Summer', '2026-08-11 15:47:39.508263');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1719, 'SISP1901', 'Greening Business: Challenges and Opportunities', '1 Credit(s)', 'This course examines environmental issues faced by businesses and the potential for turning sustainability challenges into opportunities.', 'None', 'Summer', '2026-08-11 15:47:39.516561');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1720, 'SUST1000', 'Sustainability Fundamentals', '3 Credit(s)', '', '', '', '2026-08-11 15:47:54.855426');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1721, 'SUST1001', 'Special Topics in Sustainability', '1-4 Credit(s)', 'This special topics course provides students with broad and useful knowledge of various emerging sustainability topics of introductory level with a goal to arouse students'' interest in sustainability studies. May be repeated for credit, if the topics studied are different. Graded letter grade or P/F subject to different offerings.', '', '', '2026-08-11 15:47:54.863272');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1722, 'SUST1010', 'Introduction to Sustainability', '3 Credit(s)', 'This course provides students with a holistic, interdisciplinary, evidence-based understanding of the challenge of ensuring the sustainability of humanity on a planet with limited natural and social capacities. The course introduces frameworks, approaches and key trade-offs underpinning efforts to deal with existing and emerging global issues and considers how these problems relate to our own lifestyles.', 'CORE 1940', '[BLD] Blended learning', '2026-08-11 15:47:54.872919');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1723, 'SUST1020', 'Climate Films and Sustainable Future', '3 Credit(s)', 'This course bridges the artistic depiction of climate disasters in modern movies with the real science of climate change. By introducing and discussing seven films that depict extreme weather conditions, students will use these cinematic portrayals as starting points to delve into the physical science of the climate system. The course will cover the history of Earth’s climate, the ongoing challenges of climate change, and prospective technologies and strategies for a sustainable future. Students will gain fundamental knowledge of the climate system and its essential physical processes. Through immersive experiences, they will also learn to comprehend chronic environmental stresses and understand the pressures that drive sustainable behavior changes. Different pathways of sustainable development and their implications for policies and personal lifestyles will be discussed to inspire students to contribute to embrace and contribute to sustainability. Additionally, the course will explore the connections between art, science, and human behavior.', '', '', '2026-08-11 15:47:54.880793');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1724, 'SUST1030', 'Climate Change and Sustainability: An Interdisciplinary Perspective', '3 Credit(s)', 'This undergraduate course provides an accessible and engaging introduction to the scientific and societal dimensions of climate change, with a focus on both global and local perspectives. Through an interdisciplinary approach, students will learn about the fundamental physical processes that drive climate change and contribute to extreme weather events such as heatwaves, droughts, wildfires, and floods. The course explores how these changes disrupt natural ecosystems, threaten biodiversity, influence economic stability, impact public health, and reshape international relations. It also examines a variety of strategies for adapting to and mitigating the effects of climate change, including policy responses, technological innovations, and community-based approaches, using real-world examples to connect scientific concepts to everyday life. Designed to foster critical thinking, this course equips students with the foundational knowledge and skills to understand and address climate change and sustainability challenges.', '', '', '2026-08-11 15:47:54.893576');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1725, 'SUST1101', 'Environmental, Social, and Governance Fundamentals', '3 Credit(s)', 'This course examines the importance of Environmental, Social, and Governance (ESG) factors in managing modern corporations. Throughout the course, students will examine real-life examples to highlight why and to which extent ESG matters for firms and investors operating in various contexts.', '', '', '2026-08-11 15:47:54.903790');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1726, 'SUST2001', 'Special Topics in Sustainability', '1-4 Credit(s)', 'This special topics course provides students with broad and useful knowledge of various emerging sustainability topics of intermediate level with a goal to arouse students'' interest in sustainability studies and develop creative solutions to sustainability issues. May be repeated for credit, if the topics studied are different. Graded letter grade or P/F subject to different offerings.', '', '', '2026-08-11 15:47:54.911786');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1727, 'SUST3001', 'Special Topics in Sustainability', '1-4 Credit(s)', 'This special topics course provides students with in-depth knowledge of various emerging sustainability topics of advanced level to inspire students to develop solutions to the imminent sustainability issues from a multi-perspective framework. May be repeated for credit, if the topics studied are different. Graded letter grade or P/F subject to different offerings.', '', '', '2026-08-11 15:47:54.925410');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1728, 'SUST4001', 'Special Topics in Sustainability', '1-4 Credit(s)', 'This special topics course provides students with specialized knowledge of various emerging sustainability topics of advanced level with a goal to inspire students to develop solutions to the imminent sustainability issues from a multi-perspective framework and propose action plan therewith. May be repeated for credit, if the topics studied are different. Graded letter grade or P/F subject to different offerings.', '', '', '2026-08-11 15:47:54.930253');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1729, 'SOSC1000', 'Special Topics', '1-4 Credit(s)', 'Focuses on a coherent collection of topics selected from social science. May be repeated for credit, if the topics studied are different. May be graded by letter, P/F for different offerings.', '', '', '2026-08-11 15:48:20.101525');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1730, 'SOSC1050', 'Introduction to Social Science Research', '3 Credit(s)', 'This course is designed to assist students in developing a basic understanding of qualitative and quantitative data analysis and interpretation in the social sciences.', 'Enrolment is restricted to students admitted to BSc in Quantitative Social Analysis from 2022-23 and onwards.', '', '2026-08-11 15:48:20.152843');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1731, 'SOSC1100', 'Quantitative Data Analysis for Social Research I', '3 Credit(s)', 'This course focuses on practical aspects and implementation of social data analysis by introducing basic yet hands-on techniques for presenting, analyzing, and interpreting quantitative data.', 'Not to be taken by students admitted to BSc Quantitative Social Analysis from 2022-23 and onwards.', '[BLD] Blended learning', '2026-08-11 15:48:20.168442');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1732, 'SOSC1110', 'Data Analysis for Quantitative Social Research', '3 Credit(s)', 'This course focuses on practical aspects and implementation of social data analysis. The course is deliberately designed as complementary to formal and theory-based introductory statistical courses.', 'Enrolment is restricted to students admitted to BSc in Quantitative Social Analysis from 2022-23 and onwards.', '', '2026-08-11 15:48:20.186302');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1733, 'SOSC1190', 'China and the World: China''s Development in Historical and Comparative Perspectives', '3 Credit(s)', 'This course examines the economic development of contemporary China from both historical and comparative perspectives.', '', '', '2026-08-11 15:48:20.238438');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1734, 'SOSC1270', 'International Law', '3 Credit(s)', 'This course concerns public international law and covers aspects of international law through the study of legal cases and agreements.', 'CORE 1770', '', '2026-08-11 15:48:20.248513');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1735, 'SOSC1300', 'The World of Politics', '3 Credit(s)', 'This course is designed to provide a general understanding of political science and the problems of political systems, processes, and international relations.', '', '', '2026-08-11 15:48:20.253711');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1736, 'SOSC1309', 'Making Sense of Government and Politics', '3 Credit(s)', 'This course introduces students to the fundamentals of government and politics, examining political theory and comparative politics.', 'SOSC 1300; CORE 1710', '', '2026-08-11 15:48:20.268157');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1737, 'SOSC1350', 'Contemporary China: Continuity and Change', '3 Credit(s)', 'This course reviews major developments and changes in China since 1949 and critically examines transformations in multiple domains.', 'SOSC 1359', '', '2026-08-11 15:48:20.279763');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1738, 'SOSC1359', 'China: Development and Transformations', '3 Credit(s)', 'This course introduces students to the study of contemporary China, critically examining government, economic, and social changes since 1949.', 'CORE 1730; SOSC 1350', '', '2026-08-11 15:48:20.287516');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1739, 'SOSC1400', 'Hong Kong and the Greater Bay Area', '3 Credit(s)', 'This course examines the evolution of the Greater Bay Area and its development processes and challenges.', 'CORE 1740', '', '2026-08-11 15:48:20.295214');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1740, 'SOSC1420', 'Poverty', '3 Credit(s)', 'This course explores poverty measurement, causes, and the impact of poverty on society, with an emphasis on Hong Kong and mainland China.', 'CORE 1720', '', '2026-08-11 15:48:20.303222');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1741, 'SOSC1440', 'Introduction to Economics', '3 Credit(s)', 'This course provides an overview of microeconomics and macroeconomics, focusing on applications relevant to China.', 'ECON 2103, ECON 2113, ECON 2123, ECON 3113, ECON 3133, SOSC 1449', '', '2026-08-11 15:48:20.310418');
