INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1806, 'SOSC4600', 'Understanding Chinese Politics', '3 Credit(s)', 'This course explores the development of the People''s Republic of China through key political concepts.', 'SOSC 1300 or SOSC 1350', '', '2026-08-11 15:48:20.813899');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1807, 'UCOP3200', 'Design for Global Health', '3 Credit(s)', 'A project-based, experiential course that exposes students to tackle global health problems using design thinking as an innovation process. The goal of this course is to develop students’ critical thinking, understand about the needs of different communities around the world, and improve communication, design skills through a multi-disciplinary, team-based design experience. Each team will set objectives at the beginning of the semester after getting the needs of communities via the project partners. There will be several task-based assessments throughout the semester to check the progress of each project team evaluated by teaching team, faculty advisors and project partners. At the end of semester, students need to showcase their output in a form of roadshow. This is a common core course open to students from any academic background who are looking for practical experience in design thinking and motivate to tackle global health issues. Instructor''s approval is required for enrollment in the course.', 'Instructor''s approval is required for enrollment in the course.', 'Not specified.', '2026-08-11 15:48:23.395855');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1808, 'UTOP2401', 'Language Teaching Service-Learning Internship', '3 Credit(s)', 'This course provides undergraduate students with authentic overseas language teaching experience in intercultural service-learning contexts. Offered by HKUST’s Center for Language Education in collaboration with AIESEC’s Global Volunteer Program and partner institutions, students will engage in pre-teaching training, microteaching, consultations, supervised mini teaching practice, guided reflections, and a culminating showcase of their work. The course develops the ability to design, deliver, and evaluate language learning activities for diverse learners; apply effective language teaching strategies to enhance engagement; adapt materials for varied proficiency levels, age groups, and cultural contexts; and operate effectively in international and cross-cultural settings. Students will critically reflect on their teaching and on challenges in intercultural settings. Upon completion, students will be equipped with practical pedagogical skills, reflective capacity, enhanced leadership and communication capabilities to contribute meaningfully as language teachers for community impact. Instructor’s approval is required for enrolling in the course. Graded P or F.', 'Instructor’s approval is required for enrolling in the course.', 'Offered by HKUST’s Center for Language Education', '2026-08-11 15:48:43.533257');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1809, 'UTOP2910', 'Pathways to Teaching for Future Educators', '3 Credit(s)', 'This course is designed to provide undergraduate students with a unique and real-life teaching experience. Through pre-teaching training, consultation sessions, reflection sessions, and a mini teaching conference, students will acquire important knowledge and practice core competencies essential for teaching. The course aims to help students design, implement, and evaluate appropriate learning, teaching, and assessment strategies to cater to learners’ individual learning differences. Students will learn to identify and address educational issues by adopting appropriate strategies to arouse learners’ interest. Additionally, students will learn to reflect on and make reasoned analysis on their teaching. Upon completion of this course, students will be equipped with the necessary skills to accurately and effectively explain subject knowledge to learners and practice effective pedagogical instructions. For students in year 3 or above.', 'For students in year 3 or above.', 'Not specified', '2026-08-11 15:48:43.541428');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1810, 'UTOP3201', 'Practicum in STEAM Education', '3 Credit(s)', 'This course is designed to provide undergraduate students with real-life teaching experience that develops skills useful to the community learning environment. Through pre-teaching training, consultation sessions, reflection sessions, and a mini teaching conference, students will acquire important knowledge and practice core competencies essential for teaching. Students are expected to formulate, design, and evaluate lesson plans from their own knowledge and experience, and conduct teaching sessions as the instructor. Students will learn to identify and address educational issues by adopting appropriate strategies to arouse learners’ interest in a wide range of STEAM topics. Additionally, students will learn to reflect on and make reasoned analysis on their teaching. Upon completion of this course, students will have the skills and confidence to design and deliver STEAM courses and workshops, using innovative pedagogy and state-of-the-art teaching and assessment tools, for primary and secondary school students and even junior university students.', 'UTOP 2910', 'Not specified', '2026-08-11 15:48:43.545987');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1811, 'WBBA2000', 'Special Topics in World Business', '0-4 Credit(s)', 'This Special Topics course offers students a comprehensive understanding of various topics in world business, enhancing their knowledge and proficiency in international business. The course explores emerging and popular subjects in international business that are not currently covered in existing WBBA courses. Students may repeat the course for credit if the topics studied are different. The course is graded with a letter grade or P/F, depending on the specific offerings. For WBB students and students with instructors'' approval only.', 'For WBB students and students with instructors'' approval only', 'Not specified', '2026-08-11 15:48:56.456910');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1812, 'WBBA2030', 'Effective Communication in Business', '3 Credit(s)', 'Whether making a presentation, creating and executing an integrated persuasive appeal, or engaging in group problem solving - students should be able to convey ideas and feelings to their audience clearly, accurately, and persuasively. The course is designed to provide second-year WBB students with the necessary communication skills to analyze and convincingly present solutions to the type of real-world problems that they will face as managers in their career. They will learn the necessary skills they need to solve business problems and make professional presentations.', 'For WBB students in their second year of study', 'Not specified', '2026-08-11 15:48:56.467118');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1813, 'WBBA2050', 'Global Financial Markets and Institutions', '3 Credit(s)', 'This course aims to provide students with basic and practical knowledge in the structure and function of the financial system and the financial institutions active in them. Topics covered include: the fundamentals of interest rates and basic pricing of financial assets, including basic concepts such as the time value of money and the risk-return tradeoff; basic notions of market efficiency and derivatives; the structure and function of the financial system, the role and the types of financial institutions and financial intermediaries.', 'For WBB students in their second year of study', 'Not specified', '2026-08-11 15:48:56.473672');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1814, 'WBBA2080', 'Doing Business in Asia', '3 Credit(s)', 'This course explores the way key business and managerial practices play out in an Asian context. To be a successful business leader, students must possess not only the technical skills and knowledge, but also be able to deal with regional and international business issues independently. Therefore, this course provides a big-picture overview of the business framework in Asia, a platform for students to interact with leading business leaders to learn from their professional experience and obtain first-hand information of the market, as well as practical training on evaluating challenges and opportunities in doing business in Asia through a cross-disciplinary approach.', 'Not specified', 'Not specified', '2026-08-11 15:48:56.479470');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1815, 'WBBA4010', 'Capstone Project', '4 Credit(s)', 'For WBB students only. This course is designed to provide final year WBB students with an opportunity to pursue business studies above and beyond the normal course offerings of HKUST Business School. Students will work on a challenging individual or team capstone project which allows them to conduct empirical research, and synthesize skills and knowledge learned from the program.', 'WBBA 2080, For WBB students only', 'Not specified', '2026-08-11 15:48:56.486112');
INSERT INTO courses (id, code, title, credits, description, prerequisites, offered_semesters, updated_at) VALUES (1816, 'WBBA4900', 'Independent Study', '1-3 Credit(s)', 'Independent study project under the directed guidance of a faculty advisor on an international business topic not covered in other courses. The course aims to broaden and deepen the students'' grasp of knowledge on the chosen topic as identified by the faculty advisor and the student. The course culminates in a final paper and oral presentation. Enrollment in the course requires prior approval of the course instructor, and credits assigned depend on the workload. May be repeated for credits if different topics are taken. Graded by letter or DI/PA/F subject to different offerings.', 'For WBB students only in their second year of study or above', 'Not specified', '2026-08-11 15:48:56.492431');
